static int
dissect_rpcrdma(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void* data _U_)
{
tvbuff_t *volatile next_tvb;
tvbuff_t *frag_tvb;
proto_item *ti;
proto_tree *rpcordma_tree;
guint offset;
guint32 msg_type;
guint32 xid;
guint32 val;
guint32 *p_msgid;
guint write_size;
int save_visited;
rdma_lists_t rdma_lists = { NULL, NULL, NULL };
if (tvb_captured_length(tvb) < MIN_RPCRDMA_HDR_SZ)
return 0;
if (tvb_get_ntohl(tvb, 4) != 1)  
return 0;
xid = tvb_get_ntohl(tvb, 0);
msg_type = tvb_get_ntohl(tvb, 12);
col_set_str(pinfo->cinfo, COL_PROTOCOL, "RPCoRDMA");
col_add_fstr(pinfo->cinfo, COL_INFO, "%s XID 0x%x",
val_to_str(msg_type, rpcordma_message_type, "Unknown (%d)"), xid);
ti = proto_tree_add_item(tree, proto_rpcordma, tvb, 0, MIN_RPCRDMA_HDR_SZ, ENC_NA);
rpcordma_tree = proto_item_add_subtree(ti, ett_rpcordma);
offset = 0;
proto_tree_add_item(rpcordma_tree, hf_rpcordma_xid, tvb,
offset, 4, ENC_BIG_ENDIAN);
offset += 4;
proto_tree_add_item(rpcordma_tree, hf_rpcordma_vers, tvb,
offset, 4, ENC_BIG_ENDIAN);
offset += 4;
proto_tree_add_item(rpcordma_tree, hf_rpcordma_flow_control, tvb,
offset, 4, ENC_BIG_ENDIAN);
offset += 4;
proto_tree_add_item(rpcordma_tree, hf_rpcordma_message_type, tvb,
offset, 4, ENC_BIG_ENDIAN);
offset += 4;
switch (msg_type) {
case RDMA_MSG:
offset = parse_rdma_header(tvb, offset, rpcordma_tree, &rdma_lists);
proto_item_set_len(ti, offset);
frag_tvb = get_reassembled_data(tvb, offset, pinfo, tree);
if (frag_tvb) {
return call_dissector(rpc_handler, frag_tvb, pinfo, tree);
} else if (pinfo->fd->visited && !g_needs_reassembly && rdma_lists.p_read_list) {
return 0;
} else {
next_tvb = tvb_new_subset_remaining(tvb, offset);
write_size = get_rdma_list_size(rdma_lists.p_write_list, pinfo);
if (write_size > 0 && !pinfo->fd->visited) {
gp_rdma_write_offsets = wmem_array_new(wmem_packet_scope(), sizeof(gint));
TRY {
g_rpcrdma_reduced = TRUE;
call_dissector(rpc_handler, next_tvb, pinfo, tree);
}
FINALLY {
g_rpcrdma_reduced = FALSE;
}
ENDTRY;
} else if (write_size > 0 && pinfo->fd->visited) {
p_msgid = (guint32 *)p_get_proto_data(wmem_file_scope(), pinfo, proto_rpcordma, RPCRDMA_MSG_ID);
if (p_msgid) {
save_visited = pinfo->fd->visited;
pinfo->fd->visited = 0;
end_reassembly(*p_msgid, NULL, pinfo);
pinfo->fd->visited = save_visited;
}
}
frag_tvb = process_rdma_lists(next_tvb, 0, &rdma_lists, pinfo, tree);
gp_rdma_write_offsets = NULL;
if (rdma_lists.p_read_list) {
call_data_dissector(next_tvb, pinfo, tree);
break;
} else if (frag_tvb) {
next_tvb = frag_tvb;
}
}

static pj_bool_t on_accept_complete2(pj_ssl_sock_t *ssock,
pj_ssl_sock_t *new_ssock,
const pj_sockaddr_t *src_addr,
int src_addr_len, 
pj_status_t accept_status)
{    
struct tls_listener *listener;
struct tls_transport *tls;
pj_ssl_sock_info ssl_info;
char addr[PJ_INET6_ADDRSTRLEN+10];
pjsip_tp_state_callback state_cb;
pj_sockaddr tmp_src_addr;
pj_bool_t is_shutdown;
pj_status_t status;
char addr_buf[PJ_INET6_ADDRSTRLEN+10];        
PJ_UNUSED_ARG(src_addr_len);
listener = (struct tls_listener*) pj_ssl_sock_get_user_data(ssock);
if (accept_status != PJ_SUCCESS) {
if (listener && listener->tls_setting.on_accept_fail_cb) {
pjsip_tls_on_accept_fail_param param;
pj_ssl_sock_info ssi;
pj_bzero(&param, sizeof(param));
param.status = accept_status;
param.local_addr = &listener->factory.local_addr;
param.remote_addr = src_addr;
if (new_ssock &&
pj_ssl_sock_get_info(new_ssock, &ssi) == PJ_SUCCESS)
{
param.last_native_err = ssi.last_native_err;
}
(*listener->tls_setting.on_accept_fail_cb) (&param);
}
return PJ_FALSE;
}
PJ_ASSERT_RETURN(new_ssock, PJ_TRUE);
if (!listener->is_registered) {
if (listener->tls_setting.on_accept_fail_cb) {
pjsip_tls_on_accept_fail_param param;
pj_bzero(&param, sizeof(param));
param.status = PJSIP_TLS_EACCEPT;
param.local_addr = &listener->factory.local_addr;
param.remote_addr = src_addr;
(*listener->tls_setting.on_accept_fail_cb) (&param);
}
return PJ_FALSE;
}
PJ_LOG(4,(listener->factory.obj_name, 
"TLS listener %s: got incoming TLS connection "
"from %s, sock=%d",
pj_addr_str_print(&listener->factory.addr_name.host, 
listener->factory.addr_name.port, addr_buf, 
sizeof(addr_buf), 1),
pj_sockaddr_print(src_addr, addr, sizeof(addr), 3),
new_ssock));
status = pj_ssl_sock_get_info(new_ssock, &ssl_info);
if (status != PJ_SUCCESS) {
pj_ssl_sock_close(new_ssock);
if (listener->tls_setting.on_accept_fail_cb) {
pjsip_tls_on_accept_fail_param param;
pj_bzero(&param, sizeof(param));
param.status = status;
param.local_addr = &listener->factory.local_addr;
param.remote_addr = src_addr;
(*listener->tls_setting.on_accept_fail_cb) (&param);
}
return PJ_TRUE;
}
pj_bzero(&tmp_src_addr, sizeof(tmp_src_addr));
pj_sockaddr_cp(&tmp_src_addr, src_addr);
status = tls_create( listener, NULL, new_ssock, PJ_TRUE,
&ssl_info.local_addr, &tmp_src_addr, NULL,
ssl_info.grp_lock, &tls);
if (status != PJ_SUCCESS) {
if (listener->tls_setting.on_accept_fail_cb) {
pjsip_tls_on_accept_fail_param param;
pj_bzero(&param, sizeof(param));
param.status = status;
param.local_addr = &listener->factory.local_addr;
param.remote_addr = src_addr;
(*listener->tls_setting.on_accept_fail_cb) (&param);
}
return PJ_TRUE;
}
pj_ssl_sock_set_user_data(new_ssock, tls);
pjsip_transport_add_ref(&tls->base);
if (ssl_info.verify_status && listener->tls_setting.verify_client) {
if (tls->close_reason == PJ_SUCCESS) 
tls->close_reason = PJSIP_TLS_ECERTVERIF;
pjsip_transport_shutdown(&tls->base);
}
state_cb = pjsip_tpmgr_get_state_cb(tls->base.tpmgr);
if (state_cb) {
pjsip_transport_state_info state_info;
pjsip_tls_state_info tls_info;
pjsip_transport_state tp_state;
pj_bzero(&tls_info, sizeof(tls_info));
pj_bzero(&state_info, sizeof(state_info));
tls_info.ssl_sock_info = &ssl_info;
state_info.ext_info = &tls_info;
if (ssl_info.verify_status && listener->tls_setting.verify_client)
{
tp_state = PJSIP_TP_STATE_DISCONNECTED;
state_info.status = PJSIP_TLS_ECERTVERIF;
} else {
tp_state = PJSIP_TP_STATE_CONNECTED;
state_info.status = PJ_SUCCESS;
}
(*state_cb)(&tls->base, tp_state, &state_info);
}
is_shutdown = tls->base.is_shutdown;
pjsip_transport_dec_ref(&tls->base);
if (is_shutdown)
return PJ_TRUE;
status = tls_start_read(tls);
if (status != PJ_SUCCESS) {
PJ_LOG(3,(tls->base.obj_name, "New transport cancelled"));
tls_init_shutdown(tls, status);
tls_destroy(&tls->base, status);
} else {
if (pjsip_cfg()->tls.keep_alive_interval) {
pj_time_val delay = {0};    
delay.sec = pjsip_cfg()->tls.keep_alive_interval;
pjsip_endpt_schedule_timer(listener->endpt, 
&tls->ka_timer, 
&delay);
tls->ka_timer.id = PJ_TRUE;
pj_gettimeofday(&tls->last_activity);
}
}
return PJ_TRUE;
}

DxfData::DxfData(double fn, double fs, double fa, 
const std::string &filename, const std::string &layername, 
double xorigin, double yorigin, double scale)
{
std::ifstream stream(filename.c_str());
if (!stream.good()) {
LOG(message_group::Warning,Location::NONE,"","Can't open DXF file '%1$s'.",filename);
return;
}
Grid2d<std::vector<int>> grid(GRID_COARSE);
std::vector<Line> lines;                       std::unordered_map<std::string, std::vector<Line>> blockdata; 
auto in_entities_section = false;
auto in_blocks_section = false;
std::string current_block;
#define ADD_LINE(_x1, _y1, _x2, _y2) do {\
double _p1x = _x1, _p1y = _y1, _p2x = _x2, _p2y = _y2;  \
if (!in_entities_section && !in_blocks_section)         \
break;                                                \
if (in_entities_section &&                              \
!(layername.empty() || layername == layer))         \
break;                                                \
grid.align(_p1x, _p1y);                                 \
grid.align(_p2x, _p2y);                                 \
grid.data(_p1x, _p1y).push_back(lines.size());          \
grid.data(_p2x, _p2y).push_back(lines.size());          \
if (in_entities_section)                                \
lines.emplace_back(                                   \
addPoint(_p1x, _p1y), addPoint(_p2x, _p2y));        \
if (in_blocks_section && !current_block.empty())        \
blockdata[current_block].emplace_back(              \
addPoint(_p1x, _p1y), addPoint(_p2x, _p2y));      \
} while (0)
std::string mode, layer, name, iddata;
int dimtype = 0;
double coords[7][2]; std::vector<double> xverts;
std::vector<double> yverts;
double radius = 0;
double arc_start_angle = 0, arc_stop_angle = 0;
double ellipse_start_angle = 0, ellipse_stop_angle = 0;
for (int i = 0; i < 7; ++i) {
for (int j = 0; j < 2; ++j) {
coords[i][j] = 0;
}
}
typedef std::unordered_map<std::string, int> EntityList;
EntityList unsupported_entities_list;
while (!stream.eof()){
std::string id_str, data;
std::getline(stream, id_str);
boost::trim(id_str);
std::getline(stream, data);
boost::trim(data);
int id;
try {
id = boost::lexical_cast<int>(id_str);
}
catch (const boost::bad_lexical_cast &blc) {
if (!stream.eof()) {
LOG(message_group::Warning,Location::NONE,"","Illegal ID '%1$s' in `%2$s'",id_str,filename);
}
break;
}
try {
if (id >= 10 && id <= 16) {
if (in_blocks_section) {
coords[id-10][0] = boost::lexical_cast<double>(data);
}
else if (id == 11 || id == 12 || id == 16) {
coords[id-10][0] = boost::lexical_cast<double>(data) * scale;
}
else {
coords[id-10][0] = (boost::lexical_cast<double>(data) - xorigin) * scale;
}
}
if (id >= 20 && id <= 26) {
if (in_blocks_section) {
coords[id-20][1] = boost::lexical_cast<double>(data);
}
else if (id == 21 || id == 22 || id == 26) {
coords[id-20][1] = boost::lexical_cast<double>(data) * scale;
}
else {
coords[id-20][1] = (boost::lexical_cast<double>(data) - yorigin) * scale;
}
}
switch (id) {
case 0:
if (mode == "SECTION") {
in_entities_section = iddata == "ENTITIES";
in_blocks_section = iddata == "BLOCKS";
}
else if (mode == "LINE") {
ADD_LINE(xverts.at(0), yverts.at(0), xverts.at(1), yverts.at(1));
}
else if (mode == "LWPOLYLINE") {
int numverts = std::max(xverts.size(), yverts.size());
for (int i=1; i<numverts; ++i) {
ADD_LINE(xverts.at(i-1), yverts.at(i-1), xverts.at(i%numverts), yverts.at(i%numverts));
}
if (dimtype & 0x01) { ADD_LINE(xverts.at(numverts-1), yverts.at(numverts-1), xverts.at(0), yverts.at(0));
}
}
else if (mode == "CIRCLE") {
int n = Calc::get_fragments_from_r(radius, fn, fs, fa);
Vector2d center(xverts.at(0), yverts.at(0));
for (int i = 0; i < n; ++i) {
double a1 = (360.0 * i) / n;
double a2 = (360.0 *(i + 1)) / n;
ADD_LINE(cos_degrees(a1)*radius + center[0], sin_degrees(a1)*radius + center[1],
cos_degrees(a2)*radius + center[0], sin_degrees(a2)*radius + center[1]);
}
}
else if (mode == "ARC") {
Vector2d center(xverts.at(0), yverts.at(0));
int n = Calc::get_fragments_from_r(radius, fn, fs, fa);
while (arc_start_angle > arc_stop_angle) {
arc_stop_angle += 360.0;
}
double arc_angle = arc_stop_angle - arc_start_angle;
n = static_cast<int>(ceil(n * arc_angle / 360));
for (int i = 0; i < n; ++i) {
double a1 = arc_start_angle + arc_angle * i / n;
double a2 = arc_start_angle + arc_angle * (i + 1) / n;
ADD_LINE(cos_degrees(a1)*radius + center[0], sin_degrees(a1)*radius + center[1],
cos_degrees(a2)*radius + center[0], sin_degrees(a2)*radius + center[1]);
}
}
else if (mode == "ELLIPSE") {
while (ellipse_start_angle > ellipse_stop_angle) ellipse_stop_angle += 2 * M_PI;
Vector2d center(xverts.at(0), yverts.at(0));
Vector2d ce(xverts.at(1), yverts.at(1));
double r_major = sqrt(ce[0]*ce[0] + ce[1]*ce[1]);
double rot_angle;
{
double dot = ce[0];
double cosval = dot / r_major;
if (cosval > 1.0) cosval = 1.0;
if (cosval < -1.0) cosval = -1.0;
rot_angle = acos(cosval);
if (ce[1] < 0.0) rot_angle = 2 * M_PI - rot_angle;
}
double r_minor = r_major * radius;
double sweep_angle = ellipse_stop_angle-ellipse_start_angle;
int n = Calc::get_fragments_from_r(r_major, fn, fs, fa);
n = static_cast<int>(ceil(n * sweep_angle / (2 * M_PI)));
Vector2d p1{0.0, 0.0};
for (int i=0; i<=n; ++i) {
double a = (ellipse_start_angle + sweep_angle*i/n);
Vector2d p2(cos(a)*r_major, sin(a)*r_minor);
Vector2d p2_rot(cos(rot_angle)*p2[0] - sin(rot_angle)*p2[1],
sin(rot_angle)*p2[0] + cos(rot_angle)*p2[1]);
p2_rot[0] += center[0];
p2_rot[1] += center[1];
if (i > 0) {
ADD_LINE(p1[0], p1[1], p2_rot[0], p2_rot[1]);
}
p1[0] = p2_rot[0];
p1[1] = p2_rot[1];
}
}
else if (mode == "INSERT") {
int n = blockdata[iddata].size();
for (int i = 0; i < n; ++i) {
double a = arc_start_angle;
double lx1 = this->points[blockdata[iddata][i].idx[0]][0] * ellipse_start_angle;
double ly1 = this->points[blockdata[iddata][i].idx[0]][1] * ellipse_stop_angle;
double lx2 = this->points[blockdata[iddata][i].idx[1]][0] * ellipse_start_angle;
double ly2 = this->points[blockdata[iddata][i].idx[1]][1] * ellipse_stop_angle;
double px1 = (cos_degrees(a)*lx1 - sin_degrees(a)*ly1) * scale + xverts.at(0);
double py1 = (sin_degrees(a)*lx1 + cos_degrees(a)*ly1) * scale + yverts.at(0);
double px2 = (cos_degrees(a)*lx2 - sin_degrees(a)*ly2) * scale + xverts.at(0);
double py2 = (sin_degrees(a)*lx2 + cos_degrees(a)*ly2) * scale + yverts.at(0);
ADD_LINE(px1, py1, px2, py2);
}
}
else if (mode == "DIMENSION" &&
(layername.empty() || layername == layer)) {
this->dims.push_back(Dim());
this->dims.back().type = dimtype;
for (int i = 0; i < 7; ++i) {
for (int j = 0; j < 2; ++j) {
this->dims.back().coords[i][j] = coords[i][j];
}
}
this->dims.back().angle = arc_start_angle;
this->dims.back().length = radius;
this->dims.back().name = name;
}
else if (mode == "BLOCK") {
current_block = iddata;
}
else if (mode == "ENDBLK") {
current_block.erase();
}
else if (mode == "ENDSEC") {
}
else if (in_blocks_section || (in_entities_section &&
(layername.empty() || layername == layer))) {
unsupported_entities_list[mode]++;
}
mode = data;
layer.erase();
name.erase();
iddata.erase();
dimtype = 0;
for (int i = 0; i < 7; ++i) {
for (int j = 0; j < 2; ++j) {
coords[i][j] = 0;
}
}
xverts.clear();
yverts.clear();
radius = arc_start_angle = arc_stop_angle = 0;
ellipse_start_angle = ellipse_stop_angle = 0;
if (mode == "INSERT") {
ellipse_start_angle = ellipse_stop_angle = 1.0; }
break;
case 1:
name = data;
break;
case 2:
iddata = data;
break;
case 8:
layer = data;
break;
case 10:
if (in_blocks_section) {
xverts.push_back((boost::lexical_cast<double>(data)));
}
else {
xverts.push_back((boost::lexical_cast<double>(data) - xorigin) * scale);
}
break;
case 11:
if (in_blocks_section) {
xverts.push_back((boost::lexical_cast<double>(data)));
}
else {
xverts.push_back((boost::lexical_cast<double>(data) - xorigin) * scale);
}
break;
case 20:
if (in_blocks_section) {
yverts.push_back((boost::lexical_cast<double>(data)));
}
else {
yverts.push_back((boost::lexical_cast<double>(data) - yorigin) * scale);
}
break;
case 21:
if (in_blocks_section) {
yverts.push_back((boost::lexical_cast<double>(data)));
}
else {
yverts.push_back((boost::lexical_cast<double>(data) - yorigin) * scale);
}
break;
case 40:
radius = boost::lexical_cast<double>(data);
if (!in_blocks_section) radius *= scale;
break;
case 41:
ellipse_start_angle = boost::lexical_cast<double>(data);
break;
case 50:
arc_start_angle = boost::lexical_cast<double>(data);
break;
case 42:
ellipse_stop_angle = boost::lexical_cast<double>(data);
break;
case 51: arc_stop_angle = boost::lexical_cast<double>(data);
break;
case 70:
dimtype = boost::lexical_cast<int>(data);
break;
}
}
catch (boost::bad_lexical_cast &blc) {
LOG(message_group::Warning,Location::NONE,"","Illegal value '%1$s'in `%2$s'",data,filename);
}
catch (const std::out_of_range& oor) {
LOG(message_group::Warning,Location::NONE,"","Not enough input values for %1$s. in '%2$s'",data,filename);
}
}
for (const auto &i : unsupported_entities_list) {
if (layername.empty()) {
LOG(message_group::Warning,Location::NONE,"",
"Unsupported DXF Entity '%1$s' (%2$x) in %3$s.",i.first,i.second,QuotedString(boostfs_uncomplete(filename, fs::current_path()).generic_string()));
} else {
LOG(message_group::Warning,Location::NONE,"",
"Unsupported DXF Entity '%1$s' (%2$x) in layer '%3$s' of %4$s",i.first,i.second,layername,boostfs_uncomplete(filename, fs::current_path()).generic_string());
}
}
typedef std::map<int, int> LineMap;
LineMap enabled_lines;
for (size_t i = 0; i < lines.size(); ++i) {
enabled_lines[i] = i;
}
while (enabled_lines.size() > 0) {
int current_line, current_point;
for (const auto &l : enabled_lines) {
int idx = l.second;
for (int j = 0; j < 2; ++j) {
auto lv = grid.data(this->points[lines[idx].idx[j]][0], this->points[lines[idx].idx[j]][1]);
for (size_t ki = 0; ki < lv.size(); ++ki) {
int k = lv.at(ki);
if (k == idx || lines[k].disabled) continue;
goto next_open_path_j;
}
current_line = idx;
current_point = j;
goto create_open_path;
next_open_path_j:;
}
}
break;
create_open_path:
this->paths.push_back(Path());
Path *this_path = &this->paths.back();
this_path->indices.push_back(lines[current_line].idx[current_point]);
while (1) {
this_path->indices.push_back(lines[current_line].idx[!current_point]);
const auto &ref_point = this->points[lines[current_line].idx[!current_point]];
lines[current_line].disabled = true;
enabled_lines.erase(current_line);
auto lv = grid.data(ref_point[0], ref_point[1]);
for (size_t ki = 0; ki < lv.size(); ++ki) {
int k = lv.at(ki);
if (lines[k].disabled) continue;
if (grid.eq(ref_point[0], ref_point[1], this->points[lines[k].idx[0]][0], this->points[lines[k].idx[0]][1])) {
current_line = k;
current_point = 0;
goto found_next_line_in_open_path;
}
if (grid.eq(ref_point[0], ref_point[1], this->points[lines[k].idx[1]][0], this->points[lines[k].idx[1]][1])) {
current_line = k;
current_point = 1;
goto found_next_line_in_open_path;
}
}
break;
found_next_line_in_open_path:;
}
}
while (enabled_lines.size() > 0) {
int current_line = enabled_lines.begin()->second;
int current_point = 0;
this->paths.push_back(Path());
auto& this_path = this->paths.back();
this_path.is_closed = true;
this_path.indices.push_back(lines[current_line].idx[current_point]);
while (1) {
this_path.indices.push_back(lines[current_line].idx[!current_point]);
const auto &ref_point = this->points[lines[current_line].idx[!current_point]];
lines[current_line].disabled = true;
enabled_lines.erase(current_line);
auto lv = grid.data(ref_point[0], ref_point[1]);
for (size_t ki = 0; ki < lv.size(); ++ki) {
int k = lv.at(ki);
if (lines[k].disabled) continue;
if (grid.eq(ref_point[0], ref_point[1], this->points[lines[k].idx[0]][0], this->points[lines[k].idx[0]][1])) {
current_line = k;
current_point = 0;
goto found_next_line_in_closed_path;
}
if (grid.eq(ref_point[0], ref_point[1], this->points[lines[k].idx[1]][0], this->points[lines[k].idx[1]][1])) {
current_line = k;
current_point = 1;
goto found_next_line_in_closed_path;
}
}
break;
found_next_line_in_closed_path:;
}
}
fixup_path_direction();
#if 0
printf("----- DXF Data -----\n");
for (int i = 0; i < this->paths.size(); ++i) {
printf("Path %d (%s):\n", i, this->paths[i].is_closed ? "closed" : "open");
for (int j = 0; j < this->paths[i].points.size(); ++j)
printf("  %f %f\n", (*this->paths[i].points[j])[0], (*this->paths[i].points[j])[1]);
}
printf("--------------------\n");
fflush(stdout);
#endif
}

R_API void r_anal_list_vtables(RAnal *anal, int rad) {
RVTableContext context;
r_anal_vtable_begin (anal, &context);
const char *noMethodName = "No Name found";
RVTableMethodInfo *curMethod;
RListIter *vtableIter;
RVTableInfo *table;
RList *vtables = r_anal_vtable_search (&context);
if (rad == 'j') {
PJ *pj = pj_new ();
if (!pj) {
return;
}
pj_a (pj);
r_list_foreach (vtables, vtableIter, table) {
pj_o (pj);
pj_kN (pj, "offset", table->saddr);
pj_ka (pj, "methods");
r_vector_foreach (&table->methods, curMethod) {
RAnalFunction *fcn = r_anal_get_fcn_in (anal, curMethod->addr, 0);
const char *const name = fcn ? fcn->name : NULL;
pj_o (pj);
pj_kN (pj, "offset", curMethod->addr);
pj_ks (pj, "name", r_str_get_fail (name, noMethodName));
pj_end (pj);
}
pj_end (pj);
pj_end (pj);
}
pj_end (pj);
r_cons_println (pj_string (pj));
pj_free (pj);
} else if (rad == '*') {
r_list_foreach (vtables, vtableIter, table) {
r_cons_printf ("f vtable.0x%08"PFMT64x" %"PFMT64d" @ 0x%08"PFMT64x"\n",
table->saddr,
r_anal_vtable_info_get_size (&context, table),
table->saddr);
r_vector_foreach (&table->methods, curMethod) {
r_cons_printf ("Cd %d @ 0x%08"PFMT64x"\n", context.word_size, table->saddr + curMethod->vtable_offset);
RAnalFunction *fcn = r_anal_get_fcn_in (anal, curMethod->addr, 0);
const char *const name = fcn ? fcn->name : NULL;
if (name) {
r_cons_printf ("f %s=0x%08"PFMT64x"\n", name, curMethod->addr);
} else {
r_cons_printf ("f method.virtual.0x%08"PFMT64x"=0x%08"PFMT64x"\n", curMethod->addr, curMethod->addr);
}
}
}
} else {
r_list_foreach (vtables, vtableIter, table) {
ut64 vtableStartAddress = table->saddr;
r_cons_printf ("\nVtable Found at 0x%08"PFMT64x"\n", vtableStartAddress);
r_vector_foreach (&table->methods, curMethod) {
RAnalFunction *fcn = r_anal_get_fcn_in (anal, curMethod->addr, 0);
const char *const name = fcn ? fcn->name : NULL;
r_cons_printf ("0x%08"PFMT64x" : %s\n", vtableStartAddress, r_str_get_fail (name, noMethodName));
vtableStartAddress += context.word_size;
}
r_cons_newline ();
}
}
r_list_free (vtables);
}

static void
_blackbox_vlogger(int32_t target,
struct qb_log_callsite *cs, struct timespec *timestamp, va_list ap)
{
size_t max_size;
size_t actual_size;
uint32_t fn_size;
char *chunk;
char *msg_len_pt;
uint32_t msg_len;
struct qb_log_target *t = qb_log_target_get(target);
if (t->instance == NULL) {
return;
}
fn_size = strlen(cs->function) + 1;
actual_size = 4 * sizeof(uint32_t) + sizeof(uint8_t) + fn_size + sizeof(struct timespec);
max_size = actual_size + t->max_line_length;
chunk = qb_rb_chunk_alloc(t->instance, max_size);
if (chunk == NULL) {
qb_util_perror(LOG_ERR, "Blackbox allocation error, aborting blackbox log %s", t->filename);
qb_rb_close(qb_rb_lastref_and_ret(
(struct qb_ringbuffer_s **) &t->instance
));
return;
}
memcpy(chunk, &cs->lineno, sizeof(uint32_t));
chunk += sizeof(uint32_t);
memcpy(chunk, &cs->tags, sizeof(uint32_t));
chunk += sizeof(uint32_t);
memcpy(chunk, &cs->priority, sizeof(uint8_t));
chunk += sizeof(uint8_t);
memcpy(chunk, &fn_size, sizeof(uint32_t));
chunk += sizeof(uint32_t);
memcpy(chunk, cs->function, fn_size);
chunk += fn_size;
memcpy(chunk, timestamp, sizeof(struct timespec));
chunk += sizeof(struct timespec);
msg_len_pt = chunk;
chunk += sizeof(uint32_t);
msg_len = qb_vsnprintf_serialize(chunk, max_size, cs->format, ap);
if (msg_len >= max_size) {
chunk = msg_len_pt + sizeof(uint32_t); 
msg_len = qb_vsnprintf_serialize(chunk, QB_LOG_MAX_LEN,
"Log message too long to be stored in the blackbox.  "\
"Maximum is QB_LOG_MAX_LEN" , ap);
}
actual_size += msg_len;
memcpy(msg_len_pt, &msg_len, sizeof(uint32_t));
(void)qb_rb_chunk_commit(t->instance, actual_size);
}

static int adjust_scalar_min_max_vals(struct bpf_verifier_env *env,
struct bpf_insn *insn,
struct bpf_reg_state *dst_reg,
struct bpf_reg_state src_reg)
{
struct bpf_reg_state *regs = cur_regs(env);
u8 opcode = BPF_OP(insn->code);
bool src_known, dst_known;
s64 smin_val, smax_val;
u64 umin_val, umax_val;
u64 insn_bitness = (BPF_CLASS(insn->code) == BPF_ALU64) ? 64 : 32;
smin_val = src_reg.smin_value;
smax_val = src_reg.smax_value;
umin_val = src_reg.umin_value;
umax_val = src_reg.umax_value;
src_known = tnum_is_const(src_reg.var_off);
dst_known = tnum_is_const(dst_reg->var_off);
switch (opcode) {
case BPF_ADD:
if (signed_add_overflows(dst_reg->smin_value, smin_val) ||
signed_add_overflows(dst_reg->smax_value, smax_val)) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value += smin_val;
dst_reg->smax_value += smax_val;
}
if (dst_reg->umin_value + umin_val < umin_val ||
dst_reg->umax_value + umax_val < umax_val) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value += umin_val;
dst_reg->umax_value += umax_val;
}
dst_reg->var_off = tnum_add(dst_reg->var_off, src_reg.var_off);
break;
case BPF_SUB:
if (signed_sub_overflows(dst_reg->smin_value, smax_val) ||
signed_sub_overflows(dst_reg->smax_value, smin_val)) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value -= smax_val;
dst_reg->smax_value -= smin_val;
}
if (dst_reg->umin_value < umax_val) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value -= umax_val;
dst_reg->umax_value -= umin_val;
}
dst_reg->var_off = tnum_sub(dst_reg->var_off, src_reg.var_off);
break;
case BPF_MUL:
dst_reg->var_off = tnum_mul(dst_reg->var_off, src_reg.var_off);
if (smin_val < 0 || dst_reg->smin_value < 0) {
__mark_reg_unbounded(dst_reg);
__update_reg_bounds(dst_reg);
break;
}
if (umax_val > U32_MAX || dst_reg->umax_value > U32_MAX) {
__mark_reg_unbounded(dst_reg);
__update_reg_bounds(dst_reg);
break;
}
dst_reg->umin_value *= umin_val;
dst_reg->umax_value *= umax_val;
if (dst_reg->umax_value > S64_MAX) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = dst_reg->umin_value;
dst_reg->smax_value = dst_reg->umax_value;
}
break;
case BPF_AND:
if (src_known && dst_known) {
__mark_reg_known(dst_reg, dst_reg->var_off.value &
src_reg.var_off.value);
break;
}
dst_reg->var_off = tnum_and(dst_reg->var_off, src_reg.var_off);
dst_reg->umin_value = dst_reg->var_off.value;
dst_reg->umax_value = min(dst_reg->umax_value, umax_val);
if (dst_reg->smin_value < 0 || smin_val < 0) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = dst_reg->umin_value;
dst_reg->smax_value = dst_reg->umax_value;
}
__update_reg_bounds(dst_reg);
break;
case BPF_OR:
if (src_known && dst_known) {
__mark_reg_known(dst_reg, dst_reg->var_off.value |
src_reg.var_off.value);
break;
}
dst_reg->var_off = tnum_or(dst_reg->var_off, src_reg.var_off);
dst_reg->umin_value = max(dst_reg->umin_value, umin_val);
dst_reg->umax_value = dst_reg->var_off.value |
dst_reg->var_off.mask;
if (dst_reg->smin_value < 0 || smin_val < 0) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = dst_reg->umin_value;
dst_reg->smax_value = dst_reg->umax_value;
}
__update_reg_bounds(dst_reg);
break;
case BPF_LSH:
if (umax_val >= insn_bitness) {
mark_reg_unknown(env, regs, insn->dst_reg);
break;
}
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
if (dst_reg->umax_value > 1ULL << (63 - umax_val)) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value <<= umin_val;
dst_reg->umax_value <<= umax_val;
}
if (src_known)
dst_reg->var_off = tnum_lshift(dst_reg->var_off, umin_val);
else
dst_reg->var_off = tnum_lshift(tnum_unknown, umin_val);
__update_reg_bounds(dst_reg);
break;
case BPF_RSH:
if (umax_val >= insn_bitness) {
mark_reg_unknown(env, regs, insn->dst_reg);
break;
}
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
if (src_known)
dst_reg->var_off = tnum_rshift(dst_reg->var_off,
umin_val);
else
dst_reg->var_off = tnum_rshift(tnum_unknown, umin_val);
dst_reg->umin_value >>= umax_val;
dst_reg->umax_value >>= umin_val;
__update_reg_bounds(dst_reg);
break;
default:
mark_reg_unknown(env, regs, insn->dst_reg);
break;
}
if (BPF_CLASS(insn->code) != BPF_ALU64) {
coerce_reg_to_size(dst_reg, 4);
coerce_reg_to_size(&src_reg, 4);
}
__reg_deduce_bounds(dst_reg);
__reg_bound_offset(dst_reg);
return 0;
}

int
sudo_passwd_verify(struct passwd *pw, char *pass, sudo_auth *auth, struct sudo_conv_callback *callback)
{
char sav, *epass;
char *pw_epasswd = auth->data;
size_t pw_len;
int matched = 0;
debug_decl(sudo_passwd_verify, SUDOERS_DEBUG_AUTH);
if (pass[0] == '\0')
debug_return_int(pw_epasswd[0] ? AUTH_FAILURE : AUTH_SUCCESS);
sav = pass[8];
pw_len = strlen(pw_epasswd);
if (pw_len == DESLEN || HAS_AGEINFO(pw_epasswd, pw_len))
pass[8] = '\0';
epass = (char *) crypt(pass, pw_epasswd);
pass[8] = sav;
if (epass != NULL) {
if (HAS_AGEINFO(pw_epasswd, pw_len) && strlen(epass) == DESLEN)
matched = !strncmp(pw_epasswd, epass, DESLEN);
else
matched = !strcmp(pw_epasswd, epass);
}
debug_return_int(matched ? AUTH_SUCCESS : AUTH_FAILURE);
}

static int _parse_dns_reply(uint8_t *buf, size_t len, void* addr_out, int family)
{
sock_dns_hdr_t *hdr = (sock_dns_hdr_t*) buf;
uint8_t *bufpos = buf + sizeof(*hdr);
for (unsigned n = 0; n < ntohs(hdr->qdcount); n++) {
bufpos += _skip_hostname(bufpos);
bufpos += 4;    
}
for (unsigned n = 0; n < ntohs(hdr->ancount); n++) {
bufpos += _skip_hostname(bufpos);
uint16_t _type = ntohs(_get_short(bufpos));
bufpos += 2;
uint16_t class = ntohs(_get_short(bufpos));
bufpos += 2;
bufpos += 4; 
unsigned addrlen = ntohs(_get_short(bufpos));
bufpos += 2;
if ((bufpos + addrlen) > (buf + len)) {
return -EBADMSG;
}
if ((class != DNS_CLASS_IN) ||
((_type == DNS_TYPE_A) && (family == AF_INET6)) ||
((_type == DNS_TYPE_AAAA) && (family == AF_INET)) ||
! ((_type == DNS_TYPE_A) || ((_type == DNS_TYPE_AAAA))
)) {
bufpos += addrlen;
continue;
}
memcpy(addr_out, bufpos, addrlen);
return addrlen;
}
return -1;
}

void CConnection::processSecurityTypesMsg()
{
vlog.debug("processing security types message");
int secType = secTypeInvalid;
std::list<rdr::U8> secTypes;
secTypes = security->GetEnabledSecTypes();
if (cp.isVersion(3,3)) {
secType = is->readU32();
if (secType == secTypeInvalid) {
throwConnFailedException();
} else if (secType == secTypeNone || secType == secTypeVncAuth) {
std::list<rdr::U8>::iterator i;
for (i = secTypes.begin(); i != secTypes.end(); i++)
if (*i == secType) {
secType = *i;
break;
}
if (i == secTypes.end())
secType = secTypeInvalid;
} else {
vlog.error("Unknown 3.3 security type %d", secType);
throw Exception("Unknown 3.3 security type");
}
} else {
int nServerSecTypes = is->readU8();
if (nServerSecTypes == 0)
throwConnFailedException();
std::list<rdr::U8>::iterator j;
for (int i = 0; i < nServerSecTypes; i++) {
rdr::U8 serverSecType = is->readU8();
vlog.debug("Server offers security type %s(%d)",
secTypeName(serverSecType), serverSecType);
if (secType == secTypeInvalid) {
for (j = secTypes.begin(); j != secTypes.end(); j++)
if (*j == serverSecType) {
secType = *j;
break;
}
}
}
if (secType != secTypeInvalid) {
os->writeU8(secType);
os->flush();
vlog.info("Choosing security type %s(%d)",secTypeName(secType),secType);
}
}
if (secType == secTypeInvalid) {
state_ = RFBSTATE_INVALID;
vlog.error("No matching security types");
throw Exception("No matching security types");
}
state_ = RFBSTATE_SECURITY;
csecurity = security->GetCSecurity(secType);
processSecurityMsg();
}

