static PyObject *Py_FindObjects(PyObject *obj, PyObject *args)
{
PyArrayObject *input = NULL;
PyObject *result = NULL, *tuple = NULL, *start = NULL, *end = NULL;
PyObject *slc = NULL;
int jj;
npy_intp max_label;
npy_intp ii, *regions = NULL;
if (!PyArg_ParseTuple(args, "O&n",
NI_ObjectToInputArray, &input, &max_label))
goto exit;
if (max_label < 0)
max_label = 0;
if (max_label > 0) {
if (PyArray_NDIM(input) > 0) {
regions = (npy_intp*)malloc(2 * max_label * PyArray_NDIM(input) *
sizeof(npy_intp));
} else {
regions = (npy_intp*)malloc(max_label * sizeof(npy_intp));
}
if (!regions) {
PyErr_NoMemory();
goto exit;
}
}
if (!NI_FindObjects(input, max_label, regions))
goto exit;
result = PyList_New(max_label);
if (!result) {
PyErr_NoMemory();
goto exit;
}
for(ii = 0; ii < max_label; ii++) {
npy_intp idx =
PyArray_NDIM(input) > 0 ? 2 * PyArray_NDIM(input) * ii : ii;
if (regions[idx] >= 0) {
PyObject *tuple = PyTuple_New(PyArray_NDIM(input));
if (!tuple) {
PyErr_NoMemory();
goto exit;
}
for(jj = 0; jj < PyArray_NDIM(input); jj++) {
start = PyLong_FromSsize_t(regions[idx + jj]);
end = PyLong_FromSsize_t(regions[idx + jj +
PyArray_NDIM(input)]);
if (!start || !end) {
PyErr_NoMemory();
goto exit;
}
slc = PySlice_New(start, end, NULL);
if (!slc) {
PyErr_NoMemory();
goto exit;
}
Py_XDECREF(start);
Py_XDECREF(end);
start = end = NULL;
PyTuple_SetItem(tuple, jj, slc);
slc = NULL;
}
PyList_SetItem(result, ii, tuple);
tuple = NULL;
} else {
Py_INCREF(Py_None);
PyList_SetItem(result, ii, Py_None);
}
}
Py_INCREF(result);
exit:
Py_XDECREF(input);
Py_XDECREF(result);
Py_XDECREF(tuple);
Py_XDECREF(start);
Py_XDECREF(end);
Py_XDECREF(slc);
free(regions);
if (PyErr_Occurred()) {
Py_XDECREF(result);
return NULL;
} else {
return result;
}
}

uint16_t
get_l2protocol(const u_char *pktdata, const uint32_t datalen, const int datalink)
{
uint16_t eth_hdr_offset = 0;
if (!pktdata || !datalen) {
errx(-1, "invalid l2 parameters: pktdata=0x%p len=%d",
pktdata, datalen);
return 0;
}
switch (datalink) {
case DLT_RAW:
if ((pktdata[0] >> 4) == 4)
return ETHERTYPE_IP;
else if ((pktdata[0] >> 4) == 6)
return ETHERTYPE_IP6;
break;
case DLT_JUNIPER_ETHER:
if (datalen < 5)
return 0;
if (memcmp(pktdata, "MGC", 3))
warnx("No Magic Number found: %s (0x%x)",
pcap_datalink_val_to_description(datalink), datalink);
if ((pktdata[3] & 0x80) == 0x80) {
eth_hdr_offset = ntohs(*((uint16_t*)&pktdata[4]));
eth_hdr_offset += 6;
} else {
eth_hdr_offset = 4; 
}
case DLT_EN10MB:
if ((size_t)datalen >= (sizeof(eth_hdr_t) + eth_hdr_offset)) {
eth_hdr_t *eth_hdr = (eth_hdr_t *)(pktdata + eth_hdr_offset);
uint16_t ether_type = ntohs(eth_hdr->ether_type);
uint16_t l2_len = sizeof(*eth_hdr) + eth_hdr_offset;
while (ether_type == ETHERTYPE_VLAN) {
if (datalen < l2_len + sizeof(vlan_hdr_t))
return 0;
vlan_hdr_t *vlan_hdr = (vlan_hdr_t*)(pktdata + l2_len);
ether_type = ntohs(vlan_hdr->vlan_tpid);
l2_len += sizeof(vlan_hdr_t);
}
return ether_type; 
}
break;
case DLT_PPP_SERIAL:
if ((size_t)datalen >= sizeof(struct tcpr_pppserial_hdr)) {
struct tcpr_pppserial_hdr *ppp = (struct tcpr_pppserial_hdr *)pktdata;
if (ntohs(ppp->protocol) == 0x0021)
return htons(ETHERTYPE_IP);
else
return ppp->protocol;
}
break;
case DLT_C_HDLC:
if ((size_t)datalen >= sizeof(hdlc_hdr_t)) {
hdlc_hdr_t *hdlc_hdr = (hdlc_hdr_t *)pktdata;
return hdlc_hdr->protocol;
}
break;
case DLT_LINUX_SLL:
if ((size_t)datalen >= sizeof(sll_hdr_t)) {
sll_hdr_t *sll_hdr = (sll_hdr_t *)pktdata;
return sll_hdr->sll_protocol;
}
break;
default:
errx(-1, "Unable to process unsupported DLT type: %s (0x%x)", 
pcap_datalink_val_to_description(datalink), datalink);
}
return 0;
}

