static void
gaussian_blur_surface (cairo_surface_t *in,
cairo_surface_t *out,
gdouble sx,
gdouble sy)
{
gboolean use_box_blur;
gint width, height;
cairo_format_t in_format, out_format;
gint in_stride;
gint out_stride;
guchar *in_data, *out_data;
gint bpp;
gboolean out_has_data;
cairo_surface_flush (in);
width = cairo_image_surface_get_width (in);
height = cairo_image_surface_get_height (in);
g_assert (width == cairo_image_surface_get_width (out)
&& height == cairo_image_surface_get_height (out));
in_format = cairo_image_surface_get_format (in);
out_format = cairo_image_surface_get_format (out);
g_assert (in_format == out_format);
g_assert (in_format == CAIRO_FORMAT_ARGB32
|| in_format == CAIRO_FORMAT_A8);
if (in_format == CAIRO_FORMAT_ARGB32)
bpp = 4;
else if (in_format == CAIRO_FORMAT_A8)
bpp = 1;
else {
g_assert_not_reached ();
return;
}
in_stride = cairo_image_surface_get_stride (in);
out_stride = cairo_image_surface_get_stride (out);
in_data = cairo_image_surface_get_data (in);
out_data = cairo_image_surface_get_data (out);
if (sx < 0.0)
sx = 0.0;
if (sy < 0.0)
sy = 0.0;
if (sx < 10.0 && sy < 10.0)
use_box_blur = FALSE;
else
use_box_blur = TRUE;
if ((sx == 0.0 && sy == 0.0)
|| sx > 1000 || sy > 1000) {
cairo_t *cr;
cr = cairo_create (out);
cairo_set_source_surface (cr, in, 0, 0);
cairo_paint (cr);
cairo_destroy (cr);
return;
}
if (sx != 0.0) {
gint box_width;
gdouble *gaussian_matrix;
gint gaussian_matrix_len;
int y;
guchar *row_buffer = NULL;
guchar *row1, *row2;
if (use_box_blur) {
box_width = compute_box_blur_width (sx);
row_buffer = g_new0 (guchar, width * bpp * 2);
row1 = row_buffer;
row2 = row_buffer + width * bpp;
} else
make_gaussian_convolution_matrix (sx, &gaussian_matrix, &gaussian_matrix_len);
for (y = 0; y < height; y++) {
guchar *in_row, *out_row;
in_row = in_data + in_stride * y;
out_row = out_data + out_stride * y;
if (use_box_blur) {
if (box_width % 2 != 0) {
box_blur_line (box_width, 0, in_row, row1,    width, bpp);
box_blur_line (box_width, 0, row1,   row2,    width, bpp);
box_blur_line (box_width, 0, row2,   out_row, width, bpp);
} else {
box_blur_line (box_width,     -1, in_row, row1,    width, bpp);
box_blur_line (box_width,      1, row1,   row2,    width, bpp);
box_blur_line (box_width + 1,  0, row2,   out_row, width, bpp);
}
} else
gaussian_blur_line (gaussian_matrix, gaussian_matrix_len, in_row, out_row, width, bpp);
}
if (!use_box_blur)
g_free (gaussian_matrix);
g_free (row_buffer);
out_has_data = TRUE;
} else
out_has_data = FALSE;
if (sy != 0.0) {
gint box_height;
gdouble *gaussian_matrix = NULL;
gint gaussian_matrix_len;
guchar *col_buffer;
guchar *col1, *col2;
int x;
col_buffer = g_new0 (guchar, height * bpp * 2);
col1 = col_buffer;
col2 = col_buffer + height * bpp;
if (use_box_blur) {
box_height = compute_box_blur_width (sy);
} else
make_gaussian_convolution_matrix (sy, &gaussian_matrix, &gaussian_matrix_len);
for (x = 0; x < width; x++) {
if (out_has_data)
get_column (col1, out_data, out_stride, bpp, height, x);
else
get_column (col1, in_data, in_stride, bpp, height, x);
if (use_box_blur) {
if (box_height % 2 != 0) {
box_blur_line (box_height, 0, col1, col2, height, bpp);
box_blur_line (box_height, 0, col2, col1, height, bpp);
box_blur_line (box_height, 0, col1, col2, height, bpp);
} else {
box_blur_line (box_height,     -1, col1, col2, height, bpp);
box_blur_line (box_height,      1, col2, col1, height, bpp);
box_blur_line (box_height + 1,  0, col1, col2, height, bpp);
}
} else
gaussian_blur_line (gaussian_matrix, gaussian_matrix_len, col1, col2, height, bpp);
put_column (col2, out_data, out_stride, bpp, height, x);
}
g_free (gaussian_matrix);
g_free (col_buffer);
}
cairo_surface_mark_dirty (out);
}

static void Fp_toString(js_State *J)
{
js_Object *self = js_toobject(J, 0);
char *s;
int i, n;
if (!js_iscallable(J, 0))
js_typeerror(J, "not a function");
if (self->type == JS_CFUNCTION || self->type == JS_CSCRIPT) {
js_Function *F = self->u.f.function;
n = strlen("function () { ... }");
n += strlen(F->name);
for (i = 0; i < F->numparams; ++i)
n += strlen(F->vartab[i]) + 1;
s = js_malloc(J, n);
strcpy(s, "function ");
strcat(s, F->name);
strcat(s, "(");
for (i = 0; i < F->numparams; ++i) {
if (i > 0) strcat(s, ",");
strcat(s, F->vartab[i]);
}
strcat(s, ") { ... }");
if (js_try(J)) {
js_free(J, s);
js_throw(J);
}
js_pushstring(J, s);
js_free(J, s);
js_endtry(J);
} else {
js_pushliteral(J, "function () { ... }");
}
}

int
main (int argc, char *argv[])
{
int error;
int i = 1;
Dwg_Data dwg;
char *filename_in;
const char *version = NULL;
char *filename_out = NULL;
Dwg_Version_Type dwg_version;
BITCODE_BL num_objects;
int c;
#ifdef HAVE_GETOPT_LONG
int option_index = 0;
static struct option long_options[]
= { { "verbose", 1, &opts, 1 },           { "file", 1, 0, 'o' },      { "as", 1, 0, 'a' }, { "help", 0, 0, 0 },
{ "version", 0, 0, 0 },     { NULL, 0, NULL, 0 } };
#endif
if (argc < 2)
return usage ();
while
#ifdef HAVE_GETOPT_LONG
((c = getopt_long (argc, argv, ":a:v::o:h", long_options, &option_index))
!= -1)
#else
((c = getopt (argc, argv, ":a:v::o:hi")) != -1)
#endif
{
if (c == -1)
break;
switch (c)
{
case ':':           if (optarg && !strcmp (optarg, "v"))
{
opts = 1;
break;
}
fprintf (stderr, "%s: option '-%c' requires an argument\n", argv[0],
optopt);
break;
#ifdef HAVE_GETOPT_LONG
case 0:
if (!strcmp (long_options[option_index].name, "verbose"))
{
if (opts < 0 || opts > 9)
return usage ();
#  if defined(USE_TRACING) && defined(HAVE_SETENV)
{
char v[2];
*v = opts + '0';
*(v + 1) = 0;
setenv ("LIBREDWG_TRACE", v, 1);
}
#  endif
break;
}
if (!strcmp (long_options[option_index].name, "version"))
return opt_version ();
if (!strcmp (long_options[option_index].name, "help"))
return help ();
break;
#else
case 'i':
return opt_version ();
#endif
case 'o':
filename_out = optarg;
break;
case 'a':
dwg_version = dwg_version_as (optarg);
if (dwg_version == R_INVALID)
{
fprintf (stderr, "Invalid version '%s'\n", argv[1]);
return usage ();
}
version = optarg;
break;
case 'v':           i = (optind > 0 && optind < argc) ? optind - 1 : 1;
if (!memcmp (argv[i], "-v", 2))
{
opts = argv[i][2] ? argv[i][2] - '0' : 1;
}
if (opts < 0 || opts > 9)
return usage ();
#if defined(USE_TRACING) && defined(HAVE_SETENV)
{
char v[2];
*v = opts + '0';
*(v + 1) = 0;
setenv ("LIBREDWG_TRACE", v, 1);
}
#endif
break;
case 'h':
return help ();
case '?':
fprintf (stderr, "%s: invalid option '-%c' ignored\n", argv[0],
optopt);
break;
default:
return usage ();
}
}
i = optind;
memset (&dwg, 0, sizeof (Dwg_Data));
dwg.opts = opts;
filename_in = argv[i];
if (!filename_in)
{
puts ("No input file specified");
return 1;
}
if (!filename_out)
{
if (argc > i + 1)
filename_out = argv[i + 1];
else
filename_out = suffix (filename_in, "-rewrite.dwg");
}
if (!filename_out || !strcmp (filename_in, filename_out))
{
if (filename_out != argv[i + 1])
free (filename_out);
return usage ();
}
printf ("Reading DWG file %s\n", filename_in);
error = dwg_read_file (filename_in, &dwg);
if (error >= DWG_ERR_CRITICAL)
fprintf (stderr, "READ ERROR 0x%x\n", error);
num_objects = dwg.num_objects;
if (!num_objects)
{
printf ("Read 0 objects\n");
if (error >= DWG_ERR_CRITICAL)
{
if (filename_out != argv[i + 1])
free (filename_out);
return error;
}
}
if (opts)
printf ("\n");
printf ("Writing DWG file %s", filename_out);
#ifndef USE_WRITE
error = 1;
#else
if (version)
{       printf (" as %s\n", version);
if (dwg.header.from_version != dwg.header.version)
dwg.header.from_version = dwg.header.version;
dwg.header.version = dwg_version;
}
else if (dwg.header.version < R_13 || dwg.header.version > R_2000)
{
printf (" as r2000\n");
dwg.header.version = R_2000;
}
else
{
printf ("\n");
}
{
struct stat attrib;
if (!stat (filename_out, &attrib))       {
if (S_ISREG (attrib.st_mode) &&                    (access (filename_out, W_OK) == 0) #ifndef _WIN32
&& !S_ISLNK (attrib.st_mode)
#endif
)
unlink (filename_out);
else
{
fprintf (stderr, "Not writable file or symlink: %s\n",
filename_out);
error |= DWG_ERR_IOERROR;
}
}
}
error = dwg_write_file (filename_out, &dwg);
#endif
if (error >= DWG_ERR_CRITICAL)
{
printf ("WRITE ERROR 0x%x\n", error);
if (filename_out != argv[i + 1])
free (filename_out);
return error;
}

int enc_untrusted_inet_pton(int af, const char *src, void *dst) {
if (!src || !dst) {
return 0;
}
MessageWriter input;
input.Push<int>(TokLinuxAfFamily(af));
input.PushByReference(Extent{
src, std::min(strlen(src) + 1, static_cast<size_t>(INET6_ADDRSTRLEN))});
MessageReader output;
const auto status = NonSystemCallDispatcher(
::asylo::host_call::kInetPtonHandler, &input, &output);
CheckStatusAndParamCount(status, output, "enc_untrusted_inet_pton", 3);
int result = output.next<int>();
int klinux_errno = output.next<int>();
if (result == -1) {
errno = FromkLinuxErrorNumber(klinux_errno);
return -1;
}
auto klinux_addr_buffer = output.next();
size_t max_size = 0;
if (af == AF_INET) {
max_size = sizeof(struct in_addr);
} else if (af == AF_INET6) {
max_size = sizeof(struct in6_addr);
}
memcpy(dst, klinux_addr_buffer.data(),
std::min(klinux_addr_buffer.size(), max_size));
return result;
}

static void vgacon_scrolldelta(struct vc_data *c, int lines)
{
int start, end, count, soff;
if (!lines) {
vgacon_restore_screen(c);
return;
}
if (!vgacon_scrollback_cur->data)
return;
if (!vgacon_scrollback_cur->save) {
vgacon_cursor(c, CM_ERASE);
vgacon_save_screen(c);
c->vc_origin = (unsigned long)c->vc_screenbuf;
vgacon_scrollback_cur->save = 1;
}
vgacon_scrollback_cur->restore = 0;
start = vgacon_scrollback_cur->cur + lines;
end = start + abs(lines);
if (start < 0)
start = 0;
if (start > vgacon_scrollback_cur->cnt)
start = vgacon_scrollback_cur->cnt;
if (end < 0)
end = 0;
if (end > vgacon_scrollback_cur->cnt)
end = vgacon_scrollback_cur->cnt;
vgacon_scrollback_cur->cur = start;
count = end - start;
soff = vgacon_scrollback_cur->tail -
((vgacon_scrollback_cur->cnt - end) * c->vc_size_row);
soff -= count * c->vc_size_row;
if (soff < 0)
soff += vgacon_scrollback_cur->size;
count = vgacon_scrollback_cur->cnt - start;
if (count > c->vc_rows)
count = c->vc_rows;
if (count) {
int copysize;
int diff = c->vc_rows - count;
void *d = (void *) c->vc_visible_origin;
void *s = (void *) c->vc_screenbuf;
count *= c->vc_size_row;
copysize = min(count, vgacon_scrollback_cur->size - soff);
scr_memcpyw(d, vgacon_scrollback_cur->data + soff, copysize);
d += copysize;
count -= copysize;
if (count) {
scr_memcpyw(d, vgacon_scrollback_cur->data, count);
d += count;
}
if (diff)
scr_memcpyw(d, s, diff * c->vc_size_row);
} else
vgacon_cursor(c, CM_MOVE);
}

void
wc_push_to_iso2022(Str os, wc_wchar_t cc, wc_status *st)
{
wc_uchar g = 0;
wc_bool is_wide = WC_FALSE, retry = WC_FALSE;
wc_wchar_t cc2;
while (1) {
switch (WC_CCS_TYPE(cc.ccs)) {
case WC_CCS_A_CS94:
if (cc.ccs == WC_CCS_US_ASCII)
cc.ccs = st->g0_ccs;
g = cs94_gmap[WC_CCS_INDEX(cc.ccs) - WC_F_ISO_BASE];
break;
case WC_CCS_A_CS94W:
is_wide = 1;
switch (cc.ccs) {
#ifdef USE_UNICODE
case WC_CCS_JIS_X_0212:
if (!WcOption.use_jisx0212 && WcOption.use_jisx0213 &&
WcOption.ucs_conv) {
cc2 = wc_jisx0212_to_jisx0213(cc);
if (cc2.ccs == WC_CCS_JIS_X_0213_1 ||
cc2.ccs == WC_CCS_JIS_X_0213_2) {
cc = cc2;
continue;
}
}
break;
case WC_CCS_JIS_X_0213_1:
case WC_CCS_JIS_X_0213_2:
if (!WcOption.use_jisx0213 && WcOption.use_jisx0212 &&
WcOption.ucs_conv) {
cc2 = wc_jisx0213_to_jisx0212(cc);
if (cc2.ccs == WC_CCS_JIS_X_0212) {
cc = cc2;
continue;
}
}
break;
#endif
}
g = cs94w_gmap[WC_CCS_INDEX(cc.ccs) - WC_F_ISO_BASE];
break;
case WC_CCS_A_CS96:
g = cs96_gmap[WC_CCS_INDEX(cc.ccs) - WC_F_ISO_BASE];
break;
case WC_CCS_A_CS96W:
is_wide = 1;
g = cs96w_gmap[WC_CCS_INDEX(cc.ccs) - WC_F_ISO_BASE];
break;
case WC_CCS_A_CS942:
g = cs942_gmap[WC_CCS_INDEX(cc.ccs) - WC_F_ISO_BASE];
break;
case WC_CCS_A_UNKNOWN_W:
if (WcOption.no_replace)
return;
is_wide = 1;
cc.ccs = WC_CCS_US_ASCII;
g = cs94_gmap[WC_CCS_INDEX(cc.ccs) - WC_F_ISO_BASE];
cc.code = ((wc_uint32)WC_REPLACE_W[0] << 8) | WC_REPLACE_W[1];
break;
case WC_CCS_A_UNKNOWN:
if (WcOption.no_replace)
return;
cc.ccs = WC_CCS_US_ASCII;
g = cs94_gmap[WC_CCS_INDEX(cc.ccs) - WC_F_ISO_BASE];
cc.code = (wc_uint32)WC_REPLACE[0];
break;
default:
if ((cc.ccs == WC_CCS_JOHAB || cc.ccs == WC_CCS_JOHAB_1 ||
cc.ccs == WC_CCS_JOHAB_2 || cc.ccs == WC_CCS_JOHAB_3) &&
cs94w_gmap[WC_F_KS_X_1001 - WC_F_ISO_BASE]) {
wc_wchar_t cc2 = wc_johab_to_ksx1001(cc);
if (cc2.ccs == WC_CCS_KS_X_1001) {
cc = cc2;
continue;
}
}
#ifdef USE_UNICODE
if (WcOption.ucs_conv)
cc = wc_any_to_iso2022(cc, st);
else
#endif
cc.ccs = WC_CCS_IS_WIDE(cc.ccs) ? WC_CCS_UNKNOWN_W : WC_CCS_UNKNOWN;
continue;
}
if (! g) {
#ifdef USE_UNICODE
if (WcOption.ucs_conv && ! retry)
cc = wc_any_to_any_ces(cc, st);
else
#endif
cc.ccs = WC_CCS_IS_WIDE(cc.ccs) ? WC_CCS_UNKNOWN_W : WC_CCS_UNKNOWN;
retry = WC_TRUE;
continue;
}
wc_push_iso2022_esc(os, cc.ccs, g, 1, st);
if (is_wide)
Strcat_char(os, (char)((cc.code >> 8) & 0x7f));
Strcat_char(os, (char)(cc.code & 0x7f));
return;
}
}

