void bm_circle(Bitmap *b, int x0, int y0, int r) {
int x = -r;
int y = 0;
int err = 2 - 2 * r;
do {
int xp, yp;
xp = x0 - x; yp = y0 + y;
if(xp >= b->clip.x0 && xp < b->clip.x1 && yp >= b->clip.y0 && yp < b->clip.y1)
BM_SET(b, xp, yp, b->color);
xp = x0 - y; yp = y0 - x;
if(xp >= b->clip.x0 && xp < b->clip.x1 && yp >= b->clip.y0 && yp < b->clip.y1)
BM_SET(b, xp, yp, b->color);
xp = x0 + x; yp = y0 - y;
if(xp >= b->clip.x0 && xp < b->clip.x1 && yp >= b->clip.y0 && yp < b->clip.y1)
BM_SET(b, xp, yp, b->color);
xp = x0 + y; yp = y0 + x;
if(xp >= b->clip.x0 && xp < b->clip.x1 && yp >= b->clip.y0 && yp < b->clip.y1)
BM_SET(b, xp, yp, b->color);
r = err;
if(r > x) {
x++;
err += x*2 + 1;
}
if(r <= y) {
y++;
err += y * 2 + 1;
}
} while(x < 0);
}

