return CL_EFORMAT;
}

static pj_status_t ipp_alloc_codec( pjmedia_codec_factory *factory, 
const pjmedia_codec_info *id,
pjmedia_codec **p_codec)
{
ipp_private_t *codec_data;
pjmedia_codec *codec;
int idx;
pj_pool_t *pool;
unsigned i;
PJ_ASSERT_RETURN(factory && id && p_codec, PJ_EINVAL);
PJ_ASSERT_RETURN(factory == &ipp_factory.base, PJ_EINVAL);
pj_mutex_lock(ipp_factory.mutex);
idx = -1;
for (i = 0; i < PJ_ARRAY_SIZE(ipp_codec); ++i) {
pj_str_t name = pj_str((char*)ipp_codec[i].name);
if ((pj_stricmp(&id->encoding_name, &name) == 0) &&
(id->clock_rate == (unsigned)ipp_codec[i].clock_rate) &&
(id->channel_cnt == (unsigned)ipp_codec[i].channel_count) &&
(ipp_codec[i].enabled))
{
idx = i;
break;
}
}
if (idx == -1) {
*p_codec = NULL;
return PJMEDIA_CODEC_EFAILED;
}
pool = pjmedia_endpt_create_pool(ipp_factory.endpt, "IPPcodec", 512, 512);
codec = PJ_POOL_ZALLOC_T(pool, pjmedia_codec);
PJ_ASSERT_RETURN(codec != NULL, PJ_ENOMEM);
codec->op = &ipp_op;
codec->factory = factory;
codec->codec_data = PJ_POOL_ZALLOC_T(pool, ipp_private_t);
codec_data = (ipp_private_t*) codec->codec_data;
if (!ipp_codec[idx].has_native_plc) {
pj_status_t status;
status = pjmedia_plc_create(pool, ipp_codec[idx].clock_rate, 
ipp_codec[idx].samples_per_frame, 0,
&codec_data->plc);
if (status != PJ_SUCCESS) {
pj_pool_release(pool);
pj_mutex_unlock(ipp_factory.mutex);
return status;
}
}
if (!ipp_codec[idx].has_native_vad) {
pj_status_t status;
status = pjmedia_silence_det_create(pool,
ipp_codec[idx].clock_rate,
ipp_codec[idx].samples_per_frame,
&codec_data->vad);
if (status != PJ_SUCCESS) {
pj_pool_release(pool);
pj_mutex_unlock(ipp_factory.mutex);
return status;
}
}
codec_data->pool = pool;
codec_data->codec_idx = idx;
pj_mutex_unlock(ipp_factory.mutex);
*p_codec = codec;
return PJ_SUCCESS;
}

static Jsi_RC ObjListifyCallback(Jsi_Tree *tree, Jsi_TreeEntry *hPtr, void *data)
{
Jsi_Interp *interp = tree->opts.interp;
Jsi_Obj *obj = (Jsi_Obj*)data;
int n;
if (!hPtr->f.bits.dontenum) {
char *ep = NULL, *cp = (char*)Jsi_TreeKeyGet(hPtr);
if (!cp || !isdigit(*cp))
return JSI_OK;
n = (int)strtol(cp, &ep, 0);
if (n<0 || n >= interp->maxArrayList)
return JSI_OK;
hPtr->f.bits.isarrlist = 1;
if (Jsi_ObjArraySizer(interp, obj, n) <= 0) 
return Jsi_LogError("too long");
obj->arr[n] = (Jsi_Value*)Jsi_TreeValueGet(hPtr);
}
return JSI_OK;
}

int
sqlo_expand_jts (sqlo_t *so, ST **ptree, ST *select_stmt, int was_top)
{
int res = 0;
ST *tree = *ptree;
if (THR_IS_STACK_OVERFLOW (THREAD_CURRENT_THREAD, &tree, 8000))
sqlc_error (so->so_sc->sc_cc, ".....", "Stack Overflow");
if (DK_MEM_RESERVE)
sqlc_error (so->so_sc->sc_cc, ".....", "Out of memory");
if (ST_P (tree, SELECT_STMT))
{
res += sqlo_expand_jts (so, &tree->_.select_stmt.table_exp, tree, select_stmt ? 0 : 1);
res += sqlo_expand_jts (so, (ST **) &tree->_.select_stmt.selection, tree, select_stmt ? 0 : 1);
}
else if (ST_P (tree, TABLE_REF) &&
ST_P (tree->_.table_ref.table, JOINED_TABLE) &&
tree->_.table_ref.table->_.join.type == OJ_FULL &&
!tree->_.table_ref.range)
{ 
char buffer[20];
ST *left;
caddr_t jtm_prefix;
snprintf (buffer, sizeof (buffer), "fjtc%d", so->so_name_ctr++);
jtm_prefix = tree->_.table_ref.range = t_box_string (buffer);
res += sqlo_expand_jts (so, &tree->_.table_ref.table, select_stmt, was_top);
left = sqlp_union_tree_select (tree->_.table_ref.table->_.select_stmt.table_exp->_.table_exp.from[0]->_.table_ref.table);
sqlo_jt_replace_col_refs (&select_stmt, jtm_prefix,
(ST **)left->_.select_stmt.selection, tree, 0);
if (was_top)
{
int inx;
ST **sel = (ST **)left->_.select_stmt.selection;
DO_BOX (ST *, sel_exp, inx, select_stmt->_.select_stmt.selection)
{
if (ST_COLUMN (sel_exp, COL_DOTTED) &&
!CASEMODESTRCMP (sel_exp->_.col_ref.prefix, jtm_prefix))
{
int col_inx = atoi (sel_exp->_.col_ref.name + 5);
if (!col_inx || col_inx > BOX_ELEMENTS_INT (sel))
GPF_T1 ("an unknown column detected in jt");
((ST **)select_stmt->_.select_stmt.selection)[inx] =
t_listst (5, BOP_AS, sel_exp, NULL,
sel[col_inx - 1]->_.as_exp.left->_.col_ref.name, NULL);
}
}
END_DO_BOX;
}
}
else if (ST_P (tree, JOINED_TABLE) && select_stmt)
{
res += sqlo_expand_jts (so, &tree->_.join.left, select_stmt, was_top);
res += sqlo_expand_jts (so, &tree->_.join.right, select_stmt, was_top);
if (0 == res && (J_INNER == tree->_.join.type || J_CROSS == tree->_.join.type))
return res;
if (OJ_LEFT != tree->_.join.type)
res += sqlo_jt_dt_wrap (so, &tree->_.join.left, select_stmt, was_top, 1);
if (OJ_RIGHT != tree->_.join.type)
res += sqlo_jt_dt_wrap (so, &tree->_.join.right, select_stmt, was_top, 1);
if (tree->_.join.type == OJ_FULL)
{
ST *left_oj_tree = (ST *) t_box_copy_tree ((caddr_t) tree);
ST *right_oj_tree = (ST *) t_box_copy_tree ((caddr_t) tree);
left_oj_tree->_.join.type = OJ_LEFT;
right_oj_tree->_.join.type = OJ_RIGHT;
res += sqlo_jt_dt_wrap (so, &left_oj_tree, select_stmt, 1, 0);
res += sqlo_jt_dt_wrap (so, &right_oj_tree, select_stmt, 1, 0);
*ptree = t_listst (5, UNION_ST, left_oj_tree->_.table_ref.table,
right_oj_tree->_.table_ref.table, NULL, 0);
*ptree = sqlc_union_dt_wrap (*ptree);
res ++;
}
}
else if (ST_P (tree, CALL_STMT))
{
int inx;
DO_BOX (ST *, par, inx, tree->_.call.params)
{
res += sqlo_expand_jts (so, &par, select_stmt, was_top);
}
END_DO_BOX;
}
else if (ST_P (tree, COALESCE_EXP) ||
ST_P (tree, SIMPLE_CASE) ||
ST_P (tree, SEARCHED_CASE) ||
ST_P (tree, COMMA_EXP))
{
int inx;
_DO_BOX (inx, tree->_.comma_exp.exps)
{
res += sqlo_expand_jts (so, &(tree->_.comma_exp.exps[inx]), select_stmt, was_top);
}
END_DO_BOX;
}
else if (ARRAYP (tree))
{
int inx;
for (inx = 0; inx < BOX_ELEMENTS_INT (tree); inx++)
res += sqlo_expand_jts (so, &(((ST **)tree)[inx]), select_stmt, was_top);
}
return res;
}

void SoftMP3::onQueueFilled(OMX_U32 ) {
if (mSignalledError || mOutputPortSettingsChange != NONE) {
return;
}
List<BufferInfo *> &inQueue = getPortQueue(0);
List<BufferInfo *> &outQueue = getPortQueue(1);
while ((!inQueue.empty() || (mSawInputEos && !mSignalledOutputEos)) && !outQueue.empty()) {
BufferInfo *inInfo = NULL;
OMX_BUFFERHEADERTYPE *inHeader = NULL;
if (!inQueue.empty()) {
inInfo = *inQueue.begin();
inHeader = inInfo->mHeader;
}
BufferInfo *outInfo = *outQueue.begin();
OMX_BUFFERHEADERTYPE *outHeader = outInfo->mHeader;
outHeader->nFlags = 0;
if (inHeader) {
if (inHeader->nOffset == 0 && inHeader->nFilledLen) {
mAnchorTimeUs = inHeader->nTimeStamp;
mNumFramesOutput = 0;
}
if (inHeader->nFlags & OMX_BUFFERFLAG_EOS) {
mSawInputEos = true;
}
mConfig->pInputBuffer =
inHeader->pBuffer + inHeader->nOffset;
mConfig->inputBufferCurrentLength = inHeader->nFilledLen;
} else {
mConfig->pInputBuffer = NULL;
mConfig->inputBufferCurrentLength = 0;
}
mConfig->inputBufferMaxLength = 0;
mConfig->inputBufferUsedLength = 0;
mConfig->outputFrameSize = kOutputBufferSize / sizeof(int16_t);
if ((int32)outHeader->nAllocLen < mConfig->outputFrameSize) {
ALOGE("input buffer too small: got %u, expected %u",
outHeader->nAllocLen, mConfig->outputFrameSize);
android_errorWriteLog(0x534e4554, "27793371");
notify(OMX_EventError, OMX_ErrorUndefined, OUTPUT_BUFFER_TOO_SMALL, NULL);
mSignalledError = true;
return;
}
mConfig->pOutputBuffer =
reinterpret_cast<int16_t *>(outHeader->pBuffer);
ERROR_CODE decoderErr;
if ((decoderErr = pvmp3_framedecoder(mConfig, mDecoderBuf))
!= NO_DECODING_ERROR) {
ALOGV("mp3 decoder returned error %d", decoderErr);
if (decoderErr != NO_ENOUGH_MAIN_DATA_ERROR
&& decoderErr != SIDE_INFO_ERROR) {
ALOGE("mp3 decoder returned error %d", decoderErr);
notify(OMX_EventError, OMX_ErrorUndefined, decoderErr, NULL);
mSignalledError = true;
return;
}
if (mConfig->outputFrameSize == 0) {
mConfig->outputFrameSize = kOutputBufferSize / sizeof(int16_t);
}
if (decoderErr == NO_ENOUGH_MAIN_DATA_ERROR && mSawInputEos) {
if (!mIsFirst) {
outHeader->nOffset = 0;
outHeader->nFilledLen = kPVMP3DecoderDelay * mNumChannels * sizeof(int16_t);
memset(outHeader->pBuffer, 0, outHeader->nFilledLen);
}
outHeader->nFlags = OMX_BUFFERFLAG_EOS;
mSignalledOutputEos = true;
} else {
ALOGV_IF(mIsFirst, "insufficient data for first frame, sending silence");
memset(outHeader->pBuffer,
0,
mConfig->outputFrameSize * sizeof(int16_t));
if (inHeader) {
mConfig->inputBufferUsedLength = inHeader->nFilledLen;
}
}
} else if (mConfig->samplingRate != mSamplingRate
|| mConfig->num_channels != mNumChannels) {
mSamplingRate = mConfig->samplingRate;
mNumChannels = mConfig->num_channels;
notify(OMX_EventPortSettingsChanged, 1, 0, NULL);
mOutputPortSettingsChange = AWAITING_DISABLED;
return;
}
if (mIsFirst) {
mIsFirst = false;
outHeader->nOffset =
kPVMP3DecoderDelay * mNumChannels * sizeof(int16_t);
outHeader->nFilledLen =
mConfig->outputFrameSize * sizeof(int16_t) - outHeader->nOffset;
} else if (!mSignalledOutputEos) {
outHeader->nOffset = 0;
outHeader->nFilledLen = mConfig->outputFrameSize * sizeof(int16_t);
}
outHeader->nTimeStamp =
mAnchorTimeUs + (mNumFramesOutput * 1000000ll) / mSamplingRate;
if (inHeader) {
CHECK_GE(inHeader->nFilledLen, mConfig->inputBufferUsedLength);
inHeader->nOffset += mConfig->inputBufferUsedLength;
inHeader->nFilledLen -= mConfig->inputBufferUsedLength;
if (inHeader->nFilledLen == 0) {
inInfo->mOwnedByUs = false;
inQueue.erase(inQueue.begin());
inInfo = NULL;
notifyEmptyBufferDone(inHeader);
inHeader = NULL;
}
}
mNumFramesOutput += mConfig->outputFrameSize / mNumChannels;
outInfo->mOwnedByUs = false;
outQueue.erase(outQueue.begin());
outInfo = NULL;
notifyFillBufferDone(outHeader);
outHeader = NULL;
}
}

