void Compute(OpKernelContext* ctx) override {
const Tensor& input = ctx->input(kInputTensorIndex);
const Tensor& input_min = ctx->input(kInputMinIndex);
const Tensor& input_max = ctx->input(kInputMaxIndex);
const size_t depth = input_max.NumElements();
OP_REQUIRES(
ctx, input_min.dim_size(0) == depth,
errors::InvalidArgument("input_min has incorrect size, expected ",
depth, " was ", input_min.dim_size(0)));
OP_REQUIRES(
ctx, input_max.dim_size(0) == depth,
errors::InvalidArgument("input_max has incorrect size, expected ",
depth, " was ", input_max.dim_size(0)));
const float* input_min_data = input_min.flat<float>().data();
const float* input_max_data = input_max.flat<float>().data();
std::vector<float> ranges(depth);
bool is_non_negative = true;
Eigen::array<int, 2> shuffling({1, 0});
auto input_matrix = input.flat_inner_dims<qint32>();
auto transposed_input = input_matrix.shuffle(shuffling);
float out_min_max = std::numeric_limits<float>::min();
#ifdef ENABLE_ONEDNN_OPENMP
#ifdef _MSC_VER
#pragma omp parallel for
#else
#pragma omp parallel for reduction(max : out_min_max)
#endif
#endif          for (int64_t i = 0; i < depth; ++i) {
Eigen::Tensor<qint32, 0, Eigen::RowMajor> min =
transposed_input.chip<0>(i).minimum();
Eigen::Tensor<qint32, 0, Eigen::RowMajor> max =
transposed_input.chip<0>(i).maximum();
const int32_t min_per_channel = min();
const int32_t max_per_channel = max();
const int32_t abs_max =
std::max(std::abs(min_per_channel), std::abs(max_per_channel));
float scale =
std::max(std::abs(input_min_data[i]), std::abs(input_max_data[i]));
ranges[i] =
scale * static_cast<float>(abs_max) / static_cast<float>(1L << 31);
if (min_per_channel < 0) is_non_negative = false;
out_min_max = std::max(out_min_max, ranges[i]);
}
if (out_min_max > clip_value_max_) out_min_max = clip_value_max_;
Tensor* output_min = nullptr;
Tensor* output_max = nullptr;
OP_REQUIRES_OK(ctx, ctx->allocate_output(kOutputMinIndex, {}, &output_min));
OP_REQUIRES_OK(ctx, ctx->allocate_output(kOutputMaxIndex, {}, &output_max));
output_min->flat<float>()(0) = is_non_negative ? 0.0f : -out_min_max;
output_max->flat<float>()(0) = out_min_max;
}

int nbd_client_co_flush(BlockDriverState *bs)
{
NBDClientSession *client = nbd_get_client_session(bs);
NBDRequest request = { .type = NBD_CMD_FLUSH };
NBDReply reply;
ssize_t ret;
if (!(client->nbdflags & NBD_FLAG_SEND_FLUSH)) {
return 0;
}
request.from = 0;
request.len = 0;
nbd_coroutine_start(client, &request);
ret = nbd_co_send_request(bs, &request, NULL);
if (ret < 0) {
reply.error = -ret;
} else {
nbd_co_receive_reply(client, &request, &reply, NULL);
}
nbd_coroutine_end(client, &request);
return -reply.error;
}

int main(int argc, char **argv) {
el::Configurations defaultConf = LogHandler::setupLogHandler(&argc, &argv);
LogHandler::setupStdoutLogger();
et::HandleTerminate();
::signal(SIGINT, et::InterruptSignalHandler);
cxxopts::Options options("etserver",
"Remote shell for the busy and impatient");
try {
options.allow_unrecognised_options();
options.add_options()                     ("h,help", "Print help")              ("version", "Print version")          ("port", "Port to listen on",
cxxopts::value<int>()->default_value("0"))          ("bindip", "IP to listen on",
cxxopts::value<string>()->default_value(""))          ("daemon", "Daemonize the server")                     ("cfgfile", "Location of the config file",
cxxopts::value<std::string>()->default_value(""))          ("logtostdout", "log to stdout")                            ("pidfile", "Location of the pid file",
cxxopts::value<std::string>()->default_value(
"/var/run/etserver.pid"))          ("v,verbose", "Enable verbose logging",
cxxopts::value<int>()->default_value("0"), "LEVEL")          ("serverfifo",
"If set, listens on the matching fifo name",                cxxopts::value<std::string>()->default_value(""))          ("telemetry",
"Allow et to anonymously send errors to guide future improvements",
cxxopts::value<bool>())          ;
auto result = options.parse(argc, argv);
if (result.count("help")) {
CLOG(INFO, "stdout") << options.help({}) << endl;
exit(0);
}
if (result.count("version")) {
CLOG(INFO, "stdout") << "et version " << ET_VERSION << endl;
exit(0);
}
el::Loggers::setVerboseLevel(result["verbose"].as<int>());
if (result.count("daemon")) {
if (DaemonCreator::create(true, result["pidfile"].as<string>()) == -1) {
STFATAL << "Error creating daemon: " << strerror(GetErrno());
}
}
if (result.count("logtostdout")) {
defaultConf.setGlobally(el::ConfigurationType::ToStandardOutput, "true");
} else {
defaultConf.setGlobally(el::ConfigurationType::ToStandardOutput, "false");
LogHandler::stderrToFile(GetTempDirectory() + "etserver");
}
ServerFifoPath serverFifo;
string maxlogsize = "20971520";
int port = 0;
string bindIp = "";
bool telemetry = false;
if (result.count("cfgfile")) {
CSimpleIniA ini(true, false, false);
string cfgfilename = result["cfgfile"].as<string>();
SI_Error rc = ini.LoadFile(cfgfilename.c_str());
if (rc == 0) {
if (!result.count("port")) {
const char *portString = ini.GetValue("Networking", "port", NULL);
if (portString) {
port = stoi(portString);
}
}
if (!result.count("bindip")) {
const char *bindIpPtr = ini.GetValue("Networking", "bind_ip", NULL);
if (bindIpPtr) {
bindIp = string(bindIpPtr);
}
}
telemetry = ini.GetBoolValue("Debug", "telemetry", false);
const char *vlevel = ini.GetValue("Debug", "verbose", NULL);
if (result.count("verbose")) {
el::Loggers::setVerboseLevel(result["verbose"].as<int>());
} else if (vlevel) {
el::Loggers::setVerboseLevel(atoi(vlevel));
}
const char *fifoName = ini.GetValue("Debug", "serverfifo", NULL);
if (fifoName) {
const string fifoNameStr(fifoName);
if (!fifoNameStr.empty()) {
serverFifo.setPathOverride(fifoNameStr);
}
}
const char *silent = ini.GetValue("Debug", "silent", NULL);
if (silent && atoi(silent) != 0) {
defaultConf.setGlobally(el::ConfigurationType::Enabled, "false");
}
const char *logsize = ini.GetValue("Debug", "logsize", NULL);
if (logsize && atoi(logsize) != 0) {
maxlogsize = string(logsize);
}
} else {
STFATAL << "Invalid config file: " << cfgfilename;
}
}
if (result.count("serverfifo") &&
!result["serverfifo"].as<string>().empty()) {
serverFifo.setPathOverride(result["serverfifo"].as<string>());
}
if (result.count("port")) {
port = result["port"].as<int>();
}
if (result.count("bindip")) {
bindIp = result["bindip"].as<string>();
}
if (result.count("telemetry")) {
telemetry = result["telemetry"].as<bool>();
}
GOOGLE_PROTOBUF_VERIFY_VERSION;
srand(1);
if (port == 0) {
port = 2022;
}
LogHandler::setupLogFile(&defaultConf,
GetTempDirectory() + "etserver-%datetime.log",
maxlogsize);
el::Loggers::reconfigureLogger("default", defaultConf);
el::Helpers::setThreadName("etserver-main");
el::Helpers::installPreRollOutCallback(LogHandler::rolloutHandler);
TelemetryService::create(
telemetry, GetTempDirectory() + "/.sentry-native-etserver", "Server");
serverFifo.createDirectoriesIfRequired();
std::shared_ptr<SocketHandler> tcpSocketHandler(new TcpSocketHandler());
std::shared_ptr<PipeSocketHandler> pipeSocketHandler(
new PipeSocketHandler());
LOG(INFO) << "In child, about to start server.";
SocketEndpoint serverEndpoint;
serverEndpoint.set_port(port);
if (bindIp.length()) {
serverEndpoint.set_name(bindIp);
}
SocketEndpoint routerFifo;
routerFifo.set_name(serverFifo.getPathForCreation());
TerminalServer terminalServer(tcpSocketHandler, serverEndpoint,
pipeSocketHandler, routerFifo);
terminalServer.run();
} catch (cxxopts::OptionException &oe) {
CLOG(INFO, "stdout") << "Exception: " << oe.what() << "\n" << endl;
CLOG(INFO, "stdout") << options.help({}) << endl;
exit(1);
}
el::Helpers::uninstallPreRollOutCallback();
}

