void
wiki_handle_http_request(HttpRequest *req)
{
HttpResponse *res      = http_response_new(req);
char         *page     = http_request_get_path_info(req); 
char         *command  = http_request_get_query_string(req); 
char         *wikitext = "";
util_dehttpize(page); 
if (!strcmp(page, "/"))
{
if (access("WikiHome", R_OK) != 0)
wiki_redirect(res, "/WikiHome?create");
page = "/WikiHome";
}
if (!strcmp(page, "/styles.css"))
{
http_response_set_content_type(res, "text/css");
http_response_printf(res, "%s", CssData);
http_response_send(res);
exit(0);
}
if (!strcmp(page, "/favicon.ico"))
{
http_response_set_content_type(res, "image/ico");
http_response_set_data(res, FaviconData, FaviconDataLen);
http_response_send(res);
exit(0);
}
page = page + 1; 
if (!strncmp(page, "api/", 4))
{
char *p;
page += 4; 
for (p=page; *p != '\0'; p++)
if (*p=='?') { *p ='\0'; break; }
wiki_handle_rest_call(req, res, page); 
exit(0);
}
if (strchr(page, '/'))
{
http_response_set_status(res, 404, "Not Found");
http_response_printf(res, "<html><body>404 Not Found</body></html>\n");
http_response_send(res);
exit(0);
}
if (!strcmp(page, "Changes"))
{
wiki_show_changes_page(res);
}
else if (!strcmp(page, "ChangesRss"))
{
wiki_show_changes_page_rss(res);
}
else if (!strcmp(page, "Search"))
{
wiki_show_search_results_page(res, http_request_param_get(req, "expr"));
}
else if (!strcmp(page, "Create"))
{
if ( (wikitext = http_request_param_get(req, "title")) != NULL)
{
wiki_redirect(res, http_request_param_get(req, "title"));
}
else
{
wiki_show_create_page(res);
}
}
else
{
if ( (wikitext = http_request_param_get(req, "wikitext")) != NULL)
{
file_write(page, wikitext);      
}
if (access(page, R_OK) == 0) 
{
wikitext = file_read(page);
if (!strcmp(command, "edit"))
{
wiki_show_edit_page(res, wikitext, page);
}
else
{
wiki_show_page(res, wikitext, page);
}
}
else
{
if (!strcmp(command, "create"))
{
wiki_show_edit_page(res, NULL, page);
}
else
{
char buf[1024];
snprintf(buf, 1024, "%s?create", page);
wiki_redirect(res, buf);
}
}
}
}

void
addMultirowsForm(Buffer *buf, AnchorList *al)
{
int i, j, k, col, ecol, pos;
Anchor a_form, *a;
Line *l, *ls;
if (al == NULL || al->nanchor == 0)
return;
for (i = 0; i < al->nanchor; i++) {
a_form = al->anchors[i];
al->anchors[i].rows = 1;
if (a_form.hseq < 0 || a_form.rows <= 1)
continue;
for (l = buf->firstLine; l != NULL; l = l->next) {
if (l->linenumber == a_form.y)
break;
}
if (!l)
continue;
if (a_form.y == a_form.start.line)
ls = l;
else {
for (ls = l; ls != NULL;
ls = (a_form.y < a_form.start.line) ? ls->next : ls->prev) {
if (ls->linenumber == a_form.start.line)
break;
}
if (!ls)
continue;
}
col = COLPOS(ls, a_form.start.pos);
ecol = COLPOS(ls, a_form.end.pos);
for (j = 0; l && j < a_form.rows; l = l->next, j++) {
pos = columnPos(l, col);
if (j == 0) {
buf->hmarklist->marks[a_form.hseq].line = l->linenumber;
buf->hmarklist->marks[a_form.hseq].pos = pos;
}
if (a_form.start.line == l->linenumber)
continue;
buf->formitem = putAnchor(buf->formitem, a_form.url,
a_form.target, &a, NULL, NULL, '\0',
l->linenumber, pos);
a->hseq = a_form.hseq;
a->y = a_form.y;
a->end.pos = pos + ecol - col;
l->lineBuf[pos - 1] = '[';
l->lineBuf[a->end.pos] = ']';
for (k = pos; k < a->end.pos; k++)
l->propBuf[k] |= PE_FORM;
}
}
}

static Image *ReadJP2Image(const ImageInfo *image_info,ExceptionInfo *exception)
{
const char
*option;
Image
*image;
int
jp2_status;
MagickBooleanType
status;
opj_codec_t
*jp2_codec;
opj_codestream_index_t
*codestream_index = (opj_codestream_index_t *) NULL;
opj_dparameters_t
parameters;
opj_image_t
*jp2_image;
opj_stream_t
*jp2_stream;
register ssize_t
i;
ssize_t
y;
unsigned char
sans[4];
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickSignature);
image=AcquireImage(image_info);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
if (ReadBlob(image,4,sans) != 4)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
(void) SeekBlob(image,SEEK_SET,0);
if (LocaleCompare(image_info->magick,"JPT") == 0)
jp2_codec=opj_create_decompress(OPJ_CODEC_JPT);
else
if (IsJ2K(sans,4) != MagickFalse)
jp2_codec=opj_create_decompress(OPJ_CODEC_J2K);
else
jp2_codec=opj_create_decompress(OPJ_CODEC_JP2);
opj_set_warning_handler(jp2_codec,JP2WarningHandler,exception);
opj_set_error_handler(jp2_codec,JP2ErrorHandler,exception);
opj_set_default_decoder_parameters(&parameters);
option=GetImageOption(image_info,"jp2:reduce-factor");
if (option != (const char *) NULL)
parameters.cp_reduce=StringToInteger(option);
option=GetImageOption(image_info,"jp2:quality-layers");
if (option == (const char *) NULL)
option=GetImageOption(image_info,"jp2:layer-number");
if (option != (const char *) NULL)
parameters.cp_layer=StringToInteger(option);
if (opj_setup_decoder(jp2_codec,&parameters) == 0)
{
opj_destroy_codec(jp2_codec);
ThrowReaderException(DelegateError,"UnableToManageJP2Stream");
}
jp2_stream=opj_stream_create(OPJ_J2K_STREAM_CHUNK_SIZE,OPJ_TRUE);
opj_stream_set_read_function(jp2_stream,JP2ReadHandler);
opj_stream_set_write_function(jp2_stream,JP2WriteHandler);
opj_stream_set_seek_function(jp2_stream,JP2SeekHandler);
opj_stream_set_skip_function(jp2_stream,JP2SkipHandler);
opj_stream_set_user_data(jp2_stream,image,NULL);
opj_stream_set_user_data_length(jp2_stream,GetBlobSize(image));
if (opj_read_header(jp2_stream,jp2_codec,&jp2_image) == 0)
{
opj_stream_destroy(jp2_stream);
opj_destroy_codec(jp2_codec);
ThrowReaderException(DelegateError,"UnableToDecodeImageFile");
}
jp2_status=1;
if ((image->columns != 0) && (image->rows != 0))
{
jp2_status=opj_set_decode_area(jp2_codec,jp2_image,
(OPJ_INT32) image->extract_info.x,(OPJ_INT32) image->extract_info.y,
(OPJ_INT32) image->extract_info.x+(ssize_t) image->columns,
(OPJ_INT32) image->extract_info.y+(ssize_t) image->rows);
if (jp2_status == 0)
{
opj_stream_destroy(jp2_stream);
opj_destroy_codec(jp2_codec);
opj_image_destroy(jp2_image);
ThrowReaderException(DelegateError,"UnableToDecodeImageFile");
}
}
if ((image_info->number_scenes != 0) && (image_info->scene != 0))
jp2_status=opj_get_decoded_tile(jp2_codec,jp2_stream,jp2_image,
(unsigned int) image_info->scene-1);
else
if (image->ping == MagickFalse)
{
jp2_status=opj_decode(jp2_codec,jp2_stream,jp2_image);
if (jp2_status != 0)
jp2_status=opj_end_decompress(jp2_codec,jp2_stream);
}
if (jp2_status == 0)
{
opj_stream_destroy(jp2_stream);
opj_destroy_codec(jp2_codec);
opj_image_destroy(jp2_image);
ThrowReaderException(DelegateError,"UnableToDecodeImageFile");
}
opj_stream_destroy(jp2_stream);
for (i=0; i < (ssize_t) jp2_image->numcomps; i++)
{
if ((jp2_image->comps[i].dx == 0) || (jp2_image->comps[i].dy == 0))
{
opj_destroy_codec(jp2_codec);
opj_image_destroy(jp2_image);
ThrowReaderException(CoderError,"IrregularChannelGeometryNotSupported")
}
}
image->columns=(size_t) jp2_image->comps[0].w;
image->rows=(size_t) jp2_image->comps[0].h;
image->depth=jp2_image->comps[0].prec;
status=SetImageExtent(image,image->columns,image->rows);
if (status == MagickFalse)
{
InheritException(exception,&image->exception);
return(DestroyImageList(image));
}
image->compression=JPEG2000Compression;
if (jp2_image->color_space == 2)
{
SetImageColorspace(image,GRAYColorspace);
if (jp2_image->numcomps > 1)
image->matte=MagickTrue;
}
else
if (jp2_image->color_space == 3)
SetImageColorspace(image,Rec601YCbCrColorspace);
if (jp2_image->numcomps > 3)
image->matte=MagickTrue;
if (jp2_image->icc_profile_buf != (unsigned char *) NULL)
{
StringInfo
*profile;
profile=BlobToStringInfo(jp2_image->icc_profile_buf,
jp2_image->icc_profile_len);
if (profile != (StringInfo *) NULL)
SetImageProfile(image,"icc",profile);
}
if (image->ping != MagickFalse)
{
opj_destroy_codec(jp2_codec);
opj_image_destroy(jp2_image);
opj_destroy_cstr_index(&codestream_index);
return(GetFirstImageInList(image));
}
for (y=0; y < (ssize_t) image->rows; y++)
{
register PixelPacket
*magick_restrict q;
register ssize_t
x;
q=GetAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (PixelPacket *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
register ssize_t
i;
for (i=0; i < (ssize_t) jp2_image->numcomps; i++)
{
double
pixel,
scale;
scale=QuantumRange/(double) ((1UL << jp2_image->comps[i].prec)-1);
pixel=scale*(jp2_image->comps[i].data[y/jp2_image->comps[i].dy*
image->columns/jp2_image->comps[i].dx+x/jp2_image->comps[i].dx]+
(jp2_image->comps[i].sgnd ? 1UL << (jp2_image->comps[i].prec-1) : 0));
switch (i)
{
case 0:
{
q->red=ClampToQuantum(pixel);
q->green=q->red;
q->blue=q->red;
q->opacity=OpaqueOpacity;
break;
}
case 1:
{
if (jp2_image->numcomps == 2)
{
q->opacity=ClampToQuantum(QuantumRange-pixel);
break;
}
q->green=ClampToQuantum(pixel);
break;
}
case 2:
{
q->blue=ClampToQuantum(pixel);
break;
}
case 3:
{
q->opacity=ClampToQuantum(QuantumRange-pixel);
break;
}
}
}
q++;
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
opj_destroy_codec(jp2_codec);
opj_image_destroy(jp2_image);
opj_destroy_cstr_index(&codestream_index);
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

static ssize_tstream_read(pdfio_stream_t *st,            char           *buffer,            size_t         bytes){
ssize_trbytes;
if (st->filter == PDFIO_FILTER_NONE)
{
if (bytes > st->remaining)
rbytes = _pdfioFileRead(st->pdf, buffer, st->remaining);
else
rbytes = _pdfioFileRead(st->pdf, buffer, bytes);
if (rbytes > 0)
{
st->remaining -= (size_t)rbytes;
if (st->crypto_cb)
(st->crypto_cb)(&st->crypto_ctx, (uint8_t *)buffer, (uint8_t *)buffer, (size_t)rbytes);
}
return (rbytes);
}
else if (st->filter == PDFIO_FILTER_FLATE)
{
intstatus;
if (st->predictor == _PDFIO_PREDICTOR_NONE)
{
PDFIO_DEBUG("stream_read: No predictor.\n");
if (st->flate.avail_in == 0)
{
if (sizeof(st->cbuffer) > st->remaining)
rbytes = _pdfioFileRead(st->pdf, st->cbuffer, st->remaining);
else
rbytes = _pdfioFileRead(st->pdf, st->cbuffer, sizeof(st->cbuffer));
if (rbytes <= 0)
return (-1);
if (st->crypto_cb)
rbytes = (ssize_t)(st->crypto_cb)(&st->crypto_ctx, st->cbuffer, st->cbuffer, (size_t)rbytes);
st->remaining      -= (size_t)rbytes;
st->flate.next_in  = (Bytef *)st->cbuffer;
st->flate.avail_in = (uInt)rbytes;
}
st->flate.next_out  = (Bytef *)buffer;
st->flate.avail_out = (uInt)bytes;
if ((status = inflate(&(st->flate), Z_NO_FLUSH)) < Z_OK)
{
_pdfioFileError(st->pdf, "Unable to decompress stream data: %s", zstrerror(status));
return (-1);
}
return (st->flate.next_out - (Bytef *)buffer);
}
else if (st->predictor == _PDFIO_PREDICTOR_TIFF2)
{
size_tpbpixel = st->pbpixel,
remaining = st->pbsize;
unsigned char*bufptr = (unsigned char *)buffer,
*bufsecond = (unsigned char *)buffer + pbpixel,
*sptr = st->psbuffer;
PDFIO_DEBUG("stream_read: TIFF predictor 2.\n");
if (bytes < st->pbsize)
{
_pdfioFileError(st->pdf, "Read buffer too small for stream.");
return (-1);
}
st->flate.next_out  = (Bytef *)sptr;
st->flate.avail_out = (uInt)st->pbsize;
while (st->flate.avail_out > 0)
{
if (st->flate.avail_in == 0)
{
if (sizeof(st->cbuffer) > st->remaining)
rbytes = _pdfioFileRead(st->pdf, st->cbuffer, st->remaining);
else
rbytes = _pdfioFileRead(st->pdf, st->cbuffer, sizeof(st->cbuffer));
if (rbytes <= 0)
return (-1);
if (st->crypto_cb)
rbytes = (ssize_t)(st->crypto_cb)(&st->crypto_ctx, st->cbuffer, st->cbuffer, (size_t)rbytes);
st->remaining      -= (size_t)rbytes;
st->flate.next_in  = (Bytef *)st->cbuffer;
st->flate.avail_in = (uInt)rbytes;
}
if ((status = inflate(&(st->flate), Z_NO_FLUSH)) < Z_OK)
{
_pdfioFileError(st->pdf, "Unable to decompress stream data: %s", zstrerror(status));
return (-1);
}
else if (status == Z_STREAM_END)
break;
}
if (st->flate.avail_out > 0)
return (-1);
for (; bufptr < bufsecond; remaining --, sptr ++)
*bufptr++ = *sptr;
for (; remaining > 0; remaining --, sptr ++, bufptr ++)
*bufptr = *sptr + bufptr[-(int)pbpixel];
return ((ssize_t)st->pbsize);
}
else
{
size_tpbpixel = st->pbpixel,
remaining = st->pbsize - 1;
unsigned char*bufptr = (unsigned char *)buffer,
*bufsecond = (unsigned char *)buffer + pbpixel,
*sptr = st->psbuffer + 1,
*pptr = st->prbuffer;
PDFIO_DEBUG("stream_read: PNG predictor.\n");
if (bytes < (st->pbsize - 1))
{
_pdfioFileError(st->pdf, "Read buffer too small for stream.");
return (-1);
}
st->flate.next_out  = (Bytef *)sptr - 1;
st->flate.avail_out = (uInt)st->pbsize;
while (st->flate.avail_out > 0)
{
if (st->flate.avail_in == 0)
{
if (sizeof(st->cbuffer) > st->remaining)
rbytes = _pdfioFileRead(st->pdf, st->cbuffer, st->remaining);
else
rbytes = _pdfioFileRead(st->pdf, st->cbuffer, sizeof(st->cbuffer));
if (rbytes <= 0)
return (-1);
if (st->crypto_cb)
rbytes = (ssize_t)(st->crypto_cb)(&st->crypto_ctx, st->cbuffer, st->cbuffer, (size_t)rbytes);
st->remaining      -= (size_t)rbytes;
st->flate.next_in  = (Bytef *)st->cbuffer;
st->flate.avail_in = (uInt)rbytes;
}
if ((status = inflate(&(st->flate), Z_NO_FLUSH)) < Z_OK)
{
_pdfioFileError(st->pdf, "Unable to decompress stream data: %s", zstrerror(status));
return (-1);
}
else if (status == Z_STREAM_END)
break;
}
if (st->flate.avail_out > 0)
{
PDFIO_DEBUG("stream_read: Early EOF (remaining=%u, avail_in=%d, avail_out=%d, data_type=%d, next_in=<%02X%02X%02X%02X...>).\n", (unsigned)st->remaining, st->flate.avail_in, st->flate.avail_out, st->flate.data_type, st->flate.next_in[0], st->flate.next_in[1], st->flate.next_in[2], st->flate.next_in[3]);
return (-1);
}
PDFIO_DEBUG("stream_read: Line %02X %02X %02X %02X %02X.\n", sptr[-1], sptr[0], sptr[0], sptr[2], sptr[3]);
switch (sptr[-1])
{
case 0 :         case 10 :             memcpy(buffer, sptr, remaining);
break;
case 1 :         case 11 :             for (; bufptr < bufsecond; remaining --, sptr ++)
*bufptr++ = *sptr;
for (; remaining > 0; remaining --, sptr ++, bufptr ++)
*bufptr = *sptr + bufptr[-(int)pbpixel];
break;
case 2 :         case 12 :             for (; remaining > 0; remaining --, sptr ++, pptr ++)
*bufptr++ = *sptr + *pptr;
break;
case 3 :         case 13 :     for (; bufptr < bufsecond; remaining --, sptr ++, pptr ++)
*bufptr++ = *sptr + *pptr / 2;
for (; remaining > 0; remaining --, sptr ++, pptr ++, bufptr ++)
*bufptr = *sptr + (bufptr[-(int)pbpixel] + *pptr) / 2;
break;
case 4 :         case 14 :             for (; bufptr < bufsecond; remaining --, sptr ++, pptr ++)
*bufptr++ = *sptr + stream_paeth(0, *pptr, 0);
for (; remaining > 0; remaining --, sptr ++, pptr ++, bufptr ++)
*bufptr = *sptr + stream_paeth(bufptr[-(int)pbpixel], *pptr, pptr[-(int)pbpixel]);
break;
default :
_pdfioFileError(st->pdf, "Bad PNG filter %d in data stream.", sptr[-1]);
return (-1);
}
memcpy(st->prbuffer, buffer, st->pbsize - 1);
return ((ssize_t)(st->pbsize - 1));
}
}
return (-1);
}

void rfc1867PostHandler(Transport* transport,
Array& post,
Array& files,
size_t content_length,
const void*& data, size_t& size,
const std::string boundary) {
char *s=nullptr, *start_arr=nullptr;
std::string array_index, abuf;
char *lbuf=nullptr;
int total_bytes=0, cancel_upload=0, is_arr_upload=0, array_len=0;
int max_file_size=0, skip_upload=0, anonindex=0, is_anonymous;
std::set<std::string> &uploaded_files = s_rfc1867_data->rfc1867UploadedFiles;
multipart_buffer *mbuff;
int fd=-1;
void *event_extra_data = nullptr;
unsigned int llen = 0;
int upload_count = RuntimeOption::MaxFileUploads;
if (!(mbuff = multipart_buffer_new(transport,
(const char *)data, size, boundary))) {
Logger::Warning("Unable to initialize the input buffer");
return;
}
s_rfc1867_data->rfc1867ProtectedVariables.clear();
uploaded_files.clear();
int (*php_rfc1867_callback)(apc_rfc1867_data *rfc1867ApcData,
unsigned int event, void *event_data,
void **extra) = s_rfc1867_data->rfc1867Callback;
if (php_rfc1867_callback != nullptr) {
multipart_event_start event_start;
event_start.content_length = content_length;
if (php_rfc1867_callback(&s_rfc1867_data->rfc1867ApcData,
MULTIPART_EVENT_START, &event_start,
&event_extra_data) == FAILURE) {
goto fileupload_done;
}
}
while (!multipart_buffer_eof(mbuff)) {
std::string temp_filename;
char buff[FILLUNIT];
char *cd=nullptr,*param=nullptr,*filename=nullptr, *tmp=nullptr;
size_t blen=0, wlen=0;
off_t offset;
header_list header;
if (!multipart_buffer_headers(mbuff, header)) {
goto fileupload_done;
}
if ((cd = php_mime_get_hdr_value(header, "Content-Disposition"))) {
char *pair=nullptr;
int end=0;
while (isspace(*cd)) {
++cd;
}
while (*cd && (pair = php_ap_getword(&cd, ';')))
{
char *key=nullptr, *word = pair;
while (isspace(*cd)) {
++cd;
}
if (strchr(pair, '=')) {
key = php_ap_getword(&pair, '=');
if (!strcasecmp(key, "name")) {
if (param) {
free(param);
}
param = php_ap_getword_conf(&pair);
} else if (!strcasecmp(key, "filename")) {
if (filename) {
free(filename);
}
filename = php_ap_getword_conf(&pair);
}
}
if (key) free(key);
free(word);
}
if (!filename && param) {
unsigned int value_len;
char *value = multipart_buffer_read_body(mbuff, &value_len);
unsigned int new_val_len; 
if (!value) {
value = strdup("");
}
new_val_len = value_len;
if (php_rfc1867_callback != nullptr) {
multipart_event_formdata event_formdata;
size_t newlength = new_val_len;
event_formdata.post_bytes_processed = mbuff->read_post_bytes;
event_formdata.name = param;
event_formdata.value = &value;
event_formdata.length = new_val_len;
event_formdata.newlength = &newlength;
if (php_rfc1867_callback(&s_rfc1867_data->rfc1867ApcData,
MULTIPART_EVENT_FORMDATA, &event_formdata,
&event_extra_data) == FAILURE) {
free(param);
free(value);
continue;
}
new_val_len = newlength;
}
String val(value, new_val_len, CopyString);
safe_php_register_variable(param, val, post, 0);
if (!strcasecmp(param, "MAX_FILE_SIZE")) {
max_file_size = atol(value);
}
free(param);
free(value);
continue;
}
if (!RuntimeOption::EnableFileUploads) {
skip_upload = 1;
} else if (upload_count <= 0) {
Logger::Warning(
"Maximum number of allowable file uploads has been exceeded"
);
skip_upload = 1;
}
if (!param && !filename) {
Logger::Warning("File Upload Mime headers garbled");
goto fileupload_done;
}
if (!param) {
is_anonymous = 1;
param = (char*)malloc(MAX_SIZE_ANONNAME);
snprintf(param, MAX_SIZE_ANONNAME, "%u", anonindex++);
} else {
is_anonymous = 0;
}
if (!skip_upload) {
tmp = param;
long c = 0;
while (*tmp) {
if (*tmp == '[') {
c++;
} else if (*tmp == ']') {
c--;
if (tmp[1] && tmp[1] != '[') {
skip_upload = 1;
break;
}
}
if (c < 0) {
skip_upload = 1;
break;
}
tmp++;
}
}
total_bytes = cancel_upload = 0;
if (!skip_upload) {
char path[PATH_MAX];
snprintf(path, sizeof(path), "%s/XXXXXX",
RuntimeOption::UploadTmpDir.c_str());
fd = mkstemp(path);
upload_count--;
if (fd == -1) {
Logger::Warning("Unable to open temporary file");
Logger::Warning("File upload error - unable to create a "
"temporary file");
cancel_upload = UPLOAD_ERROR_E;
}
temp_filename = path;
}
if (!skip_upload && php_rfc1867_callback != nullptr) {
multipart_event_file_start event_file_start;
event_file_start.post_bytes_processed = mbuff->read_post_bytes;
event_file_start.name = param;
event_file_start.filename = &filename;
if (php_rfc1867_callback(&s_rfc1867_data->rfc1867ApcData,
MULTIPART_EVENT_FILE_START,
&event_file_start,
&event_extra_data) == FAILURE) {
if (!temp_filename.empty()) {
if (cancel_upload != UPLOAD_ERROR_E) { 
close(fd);
unlink(temp_filename.c_str());
}
}
temp_filename="";
free(param);
free(filename);
continue;
}
}
if (skip_upload) {
free(param);
free(filename);
continue;
}
if (strlen(filename) == 0) {
Logger::Verbose("No file uploaded");
cancel_upload = UPLOAD_ERROR_D;
}
offset = 0;
end = 0;
while (!cancel_upload &&
(blen = multipart_buffer_read(mbuff, buff, sizeof(buff), &end)))
{
if (php_rfc1867_callback != nullptr) {
multipart_event_file_data event_file_data;
event_file_data.post_bytes_processed = mbuff->read_post_bytes;
event_file_data.offset = offset;
event_file_data.data = buff;
event_file_data.length = blen;
event_file_data.newlength = &blen;
if (php_rfc1867_callback(&s_rfc1867_data->rfc1867ApcData,
MULTIPART_EVENT_FILE_DATA,
&event_file_data,
&event_extra_data) == FAILURE) {
cancel_upload = UPLOAD_ERROR_X;
continue;
}
}
if (VirtualHost::GetUploadMaxFileSize() > 0 &&
total_bytes > VirtualHost::GetUploadMaxFileSize()) {
Logger::Verbose("upload_max_filesize of %" PRId64 " bytes exceeded "
"- file [%s=%s] not saved",
VirtualHost::GetUploadMaxFileSize(),
param, filename);
cancel_upload = UPLOAD_ERROR_A;
} else if (max_file_size && (total_bytes > max_file_size)) {
Logger::Verbose("MAX_FILE_SIZE of %d bytes exceeded - "
"file [%s=%s] not saved",
max_file_size, param, filename);
cancel_upload = UPLOAD_ERROR_B;
} else if (blen > 0) {
wlen = folly::writeFull(fd, buff, blen);
if (wlen < blen) {
Logger::Verbose("Only %zd bytes were written, expected to "
"write %zd", wlen, blen);
cancel_upload = UPLOAD_ERROR_F;
} else {
total_bytes += wlen;
}
offset += wlen;
}
}
if (fd!=-1) { 
close(fd);
}
if (!cancel_upload && !end) {
Logger::Verbose("Missing mime boundary at the end of the data for "
"file %s", strlen(filename) > 0 ? filename : "");
cancel_upload = UPLOAD_ERROR_C;
}
if (strlen(filename) > 0 && total_bytes == 0 && !cancel_upload) {
Logger::Verbose("Uploaded file size 0 - file [%s=%s] not saved",
param, filename);
cancel_upload = 5;
}
if (php_rfc1867_callback != nullptr) {
multipart_event_file_end event_file_end;
event_file_end.post_bytes_processed = mbuff->read_post_bytes;
event_file_end.temp_filename = temp_filename.c_str();
event_file_end.cancel_upload = cancel_upload;
if (php_rfc1867_callback(&s_rfc1867_data->rfc1867ApcData,
MULTIPART_EVENT_FILE_END,
&event_file_end,
&event_extra_data) == FAILURE) {
cancel_upload = UPLOAD_ERROR_X;
}
}
if (cancel_upload && cancel_upload != UPLOAD_ERROR_C) {
if (!temp_filename.empty()) {
if (cancel_upload != UPLOAD_ERROR_E) { 
unlink(temp_filename.c_str());
}
}
temp_filename="";
} else {
s_rfc1867_data->rfc1867UploadedFiles.insert(temp_filename);
}
is_arr_upload = (start_arr = strchr(param,'[')) &&
(param[strlen(param)-1] == ']');
if (is_arr_upload) {
array_len = strlen(start_arr);
array_index = std::string(start_arr+1, array_len-2);
}
if (llen < strlen(param) + MAX_SIZE_OF_INDEX + 1) {
llen = strlen(param);
lbuf = (char *) realloc(lbuf, llen + MAX_SIZE_OF_INDEX + 1);
llen += MAX_SIZE_OF_INDEX + 1;
}
if (is_arr_upload) {
abuf = std::string(param, strlen(param)-array_len);
snprintf(lbuf, llen, "%s_name[%s]",
abuf.c_str(), array_index.c_str());
} else {
snprintf(lbuf, llen, "%s_name", param);
}
s = strrchr(filename, '\\');
if ((tmp = strrchr(filename, '/')) > s) {
s = tmp;
}
Array globals = php_globals_as_array();
if (!is_anonymous) {
if (s) {
String val(s+1, strlen(s+1), CopyString);
safe_php_register_variable(lbuf, val, globals, 0);
} else {
String val(filename, strlen(filename), CopyString);
safe_php_register_variable(lbuf, val, globals, 0);
}
}
if (is_arr_upload) {
snprintf(lbuf, llen, "%s[name][%s]",
abuf.c_str(), array_index.c_str());
} else {
snprintf(lbuf, llen, "%s[name]", param);
}
if (s) {
String val(s+1, strlen(s+1), CopyString);
safe_php_register_variable(lbuf, val, files, 0);
} else {
String val(filename, strlen(filename), CopyString);
safe_php_register_variable(lbuf, val, files, 0);
}
free(filename);
s = nullptr;
if ((cancel_upload && cancel_upload != UPLOAD_ERROR_C) ||
!(cd = php_mime_get_hdr_value(header, "Content-Type"))) {
cd = "";
} else {
s = strchr(cd, ';');
if (s != nullptr) {
*s = '\0';
}
}
if (is_arr_upload) {
snprintf(lbuf, llen, "%s_type[%s]",
abuf.c_str(), array_index.c_str());
} else {
snprintf(lbuf, llen, "%s_type", param);
}
if (!is_anonymous) {
String val(cd, strlen(cd), CopyString);
safe_php_register_variable(lbuf, val, globals, 0);
}
if (is_arr_upload) {
snprintf(lbuf, llen, "%s[type][%s]",
abuf.c_str(), array_index.c_str());
} else {
snprintf(lbuf, llen, "%s[type]", param);
}
String val(cd, strlen(cd), CopyString);
safe_php_register_variable(lbuf, val, files, 0);
if (s != nullptr) {
*s = ';';
}
s = "";
add_protected_variable(param);
Variant tempFileName(temp_filename);
if (!is_anonymous) {
safe_php_register_variable(param, tempFileName, globals, 1);
}
if (is_arr_upload) {
snprintf(lbuf, llen, "%s[tmp_name][%s]",
abuf.c_str(), array_index.c_str());
} else {
snprintf(lbuf, llen, "%s[tmp_name]", param);
}
add_protected_variable(lbuf);
safe_php_register_variable(lbuf, tempFileName, files, 1);
Variant file_size, error_type;
error_type = cancel_upload;
if (cancel_upload) {
file_size = 0;
} else {
file_size = total_bytes;
}
if (is_arr_upload) {
snprintf(lbuf, llen, "%s[error][%s]",
abuf.c_str(), array_index.c_str());
} else {
snprintf(lbuf, llen, "%s[error]", param);
}
safe_php_register_variable(lbuf, error_type, files, 0);
if (is_arr_upload) {
snprintf(lbuf, llen, "%s_size[%s]",
abuf.c_str(), array_index.c_str());
} else {
snprintf(lbuf, llen, "%s_size", param);
}
if (!is_anonymous) {
safe_php_register_variable(lbuf, file_size, globals, 0);
}
if (is_arr_upload) {
snprintf(lbuf, llen, "%s[size][%s]",
abuf.c_str(), array_index.c_str());
} else {
snprintf(lbuf, llen, "%s[size]", param);
}
safe_php_register_variable(lbuf, file_size, files, 0);
free(param);
}
}
fileupload_done:
data = mbuff->post_data;
size = mbuff->post_size;
if (php_rfc1867_callback != nullptr) {
multipart_event_end event_end;
event_end.post_bytes_processed = mbuff->read_post_bytes;
php_rfc1867_callback(&s_rfc1867_data->rfc1867ApcData,
MULTIPART_EVENT_END, &event_end, &event_extra_data);
}
if (lbuf) free(lbuf);
s_rfc1867_data->rfc1867ProtectedVariables.clear();
if (mbuff->boundary_next) free(mbuff->boundary_next);
if (mbuff->boundary) free(mbuff->boundary);
if (mbuff->buffer) free(mbuff->buffer);
if (mbuff) free(mbuff);
}

void ConnectionManagerImpl::ActiveStream::recreateStream(
StreamInfo::FilterStateSharedPtr filter_state) {
ResponseEncoder* response_encoder = response_encoder_;
response_encoder_ = nullptr;
Buffer::InstancePtr request_data = std::make_unique<Buffer::OwnedImpl>();
const auto& buffered_request_data = filter_manager_.bufferedRequestData();
const bool proxy_body = buffered_request_data != nullptr && buffered_request_data->length() > 0;
if (proxy_body) {
request_data->move(*buffered_request_data);
}
response_encoder->getStream().removeCallbacks(*this);
connection_manager_.doEndStream(*this);
RequestDecoder& new_stream = connection_manager_.newStream(*response_encoder, true);
if (filter_state->hasDataAtOrAboveLifeSpan(StreamInfo::FilterState::LifeSpan::Request)) {
(*connection_manager_.streams_.begin())->filter_manager_.streamInfo().filter_state_ =
std::make_shared<StreamInfo::FilterStateImpl>(
filter_state->parent(), StreamInfo::FilterState::LifeSpan::FilterChain);
}
new_stream.decodeHeaders(std::move(request_headers_), !proxy_body);
if (proxy_body) {
new_stream.decodeData(*request_data, true);
}
}

FT_LOCAL_DEF( FT_Error )
tt_size_reset( TT_Size  size,
FT_Bool  only_height )
{
TT_Face           face;
FT_Size_Metrics*  metrics;
size->ttmetrics.valid = FALSE;
face = (TT_Face)size->root.face;
metrics = &size->metrics;
*metrics = size->root.metrics;
if ( metrics->x_ppem < 1 || metrics->y_ppem < 1 )
return FT_THROW( Invalid_PPem );
if ( face->header.Flags & 8 )
{
metrics->ascender =
FT_PIX_ROUND( FT_MulFix( face->root.ascender, metrics->y_scale ) );
metrics->descender =
FT_PIX_ROUND( FT_MulFix( face->root.descender, metrics->y_scale ) );
metrics->height =
FT_PIX_ROUND( FT_MulFix( face->root.height, metrics->y_scale ) );
}
size->ttmetrics.valid = TRUE;
if ( only_height )
return FT_Err_Ok;
if ( face->header.Flags & 8 )
{
metrics->x_scale = FT_DivFix( metrics->x_ppem << 6,
face->root.units_per_EM );
metrics->y_scale = FT_DivFix( metrics->y_ppem << 6,
face->root.units_per_EM );
metrics->max_advance =
FT_PIX_ROUND( FT_MulFix( face->root.max_advance_width,
metrics->x_scale ) );
}
if ( metrics->x_ppem >= metrics->y_ppem )
{
size->ttmetrics.scale   = metrics->x_scale;
size->ttmetrics.ppem    = metrics->x_ppem;
size->ttmetrics.x_ratio = 0x10000L;
size->ttmetrics.y_ratio = FT_DivFix( metrics->y_ppem,
metrics->x_ppem );
}
else
{
size->ttmetrics.scale   = metrics->y_scale;
size->ttmetrics.ppem    = metrics->y_ppem;
size->ttmetrics.x_ratio = FT_DivFix( metrics->x_ppem,
metrics->y_ppem );
size->ttmetrics.y_ratio = 0x10000L;
}
#ifdef TT_USE_BYTECODE_INTERPRETER
size->cvt_ready = -1;
#endif 
return FT_Err_Ok;
}

static void
win_redr_status(win_T *wp, int ignore_pum UNUSED)
{
introw;
char_u*p;
intlen;
intfillchar;
intattr;
intthis_ru_col;
static int  busy = FALSE;
if (busy)
