static int do_timer_create(clockid_t which_clock, struct sigevent *event,
timer_t __user *created_timer_id)
{
const struct k_clock *kc = clockid_to_kclock(which_clock);
struct k_itimer *new_timer;
int error, new_timer_id;
int it_id_set = IT_ID_NOT_SET;
if (!kc)
return -EINVAL;
if (!kc->timer_create)
return -EOPNOTSUPP;
new_timer = alloc_posix_timer();
if (unlikely(!new_timer))
return -EAGAIN;
spin_lock_init(&new_timer->it_lock);
new_timer_id = posix_timer_add(new_timer);
if (new_timer_id < 0) {
error = new_timer_id;
goto out;
}
it_id_set = IT_ID_SET;
new_timer->it_id = (timer_t) new_timer_id;
new_timer->it_clock = which_clock;
new_timer->kclock = kc;
new_timer->it_overrun = -1;
if (event) {
rcu_read_lock();
new_timer->it_pid = get_pid(good_sigevent(event));
rcu_read_unlock();
if (!new_timer->it_pid) {
error = -EINVAL;
goto out;
}
new_timer->it_sigev_notify     = event->sigev_notify;
new_timer->sigq->info.si_signo = event->sigev_signo;
new_timer->sigq->info.si_value = event->sigev_value;
} else {
new_timer->it_sigev_notify     = SIGEV_SIGNAL;
new_timer->sigq->info.si_signo = SIGALRM;
memset(&new_timer->sigq->info.si_value, 0, sizeof(sigval_t));
new_timer->sigq->info.si_value.sival_int = new_timer->it_id;
new_timer->it_pid = get_pid(task_tgid(current));
}
new_timer->sigq->info.si_tid   = new_timer->it_id;
new_timer->sigq->info.si_code  = SI_TIMER;
if (copy_to_user(created_timer_id,
&new_timer_id, sizeof (new_timer_id))) {
error = -EFAULT;
goto out;
}
error = kc->timer_create(new_timer);
if (error)
goto out;
spin_lock_irq(&current->sighand->siglock);
new_timer->it_signal = current->signal;
list_add(&new_timer->list, &current->signal->posix_timers);
spin_unlock_irq(&current->sighand->siglock);
return 0;
out:
release_posix_timer(new_timer, it_id_set);
return error;
}

static void
icmp6_rrenum_print(netdissect_options *ndo, const u_char *bp, const u_char *ep)
{
const struct icmp6_router_renum *rr6;
const char *cp;
const struct rr_pco_match *match;
const struct rr_pco_use *use;
char hbuf[NI_MAXHOST];
int n;
if (ep < bp)
return;
rr6 = (const struct icmp6_router_renum *)bp;
cp = (const char *)(rr6 + 1);
ND_TCHECK(rr6->rr_reserved);
switch (rr6->rr_code) {
case ICMP6_ROUTER_RENUMBERING_COMMAND:
ND_PRINT((ndo,"router renum: command"));
break;
case ICMP6_ROUTER_RENUMBERING_RESULT:
ND_PRINT((ndo,"router renum: result"));
break;
case ICMP6_ROUTER_RENUMBERING_SEQNUM_RESET:
ND_PRINT((ndo,"router renum: sequence number reset"));
break;
default:
ND_PRINT((ndo,"router renum: code-#%d", rr6->rr_code));
break;
}
ND_PRINT((ndo,", seq=%u", EXTRACT_32BITS(&rr6->rr_seqnum)));
if (ndo->ndo_vflag) {
#define F(x, y)((rr6->rr_flags) & (x) ? (y) : "")
ND_PRINT((ndo,"["));
if (rr6->rr_flags) {
ND_PRINT((ndo,"%s%s%s%s%s,", F(ICMP6_RR_FLAGS_TEST, "T"),
F(ICMP6_RR_FLAGS_REQRESULT, "R"),
F(ICMP6_RR_FLAGS_FORCEAPPLY, "A"),
F(ICMP6_RR_FLAGS_SPECSITE, "S"),
F(ICMP6_RR_FLAGS_PREVDONE, "P")));
}
ND_PRINT((ndo,"seg=%u,", rr6->rr_segnum));
ND_PRINT((ndo,"maxdelay=%u", EXTRACT_16BITS(&rr6->rr_maxdelay)));
if (rr6->rr_reserved)
ND_PRINT((ndo,"rsvd=0x%x", EXTRACT_32BITS(&rr6->rr_reserved)));
ND_PRINT((ndo,"]"));
#undef F
}
if (rr6->rr_code == ICMP6_ROUTER_RENUMBERING_COMMAND) {
match = (const struct rr_pco_match *)cp;
cp = (const char *)(match + 1);
ND_TCHECK(match->rpm_prefix);
if (ndo->ndo_vflag > 1)
ND_PRINT((ndo,"\n\t"));
else
ND_PRINT((ndo," "));
ND_PRINT((ndo,"match("));
switch (match->rpm_code) {
case RPM_PCO_ADD:ND_PRINT((ndo,"add")); break;
case RPM_PCO_CHANGE:ND_PRINT((ndo,"change")); break;
case RPM_PCO_SETGLOBAL:ND_PRINT((ndo,"setglobal")); break;
default:ND_PRINT((ndo,"#%u", match->rpm_code)); break;
}
if (ndo->ndo_vflag) {
ND_PRINT((ndo,",ord=%u", match->rpm_ordinal));
ND_PRINT((ndo,",min=%u", match->rpm_minlen));
ND_PRINT((ndo,",max=%u", match->rpm_maxlen));
}
if (addrtostr6(&match->rpm_prefix, hbuf, sizeof(hbuf)))
ND_PRINT((ndo,",%s/%u", hbuf, match->rpm_matchlen));
else
ND_PRINT((ndo,",?/%u", match->rpm_matchlen));
ND_PRINT((ndo,")"));
n = match->rpm_len - 3;
if (n % 4)
goto trunc;
n /= 4;
while (n-- > 0) {
use = (const struct rr_pco_use *)cp;
cp = (const char *)(use + 1);
ND_TCHECK(use->rpu_prefix);
if (ndo->ndo_vflag > 1)
ND_PRINT((ndo,"\n\t"));
else
ND_PRINT((ndo," "));
ND_PRINT((ndo,"use("));
if (use->rpu_flags) {
#define F(x, y)((use->rpu_flags) & (x) ? (y) : "")
ND_PRINT((ndo,"%s%s,",
F(ICMP6_RR_PCOUSE_FLAGS_DECRVLTIME, "V"),
F(ICMP6_RR_PCOUSE_FLAGS_DECRPLTIME, "P")));
#undef F
}
if (ndo->ndo_vflag) {
ND_PRINT((ndo,"mask=0x%x,", use->rpu_ramask));
ND_PRINT((ndo,"raflags=0x%x,", use->rpu_raflags));
if (~use->rpu_vltime == 0)
ND_PRINT((ndo,"vltime=infty,"));
else
ND_PRINT((ndo,"vltime=%u,",
EXTRACT_32BITS(&use->rpu_vltime)));
if (~use->rpu_pltime == 0)
ND_PRINT((ndo,"pltime=infty,"));
else
ND_PRINT((ndo,"pltime=%u,",
EXTRACT_32BITS(&use->rpu_pltime)));
}
if (addrtostr6(&use->rpu_prefix, hbuf, sizeof(hbuf)))
ND_PRINT((ndo,"%s/%u/%u", hbuf, use->rpu_uselen,
use->rpu_keeplen));
else
ND_PRINT((ndo,"?/%u/%u", use->rpu_uselen,
use->rpu_keeplen));
ND_PRINT((ndo,")"));
}
}
return;
trunc:
ND_PRINT((ndo,"[|icmp6]"));
}

int ip6_mroute_getsockopt(struct sock *sk, int optname, char __user *optval,
int __user *optlen)
{
int olr;
int val;
struct net *net = sock_net(sk);
struct mr6_table *mrt;
mrt = ip6mr_get_table(net, raw6_sk(sk)->ip6mr_table ? : RT6_TABLE_DFLT);
if (!mrt)
return -ENOENT;
switch (optname) {
case MRT6_VERSION:
val = 0x0305;
break;
#ifdef CONFIG_IPV6_PIMSM_V2
case MRT6_PIM:
val = mrt->mroute_do_pim;
break;
#endif
case MRT6_ASSERT:
val = mrt->mroute_do_assert;
break;
default:
return -ENOPROTOOPT;
}
if (get_user(olr, optlen))
return -EFAULT;
olr = min_t(int, olr, sizeof(int));
if (olr < 0)
return -EINVAL;
if (put_user(olr, optlen))
return -EFAULT;
if (copy_to_user(optval, &val, olr))
return -EFAULT;
return 0;
}

void fx_Number_prototype_toString(txMachine* the)
{
txInteger radix;
txSlot* slot = fxCheckNumber(the, mxThis);
if (!slot) mxTypeError("this is no number");
if ((mxArgc > 0) && (!mxIsUndefined(mxArgv(0)))) {
radix = fxToInteger(the, mxArgv(0));
if ((radix < 2) || (36 < radix))
mxRangeError("invalid radix");
}
else
radix = 10;
mxResult->kind = slot->kind;
mxResult->value = slot->value;
if (radix == 10)
fxToString(the, mxResult);
else {
txNumber value = mxResult->value.number;
switch (c_fpclassify(value)) {
case C_FP_INFINITE:
if (value < 0)
fxStringX(the, mxResult, "-Infinity");
else
fxStringX(the, mxResult, "Infinity");
break;
case C_FP_NAN:
fxStringX(the, mxResult, "NaN");
break;
case C_FP_ZERO:
fxStringX(the, mxResult, "0");
break;
default: {
static const char gxDigits[] ICACHE_FLASH_ATTR = "0123456789abcdefghijklmnopqrstuvwxyz";
txInteger minus;
txNumber integer;
txNumber fraction;
txNumber next;
txU8* nextCast = (txU8*)&next;
txNumber delta;
txSize length;
txString string;
txNumber modulo;
if (value < 0) {
minus = 1;
value = -value;
} 
else
minus = 0;
integer = c_floor(value);
fraction = value - integer;
next = value;
*nextCast = *nextCast + 1;
delta = 0.5 * (next - value);
next = 0;
*nextCast = *nextCast + 1;
if (delta < next)
delta = next;
length = minus + ((integer)? (txSize)c_floor(c_log(integer) / c_log(radix)) : 0) + 1;
if (fraction >= delta) {
#define mxFractionPartLength 2048
txString dot;
txInteger i = 0;
txInteger digit;
string = mxResult->value.string = fxNewChunk(the, length + 1 + mxFractionPartLength + 1);
dot = string + length;
dot[i++] = '.';
do {
fraction *= radix;
delta *= radix;
digit = (txInteger)fraction;
dot[i++] = c_read8(gxDigits + digit);
fraction -= digit;
if (fraction > 0.5 || (fraction == 0.5 && (digit & 1))) {
if (fraction + delta > 1) {
for (;;) {
char c;
i--;
if (i == 0) {
integer += 1;
break;
}
c = dot[i];
digit = c > '9' ? (c - 'a' + 10) : (c - '0');
if (digit + 1 < radix) {
dot[i++] = c_read8(gxDigits + digit + 1);
break;
}
}
break;
}
}
} while ((fraction >= delta) && (i < mxFractionPartLength));
dot[i++] = 0;
length += i;
string = dot;
}
else {
length++;
string = mxResult->value.string = fxNewChunk(the, length);
string += length;
*(--string) = 0;
}
modulo = C_MAX_SAFE_INTEGER * radix;
while (integer > modulo) {
*(--string) = '0';
integer = integer / radix;
}
do {
modulo = c_fmod(integer, radix);
*(--string) = c_read8(gxDigits + (txInteger)modulo);
integer = (integer - modulo) / radix;
} while (integer >= 1);
if (minus) {
*(--string) = '-';
}
minus = (txInteger)(string - mxResult->value.string);
if (minus > 0) {
length -= minus;
c_memmove(mxResult->value.string, string, length);
}
mxResult->value.string = fxRenewChunk(the, mxResult->value.string, length);
mxResult->kind = XS_STRING_KIND;
}}
}
}

static void parse_generic_line(pj_scanner *scanner, pj_str_t *str,
volatile parse_context *ctx)
{
