static Image *ReadVIDEOImage(const ImageInfo *image_info,
ExceptionInfo *exception)
{
const DelegateInfo
*delegate_info;
Image
*image,
*images,
*next;
ImageInfo
*read_info;
MagickBooleanType
status;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
if (IsEventLogging() != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
image=AcquireImage(image_info,exception);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
(void) CloseBlob(image);
(void) DestroyImageList(image);
images=(Image *) NULL;
read_info=CloneImageInfo(image_info);
delegate_info=GetDelegateInfo("video:decode",(char *) NULL,exception);
if (delegate_info != (const DelegateInfo *) NULL)
{
char
command[MagickPathExtent],
message[MagickPathExtent];
char
*options,
*sanitized_option;
const char
*intermediate_format,
*option;
int
exit_code;
options=AcquireString("");
if (image_info->number_scenes > 0)
(void) FormatLocaleString(options,MagickPathExtent,"-vframes %i",
(int) image_info->number_scenes);
option=GetImageOption(image_info,"video:vsync");
if (option != (const char *) NULL)
{
sanitized_option=SanitizeDelegateString(option);
(void) FormatLocaleString(command,MagickPathExtent," -vsync %s",
sanitized_option);
DestroyString(sanitized_option);
(void) ConcatenateMagickString(options,command,MagickPathExtent);
}
option=GetImageOption(image_info,"video:pixel-format");
if (option != (const char *) NULL)
{
sanitized_option=SanitizeDelegateString(option);
(void) FormatLocaleString(command,MagickPathExtent," -pix_fmt %s",
sanitized_option);
DestroyString(sanitized_option);
(void) ConcatenateMagickString(options,command,MagickPathExtent);
}
else
if (LocaleNCompare(image_info->magick,"APNG",MagickPathExtent) == 0)
(void) ConcatenateMagickString(options," -pix_fmt rgba",
MagickPathExtent);
intermediate_format=GetIntermediateFormat(image_info);
(void) FormatLocaleString(command,MagickPathExtent," -vcodec %s",
intermediate_format);
(void) ConcatenateMagickString(options,command,MagickPathExtent);
AcquireUniqueFilename(read_info->unique);
(void) AcquireUniqueSymbolicLink(image_info->filename,
read_info->filename);
(void) FormatLocaleString(command,MagickPathExtent,
GetDelegateCommands(delegate_info),read_info->filename,options,
read_info->unique);
options=DestroyString(options);
(void) CopyMagickString(read_info->magick,intermediate_format,
MagickPathExtent);
(void) CopyMagickString(read_info->filename,read_info->unique,
MagickPathExtent);
exit_code=ExternalDelegateCommand(MagickFalse,image_info->verbose,
command,message,exception);
if (exit_code == 0)
images=ReadImage(read_info,exception);
else
if (*message != '\0')
(void) ThrowMagickException(exception,GetMagickModule(),DelegateError,
"VideoDelegateFailed","`%s'",message);
(void) RelinquishUniqueFileResource(read_info->filename);
(void) RelinquishUniqueFileResource(read_info->unique);
if (images != (Image *) NULL)
for (next=images; next != (Image *) NULL; next=next->next)
{
(void) CopyMagickString(next->filename,image_info->filename,
MagickPathExtent);
(void) CopyMagickString(next->magick,image_info->magick,
MagickPathExtent);
}
}
read_info=DestroyImageInfo(read_info);
return(images);
}

status_t IPCThreadState::executeCommand(int32_t cmd)
{
BBinder* obj;
RefBase::weakref_type* refs;
status_t result = NO_ERROR;
switch ((uint32_t)cmd) {
case BR_ERROR:
result = mIn.readInt32();
break;
case BR_OK:
break;
case BR_ACQUIRE:
refs = (RefBase::weakref_type*)mIn.readPointer();
obj = (BBinder*)mIn.readPointer();
ALOG_ASSERT(refs->refBase() == obj,
"BR_ACQUIRE: object %p does not match cookie %p (expected %p)",
refs, obj, refs->refBase());
obj->incStrong(mProcess.get());
IF_LOG_REMOTEREFS() {
LOG_REMOTEREFS("BR_ACQUIRE from driver on %p", obj);
obj->printRefs();
}
mOut.writeInt32(BC_ACQUIRE_DONE);
mOut.writePointer((uintptr_t)refs);
mOut.writePointer((uintptr_t)obj);
break;
case BR_RELEASE:
refs = (RefBase::weakref_type*)mIn.readPointer();
obj = (BBinder*)mIn.readPointer();
ALOG_ASSERT(refs->refBase() == obj,
"BR_RELEASE: object %p does not match cookie %p (expected %p)",
refs, obj, refs->refBase());
IF_LOG_REMOTEREFS() {
LOG_REMOTEREFS("BR_RELEASE from driver on %p", obj);
obj->printRefs();
}
mPendingStrongDerefs.push(obj);
break;
case BR_INCREFS:
refs = (RefBase::weakref_type*)mIn.readPointer();
obj = (BBinder*)mIn.readPointer();
refs->incWeak(mProcess.get());
mOut.writeInt32(BC_INCREFS_DONE);
mOut.writePointer((uintptr_t)refs);
mOut.writePointer((uintptr_t)obj);
break;
case BR_DECREFS:
refs = (RefBase::weakref_type*)mIn.readPointer();
obj = (BBinder*)mIn.readPointer();
mPendingWeakDerefs.push(refs);
break;
case BR_ATTEMPT_ACQUIRE:
refs = (RefBase::weakref_type*)mIn.readPointer();
obj = (BBinder*)mIn.readPointer();
{
const bool success = refs->attemptIncStrong(mProcess.get());
ALOG_ASSERT(success && refs->refBase() == obj,
"BR_ATTEMPT_ACQUIRE: object %p does not match cookie %p (expected %p)",
refs, obj, refs->refBase());
mOut.writeInt32(BC_ACQUIRE_RESULT);
mOut.writeInt32((int32_t)success);
}
break;
case BR_TRANSACTION:
{
binder_transaction_data tr;
result = mIn.read(&tr, sizeof(tr));
ALOG_ASSERT(result == NO_ERROR,
"Not enough command data for brTRANSACTION");
if (result != NO_ERROR) break;
Parcel buffer;
buffer.ipcSetDataReference(
reinterpret_cast<const uint8_t*>(tr.data.ptr.buffer),
tr.data_size,
reinterpret_cast<const binder_size_t*>(tr.data.ptr.offsets),
tr.offsets_size/sizeof(binder_size_t), freeBuffer, this);
const pid_t origPid = mCallingPid;
const uid_t origUid = mCallingUid;
const int32_t origStrictModePolicy = mStrictModePolicy;
const int32_t origTransactionBinderFlags = mLastTransactionBinderFlags;
mCallingPid = tr.sender_pid;
mCallingUid = tr.sender_euid;
mLastTransactionBinderFlags = tr.flags;
int curPrio = getpriority(PRIO_PROCESS, mMyThreadId);
if (gDisableBackgroundScheduling) {
if (curPrio > ANDROID_PRIORITY_NORMAL) {
setpriority(PRIO_PROCESS, mMyThreadId, ANDROID_PRIORITY_NORMAL);
}
} else {
if (curPrio >= ANDROID_PRIORITY_BACKGROUND) {
set_sched_policy(mMyThreadId, SP_BACKGROUND);
}
}
Parcel reply;
status_t error;
IF_LOG_TRANSACTIONS() {
TextOutput::Bundle _b(alog);
alog << "BR_TRANSACTION thr " << (void*)pthread_self()
<< " / obj " << tr.target.ptr << " / code "
<< TypeCode(tr.code) << ": " << indent << buffer
<< dedent << endl
<< "Data addr = "
<< reinterpret_cast<const uint8_t*>(tr.data.ptr.buffer)
<< ", offsets addr="
<< reinterpret_cast<const size_t*>(tr.data.ptr.offsets) << endl;
}
if (tr.target.ptr) {
sp<BBinder> b((BBinder*)tr.cookie);
error = b->transact(tr.code, buffer, &reply, tr.flags);
} else {
error = the_context_object->transact(tr.code, buffer, &reply, tr.flags);
}
if ((tr.flags & TF_ONE_WAY) == 0) {
LOG_ONEWAY("Sending reply to %d!", mCallingPid);
if (error < NO_ERROR) reply.setError(error);
sendReply(reply, 0);
} else {
LOG_ONEWAY("NOT sending reply to %d!", mCallingPid);
}
mCallingPid = origPid;
mCallingUid = origUid;
mStrictModePolicy = origStrictModePolicy;
mLastTransactionBinderFlags = origTransactionBinderFlags;
IF_LOG_TRANSACTIONS() {
TextOutput::Bundle _b(alog);
alog << "BC_REPLY thr " << (void*)pthread_self() << " / obj "
<< tr.target.ptr << ": " << indent << reply << dedent << endl;
}
}
break;
case BR_DEAD_BINDER:
{
BpBinder *proxy = (BpBinder*)mIn.readPointer();
proxy->sendObituary();
mOut.writeInt32(BC_DEAD_BINDER_DONE);
mOut.writePointer((uintptr_t)proxy);
} break;
case BR_CLEAR_DEATH_NOTIFICATION_DONE:
{
BpBinder *proxy = (BpBinder*)mIn.readPointer();
proxy->getWeakRefs()->decWeak(proxy);
} break;
case BR_FINISHED:
result = TIMED_OUT;
break;
case BR_NOOP:
break;
case BR_SPAWN_LOOPER:
mProcess->spawnPooledThread(false);
break;
default:
printf("*** BAD COMMAND %d received from Binder driver\n", cmd);
result = UNKNOWN_ERROR;
break;
}
if (result != NO_ERROR) {
mLastError = result;
}
return result;
}

static int DoTls13CertificateVerify(WOLFSSL* ssl, byte* input,
word32* inOutIdx, word32 totalSz)
{
int         ret = 0;
buffer*     sig = &ssl->buffers.sig;
#ifdef WOLFSSL_ASYNC_CRYPT
Dcv13Args* args = (Dcv13Args*)ssl->async.args;
typedef char args_test[sizeof(ssl->async.args) >= sizeof(*args) ? 1 : -1];
(void)sizeof(args_test);
#else
Dcv13Args  args[1];
#endif
WOLFSSL_START(WC_FUNC_CERTIFICATE_VERIFY_DO);
WOLFSSL_ENTER("DoTls13CertificateVerify");
#ifdef WOLFSSL_ASYNC_CRYPT
ret = wolfSSL_AsyncPop(ssl, &ssl->options.asyncState);
if (ret != WC_NOT_PENDING_E) {
if (ret < 0)
goto exit_dcv;
}
else
#endif
{
ret = 0;
ssl->options.asyncState = TLS_ASYNC_BEGIN;
XMEMSET(args, 0, sizeof(Dcv13Args));
args->hashAlgo = sha_mac;
args->sigAlgo = anonymous_sa_algo;
args->idx = *inOutIdx;
args->begin = *inOutIdx;
#ifdef WOLFSSL_ASYNC_CRYPT
ssl->async.freeArgs = FreeDcv13Args;
#endif
}
switch(ssl->options.asyncState)
{
case TLS_ASYNC_BEGIN:
{
#ifdef WOLFSSL_CALLBACKS
if (ssl->hsInfoOn) AddPacketName(ssl, "CertificateVerify");
if (ssl->toInfoOn) AddLateName("CertificateVerify",
&ssl->timeoutInfo);
#endif
ssl->options.asyncState = TLS_ASYNC_BUILD;
} 
FALL_THROUGH;
case TLS_ASYNC_BUILD:
{
if ((args->idx - args->begin) + ENUM_LEN + ENUM_LEN > totalSz) {
ERROR_OUT(BUFFER_ERROR, exit_dcv);
}
ret = DecodeTls13SigAlg(input + args->idx, &args->hashAlgo,
&args->sigAlgo);
if (ret < 0)
goto exit_dcv;
args->idx += OPAQUE16_LEN;
if ((args->idx - args->begin) + OPAQUE16_LEN > totalSz) {
ERROR_OUT(BUFFER_ERROR, exit_dcv);
}
ato16(input + args->idx, &args->sz);
args->idx += OPAQUE16_LEN;
if ((args->idx - args->begin) + args->sz > totalSz ||
args->sz > ENCRYPT_LEN) {
ERROR_OUT(BUFFER_ERROR, exit_dcv);
}
#ifdef HAVE_ED25519
if (args->sigAlgo == ed25519_sa_algo &&
!ssl->peerEd25519KeyPresent) {
WOLFSSL_MSG("Oops, peer sent ED25519 key but not in verify");
}
#endif
#ifdef HAVE_ED448
if (args->sigAlgo == ed448_sa_algo && !ssl->peerEd448KeyPresent) {
WOLFSSL_MSG("Oops, peer sent ED448 key but not in verify");
}
#endif
#ifdef HAVE_ECC
if (args->sigAlgo == ecc_dsa_sa_algo &&
!ssl->peerEccDsaKeyPresent) {
WOLFSSL_MSG("Oops, peer sent ECC key but not in verify");
}
#endif
#ifndef NO_RSA
if (args->sigAlgo == rsa_sa_algo) {
WOLFSSL_MSG("Oops, peer sent PKCS#1.5 signature");
ERROR_OUT(INVALID_PARAMETER, exit_dcv);
}
if (args->sigAlgo == rsa_pss_sa_algo &&
(ssl->peerRsaKey == NULL || !ssl->peerRsaKeyPresent)) {
WOLFSSL_MSG("Oops, peer sent RSA key but not in verify");
}
#endif
sig->buffer = (byte*)XMALLOC(args->sz, ssl->heap,
DYNAMIC_TYPE_SIGNATURE);
if (sig->buffer == NULL) {
ERROR_OUT(MEMORY_E, exit_dcv);
}
sig->length = args->sz;
XMEMCPY(sig->buffer, input + args->idx, args->sz);
#ifdef HAVE_ECC
if (ssl->peerEccDsaKeyPresent) {
WOLFSSL_MSG("Doing ECC peer cert verify");
args->sigData = (byte*)XMALLOC(MAX_SIG_DATA_SZ, ssl->heap,
DYNAMIC_TYPE_SIGNATURE);
if (args->sigData == NULL) {
ERROR_OUT(MEMORY_E, exit_dcv);
}
ret = CreateSigData(ssl, args->sigData, &args->sigDataSz, 1);
if (ret != 0)
goto exit_dcv;
ret = CreateECCEncodedSig(args->sigData,
args->sigDataSz, args->hashAlgo);
if (ret < 0)
goto exit_dcv;
args->sigDataSz = (word16)ret;
ret = 0;
}
#endif
#ifdef HAVE_ED25519
if (ssl->peerEd25519KeyPresent) {
WOLFSSL_MSG("Doing ED25519 peer cert verify");
args->sigData = (byte*)XMALLOC(MAX_SIG_DATA_SZ, ssl->heap,
DYNAMIC_TYPE_SIGNATURE);
if (args->sigData == NULL) {
ERROR_OUT(MEMORY_E, exit_dcv);
}
CreateSigData(ssl, args->sigData, &args->sigDataSz, 1);
ret = 0;
}
#endif
#ifdef HAVE_ED448
if (ssl->peerEd448KeyPresent) {
WOLFSSL_MSG("Doing ED448 peer cert verify");
args->sigData = (byte*)XMALLOC(MAX_SIG_DATA_SZ, ssl->heap,
DYNAMIC_TYPE_SIGNATURE);
if (args->sigData == NULL) {
ERROR_OUT(MEMORY_E, exit_dcv);
}
CreateSigData(ssl, args->sigData, &args->sigDataSz, 1);
ret = 0;
}
#endif
ssl->options.asyncState = TLS_ASYNC_DO;
} 
FALL_THROUGH;
case TLS_ASYNC_DO:
{
#ifndef NO_RSA
if (ssl->peerRsaKey != NULL && ssl->peerRsaKeyPresent != 0) {
WOLFSSL_MSG("Doing RSA peer cert verify");
ret = RsaVerify(ssl, sig->buffer, (word32)sig->length, &args->output,
args->sigAlgo, args->hashAlgo, ssl->peerRsaKey,
#ifdef HAVE_PK_CALLBACKS
&ssl->buffers.peerRsaKey
#else
NULL
#endif
);
if (ret >= 0) {
args->sendSz = ret;
ret = 0;
}
}
#endif 
#ifdef HAVE_ECC
if (ssl->peerEccDsaKeyPresent) {
WOLFSSL_MSG("Doing ECC peer cert verify");
ret = EccVerify(ssl, input + args->idx, args->sz,
args->sigData, args->sigDataSz,
ssl->peerEccDsaKey,
#ifdef HAVE_PK_CALLBACKS
&ssl->buffers.peerEccDsaKey
#else
NULL
#endif
);
if (ret >= 0) {
FreeKey(ssl, DYNAMIC_TYPE_ECC, (void**)&ssl->peerEccDsaKey);
ssl->peerEccDsaKeyPresent = 0;
}
}
#endif 
#ifdef HAVE_ED25519
if (ssl->peerEd25519KeyPresent) {
WOLFSSL_MSG("Doing ED25519 peer cert verify");
ret = Ed25519Verify(ssl, input + args->idx, args->sz,
args->sigData, args->sigDataSz,
ssl->peerEd25519Key,
#ifdef HAVE_PK_CALLBACKS
&ssl->buffers.peerEd25519Key
#else
NULL
#endif
);
if (ret >= 0) {
FreeKey(ssl, DYNAMIC_TYPE_ED25519,
(void**)&ssl->peerEd25519Key);
ssl->peerEd25519KeyPresent = 0;
}
}
#endif
#ifdef HAVE_ED448
if (ssl->peerEd448KeyPresent) {
WOLFSSL_MSG("Doing ED448 peer cert verify");
ret = Ed448Verify(ssl, input + args->idx, args->sz,
args->sigData, args->sigDataSz,
ssl->peerEd448Key,
#ifdef HAVE_PK_CALLBACKS
&ssl->buffers.peerEd448Key
#else
NULL
#endif
);
if (ret >= 0) {
FreeKey(ssl, DYNAMIC_TYPE_ED448,
(void**)&ssl->peerEd448Key);
ssl->peerEd448KeyPresent = 0;
}
}
#endif
if (ret != 0) {
goto exit_dcv;
}
ssl->options.asyncState = TLS_ASYNC_VERIFY;
} 
FALL_THROUGH;
case TLS_ASYNC_VERIFY:
{
#if !defined(NO_RSA) && defined(WC_RSA_PSS)
if (ssl->peerRsaKey != NULL && ssl->peerRsaKeyPresent != 0) {
ret = CheckRSASignature(ssl, args->sigAlgo, args->hashAlgo,
args->output, args->sendSz);
if (ret != 0)
goto exit_dcv;
FreeKey(ssl, DYNAMIC_TYPE_RSA, (void**)&ssl->peerRsaKey);
ssl->peerRsaKeyPresent = 0;
}
#endif 
ssl->options.asyncState = TLS_ASYNC_FINALIZE;
} 
FALL_THROUGH;
case TLS_ASYNC_FINALIZE:
{
ssl->options.havePeerVerify = 1;
args->idx += args->sz;
*inOutIdx = args->idx;
*inOutIdx += ssl->keys.padSz;
ssl->options.asyncState = TLS_ASYNC_END;
#if !defined(NO_WOLFSSL_CLIENT)
if (ssl->options.side == WOLFSSL_CLIENT_END)
ssl->options.serverState = SERVER_CERT_VERIFY_COMPLETE;
#endif
} 
case TLS_ASYNC_END:
{
break;
}
default:
ret = INPUT_CASE_ERROR;
} 
exit_dcv:
WOLFSSL_LEAVE("DoTls13CertificateVerify", ret);
WOLFSSL_END(WC_FUNC_CERTIFICATE_VERIFY_DO);
#ifdef WOLFSSL_ASYNC_CRYPT
if (ret == WC_PENDING_E) {
ssl->msgsReceived.got_certificate_verify = 0;
return ret;
}
else
#endif 
if (ret != 0 && ret != INVALID_PARAMETER)
SendAlert(ssl, alert_fatal, decrypt_error);
FreeDcv13Args(ssl, args);
FreeKeyExchange(ssl);
return ret;
}

void union_ (const hb_bit_set_invertible_t &other)
{
if (likely (inverted == other.inverted))
{
if (unlikely (inverted))
process (hb_bitwise_and, other);
else
process (hb_bitwise_or, other); 
}
else
{
if (unlikely (inverted))
process (hb_bitwise_gt, other);
else
process (hb_bitwise_lt, other);
}
inverted = inverted || other.inverted;
}

static const char *
build_pathname(struct archive_string *as, struct file_info *file)
{
if (file->parent != NULL && archive_strlen(&file->parent->name) > 0) {
build_pathname(as, file->parent);
archive_strcat(as, "/");
}
if (archive_strlen(&file->name) == 0)
archive_strcat(as, ".");
else
archive_string_concat(as, &file->name);
return (as->s);
}

uint8_t* picoquic_decode_new_connection_id_frame(picoquic_cnx_t* cnx, uint8_t* bytes, const uint8_t* bytes_max, uint64_t current_time)
{
uint64_t sequence = 0;
uint64_t retire_before = 0;
uint8_t cid_length = 0;
uint8_t * cnxid_bytes = NULL;
uint8_t * secret_bytes = NULL;
if ((bytes = picoquic_frames_varint_decode(bytes + 1, bytes_max, &sequence)) != NULL) {
bytes = picoquic_frames_varint_decode(bytes, bytes_max, &retire_before);
if (bytes != NULL) {
bytes = picoquic_frames_uint8_decode(bytes, bytes_max, &cid_length);
}
}
if (bytes != NULL) {
cnxid_bytes = bytes;
secret_bytes = bytes + cid_length;
bytes = picoquic_frames_fixed_skip(bytes, bytes_max, (size_t)cid_length + PICOQUIC_RESET_SECRET_SIZE);
}
if (bytes == NULL || cid_length > PICOQUIC_CONNECTION_ID_MAX_SIZE ||
retire_before > sequence) {
picoquic_connection_error(cnx, (bytes == NULL) ? PICOQUIC_TRANSPORT_FRAME_FORMAT_ERROR : PICOQUIC_TRANSPORT_PROTOCOL_VIOLATION,
picoquic_frame_type_new_connection_id);
} else {
uint16_t ret = 0;
if (bytes != NULL && retire_before > cnx->retire_cnxid_before) {
ret = (uint16_t)picoquic_remove_not_before_cid(cnx, retire_before, current_time);
}
if (ret == 0 && sequence >= cnx->retire_cnxid_before) {
ret = (uint16_t)picoquic_enqueue_cnxid_stash(cnx, sequence, cid_length, cnxid_bytes, secret_bytes, NULL);
}
if (ret != 0) {
picoquic_connection_error(cnx, ret, picoquic_frame_type_new_connection_id);
bytes = NULL;
}
}
return bytes;
}

int main(int argc, char * * argv) {
struct ngiflib_gif * gif;
struct ngiflib_img * img;
int err, i;
char tganame[256];
const char * input_file = NULL;
int indexed = 0;
const char * outbase = NULL;
FILE * log = NULL;
#ifdef NGIFLIB_NO_FILE
long filesize;
u8 * buffer;
#endif 
if(argc<2) {
printf("Usage: %s [--log logfile] [--indexed|-i] [--outbase path/file] truc.gif\n", argv[0]);
return 1;
}
for(i=1; i < argc; i++) {
if(argv[i][0] == '-') {
if(strcmp(argv[i], "--indexed") == 0
|| strcmp(argv[i], "-i") == 0) {
indexed = 1;
} else if(strcmp(argv[i], "--outbase") == 0) {
if(++i >= argc) {
fprintf(stderr, "option %s need one argument.\n", argv[i - 1]);
return 2;
}
outbase = argv[i];
} else if(strcmp(argv[i], "--log") == 0) {
if(++i >= argc) {
fprintf(stderr, "option %s need one argument.\n", argv[i - 1]);
return 2;
}
log = fopen(argv[i], "w");
if(log == NULL) fprintf(stderr, "failed to open log file %s\n", argv[i]);
} else {
fprintf(stderr, "%s: unknown option.\n", argv[i]);
return 2;
}
} else if(input_file == NULL) {
input_file = argv[i];
} else {
fprintf(stderr, "%s: invalid argument.\n", argv[i]);
return 2;
}
}
gif = (struct ngiflib_gif *)malloc(sizeof(struct ngiflib_gif));
memset(gif, 0, sizeof(struct ngiflib_gif));
#ifndef NGIFLIB_NO_FILE
gif->log = log;
#endif 
fgif = fopen(input_file, "rb");
if(fgif==NULL) {
printf("Cannot open %s\n", input_file);
return 3;
}
#ifdef NGIFLIB_NO_FILE
fseek(fgif, 0, SEEK_END);
filesize = ftell(fgif);
fseek(fgif, 0, SEEK_SET);
buffer = malloc(filesize);
if(buffer == NULL) {
printf("Cannot allocate %ld bytes of memory.\n", filesize);
fclose(fgif);
return 4;
}
fread(buffer, 1, filesize, fgif);
gif->input.bytes = buffer;
gif->mode = NGIFLIB_MODE_FROM_MEM;
#else 
gif->input.file = fgif;
gif->mode = NGIFLIB_MODE_FROM_FILE;
#endif 
if(indexed) {
gif->mode |= NGIFLIB_MODE_INDEXED;
printf("INDEXED MODE\n");
} else gif->mode |= NGIFLIB_MODE_TRUE_COLOR;
do {
err = LoadGif(gif); 
printf("LoadGif() returned %d\n", err);
if(err==1) {
int localpalsize;
char * p;
img = gif->cur_img;
localpalsize = 1 << img->localpalbits;
if(outbase) {
p = tganame + snprintf(tganame, sizeof(tganame), "%s", outbase);
} else {
snprintf(tganame, sizeof(tganame), "%s", input_file);
p = strrchr(tganame, '.');
if(p == NULL) {
p = tganame + strlen(tganame);
}
}
sprintf(p, "_out%02d.tga", gif->nimg);
ftga = fopen(tganame, "wb");
if(ftga == NULL) {
fprintf(stderr, "cannot open file %s for writing.\n", tganame);
return 5;
}
putc(0, ftga);
if(gif->mode & NGIFLIB_MODE_INDEXED) {
putc(1, ftga);
putc(1, ftga);
putc(0, ftga);
putc(0, ftga);
putc(localpalsize & 255, ftga);
putc(localpalsize >> 8, ftga);
putc(24, ftga);
for(i=0; i<4; i++) putc(0, ftga);
} else {
putc(0, ftga);
putc(2, ftga);
for(i=0; i<9; i++) putc(0, ftga);
}
putc(gif->width & 255, ftga);
putc(gif->width >> 8, ftga);
putc(gif->height & 255, ftga);
putc(gif->height >>8, ftga);
if(gif->mode & NGIFLIB_MODE_INDEXED) {
putc(8, ftga);
putc(32, ftga);
for(i=0; i<localpalsize; i++) {
putc(img->palette[i].b, ftga);
putc(img->palette[i].g, ftga);
putc(img->palette[i].r, ftga);
}
fwrite(gif->frbuff.p8, 1,
(size_t)gif->width * (size_t)gif->height, ftga);
} else {
long l;
u32 pixel;
putc(32, ftga);
putc(32+8, ftga); 
for(l = 0; l < (long)gif->width * (long)gif->height; l++) {
pixel = gif->frbuff.p32[l];
putc(pixel & 0xff, ftga);
putc((pixel >> 8) & 0xff, ftga);
putc((pixel >> 16) & 0xff, ftga);
putc(0xff, ftga);
}
}
fclose(ftga);
printf("%s written\n",tganame);
}
} while(err==1);
fclose(fgif);
#ifdef NGIFLIB_NO_FILE
free(buffer);
#endif 
#if DEBUG
fprintf_ngiflib_gif(stdout, gif);
#endif 
GifDestroy(gif);
if(log) fclose(log);
return 0;
}

OMX_ERRORTYPE SoftMPEG4Encoder::initEncParams() {
CHECK(mHandle != NULL);
memset(mHandle, 0, sizeof(tagvideoEncControls));
CHECK(mEncParams != NULL);
memset(mEncParams, 0, sizeof(tagvideoEncOptions));
if (!PVGetDefaultEncOption(mEncParams, 0)) {
ALOGE("Failed to get default encoding parameters");
return OMX_ErrorUndefined;
}
mEncParams->encMode = mEncodeMode;
mEncParams->encWidth[0] = mWidth;
mEncParams->encHeight[0] = mHeight;
mEncParams->encFrameRate[0] = mFramerate >> 16;     mEncParams->rcType = VBR_1;
mEncParams->vbvDelay = 5.0f;
mEncParams->profile_level = CORE_PROFILE_LEVEL2;
mEncParams->packetSize = 32;
mEncParams->rvlcEnable = PV_OFF;
mEncParams->numLayers = 1;
mEncParams->timeIncRes = 1000;
mEncParams->tickPerSrc = ((int64_t)mEncParams->timeIncRes << 16) / mFramerate;
mEncParams->bitRate[0] = mBitrate;
mEncParams->iQuant[0] = 15;
mEncParams->pQuant[0] = 12;
mEncParams->quantType[0] = 0;
mEncParams->noFrameSkipped = PV_OFF;
if (mColorFormat != OMX_COLOR_FormatYUV420Planar || mInputDataIsMeta) {
free(mInputFrameData);
mInputFrameData = NULL;
if (((uint64_t)mWidth * mHeight) > ((uint64_t)INT32_MAX / 3)) {
ALOGE("b/25812794, Buffer size is too big.");
return OMX_ErrorBadParameter;
}
mInputFrameData =
(uint8_t *) malloc((mWidth * mHeight * 3 ) >> 1);
CHECK(mInputFrameData != NULL);
}
if (mWidth % 16 != 0 || mHeight % 16 != 0) {
ALOGE("Video frame size %dx%d must be a multiple of 16",
mWidth, mHeight);
return OMX_ErrorBadParameter;
}
if (mIDRFrameRefreshIntervalInSec < 0) {
mEncParams->intraPeriod = -1;
} else if (mIDRFrameRefreshIntervalInSec == 0) {
mEncParams->intraPeriod = 1;      } else {
mEncParams->intraPeriod =
(mIDRFrameRefreshIntervalInSec * mFramerate) >> 16;
}
mEncParams->numIntraMB = 0;
mEncParams->sceneDetect = PV_ON;
mEncParams->searchRange = 16;
mEncParams->mv8x8Enable = PV_OFF;
mEncParams->gobHeaderInterval = 0;
mEncParams->useACPred = PV_ON;
mEncParams->intraDCVlcTh = 0;
return OMX_ErrorNone;
}

int
nbd_unlocked_opt_info (struct nbd_handle *h)
{
int err;
nbd_completion_callback c = { .callback = go_complete, .user_data = &err };
int r = nbd_unlocked_aio_opt_info (h, &c);
if (r == -1)
return r;
r = wait_for_option (h);
if (r == 0 && err) {
assert (nbd_internal_is_state_negotiating (get_next_state (h)));
set_error (err, "server replied with error to opt_info request");
return -1;
}
return r;
}

void WT_VoiceFilter (S_FILTER_CONTROL *pFilter, S_WT_INT_FRAME *pWTIntFrame)
{
EAS_PCM *pAudioBuffer;
EAS_I32 k;
EAS_I32 b1;
EAS_I32 b2;
EAS_I32 z1;
EAS_I32 z2;
EAS_I32 acc0;
EAS_I32 acc1;
EAS_I32 numSamples;
numSamples = pWTIntFrame->numSamples;
if (numSamples <= 0) {
ALOGE("b/26366256");
return;
}
pAudioBuffer = pWTIntFrame->pAudioBuffer;
z1 = pFilter->z1;
z2 = pFilter->z2;
b1 = -pWTIntFrame->frame.b1;
b2 = -pWTIntFrame->frame.b2 >> 1;
k = pWTIntFrame->frame.k >> 1;
while (numSamples--)
{
acc0 = *pAudioBuffer;
acc1 = z1 * b1;
acc1 += z2 * b2;
acc0 = acc1 + k * acc0;
z2 = z1;
z1 = acc0 >> 14;
*pAudioBuffer++ = (EAS_I16) z1;
}
pFilter->z1 = (EAS_I16) z1;
pFilter->z2 = (EAS_I16) z2;
}

void
spell_add_word(
char_u*word,
intlen,
intwhat,        intidx,            intundo)    {
FILE*fd = NULL;
buf_T*buf = NULL;
intnew_spf = FALSE;
char_u*fname;
char_u*fnamebuf = NULL;
char_uline[MAXWLEN * 2];
longfpos, fpos_next = 0;
inti;
char_u*spf;
if (idx == 0)        {
if (int_wordlist == NULL)
{
int_wordlist = vim_tempname('s', FALSE);
if (int_wordlist == NULL)
return;
}
fname = int_wordlist;
}
else
{
if (*curwin->w_s->b_p_spf == NUL)
{
init_spellfile();
new_spf = TRUE;
}
if (*curwin->w_s->b_p_spf == NUL)
{
semsg(_(e_option_str_is_not_set), "spellfile");
return;
}
fnamebuf = alloc(MAXPATHL);
if (fnamebuf == NULL)
return;
for (spf = curwin->w_s->b_p_spf, i = 1; *spf != NUL; ++i)
{
copy_option_part(&spf, fnamebuf, MAXPATHL, ",");
if (i == idx)
break;
if (*spf == NUL)
{
semsg(_(e_spellfile_does_not_have_nr_entries), idx);
vim_free(fnamebuf);
return;
}
}
buf = buflist_findname_exp(fnamebuf);
if (buf != NULL && buf->b_ml.ml_mfp == NULL)
buf = NULL;
if (buf != NULL && bufIsChanged(buf))
{
emsg(_(e_file_is_loaded_in_another_buffer));
vim_free(fnamebuf);
return;
}
fname = fnamebuf;
}
if (what == SPELL_ADD_BAD || undo)
{
fd = mch_fopen((char *)fname, "r");
if (fd != NULL)
{
while (!vim_fgets(line, MAXWLEN * 2, fd))
{
fpos = fpos_next;
fpos_next = ftell(fd);
if (fpos_next < 0)
break;  if (STRNCMP(word, line, len) == 0
&& (line[len] == '/' || line[len] < ' '))
{
fclose(fd);
fd = mch_fopen((char *)fname, "r+");
if (fd == NULL)
break;
if (fseek(fd, fpos, SEEK_SET) == 0)
{
fputc('#', fd);
if (undo)
{
home_replace(NULL, fname, NameBuff, MAXPATHL, TRUE);
smsg(_("Word '%.*s' removed from %s"),
len, word, NameBuff);
}
}
if (fseek(fd, fpos_next, SEEK_SET) != 0)
{
PERROR(_("Seek error in spellfile"));
break;
}
}
}
if (fd != NULL)
fclose(fd);
}
}
if (!undo)
{
fd = mch_fopen((char *)fname, "a");
if (fd == NULL && new_spf)
{
char_u *p;
if (!dir_of_file_exists(fname) && (p = gettail_sep(fname)) != fname)
{
int c = *p;
*p = NUL;
vim_mkdir(fname, 0755);
*p = c;
fd = mch_fopen((char *)fname, "a");
}
}
if (fd == NULL)
semsg(_(e_cant_open_file_str), fname);
else
{
if (what == SPELL_ADD_BAD)
fprintf(fd, "%.*s/!\n", len, word);
else if (what == SPELL_ADD_RARE)
fprintf(fd, "%.*s/?\n", len, word);
else
fprintf(fd, "%.*s\n", len, word);
fclose(fd);
home_replace(NULL, fname, NameBuff, MAXPATHL, TRUE);
smsg(_("Word '%.*s' added to %s"), len, word, NameBuff);
}
}
if (fd != NULL)
{
mkspell(1, &fname, FALSE, TRUE, TRUE);
if (buf != NULL)
buf_reload(buf, buf->b_orig_mode, FALSE);
redraw_all_later(SOME_VALID);
}
vim_free(fnamebuf);
}

static int
ztype(i_ctx_t *i_ctx_p)
{
os_ptr op = osp;
ref tnref;
int code = array_get(imemory, op, (long)r_btype(op - 1), &tnref);
if (code < 0)
return code;
if (!r_has_type(&tnref, t_name)) {
check_op(2);
{                       
if (op[-1].value.pstruct != 0x00) {
const char *sname =
gs_struct_type_name_string(gs_object_type(imemory,
op[-1].value.pstruct));
int code = name_ref(imemory, (const byte *)sname, strlen(sname),
(ref *) (op - 1), 0);
if (code < 0)
return code;
} else
return_error(gs_error_stackunderflow);
}
r_set_attrs(op - 1, a_executable);
} else {
ref_assign(op - 1, &tnref);
}
pop(1);
return 0;
}

