static gint dissect_dmp_security_category (tvbuff_t *tvb, packet_info *pinfo,
proto_tree *tree,
const gchar **label_string,
gint offset, guint8 ext)
{
proto_tree *field_tree = NULL;
proto_item *tf = NULL, *tr = NULL;
gchar      *sec_cat = NULL;
guint8      message;
gboolean    country_code = FALSE;
message = tvb_get_guint8 (tvb, offset);
tf = proto_tree_add_uint_format (tree, hf_message_sec_cat_nat, tvb,
offset, 1, message, "Security Categories");
field_tree = proto_item_add_subtree (tf, ett_message_sec_cat);
switch (ext) {
case SEC_CAT_EXT_NONE:
proto_tree_add_item (field_tree, hf_message_sec_cat_cl, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item (field_tree, hf_message_sec_cat_cs, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item (field_tree, hf_message_sec_cat_ex, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item (field_tree, hf_message_sec_cat_ne, tvb, offset, 1, ENC_BIG_ENDIAN);
tr = proto_tree_add_item (field_tree, hf_reserved_0x08, tvb, offset, 1, ENC_BIG_ENDIAN);
if (message & 0x08) {
expert_add_info(pinfo, tr, &ei_reserved_value);
}
tr = proto_tree_add_item (field_tree, hf_reserved_0x04, tvb, offset, 1, ENC_BIG_ENDIAN);
if (message & 0x04) {
expert_add_info(pinfo, tr, &ei_reserved_value);
}
if (message & 0xF0) {
sec_cat = wmem_strdup_printf (wmem_packet_scope(), "%s%s%s%s",
(message & 0x80) ? ",cl" : "",
(message & 0x40) ? ",cs" : "",
(message & 0x20) ? ",ex" : "",
(message & 0x10) ? ",ne" : "");
proto_item_append_text (tf, ": %s", &sec_cat[1]);
*label_string = wmem_strconcat(wmem_packet_scope(), *label_string, sec_cat, NULL);
}
break;
case SEC_CAT_EXT_PERMISSIVE:
if ((message >> 2) == 0x3F) {
proto_tree_add_uint_format (field_tree, hf_message_sec_cat_permissive, tvb, offset, 1,
message, "1111 11.. = Next byte has Country Code (0x3F)");
country_code = TRUE;
} else {
tr = proto_tree_add_item (field_tree, hf_message_sec_cat_permissive, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_item_append_text (tf, ": rel-to-%s", get_nat_pol_id_short (message >> 2));
*label_string = wmem_strdup_printf(wmem_packet_scope(), "%s,rel-to-%s", *label_string, get_nat_pol_id_short (message >> 2));
if ((message >> 2) == 0) {
expert_add_info(pinfo, tr, &ei_reserved_value);
}
}
break;
case SEC_CAT_EXT_RESTRICTIVE:
proto_tree_add_item (field_tree, hf_message_sec_cat_restrictive, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_item_append_text (tf, " (restrictive: 0x%2.2x)", message >> 2);
break;
default:
break;
}
proto_item_append_text (tf, " (0x%2.2x)", message);
if (dmp.version == 1) {
tr = proto_tree_add_item (field_tree, hf_reserved_0x02, tvb, offset, 1, ENC_BIG_ENDIAN);
if (message & 0x02) {
expert_add_info(pinfo, tr, &ei_reserved_value);
}
tr = proto_tree_add_item (field_tree, hf_reserved_0x01, tvb, offset, 1, ENC_BIG_ENDIAN);
if (message & 0x01) {
expert_add_info(pinfo, tr, &ei_reserved_value);
}
} else {
tr = proto_tree_add_item (field_tree, hf_message_sec_cat_extended, tvb, offset, 1, ENC_BIG_ENDIAN);
if ((message & 0x01) && (message & 0x02)) {
expert_add_info(pinfo, tr, &ei_reserved_value);
} else if (message & 0x01 || message & 0x02) {
proto_item_append_text (tf, " (extended)");
offset = dissect_dmp_security_category (tvb, pinfo, tree, label_string, offset+1, message & 0x03);
}
if (country_code) {
proto_tree_add_item (field_tree, hf_message_sec_cat_country_code, tvb, offset+1, 1, ENC_BIG_ENDIAN);
proto_item_append_text (tf, " (rel-to country-code: %d)", tvb_get_guint8 (tvb, offset+1));
proto_item_set_len (tf, 2);
offset++;
}
}
return offset;
}

static int aes_ccm_ctrl(EVP_CIPHER_CTX *c, int type, int arg, void *ptr)
{
EVP_AES_CCM_CTX *cctx = EVP_C_DATA(EVP_AES_CCM_CTX,c);
switch (type) {
case EVP_CTRL_INIT:
cctx->key_set = 0;
cctx->iv_set = 0;
cctx->L = 8;
cctx->M = 12;
cctx->tag_set = 0;
cctx->len_set = 0;
cctx->tls_aad_len = -1;
return 1;
case EVP_CTRL_AEAD_TLS1_AAD:
if (arg != EVP_AEAD_TLS1_AAD_LEN)
return 0;
memcpy(EVP_CIPHER_CTX_buf_noconst(c), ptr, arg);
cctx->tls_aad_len = arg;
{
uint16_t len =
EVP_CIPHER_CTX_buf_noconst(c)[arg - 2] << 8
| EVP_CIPHER_CTX_buf_noconst(c)[arg - 1];
len -= EVP_CCM_TLS_EXPLICIT_IV_LEN;
if (!EVP_CIPHER_CTX_encrypting(c))
len -= cctx->M;
EVP_CIPHER_CTX_buf_noconst(c)[arg - 2] = len >> 8;
EVP_CIPHER_CTX_buf_noconst(c)[arg - 1] = len & 0xff;
}
return cctx->M;
case EVP_CTRL_CCM_SET_IV_FIXED:
if (arg != EVP_CCM_TLS_FIXED_IV_LEN)
return 0;
memcpy(EVP_CIPHER_CTX_iv_noconst(c), ptr, arg);
return 1;
case EVP_CTRL_AEAD_SET_IVLEN:
arg = 15 - arg;
case EVP_CTRL_CCM_SET_L:
if (arg < 2 || arg > 8)
return 0;
cctx->L = arg;
return 1;
case EVP_CTRL_AEAD_SET_TAG:
if ((arg & 1) || arg < 4 || arg > 16)
return 0;
if (EVP_CIPHER_CTX_encrypting(c) && ptr)
return 0;
if (ptr) {
cctx->tag_set = 1;
memcpy(EVP_CIPHER_CTX_buf_noconst(c), ptr, arg);
}
cctx->M = arg;
return 1;
case EVP_CTRL_AEAD_GET_TAG:
if (!EVP_CIPHER_CTX_encrypting(c) || !cctx->tag_set)
return 0;
if (!CRYPTO_ccm128_tag(&cctx->ccm, ptr, (size_t)arg))
return 0;
cctx->tag_set = 0;
cctx->iv_set = 0;
cctx->len_set = 0;
return 1;
case EVP_CTRL_COPY:
{
EVP_CIPHER_CTX *out = ptr;
EVP_AES_CCM_CTX *cctx_out = EVP_C_DATA(EVP_AES_CCM_CTX,out);
if (cctx->ccm.key) {
if (cctx->ccm.key != &cctx->ks)
return 0;
cctx_out->ccm.key = &cctx_out->ks;
}
return 1;
}
default:
return -1;
}
}

Status PySeqToTensor(PyObject* obj, DataType dtype, Tensor* ret) {
ConverterState state;
TF_RETURN_IF_ERROR(InferShapeAndType(obj, &state));
DataType requested_dtype = DT_INVALID;
if (dtype != DT_INVALID) {
requested_dtype = dtype;
}
switch (requested_dtype) {
case DT_FLOAT:
if (FloatConverter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_DOUBLE:
if (DoubleConverter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_HALF:
RETURN_STRING_AS_STATUS(NumpyHalfConverter::Convert(obj, &state, ret));
case DT_INT64:
if (Int64Converter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_INT32:
if (Int32Converter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_UINT64:
if (UInt64Converter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_COMPLEX128:
if (Complex128Converter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_STRING:
if (StringConverter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_BOOL:
if (BoolConverter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
default:
break;
}
switch (state.inferred_dtype) {
case DT_FLOAT:
if (requested_dtype == DT_INVALID) {
RETURN_STRING_AS_STATUS(FloatConverter::Convert(obj, &state, ret));
} else {
RETURN_STRING_AS_STATUS(DoubleConverter::Convert(obj, &state, ret));
}
case DT_DOUBLE:
RETURN_STRING_AS_STATUS(DoubleConverter::Convert(obj, &state, ret));
case DT_HALF:
RETURN_STRING_AS_STATUS(NumpyHalfConverter::Convert(obj, &state, ret));
case DT_INT64:
if (requested_dtype == DT_INVALID) {
const char* error = Int32Converter::Convert(obj, &state, ret);
if (error == ErrorFoundInt64) {
error = Int64Converter::Convert(obj, &state, ret);
}
if (error == ErrorFoundFloat) {
error = FloatConverter::Convert(obj, &state, ret);
}
RETURN_STRING_AS_STATUS(error);
} else {
const char* error = Int64Converter::Convert(obj, &state, ret);
if (error == ErrorFoundFloat) {
error = DoubleConverter::Convert(obj, &state, ret);
}
RETURN_STRING_AS_STATUS(error);
}
case DT_STRING:
RETURN_STRING_AS_STATUS(StringConverter::Convert(obj, &state, ret));
case DT_COMPLEX128:
RETURN_STRING_AS_STATUS(Complex128Converter::Convert(obj, &state, ret));
case DT_BOOL:
RETURN_STRING_AS_STATUS(BoolConverter::Convert(obj, &state, ret));
case DT_INVALID:        *ret = Tensor(requested_dtype == DT_INVALID ? DT_FLOAT : requested_dtype,
state.inferred_shape);
return Status::OK();
default:
return errors::Unimplemented("Missing Python -> Tensor conversion for ",
DataTypeString(state.inferred_dtype));
}
return Status::OK();
}

char *UnicodeBlockCanvas::RequestBuffers(int width, int height) {
static const int max_pixel_size =
strlen("\033[")                                       + PIXEL_SET_COLOR_LEN + ESCAPE_COLOR_MAX_LEN          + 1                                           
+ PIXEL_SET_COLOR_LEN + ESCAPE_COLOR_MAX_LEN          + 1                                           
+ PIXEL_BLOCK_CHARACTER_LEN;
static const int opt_cursor_up    = strlen(SCREEN_CURSOR_UP_FORMAT) + 3;
static const int opt_cursor_right = strlen(SCREEN_CURSOR_RIGHT_FORMAT) + 3;
const int vertical_characters = (height + 1) / 2;      const size_t content_size =
opt_cursor_up          +
vertical_characters * (opt_cursor_right                                           + width * max_pixel_size                                   + SCREEN_END_OF_LINE_LEN);  
const size_t new_backing = width * (height + 1) * sizeof(rgba_t);
if (new_backing > backing_buffer_size_) {
backing_buffer_      = (rgba_t *)realloc(backing_buffer_, new_backing);
backing_buffer_size_ = new_backing;
}
const size_t new_empty = width * sizeof(rgba_t);
if (new_empty > empty_line_size_) {
empty_line_      = (rgba_t *)realloc(empty_line_, new_empty);
empty_line_size_ = new_empty;
memset(empty_line_, 0x00, empty_line_size_);
}
return new char[content_size];
}

static int _rbuf_add(gnrc_netif_hdr_t *netif_hdr, gnrc_pktsnip_t *pkt,
size_t offset, unsigned page)
{
union {
gnrc_sixlowpan_frag_rb_base_t *super;
gnrc_sixlowpan_frag_rb_t *rbuf;
gnrc_sixlowpan_frag_vrb_t *vrb;
} entry;
const uint8_t *src = gnrc_netif_hdr_get_src_addr(netif_hdr);
const uint8_t *dst = gnrc_netif_hdr_get_dst_addr(netif_hdr);
uint8_t *data = NULL;
size_t frag_size = 0;   
int res;
uint16_t datagram_size;
uint16_t datagram_tag;
assert(_valid_offset(pkt, offset));
if (IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG) && sixlowpan_frag_is(pkt->data)) {
data = _6lo_frag_payload(pkt);
frag_size = _6lo_frag_size(pkt, offset, data);
if (frag_size == 0) {
DEBUG("6lo rbuf: integer underflow detected.\n");
gnrc_pktbuf_release(pkt);
return RBUF_ADD_ERROR;
}
datagram_size = sixlowpan_frag_datagram_size(pkt->data);
datagram_tag = sixlowpan_frag_datagram_tag(pkt->data);
}
else if (IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG_SFR) &&
sixlowpan_sfr_rfrag_is(pkt->data)) {
sixlowpan_sfr_rfrag_t *rfrag = pkt->data;
data = _6lo_sfr_payload(pkt);
frag_size = _6lo_sfr_frag_size(pkt);
datagram_size = _6lo_sfr_datagram_size(pkt, offset);
datagram_tag = rfrag->base.tag;
}
else {
assert(data != NULL);
gnrc_pktbuf_release(pkt);
return RBUF_ADD_ERROR;
}
gnrc_sixlowpan_frag_rb_gc();
if (IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG_MINFWD) &&
(offset > 0) &&
sixlowpan_frag_n_is(pkt->data) &&
(entry.vrb = gnrc_sixlowpan_frag_vrb_get(src, netif_hdr->src_l2addr_len,
datagram_tag)) != NULL) {
DEBUG("6lo rbuf minfwd: VRB entry found, trying to forward\n");
switch (_check_fragments(entry.super, frag_size, offset)) {
case RBUF_ADD_REPEAT:
DEBUG("6lo rbuf minfwd: overlap found; dropping VRB\n");
gnrc_sixlowpan_frag_vrb_rm(entry.vrb);
gnrc_pktbuf_release(pkt);
return RBUF_ADD_ERROR;
case RBUF_ADD_DUPLICATE:
DEBUG("6lo rbuf minfwd: not forwarding duplicate\n");
gnrc_pktbuf_release(pkt);
return RBUF_ADD_FORWARDED;
default:
break;
}
res = RBUF_ADD_ERROR;
if (_rbuf_update_ints(entry.super, offset, frag_size)) {
DEBUG("6lo rbuf minfwd: trying to forward fragment\n");
entry.super->current_size += (uint16_t)frag_size;
if (_forward_frag(pkt, sizeof(sixlowpan_frag_n_t), entry.vrb,
page) < 0) {
DEBUG("6lo rbuf minfwd: unable to forward fragment\n");
return RBUF_ADD_ERROR;
}
res = RBUF_ADD_FORWARDED;
}
return res;
}
else if ((res = _rbuf_get(src, netif_hdr->src_l2addr_len,
dst, netif_hdr->dst_l2addr_len,
datagram_size, datagram_tag, page)) < 0) {
DEBUG("6lo rbuf: reassembly buffer full.\n");
gnrc_pktbuf_release(pkt);
return RBUF_ADD_ERROR;
}
entry.rbuf = &rbuf[res];
#if IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG_SFR)
offset += entry.rbuf->offset_diff;
#endif  
if ((offset + frag_size) > entry.super->datagram_size) {
DEBUG("6lo rfrag: fragment too big for resulting datagram, discarding datagram\n");
gnrc_pktbuf_release(entry.rbuf->pkt);
gnrc_pktbuf_release(pkt);
gnrc_sixlowpan_frag_rb_remove(entry.rbuf);
return RBUF_ADD_ERROR;
}
switch (_check_fragments(entry.super, frag_size, offset)) {
case RBUF_ADD_REPEAT:
DEBUG("6lo rfrag: overlapping intervals, discarding datagram\n");
gnrc_pktbuf_release(entry.rbuf->pkt);
gnrc_sixlowpan_frag_rb_remove(entry.rbuf);
return RBUF_ADD_REPEAT;
case RBUF_ADD_DUPLICATE:
gnrc_pktbuf_release(pkt);
return res;
default:
break;
}
if (_rbuf_update_ints(entry.super, offset, frag_size)) {
DEBUG("6lo rbuf: add fragment data\n");
entry.super->current_size += (uint16_t)frag_size;
if (offset == 0) {
if (IS_USED(MODULE_GNRC_SIXLOWPAN_IPHC) &&
sixlowpan_iphc_is(data)) {
DEBUG("6lo rbuf: detected IPHC header.\n");
gnrc_pktsnip_t *frag_hdr = _mark_frag_hdr(pkt);
if (frag_hdr == NULL) {
DEBUG("6lo rbuf: unable to mark fragment header. "
"aborting reassembly.\n");
gnrc_pktbuf_release(entry.rbuf->pkt);
gnrc_pktbuf_release(pkt);
gnrc_sixlowpan_frag_rb_remove(entry.rbuf);
return RBUF_ADD_ERROR;
}
else {
DEBUG("6lo rbuf: handing over to IPHC reception.\n");
gnrc_sixlowpan_iphc_recv(pkt, entry.rbuf, 0);
if (gnrc_sixlowpan_frag_rb_entry_empty(entry.rbuf)) {
res = RBUF_ADD_ERROR;
}
return res;
}
}
else if (data[0] == SIXLOWPAN_UNCOMP) {
DEBUG("6lo rbuf: detected uncompressed datagram\n");
data++;
if (IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG_MINFWD) &&
sixlowpan_frag_1_is(pkt->data) &&
(entry.super->current_size == frag_size)) {
gnrc_sixlowpan_frag_vrb_t *vrbe;
gnrc_pktsnip_t tmp = {
.data = data,
.size = frag_size,
.users = 1,
};
if (_check_hdr(&tmp, page) &&
(vrbe = gnrc_sixlowpan_frag_vrb_from_route(
entry.super,
gnrc_netif_hdr_get_netif(netif_hdr),
&tmp))) {
_adapt_hdr(&tmp, page);
return _forward_uncomp(pkt, rbuf, vrbe, page);
}
}
else if (IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG_SFR) &&
sixlowpan_sfr_rfrag_is(pkt->data)) {
entry.super->datagram_size--;
}
}
}
if (IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG_MINFWD) ||
IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG_SFR)) {
res = _rbuf_resize_for_reassembly(entry.rbuf);
if (res == RBUF_ADD_ERROR) {
gnrc_pktbuf_release(pkt);
return res;
}
}
memcpy(((uint8_t *)entry.rbuf->pkt->data) + offset, data,
frag_size);
}
else {
gnrc_pktbuf_release(entry.rbuf->pkt);
gnrc_sixlowpan_frag_rb_remove(entry.rbuf);
res = RBUF_ADD_ERROR;
}
gnrc_pktbuf_release(pkt);
return res;
}

static int add_page_to_event_array(struct domain *d, unsigned long gfn)
{
void *virt;
unsigned int slot;
unsigned int port = d->evtchn_fifo->num_evtchns;
int rc;
slot = d->evtchn_fifo->num_evtchns / EVTCHN_FIFO_EVENT_WORDS_PER_PAGE;
if ( slot >= EVTCHN_FIFO_MAX_EVENT_ARRAY_PAGES )
return -ENOSPC;
rc = map_guest_page(d, gfn, &virt);
if ( rc < 0 )
return rc;
d->evtchn_fifo->event_array[slot] = virt;
d->evtchn_fifo->num_evtchns += EVTCHN_FIFO_EVENT_WORDS_PER_PAGE;
for ( ; port < d->evtchn_fifo->num_evtchns; port++ )
{
struct evtchn *evtchn;
if ( !port_is_valid(d, port) )
break;
evtchn = evtchn_from_port(d, port);
if ( evtchn->pending )
evtchn_fifo_set_pending(d->vcpu[evtchn->notify_vcpu_id], evtchn);
}
return 0;
}

static int
dissect_ike_attribute(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, int offset, decrypt_data_t *decr
)
{
guint headerlen, value_len, attr_type;
proto_item *attr_item;
proto_tree *attr_tree;
dissect_attribute_header(tvb, tree, offset,
hf_isakmp_ike_attr, ike_attr_type,
&headerlen, &value_len, &attr_type,
&attr_item, &attr_tree);
offset += headerlen;
if (value_len == 0)
{
expert_add_info(pinfo, attr_item, &ei_isakmp_attribute_value_empty);
return headerlen;
}
switch(attr_type) {
case IKE_ATTR_ENCRYPTION_ALGORITHM:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_encryption_algorithm, tvb, offset, value_len, ENC_BIG_ENDIAN);
proto_item_append_text(attr_item, ": %s", val_to_str(tvb_get_ntohs(tvb, offset), ike_attr_enc_algo, "Unknown %d"));
decr->ike_encr_alg = tvb_get_ntohs(tvb, offset);
break;
case IKE_ATTR_HASH_ALGORITHM:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_hash_algorithm, tvb, offset, value_len, ENC_BIG_ENDIAN);
proto_item_append_text(attr_item, ": %s", val_to_str(tvb_get_ntohs(tvb, offset), ike_attr_hash_algo, "Unknown %d"));
decr->ike_hash_alg = tvb_get_ntohs(tvb, offset);
break;
case IKE_ATTR_AUTHENTICATION_METHOD:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_authentication_method, tvb, offset, value_len, ENC_BIG_ENDIAN);
proto_item_append_text(attr_item, ": %s", val_to_str(tvb_get_ntohs(tvb, offset), ike_attr_authmeth, "Unknown %d"));
decr->is_psk = tvb_get_ntohs(tvb, offset) == 0x01 ? TRUE : FALSE;
break;
case IKE_ATTR_GROUP_DESCRIPTION:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_group_description, tvb, offset, value_len, ENC_BIG_ENDIAN);
proto_item_append_text(attr_item, ": %s", val_to_str(tvb_get_ntohs(tvb, offset), dh_group, "Unknown %d"));
decr->group = tvb_get_ntohs(tvb, offset);
break;
case IKE_ATTR_GROUP_TYPE:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_group_type, tvb, offset, value_len, ENC_BIG_ENDIAN);
proto_item_append_text(attr_item, ": %s", val_to_str(tvb_get_ntohs(tvb, offset), ike_attr_grp_type, "Unknown %d"));
break;
case IKE_ATTR_GROUP_PRIME:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_group_prime, tvb, offset, value_len, ENC_NA);
break;
case IKE_ATTR_GROUP_GENERATOR_ONE:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_group_generator_one, tvb, offset, value_len, ENC_NA);
break;
case IKE_ATTR_GROUP_GENERATOR_TWO:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_group_generator_two, tvb, offset, value_len, ENC_NA);
break;
case IKE_ATTR_GROUP_CURVE_A:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_group_curve_a, tvb, offset, value_len, ENC_NA);
break;
case IKE_ATTR_GROUP_CURVE_B:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_group_curve_b, tvb, offset, value_len, ENC_NA);
break;
case IKE_ATTR_LIFE_TYPE:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_life_type, tvb, offset, value_len, ENC_BIG_ENDIAN);
proto_item_append_text(attr_item, ": %s", val_to_str(tvb_get_ntohs(tvb, offset), attr_life_type, "Unknown %d"));
break;
case IKE_ATTR_LIFE_DURATION:
dissect_life_duration(tvb, attr_tree, attr_item, hf_isakmp_ike_attr_life_duration_uint32, hf_isakmp_ike_attr_life_duration_uint64, hf_isakmp_ike_attr_life_duration_bytes, offset, value_len);
break;
case IKE_ATTR_PRF:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_prf, tvb, offset, value_len, ENC_NA);
break;
case IKE_ATTR_KEY_LENGTH:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_key_length, tvb, offset, value_len, ENC_BIG_ENDIAN);
proto_item_append_text(attr_item, ": %d", tvb_get_ntohs(tvb, offset));
decr->ike_encr_keylen = tvb_get_ntohs(tvb, offset);
break;
case IKE_ATTR_FIELD_SIZE:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_field_size, tvb, offset, value_len, ENC_NA);
break;
case IKE_ATTR_GROUP_ORDER:
proto_tree_add_item(attr_tree, hf_isakmp_ike_attr_group_order, tvb, offset, value_len, ENC_NA);
break;
default:
break;
}
return headerlen + value_len;
}

int
fix_ipv6_checksums(tcpedit_t *tcpedit, struct pcap_pkthdr *pkthdr, ipv6_hdr_t *ip6_hdr)
{
int ret = 0;
assert(tcpedit);
assert(pkthdr);
assert(ip6_hdr);
if (pkthdr->caplen < sizeof(*ip6_hdr)) {
tcpedit_setwarn(tcpedit, "caplen too small to read IPv6 header: %u",
pkthdr->caplen);
return TCPEDIT_WARN;
}
ipv4_hdr_t *ip_hdr = (ipv4_hdr_t*)ip6_hdr;
if (ip_hdr->ip_v != 6) {
tcpedit_seterr(tcpedit, "Invalid packet: Expected IPv6 packet: got %u", ip_hdr->ip_v);
return TCPEDIT_ERROR;
}
if (pkthdr->caplen == pkthdr->len) {
if (ip6_hdr->ip_len < ipv6_header_length(ip6_hdr, pkthdr->len)) {
tcpedit_setwarn(tcpedit, "Unable to checksum IPv6 packet with invalid length %u",
ip6_hdr->ip_len);
return TCPEDIT_WARN;
}
ret = do_checksum(tcpedit, (u_char *)ip6_hdr, ip6_hdr->ip_nh,
htons(ip6_hdr->ip_len));
if (ret < 0)
return TCPEDIT_ERROR;
}
if (ret == TCPEDIT_WARN)
return TCPEDIT_WARN;
return TCPEDIT_OK;
}

static BOOL nsc_rle_decompress_data(NSC_CONTEXT* context)
{
if (!context)
return FALSE;
BYTE* rle = context->Planes;
WINPR_ASSERT(rle);
for (size_t i = 0; i < 4; i++)
{
const UINT32 originalSize = context->OrgByteCount[i];
const UINT32 planeSize = context->PlaneByteCount[i];
if (planeSize == 0)
{
if (context->priv->PlaneBuffersLength < originalSize)
return FALSE;
FillMemory(context->priv->PlaneBuffers[i], originalSize, 0xFF);
}
else if (planeSize < originalSize)
{
if (!nsc_rle_decode(rle, context->priv->PlaneBuffers[i],
context->priv->PlaneBuffersLength, originalSize))
return FALSE;
}
else
{
if (context->priv->PlaneBuffersLength < originalSize)
return FALSE;
CopyMemory(context->priv->PlaneBuffers[i], rle, originalSize);
}
rle += planeSize;
}
return TRUE;
}

