static Jsi_RC jsi_ArrayPushCmd(Jsi_Interp *interp, Jsi_Value *args, Jsi_Value *_this,
Jsi_Value **ret, Jsi_Func *funcPtr)
{
Jsi_Obj *obj;
if (_this->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(interp, _this->d.obj)) {
Jsi_ValueMakeNumber(interp, ret, 0);
return JSI_OK;
}
obj = _this->d.obj;
int argc = Jsi_ValueGetLength(interp, args);
int curlen = jsi_SizeOfArray(interp, obj);    
int i;
for (i = 0; i < argc; ++i) {
Jsi_Value *ov = Jsi_ValueArrayIndex(interp, args, i);
if (!ov) { Jsi_LogBug("Arguments Error"); ov = Jsi_ValueNew(interp); }
Jsi_ValueInsertArray(interp, _this, curlen + i, ov, 0);
}
Jsi_ValueMakeNumber(interp, ret, jsi_SizeOfArray(interp, obj));
return JSI_OK;
}

int _our_safe_pcap_next_ex(pcap_t *pcap, struct pcap_pkthdr **pkthdr,
const u_char **pktdata, const char *funcname,
const int line, const char *file)
{
int res = pcap_next_ex(pcap, pkthdr, pktdata);
if (*pktdata && *pkthdr) {
if ((*pkthdr)->len > MAXPACKET) {
fprintf(stderr, "safe_pcap_next_ex ERROR: Invalid packet length in %s:%s() line %d: %u is greater than maximum %u\n",
file, funcname, line, (*pkthdr)->len, MAXPACKET);
exit(-1);
}
if ((*pkthdr)->len < (*pkthdr)->caplen) {
fprintf(stderr, "safe_pcap_next_ex ERROR: Invalid packet length in %s:%s() line %d: packet length %u is less than capture length %u\n",
file, funcname, line, (*pkthdr)->len, (*pkthdr)->caplen);
exit(-1);
}
}
return res;
}

void
select_node_input_vec (select_node_t * sel, caddr_t * inst, caddr_t * state)
{
QNCAST (query_instance_t, qi, inst);
int quota = (int) (ptrlong) inst[sel->sel_out_quota];
int n_rows, row, skip = 0, top = 0, top_ctr = 0, fill = 0;
int pos_in_batch = QST_INT (inst, sel->sel_out_fill);
if (state)
{
QST_INT (inst, sel->src_gen.src_out_fill) = 0;
}
if (sel->src_gen.src_prev)
n_rows = QST_INT (inst, sel->src_gen.src_prev->src_out_fill);
else
n_rows = 1;
if (sel->sel_top)
{
top = unbox (qst_get (inst, sel->sel_top));
if (sel->sel_top_skip)
skip = unbox (qst_get (inst, sel->sel_top_skip));
if (top < 0 || skip < 0)
sqlr_new_error ("42000", "TOPSK", "select skip, top has a negative top or skip value");
top += skip;
top_ctr = unbox (qst_get (inst, sel->sel_row_ctr));
}
if (qi->qi_lc)
{
select_node_lc_input (sel, qi, n_rows, top, skip);
return;
}
if (CALLER_CLIENT != qi->qi_caller || !qi->qi_client->cli_session)
return;
if (top && top_ctr + n_rows < skip)
{
qst_set_long (inst, sel->sel_row_ctr, top_ctr + n_rows);
return;
}
if (top && top_ctr < skip)
{
int n_skipped = skip - top_ctr;
qst_set_long (inst, sel->sel_row_ctr, skip);
top_ctr = skip;
QST_INT (inst, sel->src_gen.src_out_fill) += n_skipped;
}
QST_INT (inst, sel->sel_client_batch_start) = QST_INT (inst, sel->src_gen.src_out_fill);
for (row = QST_INT (inst, sel->src_gen.src_out_fill); row < n_rows; row++)
{
int set_no;
qi->qi_set = row;
set_no = sel->sel_set_no ? unbox (qst_get (inst, sel->sel_set_no)) : 0;
if (!top || top_ctr < top)
{
int is_full = qi->qi_prefetch_bytes && qi->qi_bytes_selected > qi->qi_prefetch_bytes;
int slots = sel->sel_n_value_slots;
int inx;
OFF_T b1 = 0, b2 = 0;
PRPC_ANSWER_START (qi->qi_thread, PARTIAL);
b1 = __ses->dks_bytes_sent;
dks_array_head (__ses, slots + 1, DV_ARRAY_OF_POINTER);
print_int (is_full ? QA_ROW_LAST_IN_BATCH : QA_ROW, __ses);
for (inx = 0; inx < slots; inx++)
{
caddr_t value = QST_GET (inst, sel->sel_out_slots[inx]);
print_object (value, __ses, NULL, NULL);
}
b2 = __ses->dks_bytes_sent;
PRPC_ANSWER_END (0);
qi->qi_bytes_selected += b2 - b1;
top_ctr++;
fill++;
pos_in_batch++;
if (top && top_ctr >= top)
{
subq_init (sel->src_gen.src_query, inst);
SRC_RETURN (((data_source_t *) sel), inst);
longjmp_splice (qi->qi_thread->thr_reset_ctx, RST_AT_END);
}
if (PREFETCH_ALL == quota)
continue;
if (is_full || pos_in_batch >= quota)
{
QST_INT (inst, sel->sel_out_fill) = 0;
QST_INT (inst, sel->src_gen.src_out_fill) = row + 1;
if (sel->sel_row_ctr)
qst_set_long (inst, sel->sel_row_ctr, top_ctr);
SRC_IN_STATE (sel, inst) = (row < n_rows - 1) ? inst : NULL;
SRC_RETURN (((data_source_t *) sel), inst);
longjmp_splice (qi->qi_thread->thr_reset_ctx, RST_ENOUGH);
}
}
}
QST_INT (inst, sel->sel_out_fill) = pos_in_batch;
if (sel->sel_top)
{
QST_INT (inst, sel->src_gen.src_out_fill) = top_ctr;
qst_set_long (inst, sel->sel_row_ctr, top_ctr);
}
SRC_IN_STATE (sel, inst) = NULL;
}

int perf_cpu_time_max_percent_handler(struct ctl_table *table, int write,
void __user *buffer, size_t *lenp,
loff_t *ppos)
{
int ret = proc_dointvec(table, write, buffer, lenp, ppos);
if (ret || !write)
return ret;
if (sysctl_perf_cpu_time_max_percent == 100 ||
sysctl_perf_cpu_time_max_percent == 0) {
printk(KERN_WARNING
"perf: Dynamic interrupt throttling disabled, can hang your system!\n");
WRITE_ONCE(perf_sample_allowed_ns, 0);
} else {
update_perf_cpu_limits();
}
return 0;
}

static MagickBooleanType WritePICTImage(const ImageInfo *image_info,
Image *image,ExceptionInfo *exception)
{
#define MaxCount  128
#define PictCropRegionOp  0x01
#define PictEndOfPictureOp  0xff
#define PictJPEGOp  0x8200
#define PictInfoOp  0x0C00
#define PictInfoSize  512
#define PictPixmapOp  0x9A
#define PictPICTOp  0x98
#define PictVersion  0x11
const StringInfo
*profile;
double
x_resolution,
y_resolution;
MagickBooleanType
status;
MagickOffsetType
offset;
PICTPixmap
pixmap;
PICTRectangle
bounds,
crop_rectangle,
destination_rectangle,
frame_rectangle,
size_rectangle,
source_rectangle;
register const Quantum
*p;
register ssize_t
i,
x;
size_t
bytes_per_line,
count,
storage_class;
ssize_t
y;
unsigned char
*buffer,
*packed_scanline,
*scanline;
unsigned short
base_address,
row_bytes,
transfer_mode;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickSignature);
assert(image != (Image *) NULL);
assert(image->signature == MagickSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
if ((image->columns > 65535L) || (image->rows > 65535L))
ThrowWriterException(ImageError,"WidthOrHeightExceedsLimit");
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickSignature);
status=OpenBlob(image_info,image,WriteBinaryBlobMode,exception);
if (status == MagickFalse)
return(status);
(void) TransformImageColorspace(image,sRGBColorspace,exception);
size_rectangle.top=0;
size_rectangle.left=0;
size_rectangle.bottom=(short) image->rows;
size_rectangle.right=(short) image->columns;
frame_rectangle=size_rectangle;
crop_rectangle=size_rectangle;
source_rectangle=size_rectangle;
destination_rectangle=size_rectangle;
base_address=0xff;
row_bytes=(unsigned short) (image->columns | 0x8000);
bounds.top=0;
bounds.left=0;
bounds.bottom=(short) image->rows;
bounds.right=(short) image->columns;
pixmap.version=0;
pixmap.pack_type=0;
pixmap.pack_size=0;
pixmap.pixel_type=0;
pixmap.bits_per_pixel=8;
pixmap.component_count=1;
pixmap.component_size=8;
pixmap.plane_bytes=0;
pixmap.table=0;
pixmap.reserved=0;
transfer_mode=0;
x_resolution=image->resolution.x != 0.0 ? image->resolution.x :
DefaultResolution;
y_resolution=image->resolution.y != 0.0 ? image->resolution.y :
DefaultResolution;
storage_class=image->storage_class;
if (image_info->compression == JPEGCompression)
storage_class=DirectClass;
if (storage_class == DirectClass)
{
pixmap.component_count=image->alpha_trait != UndefinedPixelTrait ? 4 : 3;
pixmap.pixel_type=16;
pixmap.bits_per_pixel=32;
pixmap.pack_type=0x04;
transfer_mode=0x40;
row_bytes=(unsigned short) ((4*image->columns) | 0x8000);
}
bytes_per_line=image->columns;
if (storage_class == DirectClass)
bytes_per_line*=image->alpha_trait != UndefinedPixelTrait ? 4 : 3;
buffer=(unsigned char *) AcquireQuantumMemory(PictInfoSize,sizeof(*buffer));
packed_scanline=(unsigned char *) AcquireQuantumMemory((size_t)
(row_bytes+MaxCount),sizeof(*packed_scanline));
scanline=(unsigned char *) AcquireQuantumMemory(row_bytes,sizeof(*scanline));
if ((buffer == (unsigned char *) NULL) ||
(packed_scanline == (unsigned char *) NULL) ||
(scanline == (unsigned char *) NULL))
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
(void) ResetMagickMemory(scanline,0,row_bytes);
(void) ResetMagickMemory(packed_scanline,0,(size_t) (row_bytes+MaxCount));
(void) ResetMagickMemory(buffer,0,PictInfoSize);
(void) WriteBlob(image,PictInfoSize,buffer);
(void) WriteBlobMSBShort(image,0);
(void) WriteBlobMSBShort(image,(unsigned short) size_rectangle.top);
(void) WriteBlobMSBShort(image,(unsigned short) size_rectangle.left);
(void) WriteBlobMSBShort(image,(unsigned short) size_rectangle.bottom);
(void) WriteBlobMSBShort(image,(unsigned short) size_rectangle.right);
(void) WriteBlobMSBShort(image,PictVersion);
(void) WriteBlobMSBShort(image,0x02ff);  
(void) WriteBlobMSBShort(image,PictInfoOp);
(void) WriteBlobMSBLong(image,0xFFFE0000UL);
(void) WriteBlobMSBShort(image,(unsigned short) x_resolution);
(void) WriteBlobMSBShort(image,0x0000);
(void) WriteBlobMSBShort(image,(unsigned short) y_resolution);
(void) WriteBlobMSBShort(image,0x0000);
(void) WriteBlobMSBShort(image,(unsigned short) frame_rectangle.top);
(void) WriteBlobMSBShort(image,(unsigned short) frame_rectangle.left);
(void) WriteBlobMSBShort(image,(unsigned short) frame_rectangle.bottom);
(void) WriteBlobMSBShort(image,(unsigned short) frame_rectangle.right);
(void) WriteBlobMSBLong(image,0x00000000L);
profile=GetImageProfile(image,"iptc");
if (profile != (StringInfo *) NULL)
{
(void) WriteBlobMSBShort(image,0xa1);
(void) WriteBlobMSBShort(image,0x1f2);
(void) WriteBlobMSBShort(image,(unsigned short)
(GetStringInfoLength(profile)+4));
(void) WriteBlobString(image,"8BIM");
(void) WriteBlob(image,GetStringInfoLength(profile),
GetStringInfoDatum(profile));
}
profile=GetImageProfile(image,"icc");
if (profile != (StringInfo *) NULL)
{
(void) WriteBlobMSBShort(image,0xa1);
(void) WriteBlobMSBShort(image,0xe0);
(void) WriteBlobMSBShort(image,(unsigned short)
(GetStringInfoLength(profile)+4));
(void) WriteBlobMSBLong(image,0x00000000UL);
