sisusb = kzalloc(sizeof(*sisusb), GFP_KERNEL);
if (!sisusb)
return -ENOMEM;
kref_init(&sisusb->kref);
mutex_init(&(sisusb->lock));
retval = usb_register_dev(intf, &usb_sisusb_class);
if (retval) {
dev_err(&sisusb->sisusb_dev->dev,
"Failed to get a minor for device %d\n",
dev->devnum);
retval = -ENODEV;
goto error_1;
}
sisusb->sisusb_dev = dev;
sisusb->minor      = intf->minor;
sisusb->vrambase   = SISUSB_PCI_MEMBASE;
sisusb->mmiobase   = SISUSB_PCI_MMIOBASE;
sisusb->mmiosize   = SISUSB_PCI_MMIOSIZE;
sisusb->ioportbase = SISUSB_PCI_IOPORTBASE;
sisusb->ibufsize = SISUSB_IBUF_SIZE;
sisusb->ibuf = kmalloc(SISUSB_IBUF_SIZE, GFP_KERNEL);
if (!sisusb->ibuf) {
retval = -ENOMEM;
goto error_2;
}
sisusb->numobufs = 0;
sisusb->obufsize = SISUSB_OBUF_SIZE;
for (i = 0; i < NUMOBUFS; i++) {
sisusb->obuf[i] = kmalloc(SISUSB_OBUF_SIZE, GFP_KERNEL);
if (!sisusb->obuf[i]) {
if (i == 0) {
retval = -ENOMEM;
goto error_3;
}
break;
}
sisusb->numobufs++;
}
sisusb->sisurbin = usb_alloc_urb(0, GFP_KERNEL);
if (!sisusb->sisurbin) {
retval = -ENOMEM;
goto error_3;
}
sisusb->completein = 1;
for (i = 0; i < sisusb->numobufs; i++) {
sisusb->sisurbout[i] = usb_alloc_urb(0, GFP_KERNEL);
if (!sisusb->sisurbout[i]) {
retval = -ENOMEM;
goto error_4;
}
sisusb->urbout_context[i].sisusb = (void *)sisusb;
sisusb->urbout_context[i].urbindex = i;
sisusb->urbstatus[i] = 0;
}
dev_info(&sisusb->sisusb_dev->dev, "Allocated %d output buffers\n",
sisusb->numobufs);
#ifdef CONFIG_USB_SISUSBVGA_CON
sisusb->SiS_Pr = kmalloc(sizeof(struct SiS_Private), GFP_KERNEL);
if (!sisusb->SiS_Pr) {
retval = -ENOMEM;
goto error_4;
}
#endif
init_waitqueue_head(&sisusb->wait_q);
usb_set_intfdata(intf, sisusb);
usb_get_dev(sisusb->sisusb_dev);
sisusb->present = 1;
if (dev->speed == USB_SPEED_HIGH || dev->speed >= USB_SPEED_SUPER) {
int initscreen = 1;
#ifdef CONFIG_USB_SISUSBVGA_CON
if (sisusb_first_vc > 0 && sisusb_last_vc > 0 &&
sisusb_first_vc <= sisusb_last_vc &&
sisusb_last_vc <= MAX_NR_CONSOLES)
initscreen = 0;
#endif
if (sisusb_init_gfxdevice(sisusb, initscreen))
dev_err(&sisusb->sisusb_dev->dev,
"Failed to early initialize device\n");
} else
dev_info(&sisusb->sisusb_dev->dev,
"Not attached to USB 2.0 hub, deferring init\n");
sisusb->ready = 1;
#ifdef SISUSBENDIANTEST
dev_dbg(&sisusb->sisusb_dev->dev, "*** RWTEST ***\n");
sisusb_testreadwrite(sisusb);
dev_dbg(&sisusb->sisusb_dev->dev, "*** RWTEST END ***\n");
#endif
#ifdef CONFIG_USB_SISUSBVGA_CON
sisusb_console_init(sisusb, sisusb_first_vc, sisusb_last_vc);
#endif
return 0;
error_4:
sisusb_free_urbs(sisusb);
error_3:
sisusb_free_buffers(sisusb);
error_2:
usb_deregister_dev(intf, &usb_sisusb_class);
error_1:
kfree(sisusb);
return retval;
}

static int AESNI_decrypt(const BlockBase *bb, const uint8_t *in, uint8_t *out, size_t data_len)
{
unsigned rounds;
__m128i r[14+1];
const struct block_state *state;
unsigned k;
if ((bb == NULL) || (in == NULL) || (out == NULL))
return ERR_NULL;
state = &((AESNI_State*)bb)->algo_state;
rounds = state->rounds;
if (rounds > 14)
return ERR_NR_ROUNDS;
for (k=0; k<=rounds; k++) {
r[k] = state->drk[k];
}
for (; data_len >= 8*16; data_len -= 8*16) {
__m128i ct[8], data[8];
unsigned j;
ct[0] = _mm_loadu_si128((__m128i*)in); in+=16;
ct[1] = _mm_loadu_si128((__m128i*)in); in+=16;
ct[2] = _mm_loadu_si128((__m128i*)in); in+=16;
ct[3] = _mm_loadu_si128((__m128i*)in); in+=16;
ct[4] = _mm_loadu_si128((__m128i*)in); in+=16;
ct[5] = _mm_loadu_si128((__m128i*)in); in+=16;
ct[6] = _mm_loadu_si128((__m128i*)in); in+=16;
ct[7] = _mm_loadu_si128((__m128i*)in); in+=16;
data[0] = _mm_xor_si128(ct[0], r[0]);
data[1] = _mm_xor_si128(ct[1], r[0]);
data[2] = _mm_xor_si128(ct[2], r[0]);
data[3] = _mm_xor_si128(ct[3], r[0]);
data[4] = _mm_xor_si128(ct[4], r[0]);
data[5] = _mm_xor_si128(ct[5], r[0]);
data[6] = _mm_xor_si128(ct[6], r[0]);
data[7] = _mm_xor_si128(ct[7], r[0]);
for (j=1; j<10; j++) {
data[0] = _mm_aesdec_si128(data[0], r[j]);
data[1] = _mm_aesdec_si128(data[1], r[j]);
data[2] = _mm_aesdec_si128(data[2], r[j]);
data[3] = _mm_aesdec_si128(data[3], r[j]);
data[4] = _mm_aesdec_si128(data[4], r[j]);
data[5] = _mm_aesdec_si128(data[5], r[j]);
data[6] = _mm_aesdec_si128(data[6], r[j]);
data[7] = _mm_aesdec_si128(data[7], r[j]);
}
for (; j<rounds; j++) {
data[0] = _mm_aesdec_si128(data[0], r[j]);
data[1] = _mm_aesdec_si128(data[1], r[j]);
data[2] = _mm_aesdec_si128(data[2], r[j]);
data[3] = _mm_aesdec_si128(data[3], r[j]);
data[4] = _mm_aesdec_si128(data[4], r[j]);
data[5] = _mm_aesdec_si128(data[5], r[j]);
data[6] = _mm_aesdec_si128(data[6], r[j]);
data[7] = _mm_aesdec_si128(data[7], r[j]);
}
data[0] = _mm_aesdeclast_si128(data[0], r[rounds]);
data[1] = _mm_aesdeclast_si128(data[1], r[rounds]);
data[2] = _mm_aesdeclast_si128(data[2], r[rounds]);
data[3] = _mm_aesdeclast_si128(data[3], r[rounds]);
data[4] = _mm_aesdeclast_si128(data[4], r[rounds]);
data[5] = _mm_aesdeclast_si128(data[5], r[rounds]);
data[6] = _mm_aesdeclast_si128(data[6], r[rounds]);
data[7] = _mm_aesdeclast_si128(data[7], r[rounds]);
_mm_storeu_si128((__m128i*)out, data[0]); out+=16;
_mm_storeu_si128((__m128i*)out, data[1]); out+=16;
_mm_storeu_si128((__m128i*)out, data[2]); out+=16;
_mm_storeu_si128((__m128i*)out, data[3]); out+=16;
_mm_storeu_si128((__m128i*)out, data[4]); out+=16;
_mm_storeu_si128((__m128i*)out, data[5]); out+=16;
_mm_storeu_si128((__m128i*)out, data[6]); out+=16;
_mm_storeu_si128((__m128i*)out, data[7]); out+=16;
}
for (;data_len>0; data_len-=16, in+=16, out+=16) {
__m128i ct, data;
unsigned i;
ct = _mm_loadu_si128((__m128i*)in);
data = _mm_xor_si128(ct, r[0]);
for (i=1; i<10; i++) {
data = _mm_aesdec_si128(data, r[i]);
}
for (i=10; i<rounds; i+=2) {
data = _mm_aesdec_si128(data, r[i]);
data = _mm_aesdec_si128(data, r[i+1]);
}
data = _mm_aesdeclast_si128(data, r[rounds]);
_mm_storeu_si128((__m128i*)out, data);
}
if (data_len) {
return ERR_NOT_ENOUGH_DATA;
}
return 0;
}

static inline int __tcp_mtu_to_mss(struct sock *sk, int pmtu)
{
const struct tcp_sock *tp = tcp_sk(sk);
const struct inet_connection_sock *icsk = inet_csk(sk);
int mss_now;
mss_now = pmtu - icsk->icsk_af_ops->net_header_len - sizeof(struct tcphdr);
if (icsk->icsk_af_ops->net_frag_header_len) {
const struct dst_entry *dst = __sk_dst_get(sk);
if (dst && dst_allfrag(dst))
mss_now -= icsk->icsk_af_ops->net_frag_header_len;
}
if (mss_now > tp->rx_opt.mss_clamp)
mss_now = tp->rx_opt.mss_clamp;
mss_now -= icsk->icsk_ext_hdr_len;
if (mss_now < 48)
mss_now = 48;
return mss_now;
}

void ftoa_bounded_extra(JsVarFloat val,char *str, size_t len, int radix, int fractionalDigits) {
const JsVarFloat stopAtError = 0.0000001;
if (isnan(val)) strncpy(str,"NaN",len);
else if (!isfinite(val)) {
if (val<0) strncpy(str,"-Infinity",len);
else strncpy(str,"Infinity",len);
} else {
if (val<0) {
if (--len <= 0) { *str=0; return; }       *(str++) = '-';
val = -val;
}
if (((JsVarInt)(val+stopAtError)) == (1+(JsVarInt)val))
val = (JsVarFloat)(1+(JsVarInt)val);
JsVarFloat d = 1;
while (d*radix <= val) d*=radix;
while (d >= 1) {
int v = (int)(val / d);
val -= v*d;
if (--len <= 0) { *str=0; return; }       *(str++) = itoch(v);
d /= radix;
}
#ifndef USE_NO_FLOATS
if (((fractionalDigits<0) && val>0) || fractionalDigits>0) {
bool hasPt = false;
val*=radix;
while (((fractionalDigits<0) && (fractionalDigits>-12) && (val > stopAtError)) || (fractionalDigits > 0)) {
int v = (int)(val+((fractionalDigits==1) ? 0.4 : 0.00000001) );
val = (val-v)*radix;
if (v==radix) v=radix-1;
if (!hasPt) {
hasPt = true;
if (--len <= 0) { *str=0; return; }           *(str++)='.';
}
if (--len <= 0) { *str=0; return; }         *(str++)=itoch(v);
fractionalDigits--;
}
}
#endif
*(str++)=0;
}
}

