static struct bpf_program *find_prog_by_sec_insn(const struct bpf_object *obj,
size_t sec_idx, size_t insn_idx)
{
int l = 0, r = obj->nr_programs - 1, m;
struct bpf_program *prog;
while (l < r) {
m = l + (r - l + 1) / 2;
prog = &obj->programs[m];
if (prog->sec_idx < sec_idx ||
(prog->sec_idx == sec_idx && prog->sec_insn_off <= insn_idx))
l = m;
else
r = m - 1;
}
prog = &obj->programs[l];
if (prog->sec_idx == sec_idx && prog_contains_insn(prog, insn_idx))
return prog;
return NULL;
}

static int hvmemul_do_io(
bool_t is_mmio, paddr_t addr, unsigned long *reps, unsigned int size,
uint8_t dir, bool_t df, bool_t data_is_addr, uintptr_t data)
{
struct vcpu *curr = current;
struct domain *currd = curr->domain;
struct hvm_vcpu_io *vio = &curr->arch.hvm_vcpu.hvm_io;
ioreq_t p = {
.type = is_mmio ? IOREQ_TYPE_COPY : IOREQ_TYPE_PIO,
.addr = addr,
.size = size,
.count = *reps,
.dir = dir,
.df = df,
.data = data,
.data_is_ptr = data_is_addr, 
.state = STATE_IOREQ_READY,
};
void *p_data = (void *)data;
int rc;
if ( unlikely((size > sizeof(long)) || (size & (size - 1))) )
{
gdprintk(XENLOG_WARNING, "bad mmio size %d\n", size);
return X86EMUL_UNHANDLEABLE;
}
switch ( vio->io_req.state )
{
case STATE_IOREQ_NONE:
break;
case STATE_IORESP_READY:
vio->io_req.state = STATE_IOREQ_NONE;
p = vio->io_req;
if ( (p.type != (is_mmio ? IOREQ_TYPE_COPY : IOREQ_TYPE_PIO)) ||
(p.addr != addr) ||
(p.size != size) ||
(p.count > *reps) ||
(p.dir != dir) ||
(p.df != df) ||
(p.data_is_ptr != data_is_addr) )
domain_crash(currd);
if ( data_is_addr )
return X86EMUL_UNHANDLEABLE;
*reps = p.count;
goto finish_access;
default:
return X86EMUL_UNHANDLEABLE;
}
if ( dir == IOREQ_WRITE )
{
if ( !data_is_addr )
memcpy(&p.data, p_data, size);
hvmtrace_io_assist(&p);
}
vio->io_req = p;
rc = hvm_io_intercept(&p);
ASSERT(p.count <= *reps);
*reps = vio->io_req.count = p.count;
switch ( rc )
{
case X86EMUL_OKAY:
vio->io_req.state = STATE_IOREQ_NONE;
break;
case X86EMUL_UNHANDLEABLE:
{
struct hvm_ioreq_server *s = NULL;
p2m_type_t p2mt = p2m_invalid;
if ( is_mmio )
{
unsigned long gmfn = paddr_to_pfn(addr);
get_gfn_query_unlocked(currd, gmfn, &p2mt);
if ( p2mt == p2m_ioreq_server )
{
unsigned int flags;
s = p2m_get_ioreq_server(currd, &flags);
if ( s == NULL )
{
rc = X86EMUL_RETRY;
vio->io_req.state = STATE_IOREQ_NONE;
break;
}
if ( dir == IOREQ_READ )
{
rc = hvm_process_io_intercept(&ioreq_server_handler, &p);
vio->io_req.state = STATE_IOREQ_NONE;
break;
}
}
}
if ( !s )
s = hvm_select_ioreq_server(currd, &p);
if ( !s )
{
rc = hvm_process_io_intercept(&null_handler, &p);
vio->io_req.state = STATE_IOREQ_NONE;
}
else
{
rc = hvm_send_ioreq(s, &p, 0);
if ( rc != X86EMUL_RETRY || currd->is_shutting_down )
vio->io_req.state = STATE_IOREQ_NONE;
else if ( data_is_addr )
rc = X86EMUL_OKAY;
}
break;
}
case X86EMUL_UNIMPLEMENTED:
ASSERT_UNREACHABLE();
default:
BUG();
}
ASSERT(rc != X86EMUL_UNIMPLEMENTED);
if ( rc != X86EMUL_OKAY )
return rc;
finish_access:
if ( dir == IOREQ_READ )
{
hvmtrace_io_assist(&p);
if ( !data_is_addr )
memcpy(p_data, &p.data, size);
}
return X86EMUL_OKAY;
}

guint8 *
pango_log2vis_get_embedding_levels (const gchar    *text,
int             length,
