char *
XkbVModIndexText(XkbDescPtr xkb, unsigned ndx, unsigned format)
{
register int len;
register Atom *vmodNames;
char *rtrn;
const char *tmp;
char numBuf[20];
if (xkb && xkb->names)
vmodNames = xkb->names->vmods;
else
vmodNames = NULL;
tmp = NULL;
if (ndx >= XkbNumVirtualMods)
tmp = "illegal";
else if (vmodNames && (vmodNames[ndx] != None))
tmp = NameForAtom(vmodNames[ndx]);
if (tmp == NULL) {
snprintf(numBuf, sizeof(numBuf), "%d", ndx);
tmp = numBuf;
}
len = strlen(tmp) + 1;
if (format == XkbCFile)
len += 4;
if (len >= BUFFER_SIZE)
len = BUFFER_SIZE - 1;
rtrn = tbGetBuffer(len);
if (format == XkbCFile) {
strcpy(rtrn, "vmod_");
strncpy(&rtrn[5], tmp, len - 4);
}
else
strncpy(rtrn, tmp, len);
return rtrn;
}

std::string 
XmlRpcUtil::getNextTag(std::string const& xml, int* offset)
{
if (*offset >= int(xml.length())) return std::string();
size_t pos = *offset;
const char* cp = xml.c_str() + pos;
while (*cp && isspace(*cp)) {
++cp;
++pos;
}
if (*cp != '<') return std::string();
std::string s;
do {
s += *cp;
++pos;
} while (*cp++ != '>' && *cp != 0);
*offset = int(pos);
return s;
}

static long madvise_willneed(struct vm_area_struct *vma,
struct vm_area_struct **prev,
unsigned long start, unsigned long end)
{
struct file *file = vma->vm_file;
#ifdef CONFIG_SWAP
if (!file) {
*prev = vma;
force_swapin_readahead(vma, start, end);
return 0;
}
if (shmem_mapping(file->f_mapping)) {
*prev = vma;
force_shm_swapin_readahead(vma, start, end,
file->f_mapping);
return 0;
}
#else
if (!file)
return -EBADF;
#endif
if (IS_DAX(file_inode(file))) {
return 0;
}
*prev = vma;
start = ((start - vma->vm_start) >> PAGE_SHIFT) + vma->vm_pgoff;
if (end > vma->vm_end)
end = vma->vm_end;
end = ((end - vma->vm_start) >> PAGE_SHIFT) + vma->vm_pgoff;
force_page_cache_readahead(file->f_mapping, file, start, end - start);
return 0;
}

