return -EINVAL;
return d->get_page_state(pte, addr) == d->desired ? 0 : -EPERM;
}

bool Cu6mPlayer::load(const std::string &filename, const CFileProvider &fp)
{
unsigned long filesize, decompressed_filesize;
binistream *f;
f = fp.open(filename); if(!f) return false;
filesize = fp.filesize(f);
if (filesize >= 6)
{
unsigned char pseudo_header[6];
f->readString((char *)pseudo_header, 6);
decompressed_filesize = pseudo_header[0] + (pseudo_header[1] << 8);
if (!( (pseudo_header[2]==0) && (pseudo_header[3]==0) &&
(pseudo_header[4] + ((pseudo_header[5] & 0x1)<<8) == 0x100) &&
(decompressed_filesize > (filesize-4)) ))
{
fp.close(f);
return(false);
}
}
else
{
fp.close(f);
return(false);
}
song_data = new unsigned char[decompressed_filesize];
unsigned char* compressed_song_data = new unsigned char[filesize-3];
f->seek(4);
f->readString((char *)compressed_song_data, filesize - 4);
fp.close(f);
data_block source, destination;
source.size = filesize-4;
source.data = compressed_song_data;
destination.size = decompressed_filesize;
destination.data = song_data;
if (!lzw_decompress(source,destination))
{
delete[] compressed_song_data;
delete[] song_data;
return(false);
}
delete[] compressed_song_data;
rewind(0);
return (true);
}

static struct lys_node *
read_yin_leaf(struct lys_module *module, struct lys_node *parent, struct lyxml_elem *yin, int options,
struct unres_schema *unres)
{
struct ly_ctx *ctx = module->ctx;
struct lys_node *retval;
struct lys_node_leaf *leaf;
struct lyxml_elem *sub, *next;
const char *value;
int r, has_type = 0;
int c_must = 0, c_ftrs = 0, f_mand = 0, c_ext = 0;
void *reallocated;
leaf = calloc(1, sizeof *leaf);
LY_CHECK_ERR_RETURN(!leaf, LOGMEM(ctx), NULL);
leaf->nodetype = LYS_LEAF;
leaf->prev = (struct lys_node *)leaf;
retval = (struct lys_node *)leaf;
if (read_yin_common(module, parent, retval, LYEXT_PAR_NODE, yin,
OPT_IDENT | OPT_MODULE | ((options & LYS_PARSE_OPT_CFG_IGNORE) ? OPT_CFG_IGNORE :
(options & LYS_PARSE_OPT_CFG_NOINHERIT) ? OPT_CFG_PARSE : OPT_CFG_PARSE | OPT_CFG_INHERIT),
unres)) {
goto error;
}
LOGDBG(LY_LDGYIN, "parsing %s statement \"%s\"", yin->name, retval->name);
if (lys_node_addchild(parent, lys_main_module(module), retval, options)) {
goto error;
}
LY_TREE_FOR_SAFE(yin->child, next, sub) {
if (strcmp(sub->ns->value, LY_NSYIN)) {
YIN_CHECK_ARRAY_OVERFLOW_GOTO(ctx, c_ext, retval->ext_size, "extensions", "leaf", error);
c_ext++;
continue;
} else if (!strcmp(sub->name, "type")) {
if (has_type) {
LOGVAL(ctx, LYE_TOOMANY, LY_VLOG_LYS, retval, sub->name, yin->name);
goto error;
}
leaf->type.der = (struct lys_tpdf *)sub;
leaf->type.parent = (struct lys_tpdf *)leaf;
has_type = 1;
} else if (!strcmp(sub->name, "default")) {
if (leaf->dflt) {
LOGVAL(ctx, LYE_TOOMANY, LY_VLOG_LYS, retval, sub->name, yin->name);
goto error;
}
GETVAL(ctx, value, sub, "value");
leaf->dflt = lydict_insert(ctx, value, strlen(value));
if (lyp_yin_parse_subnode_ext(module, retval, LYEXT_PAR_NODE, sub, LYEXT_SUBSTMT_DEFAULT, 0, unres)) {
goto error;
}
} else if (!strcmp(sub->name, "units")) {
if (leaf->units) {
LOGVAL(ctx, LYE_TOOMANY, LY_VLOG_LYS, retval, sub->name, yin->name);
goto error;
}
GETVAL(ctx, value, sub, "name");
leaf->units = lydict_insert(ctx, value, strlen(value));
if (lyp_yin_parse_subnode_ext(module, retval, LYEXT_PAR_NODE, sub, LYEXT_SUBSTMT_UNITS, 0, unres)) {
goto error;
}
} else if (!strcmp(sub->name, "mandatory")) {
if (f_mand) {
LOGVAL(ctx, LYE_TOOMANY, LY_VLOG_LYS, retval, sub->name, yin->name);
goto error;
}
f_mand = 1;
GETVAL(ctx, value, sub, "value");
if (!strcmp(value, "true")) {
leaf->flags |= LYS_MAND_TRUE;
} else if (!strcmp(value, "false")) {
leaf->flags |= LYS_MAND_FALSE;
} else {
LOGVAL(ctx, LYE_INARG, LY_VLOG_LYS, retval, value, sub->name);
goto error;
}                   
if (lyp_yin_parse_subnode_ext(module, retval, LYEXT_PAR_NODE, sub, LYEXT_SUBSTMT_MANDATORY, 0, unres)) {
goto error;
}
} else if (!strcmp(sub->name, "when")) {
if (leaf->when) {
LOGVAL(ctx, LYE_TOOMANY, LY_VLOG_LYS, retval, sub->name, yin->name);
goto error;
}
leaf->when = read_yin_when(module, sub, unres);
if (!leaf->when) {
goto error;
}
} else if (!strcmp(sub->name, "must")) {
YIN_CHECK_ARRAY_OVERFLOW_GOTO(ctx, c_must, leaf->must_size, "musts", "leaf", error);
c_must++;
continue;
} else if (!strcmp(sub->name, "if-feature")) {
YIN_CHECK_ARRAY_OVERFLOW_GOTO(ctx, c_ftrs, retval->iffeature_size, "musts", "leaf", error);
c_ftrs++;
continue;
} else {
LOGVAL(ctx, LYE_INSTMT, LY_VLOG_LYS, retval, sub->name);
goto error;
}
}
if (!has_type) {
LOGVAL(ctx, LYE_MISSCHILDSTMT, LY_VLOG_LYS, retval, "type", yin->name);
goto error;
}
if (leaf->dflt && (leaf->flags & LYS_MAND_TRUE)) {
LOGVAL(ctx, LYE_INCHILDSTMT, LY_VLOG_LYS, retval, "mandatory", "leaf");
LOGVAL(ctx, LYE_SPEC, LY_VLOG_PREV, NULL,
"The \"mandatory\" statement is forbidden on leaf with the \"default\" statement.");
goto error;
}
if (c_must) {
leaf->must = calloc(c_must, sizeof *leaf->must);
LY_CHECK_ERR_GOTO(!leaf->must, LOGMEM(ctx), error);
}
if (c_ftrs) {
leaf->iffeature = calloc(c_ftrs, sizeof *leaf->iffeature);
LY_CHECK_ERR_GOTO(!leaf->iffeature, LOGMEM(ctx), error);
}
if (c_ext) {
reallocated = realloc(retval->ext, (c_ext + retval->ext_size) * sizeof *retval->ext);
LY_CHECK_ERR_GOTO(!reallocated, LOGMEM(ctx), error);
retval->ext = reallocated;
memset(&retval->ext[retval->ext_size], 0, c_ext * sizeof *retval->ext);
}
LY_TREE_FOR_SAFE(yin->child, next, sub) {
if (strcmp(sub->ns->value, LY_NSYIN)) {
r = lyp_yin_fill_ext(retval, LYEXT_PAR_NODE, 0, 0, module, sub, &retval->ext, &retval->ext_size, unres);
if (r) {
goto error;
}
} else if (!strcmp(sub->name, "must")) {
r = fill_yin_must(module, sub, &leaf->must[leaf->must_size], unres);
leaf->must_size++;
if (r) {
goto error;
}
} else if (!strcmp(sub->name, "if-feature")) {
r = fill_yin_iffeature(retval, 0, sub, &leaf->iffeature[leaf->iffeature_size], unres);
leaf->iffeature_size++;
if (r) {
goto error;
}
}
}
lyp_reduce_ext_list(&retval->ext, retval->ext_size, c_ext + retval->ext_size);
if (unres_schema_add_node(module, unres, &leaf->type, UNRES_TYPE_DER, retval) == -1) {
leaf->type.der = NULL;
goto error;
}
if (!(ctx->models.flags & LY_CTX_TRUSTED) &&
(unres_schema_add_node(module, unres, &leaf->type, UNRES_TYPE_DFLT,
(struct lys_node *)(&leaf->dflt)) == -1)) {
goto error;
}
if (!(ctx->models.flags & LY_CTX_TRUSTED) && (leaf->when || leaf->must)) {
if (options & LYS_PARSE_OPT_INGRP) {
if (lyxp_node_check_syntax(retval)) {
goto error;
}
} else {
if (unres_schema_add_node(module, unres, retval, UNRES_XPATH, NULL) == -1) {
goto error;
}
}
}
for (r = 0; r < retval->ext_size; ++r) {
if (retval->ext[r]->flags & LYEXT_OPT_VALID) {
retval->flags |= LYS_VALID_EXT;
break;
}
}
return retval;
error:
lys_node_free(retval, NULL, 0);
return NULL;
}

void Rewriter::VisitVariableProxy(VariableProxy* proxy) {
if (proxy->is_resolved()) {
Variable* var = proxy->var();
if (var->mode() != TEMPORARY) return;
int index = old_scope_->RemoveTemporary(var);
if (index >= 0) {
temps_.push_back(std::make_pair(var, index));
}
} else if (old_scope_->RemoveUnresolved(proxy)) {
new_scope_->AddUnresolved(proxy);
}
}

static int parse_response(unsigned char *buf, int buflen,
char *question, int qlen,
uint16_t *type, uint16_t *class, int *ttl,
unsigned char *response, unsigned int *response_len,
uint16_t *answers)
{
struct domain_hdr *hdr = (void *) buf;
struct domain_question *q;
unsigned char *ptr;
uint16_t qdcount = ntohs(hdr->qdcount);
uint16_t ancount = ntohs(hdr->ancount);
int err, i;
uint16_t qtype, qclass;
unsigned char *next = NULL;
unsigned int maxlen = *response_len;
GSList *aliases = NULL, *list;
char name[NS_MAXDNAME + 1];
if (buflen < 12)
return -EINVAL;
debug("qr %d qdcount %d", hdr->qr, qdcount);
if (hdr->qr != 1 || qdcount != 1)
return -EINVAL;
ptr = buf + sizeof(struct domain_hdr);
strncpy(question, (char *) ptr, qlen);
qlen = strlen(question);
ptr += qlen + 1; 
q = (void *) ptr;
qtype = ntohs(q->type);
if (qtype != 1 && qtype != 28)
return -ENOMSG;
qclass = ntohs(q->class);
ptr += 2 + 2; 
err = -ENOMSG;
*response_len = 0;
*answers = 0;
memset(name, 0, sizeof(name));
for (i = 0; i < ancount; i++) {
unsigned char rsp[NS_MAXCDNAME];
unsigned int rsp_len = sizeof(rsp) - 1;
int ret, rdlen;
memset(rsp, 0, sizeof(rsp));
ret = parse_rr(buf, ptr, buf + buflen, rsp, &rsp_len,
type, class, ttl, &rdlen, &next, name);
if (ret != 0) {
err = ret;
goto out;
}
if (*class != qclass) {
ptr = next;
next = NULL;
continue;
}
if (*type == 5 && strncmp(question, name, qlen) == 0) {
unsigned char *end = NULL;
int name_len = 0, output_len = 0;
memset(rsp, 0, sizeof(rsp));
rsp_len = sizeof(rsp) - 1;
ret = get_name(0, buf, next - rdlen, buf + buflen,
rsp, rsp_len, &output_len, &end,
name, &name_len);
if (ret != 0) {
ptr = next;
next = NULL;
continue;
}
aliases = g_slist_prepend(aliases, g_strdup(name));
ptr = next;
next = NULL;
continue;
}
if (*type == qtype) {
if (check_alias(aliases, name) ||
(!aliases && strncmp(question, name,
qlen) == 0)) {
if (*response_len + rsp_len > maxlen) {
err = -ENOBUFS;
goto out;
}
memcpy(response + *response_len, rsp, rsp_len);
*response_len += rsp_len;
(*answers)++;
err = 0;
}
}
ptr = next;
next = NULL;
}
out:
for (list = aliases; list; list = list->next)
g_free(list->data);
g_slist_free(aliases);
return err;
}

int doit(int argc, char *argv[], char **envp) {
#else
int main(int argc, char *argv[], char **envp) {
#endif
HTTPRequest *req;
HTTPResponse *resp = NULL;
WOURLComponents wc = WOURLComponents_Initializer;
const char *qs;
unsigned int qs_len;
char *url;
const char *script_name, *path_info, *config_url, *username, *password, *config_options;
const char *reqerr;
WOURLError urlerr;
strtbl *options = NULL;
#ifdef WIN32
_setmode(_fileno(stdout), _O_BINARY);
_setmode(_fileno(stdin), _O_BINARY);
#endif
if(argc == 2 && strcmp(argv[1], "test") == 0)
{
exit(do_tests());
}
script_name = getenv(CGI_SCRIPT_NAME);
path_info = getenv(CGI_PATH_INFO);
if (script_name == NULL)
die(INV_SCRIPT, HTTP_NOT_FOUND);
else if (path_info == NULL) {
path_info = "/";
}
config_url = getenv(WO_CONFIG_URL);
if (!config_url) {
config_url = CONFIG_URL; 
username = getenv(WO_ADAPTOR_INFO_USERNAME);
if (username && strlen(username) != 0) {
st_add(options, WOUSERNAME, username, 0);
password = getenv(WO_ADAPTOR_INFO_PASSWORD);
if(password && strlen(password) != 0) {
st_add(options, WOPASSWORD, password, 0);
}
}
config_options = getenv(WO_CONFIG_OPTIONS);
if (config_options)
st_add(options, WOOPTIONS, config_options, 0);
if (init_adaptor(options)) {
die("The request could not be completed due to a server error.", HTTP_SERVER_ERROR);
}
url = WOMALLOC(strlen(path_info) + strlen(script_name) + 1);
strcpy(url, script_name);
strcat(url, path_info);
WOLog(WO_INFO,"<CGI> new request: %s",url);
urlerr = WOParseApplicationName(&wc, url);
if (urlerr != WOURLOK) {
const char *_urlerr;
_urlerr = WOURLstrerror(urlerr);
WOLog(WO_INFO,"URL Parsing Error: %s", _urlerr);
if (urlerr == WOURLInvalidApplicationName) {
if (ac_authorizeAppListing(&wc)) {
resp = WOAdaptorInfo(NULL, &wc);
die_resp(resp);
} else {
die(_urlerr, HTTP_NOT_FOUND);
}
}
die(_urlerr, HTTP_BAD_REQUEST);
}
req = req_new( getenv("REQUEST_METHOD"), NULL);
reqerr = req_validateMethod(req);
if (reqerr) {
die(reqerr, HTTP_BAD_REQUEST);
}
while (envp && *envp) {
char *key, *value;
key = WOSTRDUP(*envp);
for (value = key; *value && !isspace((int)*value) && (*value != '='); value++) {}
if (*value) {
*value++ = '\0';  
}
while (*value && (isspace((int)*value) || (*value == '='))) {
value++;
}
if (strcmp((const char *)key, "SSL_CLIENT_CERTIFICATE") == 0 || strcmp((const char *)key, "SSL_SERVER_CERTIFICATE") == 0 ) {
value = 0;
WOLog(WO_INFO,"<CGI> DROPPING ENV VAR (DUPLICATE) = %s", key);
}
if (strcmp((const char *)key, "SSL_CLIENT_CERT") == 0 || strcmp((const char *)key, "SSL_SERVER_CERT") == 0) {
value = make_cert_one_line(value);
}
if (key && *key && value && *value) {
req_addHeader(req, key, value, STR_COPYKEY|STR_COPYVALUE);
}
if (freeValueNeeded ) {
free(value);
freeValueNeeded=0;
}
WOFREE(key);
envp++;      
}
if (req->content_length > 0) {
req_allocateContent(req, req->content_length, 1);
req->getMoreContent = (req_getMoreContentCallback)readContentData;
if (req->content_buffer_size == 0)
die(ALLOCATION_FAILURE, HTTP_SERVER_ERROR);
if (readContentData(req, req->content, req->content_buffer_size, 1) == -1) {
die(WOURLstrerror(WOURLInvalidPostData), HTTP_BAD_REQUEST);
}
}
qs = getenv("QUERY_STRING");
if (qs) {
qs_len = strlen(qs);
} else {
qs_len = 0;
}
if (qs_len > 0) {
wc.queryString.start = qs;
wc.queryString.length = qs_len;
WOLog(WO_INFO,"<CGI> new request with Query String: %s", qs);
}
resp = tr_handleRequest(req, url, &wc, getenv(CGI_SERVER_PROTOCOL), documentRoot());
if (resp != NULL) {
sendResponse(resp);
resp_free(resp);   
}
WOFREE(url);
st_free(options);
req_free(req);
#if defined(FINDLEAKS)
showleaks();
#endif
return 0;
}

static int elo_probe(struct hid_device *hdev, const struct hid_device_id *id)
{
struct elo_priv *priv;
int ret;
struct usb_device *udev;
if (!hid_is_usb(hdev))
return -EINVAL;
priv = kzalloc(sizeof(*priv), GFP_KERNEL);
if (!priv)
return -ENOMEM;
INIT_DELAYED_WORK(&priv->work, elo_work);
udev = interface_to_usbdev(to_usb_interface(hdev->dev.parent));
priv->usbdev = usb_get_dev(udev);
hid_set_drvdata(hdev, priv);
ret = hid_parse(hdev);
if (ret) {
hid_err(hdev, "parse failed\n");
goto err_free;
}
ret = hid_hw_start(hdev, HID_CONNECT_DEFAULT);
if (ret) {
hid_err(hdev, "hw start failed\n");
goto err_free;
}
if (elo_broken_firmware(priv->usbdev)) {
hid_info(hdev, "broken firmware found, installing workaround\n");
queue_delayed_work(wq, &priv->work, ELO_PERIODIC_READ_INTERVAL);
}
return 0;
err_free:
kfree(priv);
return ret;
}

bool timerqueue_del(struct timerqueue_head *head, struct timerqueue_node *node)
{
WARN_ON_ONCE(RB_EMPTY_NODE(&node->node));
if (head->next == node) {
struct rb_node *rbn = rb_next(&node->node);
head->next = rb_entry_safe(rbn, struct timerqueue_node, node);
}
rb_erase(&node->node, &head->head);
RB_CLEAR_NODE(&node->node);
return head->next != NULL;
}

static int floppy_revalidate(struct gendisk *disk)
{
int drive = (long)disk->private_data;
int cf;
int res = 0;
if (test_bit(FD_DISK_CHANGED_BIT, &UDRS->flags) ||
test_bit(FD_VERIFY_BIT, &UDRS->flags) ||
test_bit(drive, &fake_change) ||
drive_no_geom(drive)) {
if (WARN(atomic_read(&usage_count) == 0,
"VFS: revalidate called on non-open device.\n"))
return -EFAULT;
lock_fdc(drive, false);
cf = (test_bit(FD_DISK_CHANGED_BIT, &UDRS->flags) ||
test_bit(FD_VERIFY_BIT, &UDRS->flags));
if (!(cf || test_bit(drive, &fake_change) || drive_no_geom(drive))) {
process_fd_request();
return 0;
}
UDRS->maxblock = 0;
UDRS->maxtrack = 0;
if (buffer_drive == drive)
buffer_track = -1;
clear_bit(drive, &fake_change);
clear_bit(FD_DISK_CHANGED_BIT, &UDRS->flags);
if (cf)
UDRS->generation++;
if (drive_no_geom(drive)) {
res = __floppy_read_block_0(opened_bdev[drive], drive);
} else {
if (cf)
poll_drive(false, FD_RAW_NEED_DISK);
process_fd_request();
}
}
set_capacity(disk, floppy_sizes[UDRS->fd_device]);
return res;
}

static bool hvm_wait_for_io(struct hvm_ioreq_vcpu *sv, ioreq_t *p)
{
while ( sv->pending )
{
unsigned int state = p->state;
smp_rmb();
switch ( state )
{
case STATE_IOREQ_NONE:
hvm_io_assist(sv, ~0ul);
break;
case STATE_IORESP_READY: 
p->state = STATE_IOREQ_NONE;
hvm_io_assist(sv, p->data);
break;
case STATE_IOREQ_READY:  
case STATE_IOREQ_INPROCESS:
wait_on_xen_event_channel(sv->ioreq_evtchn, p->state != state);
break;
default:
gdprintk(XENLOG_ERR, "Weird HVM iorequest state %u\n", state);
sv->pending = false;
domain_crash(sv->vcpu->domain);
return false; 
}
}
return true;
}

int imap_subscribe(char *path, bool subscribe)
{
struct ImapData *idata = NULL;
char buf[LONG_STRING];
char mbox[LONG_STRING];
char errstr[STRING];
struct Buffer err, token;
struct ImapMbox mx;
if (!mx_is_imap(path) || imap_parse_path(path, &mx) || !mx.mbox)
{
mutt_error(_("Bad mailbox name"));
return -1;
}
idata = imap_conn_find(&(mx.account), 0);
if (!idata)
goto fail;
imap_fix_path(idata, mx.mbox, buf, sizeof(buf));
if (!*buf)
mutt_str_strfcpy(buf, "INBOX", sizeof(buf));
if (ImapCheckSubscribed)
{
mutt_buffer_init(&token);
mutt_buffer_init(&err);
err.data = errstr;
err.dsize = sizeof(errstr);
snprintf(mbox, sizeof(mbox), "%smailboxes \"%s\"", subscribe ? "" : "un", path);
if (mutt_parse_rc_line(mbox, &token, &err))
mutt_debug(1, "Error adding subscribed mailbox: %s\n", errstr);
FREE(&token.data);
}
if (subscribe)
mutt_message(_("Subscribing to %s..."), buf);
else
mutt_message(_("Unsubscribing from %s..."), buf);
imap_munge_mbox_name(idata, mbox, sizeof(mbox), buf);
snprintf(buf, sizeof(buf), "%sSUBSCRIBE %s", subscribe ? "" : "UN", mbox);
if (imap_exec(idata, buf, 0) < 0)
goto fail;
imap_unmunge_mbox_name(idata, mx.mbox);
if (subscribe)
mutt_message(_("Subscribed to %s"), mx.mbox);
else
mutt_message(_("Unsubscribed from %s"), mx.mbox);
FREE(&mx.mbox);
return 0;
fail:
FREE(&mx.mbox);
return -1;
}

void
PackLinuxElf32::PackLinuxElf32help1(InputFile *f)
{
e_type  = get_te16(&ehdri.e_type);
e_phnum = get_te16(&ehdri.e_phnum);
e_shnum = get_te16(&ehdri.e_shnum);
unsigned const e_phentsize = get_te16(&ehdri.e_phentsize);
if (ehdri.e_ident[Elf32_Ehdr::EI_CLASS]!=Elf32_Ehdr::ELFCLASS32
|| sizeof(Elf32_Phdr) != e_phentsize
|| (Elf32_Ehdr::ELFDATA2MSB == ehdri.e_ident[Elf32_Ehdr::EI_DATA]
&& &N_BELE_RTP::be_policy != bele)
|| (Elf32_Ehdr::ELFDATA2LSB == ehdri.e_ident[Elf32_Ehdr::EI_DATA]
&& &N_BELE_RTP::le_policy != bele)) {
e_phoff = 0;
e_shoff = 0;
sz_phdrs = 0;
return;
}
if (0==e_phnum) throwCantUnpack("0==e_phnum");
e_phoff = get_te32(&ehdri.e_phoff);
unsigned const last_Phdr = e_phoff + e_phnum * sizeof(Elf32_Phdr);
if (last_Phdr < e_phoff || (unsigned long)file_size < last_Phdr) {
throwCantUnpack("bad e_phoff");
}
e_shoff = get_te32(&ehdri.e_shoff);
unsigned const last_Shdr = e_shoff + e_shnum * sizeof(Elf32_Shdr);
if (last_Shdr < e_shoff || (unsigned long)file_size < last_Shdr) {
if (opt->cmd == CMD_COMPRESS) {
throwCantUnpack("bad e_shoff");
}
}
sz_phdrs = e_phnum * e_phentsize;
if (f && Elf32_Ehdr::ET_DYN!=e_type) {
unsigned const len = sz_phdrs + e_phoff;
alloc_file_image(file_image, len);
f->seek(0, SEEK_SET);
f->readx(file_image, len);
phdri= (Elf32_Phdr       *)(e_phoff + file_image);      }
if (f && Elf32_Ehdr::ET_DYN==e_type) {
alloc_file_image(file_image, file_size);
f->seek(0, SEEK_SET);
f->readx(file_image, file_size);
phdri= (Elf32_Phdr *)(e_phoff + file_image);          shdri= (Elf32_Shdr *)(e_shoff + file_image);          if (opt->cmd != CMD_COMPRESS) {
shdri = NULL;
}
sec_dynsym = elf_find_section_type(Elf32_Shdr::SHT_DYNSYM);
if (sec_dynsym) {
unsigned t = get_te32(&sec_dynsym->sh_link);
if (e_shnum <= t)
throwCantPack("bad dynsym->sh_link");
sec_dynstr = &shdri[t];
}
Elf32_Phdr const *phdr= phdri;
for (int j = e_phnum; --j>=0; ++phdr)
if (Elf32_Phdr::PT_DYNAMIC==get_te32(&phdr->p_type)) {
dynseg= (Elf32_Dyn const *)(check_pt_dynamic(phdr) + file_image);
invert_pt_dynamic(dynseg);
}
else if (PT_LOAD32==get_te32(&phdr->p_type)) {
check_pt_load(phdr);
}
dynstr =      (char const *)elf_find_dynamic(Elf32_Dyn::DT_STRTAB);
dynsym = (Elf32_Sym const *)elf_find_dynamic(Elf32_Dyn::DT_SYMTAB);
gashtab = (unsigned const *)elf_find_dynamic(Elf32_Dyn::DT_GNU_HASH);
hashtab = (unsigned const *)elf_find_dynamic(Elf32_Dyn::DT_HASH);
jni_onload_sym = elf_lookup("JNI_OnLoad");
if (jni_onload_sym) {
jni_onload_va = get_te32(&jni_onload_sym->st_value);
jni_onload_va = 0;          }
}
}

static int bgp_update_receive(struct peer *peer, bgp_size_t size)
{
int ret, nlri_ret;
uint8_t *end;
struct stream *s;
struct attr attr;
bgp_size_t attribute_len;
bgp_size_t update_len;
bgp_size_t withdraw_len;
bool restart = false;
enum NLRI_TYPES {
NLRI_UPDATE,
NLRI_WITHDRAW,
NLRI_MP_UPDATE,
NLRI_MP_WITHDRAW,
NLRI_TYPE_MAX
};
struct bgp_nlri nlris[NLRI_TYPE_MAX];
if (!peer_established(peer)) {
flog_err(EC_BGP_INVALID_STATUS,
"%s [FSM] Update packet received under status %s",
peer->host,
lookup_msg(bgp_status_msg, peer->connection->status,
NULL));
bgp_notify_send(peer, BGP_NOTIFY_FSM_ERR,
bgp_fsm_error_subcode(peer->connection->status));
return BGP_Stop;
}
memset(&attr, 0, sizeof(attr));
attr.label_index = BGP_INVALID_LABEL_INDEX;
attr.label = MPLS_INVALID_LABEL;
memset(&nlris, 0, sizeof(nlris));
memset(peer->rcvd_attr_str, 0, BUFSIZ);
peer->rcvd_attr_printed = 0;
s = peer->curr;
end = stream_pnt(s) + size;
if (stream_pnt(s) + 2 > end) {
flog_err(EC_BGP_UPDATE_RCV,
"%s [Error] Update packet error (packet length is short for unfeasible length)",
peer->host);
bgp_notify_send(peer, BGP_NOTIFY_UPDATE_ERR,
BGP_NOTIFY_UPDATE_MAL_ATTR);
return BGP_Stop;
}
withdraw_len = stream_getw(s);
if (stream_pnt(s) + withdraw_len > end) {
flog_err(EC_BGP_UPDATE_RCV,
"%s [Error] Update packet error (packet unfeasible length overflow %d)",
peer->host, withdraw_len);
bgp_notify_send(peer, BGP_NOTIFY_UPDATE_ERR,
BGP_NOTIFY_UPDATE_MAL_ATTR);
return BGP_Stop;
}
if (withdraw_len > 0) {
nlris[NLRI_WITHDRAW].afi = AFI_IP;
nlris[NLRI_WITHDRAW].safi = SAFI_UNICAST;
nlris[NLRI_WITHDRAW].nlri = stream_pnt(s);
nlris[NLRI_WITHDRAW].length = withdraw_len;
stream_forward_getp(s, withdraw_len);
}
if (stream_pnt(s) + 2 > end) {
flog_warn(
EC_BGP_UPDATE_PACKET_SHORT,
"%s [Error] Packet Error (update packet is short for attribute length)",
peer->host);
bgp_notify_send(peer, BGP_NOTIFY_UPDATE_ERR,
BGP_NOTIFY_UPDATE_MAL_ATTR);
return BGP_Stop;
}
attribute_len = stream_getw(s);
if (stream_pnt(s) + attribute_len > end) {
flog_warn(
EC_BGP_UPDATE_PACKET_LONG,
"%s [Error] Packet Error (update packet attribute length overflow %d)",
peer->host, attribute_len);
bgp_notify_send(peer, BGP_NOTIFY_UPDATE_ERR,
BGP_NOTIFY_UPDATE_MAL_ATTR);
return BGP_Stop;
}
enum bgp_attr_parse_ret attr_parse_ret = BGP_ATTR_PARSE_PROCEED;
#define NLRI_ATTR_ARG (attr_parse_ret != BGP_ATTR_PARSE_WITHDRAW ? &attr : NULL)
if (attribute_len) {
attr_parse_ret = bgp_attr_parse(peer, &attr, attribute_len,
&nlris[NLRI_MP_UPDATE],
&nlris[NLRI_MP_WITHDRAW]);
if (attr_parse_ret == BGP_ATTR_PARSE_ERROR) {
bgp_attr_unintern_sub(&attr);
return BGP_Stop;
}
}
if (attr_parse_ret == BGP_ATTR_PARSE_WITHDRAW
|| BGP_DEBUG(update, UPDATE_IN)
|| BGP_DEBUG(update, UPDATE_PREFIX)) {
ret = bgp_dump_attr(&attr, peer->rcvd_attr_str,
sizeof(peer->rcvd_attr_str));
peer->stat_upd_7606++;
if (attr_parse_ret == BGP_ATTR_PARSE_WITHDRAW)
flog_err(
EC_BGP_UPDATE_RCV,
"%pBP rcvd UPDATE with errors in attr(s)!! Withdrawing route.",
peer);
if (ret && bgp_debug_update(peer, NULL, NULL, 1)) {
zlog_debug("%pBP rcvd UPDATE w/ attr: %s", peer,
peer->rcvd_attr_str);
peer->rcvd_attr_printed = 1;
}
}
update_len = end - stream_pnt(s);
if (update_len) {
nlris[NLRI_UPDATE].afi = AFI_IP;
nlris[NLRI_UPDATE].safi = SAFI_UNICAST;
nlris[NLRI_UPDATE].nlri = stream_pnt(s);
nlris[NLRI_UPDATE].length = update_len;
stream_forward_getp(s, update_len);
if (CHECK_FLAG(attr.flag, ATTR_FLAG_BIT(BGP_ATTR_MP_REACH_NLRI))) {
if (bgp_attr_nexthop_valid(peer, &attr) < 0) {
bgp_attr_unintern_sub(&attr);
return BGP_Stop;
}
}
}
if (BGP_DEBUG(update, UPDATE_IN))
zlog_debug("%pBP rcvd UPDATE wlen %d attrlen %d alen %d", peer,
withdraw_len, attribute_len, update_len);
for (int i = NLRI_UPDATE; i < NLRI_TYPE_MAX; i++) {
if (!nlris[i].nlri)
continue;
if (!peer->afc[nlris[i].afi][nlris[i].safi]) {
zlog_info(
"%s [Info] UPDATE for non-enabled AFI/SAFI %u/%u",
peer->host, nlris[i].afi, nlris[i].safi);
continue;
}
if (nlris[i].length == 0)
continue;
switch (i) {
case NLRI_UPDATE:
case NLRI_MP_UPDATE:
nlri_ret = bgp_nlri_parse(peer, NLRI_ATTR_ARG,
&nlris[i], 0);
break;
case NLRI_WITHDRAW:
case NLRI_MP_WITHDRAW:
nlri_ret = bgp_nlri_parse(peer, NLRI_ATTR_ARG,
&nlris[i], 1);
break;
default:
nlri_ret = BGP_NLRI_PARSE_ERROR;
}
if (nlri_ret < BGP_NLRI_PARSE_OK
&& nlri_ret != BGP_NLRI_PARSE_ERROR_PREFIX_OVERFLOW) {
flog_err(EC_BGP_UPDATE_RCV,
"%s [Error] Error parsing NLRI", peer->host);
if (peer_established(peer))
bgp_notify_send(
peer, BGP_NOTIFY_UPDATE_ERR,
i <= NLRI_WITHDRAW
? BGP_NOTIFY_UPDATE_INVAL_NETWORK
: BGP_NOTIFY_UPDATE_OPT_ATTR_ERR);
bgp_attr_unintern_sub(&attr);
return BGP_Stop;
}
}
if ((!update_len && !withdraw_len && nlris[NLRI_MP_UPDATE].length == 0)
|| (attr_parse_ret == BGP_ATTR_PARSE_EOR)) {
afi_t afi = 0;
safi_t safi;
struct graceful_restart_info *gr_info;
if (BGP_PEER_GRACEFUL_RESTART_CAPABLE(peer)
&& BGP_PEER_RESTARTING_MODE(peer))
restart = true;
if (!attribute_len) {
afi = AFI_IP;
safi = SAFI_UNICAST;
} else if (attr.flag & ATTR_FLAG_BIT(BGP_ATTR_MP_UNREACH_NLRI)
&& nlris[NLRI_MP_WITHDRAW].length == 0) {
afi = nlris[NLRI_MP_WITHDRAW].afi;
safi = nlris[NLRI_MP_WITHDRAW].safi;
} else if (attr_parse_ret == BGP_ATTR_PARSE_EOR) {
afi = nlris[NLRI_MP_UPDATE].afi;
safi = nlris[NLRI_MP_UPDATE].safi;
}
if (afi && peer->afc[afi][safi]) {
struct vrf *vrf = vrf_lookup_by_id(peer->bgp->vrf_id);
if (!CHECK_FLAG(peer->af_sflags[afi][safi],
PEER_STATUS_EOR_RECEIVED)) {
SET_FLAG(peer->af_sflags[afi][safi],
PEER_STATUS_EOR_RECEIVED);
bgp_update_explicit_eors(peer);
gr_info = &(peer->bgp->gr_info[afi][safi]);
if (restart)
gr_info->eor_received++;
if (gr_info->eor_required
== gr_info->eor_received) {
if (bgp_debug_neighbor_events(peer))
zlog_debug(
"%s %d, %s %d",
"EOR REQ",
gr_info->eor_required,
"EOR RCV",
gr_info->eor_received);
if (gr_info->t_select_deferral) {
void *info = EVENT_ARG(
gr_info->t_select_deferral);
XFREE(MTYPE_TMP, info);
}
EVENT_OFF(gr_info->t_select_deferral);
gr_info->eor_required = 0;
gr_info->eor_received = 0;
bgp_best_path_select_defer(peer->bgp,
afi, safi);
}
}
if (peer->nsf[afi][safi])
bgp_clear_stale_route(peer, afi, safi);
zlog_info(
"%s: rcvd End-of-RIB for %s from %s in vrf %s",
__func__, get_afi_safi_str(afi, safi, false),
peer->host, vrf ? vrf->name : VRF_DEFAULT_NAME);
}
}
bgp_attr_unintern_sub(&attr);
peer->update_time = monotime(NULL);
peer->advmap_table_change = true;
return Receive_UPDATE_message;
}

static int
store_word(
spellinfo_T*spin,
char_u*word,
intflags,    intregion,    char_u*pfxlist,    intneed_affix){
intlen = (int)STRLEN(word);
intct = captype(word, word + len);
char_ufoldword[MAXWLEN];
intres = OK;
char_u*p;
(void)spell_casefold(curwin, word, len, foldword, MAXWLEN);
for (p = pfxlist; res == OK; ++p)
{
if (!need_affix || (p != NULL && *p != NUL))
res = tree_add_word(spin, foldword, spin->si_foldroot, ct | flags,
region, p == NULL ? 0 : *p);
if (p == NULL || *p == NUL)
break;
}
++spin->si_foldwcount;
if (res == OK && (ct == WF_KEEPCAP || (flags & WF_KEEPCAP)))
{
for (p = pfxlist; res == OK; ++p)
{
if (!need_affix || (p != NULL && *p != NUL))
res = tree_add_word(spin, word, spin->si_keeproot, flags,
region, p == NULL ? 0 : *p);
if (p == NULL || *p == NUL)
break;
}
++spin->si_keepwcount;
}
return res;
}

void __init init_speculation_mitigations(void)
{
enum ind_thunk thunk = THUNK_DEFAULT;
bool has_spec_ctrl, ibrs = false, hw_smt_enabled;
bool cpu_has_bug_taa, retpoline_safe;
hw_smt_enabled = check_smt_enabled();
has_spec_ctrl = (boot_cpu_has(X86_FEATURE_IBRSB) ||
boot_cpu_has(X86_FEATURE_IBRS));
if ( read_cr4() & X86_CR4_CET )
{
if ( !has_spec_ctrl )
{
printk(XENLOG_WARNING "?!? CET active, but no MSR_SPEC_CTRL?\n");
add_taint(TAINT_CPU_OUT_OF_SPEC);
}
else if ( opt_ibrs == -1 )
opt_ibrs = ibrs = true;
if ( opt_thunk == THUNK_DEFAULT || opt_thunk == THUNK_RETPOLINE )
thunk = THUNK_JMP;
}
retpoline_safe = retpoline_calculations();
if ( opt_thunk != THUNK_DEFAULT || opt_ibrs != -1 )
{
thunk = opt_thunk;
ibrs  = !!opt_ibrs;
}
else
{
if ( IS_ENABLED(CONFIG_INDIRECT_THUNK) )
{
if ( retpoline_safe )
thunk = THUNK_RETPOLINE;
else if ( has_spec_ctrl )
ibrs = true;
}
else if ( has_spec_ctrl )
ibrs = true;
}
if ( !IS_ENABLED(CONFIG_INDIRECT_THUNK) )
thunk = THUNK_NONE;
if ( ibrs && thunk == THUNK_DEFAULT )
thunk = THUNK_JMP;
if ( thunk == THUNK_DEFAULT )
thunk = THUNK_RETPOLINE;
if ( thunk == THUNK_LFENCE )
setup_force_cpu_cap(X86_FEATURE_IND_THUNK_LFENCE);
else if ( thunk == THUNK_JMP )
setup_force_cpu_cap(X86_FEATURE_IND_THUNK_JMP);
if ( boot_cpu_has(X86_FEATURE_IBRSB) )
{
if ( opt_msr_sc_pv )
{
default_spec_ctrl_flags |= SCF_ist_sc_msr;
setup_force_cpu_cap(X86_FEATURE_SC_MSR_PV);
}
if ( opt_msr_sc_hvm )
{
default_spec_ctrl_flags |= SCF_ist_sc_msr;
setup_force_cpu_cap(X86_FEATURE_SC_MSR_HVM);
}
}
if ( boot_cpu_has(X86_FEATURE_IBRS) )
{
if ( opt_msr_sc_hvm &&
(boot_cpu_data.extended_cpuid_level >= 0x8000000a) &&
(cpuid_edx(0x8000000a) & (1u << SVM_FEATURE_SPEC_CTRL)) )
setup_force_cpu_cap(X86_FEATURE_SC_MSR_HVM);
}
if ( opt_msr_sc_hvm && !cpu_has_amd_ssbd &&
(cpu_has_virt_ssbd || (amd_legacy_ssbd && amd_setup_legacy_ssbd())) )
amd_virt_spec_ctrl = true;
if ( has_spec_ctrl && ibrs )
{
if ( opt_stibp == -1 )
opt_stibp = 1;
default_xen_spec_ctrl |= SPEC_CTRL_IBRS;
}
if ( opt_stibp == -1 )
opt_stibp = !!boot_cpu_has(X86_FEATURE_AMD_STIBP);
if ( opt_stibp && (boot_cpu_has(X86_FEATURE_STIBP) ||
boot_cpu_has(X86_FEATURE_AMD_STIBP)) )
default_xen_spec_ctrl |= SPEC_CTRL_STIBP;
if ( opt_ssbd && (boot_cpu_has(X86_FEATURE_SSBD) ||
boot_cpu_has(X86_FEATURE_AMD_SSBD)) )
{
if ( opt_psfd == -1 )
opt_psfd = 1;
default_xen_spec_ctrl |= SPEC_CTRL_SSBD;
}
if ( opt_psfd == -1 )
opt_psfd = 0;
if ( opt_psfd && (boot_cpu_has(X86_FEATURE_PSFD) ||
boot_cpu_has(X86_FEATURE_INTEL_PSFD)) )
default_xen_spec_ctrl |= SPEC_CTRL_PSFD;
BUILD_BUG_ON(RO_MPT_VIRT_START != PML4_ADDR(256));
if ( opt_rsb_pv == -1 )
{
opt_rsb_pv = (opt_pv32 || !boot_cpu_has(X86_FEATURE_XEN_SMEP) ||
!rsb_is_full_width());
if ( !opt_rsb_pv && hw_smt_enabled &&
(boot_cpu_data.x86_vendor & (X86_VENDOR_AMD|X86_VENDOR_HYGON)) &&
(boot_cpu_data.x86 == 0x17 || boot_cpu_data.x86 == 0x18) )
setup_force_cpu_cap(X86_FEATURE_SC_RSB_IDLE);
}
if ( opt_rsb_pv )
{
setup_force_cpu_cap(X86_FEATURE_SC_RSB_PV);
default_spec_ctrl_flags |= SCF_ist_rsb;
}
if ( opt_rsb_hvm )
{
setup_force_cpu_cap(X86_FEATURE_SC_RSB_HVM);
if ( !cpu_has_svm )
default_spec_ctrl_flags |= SCF_ist_rsb;
}
ibpb_calculations();
if ( opt_eager_fpu == -1 )
opt_eager_fpu = should_use_eager_fpu();
init_shadow_spec_ctrl_state();
if ( boot_cpu_has(X86_FEATURE_IBRSB) && !cpu_has_eibrs &&
hw_smt_enabled && default_xen_spec_ctrl )
setup_force_cpu_cap(X86_FEATURE_SC_MSR_IDLE);
xpti_init_default();
l1tf_calculations();
if ( opt_pv_l1tf_hwdom == -1 )
opt_pv_l1tf_hwdom = 0;
if ( opt_pv_l1tf_domu == -1 )
opt_pv_l1tf_domu = !pv_shim && cpu_has_bug_l1tf;
if ( !boot_cpu_has(X86_FEATURE_L1D_FLUSH) )
opt_l1d_flush = 0;
else if ( opt_l1d_flush == -1 )
opt_l1d_flush = cpu_has_bug_l1tf && !cpu_has_skip_l1dfl;
if ( !opt_branch_harden )
setup_force_cpu_cap(X86_FEATURE_SC_NO_BRANCH_HARDEN);
if ( opt_smt == -1 && cpu_has_bug_l1tf && !pv_shim && hw_smt_enabled )
warning_add(
"Booted on L1TF-vulnerable hardware with SMT/Hyperthreading\n"
"enabled.  Please assess your configuration and choose an\n"
"explicit 'smt=<bool>' setting.  See XSA-273.\n");
mds_calculations();
if ( opt_unpriv_mmio )
opt_fb_clear_mmio = cpu_has_fb_clear;
if ( opt_md_clear_pv == -1 )
opt_md_clear_pv = ((cpu_has_bug_mds || cpu_has_bug_msbds_only) &&
boot_cpu_has(X86_FEATURE_MD_CLEAR));
if ( opt_md_clear_hvm == -1 )
opt_md_clear_hvm = ((cpu_has_bug_mds || cpu_has_bug_msbds_only) &&
boot_cpu_has(X86_FEATURE_MD_CLEAR));
if ( opt_md_clear_pv || opt_md_clear_hvm || opt_fb_clear_mmio )
setup_force_cpu_cap(X86_FEATURE_SC_VERW_IDLE);
opt_md_clear_hvm &= !cpu_has_skip_l1dfl && !opt_l1d_flush;
if ( opt_smt == -1 && cpu_has_bug_mds && hw_smt_enabled )
warning_add(
"Booted on MLPDS/MFBDS-vulnerable hardware with SMT/Hyperthreading\n"
"enabled.  Mitigations will not be fully effective.  Please\n"
"choose an explicit smt=<bool> setting.  See XSA-297.\n");
cpu_has_bug_taa =
(cpu_has_rtm || cpu_has_tsx_ctrl) && cpu_has_mds_no && !cpu_has_taa_no;
if ( opt_tsx == -1 && cpu_has_bug_taa && cpu_has_tsx_ctrl &&
((hw_smt_enabled && opt_smt) ||
!boot_cpu_has(X86_FEATURE_SC_VERW_IDLE)) )
{
opt_tsx = 0;
tsx_init();
}
if ( cpu_has_srbds_ctrl )
{
if ( opt_srb_lock == -1 && !opt_unpriv_mmio &&
cpu_has_mds_no && !cpu_has_taa_no &&
(!cpu_has_hle || (cpu_has_tsx_ctrl && rtm_disabled)) )
opt_srb_lock = 0;
set_in_mcu_opt_ctrl(MCU_OPT_CTRL_RNGDS_MITG_DIS,
opt_srb_lock ? 0 : MCU_OPT_CTRL_RNGDS_MITG_DIS);
}
print_details(thunk);
if ( has_spec_ctrl )
{
struct cpu_info *info = get_cpu_info();
unsigned int val;
bsp_delay_spec_ctrl = !cpu_has_hypervisor && default_xen_spec_ctrl;
if ( bsp_delay_spec_ctrl )
{
info->shadow_spec_ctrl = 0;
barrier();
info->spec_ctrl_flags |= SCF_use_shadow;
barrier();
}
val = bsp_delay_spec_ctrl ? 0 : default_xen_spec_ctrl;
wrmsrl(MSR_SPEC_CTRL, val);
info->last_spec_ctrl = val;
}
}

static void lsr_read_paint(GF_LASeRCodec *lsr, SVG_Paint *paint, const char *name)
{
u32 val;
GF_LSR_READ_INT(lsr, val, 1, "hasIndex");
if (val) {
GF_LSR_READ_INT(lsr, val, lsr->colorIndexBits, name);
lsr_get_color(lsr, val, &paint->color);
paint->type = SVG_PAINT_COLOR;
paint->color.type = 0;
} else {
GF_LSR_READ_INT(lsr, val, 2, "enum");
switch (val) {
case 0:
GF_LSR_READ_INT(lsr, val, 2, "choice");
switch (val) {
case 0:
paint->type = SVG_PAINT_INHERIT;
break;
case 1:
paint->type = SVG_PAINT_COLOR;
paint->color.type = SVG_COLOR_CURRENTCOLOR;
break;
default:
paint->type = SVG_PAINT_NONE;
break;
}
break;
case 1:
{
XMLRI iri;
memset(&iri, 0, sizeof(XMLRI));
iri.type = 0xFF;
lsr_read_any_uri(lsr, &iri, name);
gf_node_unregister_iri(lsr->sg, &iri);
paint->type = SVG_PAINT_URI;
if (iri.string) {
paint->type = SVG_PAINT_URI;
paint->iri.type = XMLRI_STRING;
paint->iri.string = iri.string;
} else if (iri.target) {
paint->iri.type = XMLRI_ELEMENTID;
paint->iri.target = iri.target;
}
}
break;
case 2:
{
char *sysPaint=NULL;
lsr_read_byte_align_string(lsr, &sysPaint, "systemsPaint");
if (sysPaint) {
paint->type = SVG_PAINT_COLOR;
paint->color.type = gf_svg_get_system_paint_server_type(sysPaint);
gf_free(sysPaint);
}
}
break;
case 3:
lsr_read_extension(lsr, name);
break;
}
}
}

static int
dissect_eap(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
{
guint8          eap_code;
guint8          eap_identifier;
guint16         eap_len;
guint8          eap_type;
gint            len;
conversation_t *conversation       = NULL;
conv_state_t   *conversation_state = NULL;
frame_state_t  *packet_state;
int             leap_state;
proto_tree     *ti, *ti_id, *ti_len;
proto_tree     *eap_tree;
proto_tree     *eap_tls_flags_tree;
proto_item     *eap_type_item;
static address null_address = ADDRESS_INIT_NONE;
static guint8 pae_group_address_mac_addr[6] = { 0x01, 0x80, 0xC2, 0x00, 0x00, 0x03 };
static address pae_group_address = ADDRESS_INIT(AT_ETHER, sizeof(pae_group_address_mac_addr), pae_group_address_mac_addr);
packet_info    pinfo_eapol;
packet_info    *pinfo_conv;
col_set_str(pinfo->cinfo, COL_PROTOCOL, "EAP");
col_clear(pinfo->cinfo, COL_INFO);
eap_code = tvb_get_guint8(tvb, 0);
eap_identifier = tvb_get_guint8(tvb, 1);
col_add_str(pinfo->cinfo, COL_INFO,
val_to_str(eap_code, eap_code_vals, "Unknown code (0x%02X)"));
if (pinfo->src.type == AT_ETHER) {
memcpy(&pinfo_eapol, pinfo, sizeof(packet_info));
pinfo_conv = &pinfo_eapol;
if (eap_code == EAP_REQUEST) {
copy_address_shallow(&pinfo_conv->src, &null_address);
copy_address_shallow(&pinfo_conv->dst, &pae_group_address);
pinfo_conv->srcport = 443;
} else {
copy_address_shallow(&pinfo_conv->src, &pae_group_address);
copy_address_shallow(&pinfo_conv->dst, &null_address);
pinfo_conv->destport = 443;
}
} else {
pinfo_conv = pinfo;
}
guint32 tls_group = pinfo_conv->curr_proto_layer_num << 16;
if (eap_code == EAP_REQUEST) {
pinfo_conv->destport |= tls_group;
} else {
pinfo_conv->srcport |= tls_group;
}
if (PINFO_FD_VISITED(pinfo_conv) || !(eap_code == EAP_REQUEST && tvb_get_guint8(tvb, 4) == EAP_TYPE_ID)) {
conversation = find_conversation_pinfo(pinfo_conv, 0);
}
if (conversation == NULL) {
conversation = conversation_new(pinfo_conv->num, &pinfo_conv->src,
&pinfo_conv->dst, conversation_pt_to_conversation_type(pinfo_conv->ptype),
pinfo_conv->srcport, pinfo_conv->destport, 0);
}
conversation_state = (conv_state_t *)conversation_get_proto_data(conversation, proto_eap);
if (conversation_state == NULL) {
conversation_state = wmem_new(wmem_file_scope(), conv_state_t);
conversation_state->eap_tls_seq      = -1;
conversation_state->eap_reass_cookie =  0;
conversation_state->leap_state       = -1;
conversation_state->last_eap_id_req  = -1;
conversation_state->last_eap_id_resp = -1;
conversation_add_proto_data(conversation, proto_eap, conversation_state);
}
if (eap_code == EAP_FAILURE)
conversation_state->leap_state = -1;
eap_len = tvb_get_ntohs(tvb, 2);
len     = eap_len;
ti = proto_tree_add_item(tree, proto_eap, tvb, 0, len, ENC_NA);
eap_tree = proto_item_add_subtree(ti, ett_eap);
proto_tree_add_item(eap_tree, hf_eap_code, tvb, 0, 1, ENC_BIG_ENDIAN);
ti_id = proto_tree_add_item(eap_tree, hf_eap_identifier, tvb, 1, 1, ENC_BIG_ENDIAN);
ti_len = proto_tree_add_item(eap_tree, hf_eap_len, tvb, 2, 2, ENC_BIG_ENDIAN);
if (len < 4 || (guint)len > tvb_reported_length(tvb)) {
expert_add_info(pinfo, ti_len, &ei_eap_bad_length);
}
gboolean is_duplicate_id = FALSE;
if (conversation_state) {
if (eap_code == EAP_REQUEST || eap_code == EAP_RESPONSE ||
eap_code == EAP_INITIATE || eap_code == EAP_FINISH) {
if (!PINFO_FD_VISITED(pinfo)) {
gint16 *last_eap_id = eap_code == EAP_REQUEST || eap_code == EAP_INITIATE ?
&conversation_state->last_eap_id_req :
&conversation_state->last_eap_id_resp;
is_duplicate_id = *last_eap_id == eap_identifier;
*last_eap_id = eap_identifier;
if (is_duplicate_id) {
p_add_proto_data(wmem_file_scope(), pinfo, proto_eap, PROTO_DATA_EAP_DUPLICATE_ID | tls_group, GINT_TO_POINTER(1));
}
} else {
is_duplicate_id = !!p_get_proto_data(wmem_file_scope(), pinfo, proto_eap, PROTO_DATA_EAP_DUPLICATE_ID | tls_group);
}
if (is_duplicate_id) {
expert_add_info(pinfo, ti_id, &ei_eap_retransmission);
}
}
}
switch (eap_code) {
case EAP_SUCCESS:
case EAP_FAILURE:
break;
case EAP_REQUEST:
case EAP_RESPONSE:
eap_type = tvb_get_guint8(tvb, 4);
col_append_fstr(pinfo->cinfo, COL_INFO, ", %s",
val_to_str_ext(eap_type, &eap_type_vals_ext,
"Unknown type (0x%02x)"));
eap_type_item = proto_tree_add_item(eap_tree, hf_eap_type, tvb, 4, 1, ENC_BIG_ENDIAN);
if ((len > 5) || ((len == 5) && (eap_type == EAP_TYPE_ID))) {
int     offset = 5;
gint    size   = len - offset;
switch (eap_type) {
case EAP_TYPE_ID:
if (size > 0) {
dissect_eap_identity(tvb, pinfo, eap_tree, offset, size);
}
if (conversation_state && !PINFO_FD_VISITED(pinfo)) {
conversation_state->leap_state  =  0;
conversation_state->eap_tls_seq = -1;
}
break;
case EAP_TYPE_NOTIFY:
proto_tree_add_item(eap_tree, hf_eap_notification, tvb,
offset, size, ENC_ASCII);
break;
case EAP_TYPE_NAK:
proto_tree_add_item(eap_tree, hf_eap_type_nak, tvb,
offset, 1, ENC_BIG_ENDIAN);
break;
case EAP_TYPE_MD5:
{
guint8      value_size = tvb_get_guint8(tvb, offset);
gint        extra_len  = size - 1 - value_size;
proto_item *item;
expert_add_info(pinfo, eap_type_item, &ei_eap_mitm_attacks);
item = proto_tree_add_item(eap_tree, hf_eap_md5_value_size, tvb, offset, 1, ENC_BIG_ENDIAN);
if (value_size > (size - 1))
{
expert_add_info(pinfo, item, &ei_eap_md5_value_size_overflow);
value_size = size - 1;
}
offset += 1;
proto_tree_add_item(eap_tree, hf_eap_md5_value, tvb, offset, value_size, ENC_NA);
offset += value_size;
if (extra_len > 0) {
proto_tree_add_item(eap_tree, hf_eap_md5_extra_data, tvb, offset, extra_len, ENC_NA);
}
}
break;
case EAP_TYPE_FAST:
case EAP_TYPE_PEAP:
case EAP_TYPE_TTLS:
case EAP_TYPE_TLS:
case EAP_TYPE_TEAP:
{
gboolean more_fragments;
gboolean has_length;
gboolean is_start;
gboolean outer_tlvs = false;
gint outer_tlvs_length = 0;
int      eap_tls_seq      = -1;
guint32  eap_reass_cookie =  0;
gboolean needs_reassembly =  FALSE;
if (!conversation_state) {
break;
}
ti = proto_tree_add_item(eap_tree, hf_eap_tls_flags, tvb, offset, 1, ENC_BIG_ENDIAN);
eap_tls_flags_tree = proto_item_add_subtree(ti, ett_eap_tls_flags);
proto_tree_add_item_ret_boolean(eap_tls_flags_tree, hf_eap_tls_flag_l, tvb, offset, 1, ENC_BIG_ENDIAN, &has_length);
proto_tree_add_item_ret_boolean(eap_tls_flags_tree, hf_eap_tls_flag_m, tvb, offset, 1, ENC_BIG_ENDIAN, &more_fragments);
proto_tree_add_item_ret_boolean(eap_tls_flags_tree, hf_eap_tls_flag_s, tvb, offset, 1, ENC_BIG_ENDIAN, &is_start);
switch (eap_type) {
case EAP_TYPE_TEAP:
proto_tree_add_item_ret_boolean(eap_tls_flags_tree, hf_eap_tls_flag_o, tvb, offset, 1, ENC_BIG_ENDIAN, &outer_tlvs);
case EAP_TYPE_TTLS:
case EAP_TYPE_FAST:
case EAP_TYPE_PEAP:
proto_tree_add_item(eap_tls_flags_tree, hf_eap_tls_flags_version, tvb, offset, 1, ENC_BIG_ENDIAN);
break;
}
size   -= 1;
offset += 1;
if (has_length) {
proto_tree_add_item(eap_tree, hf_eap_tls_len, tvb, offset, 4, ENC_BIG_ENDIAN);
size   -= 4;
offset += 4;
}
if (outer_tlvs) {
proto_tree_add_item_ret_uint(eap_tree, hf_eap_tls_outer_tlvs_len, tvb, offset, 4, ENC_BIG_ENDIAN, &outer_tlvs_length);
size   -= 4;
offset += 4;
}
if (is_start)
conversation_state->eap_tls_seq = -1;
if (is_duplicate_id) {
next_tvb = tvb_new_subset_length_caplen(tvb, offset, tvb_len, size);
call_data_dissector(next_tvb, pinfo, eap_tree);
break;
}
packet_state = (frame_state_t *)p_get_proto_data(wmem_file_scope(), pinfo, proto_eap, PROTO_DATA_EAP_FRAME_STATE | tls_group);
if (packet_state == NULL) {
if (!pinfo->fd->visited) {
if (conversation_state->eap_tls_seq != -1) {
needs_reassembly = TRUE;
conversation_state->eap_tls_seq++;
eap_reass_cookie = conversation_state->eap_reass_cookie;
eap_tls_seq = conversation_state->eap_tls_seq;
} else if (more_fragments && has_length) {
needs_reassembly = TRUE;
conversation_state->eap_reass_cookie = pinfo->num;
conversation_state->eap_tls_seq = 0;
eap_tls_seq = conversation_state->eap_tls_seq;
eap_reass_cookie = conversation_state->eap_reass_cookie;
}
if (needs_reassembly) {
packet_state = wmem_new(wmem_file_scope(), frame_state_t);
packet_state->info = eap_reass_cookie;
p_add_proto_data(wmem_file_scope(), pinfo, proto_eap, PROTO_DATA_EAP_FRAME_STATE | tls_group, packet_state);
}
}
} else {
needs_reassembly = TRUE;
eap_reass_cookie = packet_state->info;
eap_tls_seq = 0;
}
if (needs_reassembly) {
fragment_head   *fd_head;
save_fragmented   = pinfo->fragmented;
pinfo->fragmented = TRUE;
fd_head = fragment_add_seq(&eap_tls_reassembly_table,
tvb, offset,
pinfo, eap_reass_cookie, NULL,
eap_tls_seq,
size,
more_fragments, 0);
if (fd_head != NULL && fd_head->reassembled_in == pinfo->num) {
proto_item *frag_tree_item;
next_tvb = tvb_new_chain(tvb, fd_head->tvb_data);
add_new_data_source(pinfo, next_tvb, "Reassembled EAP-TLS");
show_fragment_seq_tree(fd_head, &eap_tls_frag_items,
eap_tree, pinfo, next_tvb, &frag_tree_item);
if (!pinfo->fd->visited)
conversation_state->eap_tls_seq = -1;
}
pinfo->fragmented = save_fragmented;
} else { 
next_tvb = tvb_new_subset_length_caplen(tvb, offset, tvb_len, size);
}
if (next_tvb) {
switch (eap_type) {
case EAP_TYPE_TTLS:
tls_set_appdata_dissector(tls_handle, pinfo_conv, diameter_avps_handle);
break;
case EAP_TYPE_PEAP:
p_add_proto_data(pinfo->pool, pinfo, proto_eap, PROTO_DATA_EAP_TVB | tls_group, tvb);
tls_set_appdata_dissector(tls_handle, pinfo_conv, peap_handle);
break;
case EAP_TYPE_TEAP:
if (outer_tlvs) {
case EAP_TYPE_LEAP:
{
guint8 count, namesize;
expert_add_info(pinfo, eap_type_item, &ei_eap_dictionary_attacks);
proto_tree_add_item(eap_tree, hf_eap_leap_version, tvb, offset, 1, ENC_BIG_ENDIAN);
offset += 1;
proto_tree_add_item(eap_tree, hf_eap_leap_reserved, tvb, offset, 1, ENC_BIG_ENDIAN);
offset += 1;
count = tvb_get_guint8(tvb, offset);
proto_tree_add_item(eap_tree, hf_eap_leap_count, tvb, offset, 1, ENC_BIG_ENDIAN);
offset += 1;
if (!conversation_state) {
break;
}
packet_state = (frame_state_t *)p_get_proto_data(wmem_file_scope(), pinfo, proto_eap, PROTO_DATA_EAP_FRAME_STATE | tls_group);
if (packet_state == NULL) {
leap_state = conversation_state->leap_state;
if (leap_state==0) leap_state =  1; else
if (leap_state==1) leap_state =  2; else
if (leap_state==2) leap_state =  3; else
if (leap_state==3) leap_state =  4; else
if (leap_state==4) leap_state = -1;
packet_state = wmem_new(wmem_file_scope(), frame_state_t);
packet_state->info = leap_state;
p_add_proto_data(wmem_file_scope(), pinfo, proto_eap, PROTO_DATA_EAP_FRAME_STATE | tls_group, packet_state);
conversation_state->leap_state = leap_state;
}
leap_state = packet_state->info;
switch (leap_state) {
case 1:
proto_tree_add_item(eap_tree, hf_eap_leap_peer_challenge, tvb, offset, count, ENC_NA);
break;
case 2:
proto_tree_add_item(eap_tree, hf_eap_leap_peer_response, tvb, offset, count, ENC_NA);
break;
case 3:
proto_tree_add_item(eap_tree, hf_eap_leap_ap_challenge, tvb, offset, count, ENC_NA);
break;
case 4:
proto_tree_add_item(eap_tree, hf_eap_leap_ap_response, tvb, offset, count, ENC_NA);
break;
default:
proto_tree_add_item(eap_tree, hf_eap_leap_data, tvb, offset, count, ENC_NA);
break;
}
offset += count;
namesize = eap_len - (8+count);
proto_tree_add_item(eap_tree, hf_eap_leap_name, tvb, offset, namesize, ENC_ASCII);
}
break; 
case EAP_TYPE_MSCHAPV2:
dissect_eap_mschapv2(eap_tree, tvb, pinfo, offset, size);
break; 
case EAP_TYPE_SIM:
dissect_eap_sim(eap_tree, tvb, pinfo, offset, size);
break; 
case EAP_TYPE_AKA:
case EAP_TYPE_AKA_PRIME:
dissect_eap_aka(eap_tree, tvb, pinfo, offset, size);
break; 
case EAP_TYPE_EXT:
{
proto_tree *exptree;
exptree   = proto_tree_add_subtree(eap_tree, tvb, offset, size, ett_eap_exp_attr, NULL, "Expanded Type");
dissect_exteap(exptree, tvb, offset, size, pinfo, eap_code, eap_identifier);
}
break;
case EAP_TYPE_PAX:
dissect_eap_pax(eap_tree, tvb, pinfo, offset, size);
break; 
case EAP_TYPE_PSK:
dissect_eap_psk(eap_tree, tvb, pinfo, offset, size);
break; 
case EAP_TYPE_SAKE:
dissect_eap_sake(eap_tree, tvb, pinfo, offset, size);
break; 
case EAP_TYPE_GPSK:
dissect_eap_gpsk(eap_tree, tvb, pinfo, offset, size);
break; 
case EAP_TYPE_IKEV2:
{
gboolean more_fragments;
gboolean has_length;
gboolean icv_present;
ti = proto_tree_add_item(eap_tree, hf_eap_ikev2_flags, tvb, offset, 1, ENC_BIG_ENDIAN);
eap_tls_flags_tree = proto_item_add_subtree(ti, hf_eap_ikev2_flags);
proto_tree_add_item_ret_boolean(eap_tls_flags_tree, hf_eap_ikev2_flag_l, tvb, offset, 1, ENC_BIG_ENDIAN, &has_length);
proto_tree_add_item_ret_boolean(eap_tls_flags_tree, hf_eap_ikev2_flag_m, tvb, offset, 1, ENC_BIG_ENDIAN, &more_fragments);
proto_tree_add_item_ret_boolean(eap_tls_flags_tree, hf_eap_ikev2_flag_i, tvb, offset, 1, ENC_BIG_ENDIAN, &icv_present);
size -= 1;
offset += 1;
if (has_length) {
proto_tree_add_item(eap_tree, hf_eap_ikev2_len, tvb, offset, 4, ENC_BIG_ENDIAN);
size -= 4;
offset += 4;
}
if (size > 0) {
tvbuff_t* next_tvb = NULL;
gint      tvb_len;
tvb_len = tvb_captured_length_remaining(tvb, offset);
if (size < tvb_len) {
tvb_len = size;
}
if (has_length || more_fragments) {
} else {
next_tvb = tvb_new_subset_length_caplen(tvb, offset, tvb_len, size);
guint tmp = call_dissector(isakmp_handle, next_tvb, pinfo, eap_tree);
size -= tmp;
offset += tmp;
if (icv_present && size > 0) {
proto_tree_add_item(eap_tree, hf_eap_ikev2_int_chk_data, tvb, offset, size, ENC_NA);
}
}
}
break;
} 
case EAP_TYPE_MSAUTH_TLV:
dissect_eap_msauth_tlv(eap_tree, tvb, pinfo, offset, size);
break; 
default:
proto_tree_add_item(eap_tree, hf_eap_data, tvb, offset, size, ENC_NA);
break;
} 
}
} 
return tvb_captured_length(tvb);
}

LIBXSMM_API_INTERN
void libxsmm_sparse_csc_reader( libxsmm_generated_code* io_generated_code,
const char*             i_csc_file_in,
unsigned int**          o_row_idx,
unsigned int**          o_column_idx,
double**                o_values,
unsigned int*           io_row_count,
unsigned int*           io_column_count,
unsigned int*           o_element_count ) {
FILE *l_csc_file_handle;
const unsigned int l_line_length = 512;
char l_line[512+1];
unsigned int l_header_read = 0;
unsigned int* l_column_idx_id = NULL;
unsigned int l_i = 0;
l_csc_file_handle = fopen( i_csc_file_in, "r" );
if ( l_csc_file_handle == NULL ) {
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSC_INPUT );
return;
}
while (fgets(l_line, l_line_length, l_csc_file_handle) != NULL) {
if ( strlen(l_line) == l_line_length ) {
free(*o_row_idx); free(*o_column_idx); free(*o_values); free(l_column_idx_id);
*o_row_idx = 0; *o_column_idx = 0; *o_values = 0;
fclose( l_csc_file_handle ); 
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSC_READ_LEN );
return;
}
if ( l_line[0] == '%' ) {
continue;
} else {
if ( l_header_read == 0 ) {
unsigned int row_count, column_count;
if (3 == sscanf(l_line, "%u %u %u", &row_count, &column_count, o_element_count) &&
0 != row_count && 0 != column_count && 0 != *o_element_count)
{
*io_column_count = LIBXSMM_MAX(*io_column_count, column_count);
*io_row_count = LIBXSMM_MAX(*io_row_count, row_count);
*o_row_idx = (unsigned int*) malloc(sizeof(unsigned int) * (*o_element_count));
*o_column_idx = (unsigned int*) malloc(sizeof(unsigned int) * ((size_t)(*io_column_count) + 1));
*o_values = (double*) malloc(sizeof(double) * (*o_element_count));
l_column_idx_id = (unsigned int*) malloc(sizeof(unsigned int) * (*io_column_count));
if ( ( *o_row_idx == NULL )      ||
( *o_column_idx == NULL )   ||
( *o_values == NULL )       ||
( l_column_idx_id == NULL ) ) {
free(*o_row_idx); free(*o_column_idx); free(*o_values); free(l_column_idx_id);
*o_row_idx = 0; *o_column_idx = 0; *o_values = 0;
fclose(l_csc_file_handle); 
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSC_ALLOC_DATA );
return;
}
memset(*o_row_idx, 0, sizeof(unsigned int) * (*o_element_count));
memset(*o_column_idx, 0, sizeof(unsigned int) * ((size_t)(*io_column_count) + 1));
memset(*o_values, 0, sizeof(double) * (*o_element_count));
memset(l_column_idx_id, 0, sizeof(unsigned int) * (*io_column_count));
for (l_i = 0; l_i <= *io_column_count; ++l_i) {
(*o_column_idx)[l_i] = *o_element_count;
}
(*o_column_idx)[0] = 0;
l_i = 0;
l_header_read = 1;
} else {
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSC_READ_DESC );
fclose( l_csc_file_handle ); 
return;
}
} else {
unsigned int l_row = 0, l_column = 0;
double l_value = 0;
if ( sscanf(l_line, "%u %u %lf", &l_row, &l_column, &l_value) != 3 ) {
free(*o_row_idx); free(*o_column_idx); free(*o_values); free(l_column_idx_id);
*o_row_idx = 0; *o_column_idx = 0; *o_values = 0;
fclose(l_csc_file_handle); 
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSC_READ_ELEMS );
return;
}
LIBXSMM_ASSERT(0 != l_row && 0 != l_column);
l_row--; l_column--;
(*o_row_idx)[l_i] = l_row;
(*o_values)[l_i] = l_value;
l_i++;
l_column_idx_id[l_column] = 1;
(*o_column_idx)[l_column+1] = l_i;
}
}
}
fclose( l_csc_file_handle );
if ( l_i != (*o_element_count) ) {
free(*o_row_idx); free(*o_column_idx); free(*o_values); free(l_column_idx_id);
*o_row_idx = 0; *o_column_idx = 0; *o_values = 0;
LIBXSMM_HANDLE_ERROR( io_generated_code, LIBXSMM_ERR_CSC_LEN );
return;
}
if ( l_column_idx_id != NULL ) {
for ( l_i = 0; l_i < (*io_column_count); l_i++) {
if ( l_column_idx_id[l_i] == 0 ) {
(*o_column_idx)[l_i+1] = (*o_column_idx)[l_i];
}
}
free( l_column_idx_id );
}
}

static gint dissect_PHSCALE(tvbuff_t *tvb, proto_tree *tree, gint offset, gint cnt)
{
proto_tree *temp_tree;
gint i;
if (0 == cnt) {
return offset;
}
temp_tree = proto_tree_add_subtree_format(tree, tvb, offset, 12 * cnt, ett_conf_phconv, NULL,
"Phasor scaling and data flags (%u)", cnt);
for (i = 0; i < cnt; i++) {
proto_tree *single_phasor_scaling_and_flags_tree;
proto_tree *phasor_flag1_tree;
proto_tree *phasor_flag2_tree;
proto_tree *data_flag_tree;
single_phasor_scaling_and_flags_tree = proto_tree_add_subtree_format(temp_tree, tvb, offset, 12,
ett_conf_phlist, NULL,
"Phasor #%u", i + 1);
data_flag_tree = proto_tree_add_subtree_format(single_phasor_scaling_and_flags_tree, tvb, offset, 4,
ett_conf_phflags, NULL, "Phasor Data flags: %s",
conf_phasor_type[tvb_get_guint8(tvb, offset + 2)].strptr);
phasor_flag1_tree = proto_tree_add_subtree_format(data_flag_tree, tvb, offset, 2, ett_conf_phmod_flags,
NULL, "Modification Flags: 0x%04x",
tvb_get_ntohs(tvb, offset));
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b15, tvb, offset, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b10, tvb, offset, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b09, tvb, offset, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b08, tvb, offset, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b07, tvb, offset, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b06, tvb, offset, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b05, tvb, offset, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b04, tvb, offset, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b03, tvb, offset, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b02, tvb, offset, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(phasor_flag1_tree, hf_conf_phasor_mod_b01, tvb, offset, 2, ENC_BIG_ENDIAN);
offset += 2;
proto_tree_add_item(data_flag_tree, hf_conf_phasor_type_b03, tvb, offset, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(data_flag_tree, hf_conf_phasor_type_b02to00, tvb, offset, 1, ENC_BIG_ENDIAN);
offset += 1;
phasor_flag2_tree = proto_tree_add_subtree_format(data_flag_tree, tvb, offset, 1, ett_conf_ph_user_flags,
NULL, "User designated flags: 0x%02x",
tvb_get_guint8(tvb, offset));
proto_tree_add_item(phasor_flag2_tree, hf_conf_phasor_user_data, tvb, offset, 1, ENC_BIG_ENDIAN);
offset += 1;
proto_tree_add_item(single_phasor_scaling_and_flags_tree, hf_conf_phasor_scale_factor,
tvb, offset, 4, ENC_BIG_ENDIAN);
offset += 4;
proto_tree_add_item(single_phasor_scaling_and_flags_tree, hf_conf_phasor_angle_offset,
tvb, offset, 4, ENC_BIG_ENDIAN);
offset += 4;
}
return offset;
}

static int map_update_elem(union bpf_attr *attr, bpfptr_t uattr)
{
bpfptr_t ukey = make_bpfptr(attr->key, uattr.is_kernel);
bpfptr_t uvalue = make_bpfptr(attr->value, uattr.is_kernel);
int ufd = attr->map_fd;
struct bpf_map *map;
void *key, *value;
u32 value_size;
struct fd f;
int err;
if (CHECK_ATTR(BPF_MAP_UPDATE_ELEM))
return -EINVAL;
f = fdget(ufd);
map = __bpf_map_get(f);
if (IS_ERR(map))
return PTR_ERR(map);
if (!(map_get_sys_perms(map, f) & FMODE_CAN_WRITE)) {
err = -EPERM;
goto err_put;
}
if ((attr->flags & BPF_F_LOCK) &&
!map_value_has_spin_lock(map)) {
err = -EINVAL;
goto err_put;
}
key = ___bpf_copy_key(ukey, map->key_size);
if (IS_ERR(key)) {
err = PTR_ERR(key);
goto err_put;
}
value_size = bpf_map_value_size(map);
err = -ENOMEM;
value = kvmalloc(value_size, GFP_USER | __GFP_NOWARN);
if (!value)
goto free_key;
err = -EFAULT;
if (copy_from_bpfptr(value, uvalue, value_size) != 0)
goto free_value;
err = bpf_map_update_value(map, f, key, value, attr->flags);
free_value:
kvfree(value);
free_key:
kvfree(key);
err_put:
fdput(f);
return err;
}

