int nbd_client_co_pwritev(BlockDriverState *bs, uint64_t offset,
uint64_t bytes, QEMUIOVector *qiov, int flags)
{
NBDClientSession *client = nbd_get_client_session(bs);
NBDRequest request = {
.type = NBD_CMD_WRITE,
.from = offset,
.len = bytes,
};
NBDReply reply;
ssize_t ret;
if (flags & BDRV_REQ_FUA) {
assert(client->nbdflags & NBD_FLAG_SEND_FUA);
request.flags |= NBD_CMD_FLAG_FUA;
}
assert(bytes <= NBD_MAX_BUFFER_SIZE);
nbd_coroutine_start(client, &request);
ret = nbd_co_send_request(bs, &request, qiov);
if (ret < 0) {
reply.error = -ret;
} else {
nbd_co_receive_reply(client, &request, &reply, NULL);
}
nbd_coroutine_end(client, &request);
return -reply.error;
}

static int sign_pFwInfo(FW_INFO_T *pFwInfo, ECC_KEY_T *ecdsa_key)
{
int ret = -1;
EC_KEY *eckey = EC_KEY_new();
if (NULL == eckey) {
printf("Failed to create new EC Key\n");
return -1;
}
EC_GROUP *ecgroup = EC_GROUP_new_by_curve_name(NID_X9_62_prime256v1);
if (NULL == ecgroup) {
printf("Failed to create new EC Group\n");
goto exit;
}
if (EC_KEY_set_group(eckey, ecgroup) != 1) {
printf("Failed to set group for EC Key\n");
goto exit;
}
memcpy((void *) pFwInfo->pubkey.au32Key0, (void *) ecdsa_key->Qx, 32);
memcpy((void *) pFwInfo->pubkey.au32Key1, (void *) ecdsa_key->Qy, 32);
BIGNUM* x = BN_bin2bn((void *) ecdsa_key->Qx, 32, NULL);
BIGNUM* y = BN_bin2bn((void *) ecdsa_key->Qy, 32, NULL);
BIGNUM* d = BN_bin2bn((void *) ecdsa_key->d, 32, NULL);
EC_KEY_set_private_key(eckey, d);
EC_KEY_set_public_key_affine_coordinates(eckey, x, y);
uint32_t au32HeadHash[8];
unsigned int u32Size = sizeof(FW_INFO_T) - sizeof(ECDSA_SIGN_T);
sha256((unsigned char *) pFwInfo, u32Size, (unsigned char *) au32HeadHash);
ECDSA_SIG *signature = ECDSA_do_sign((unsigned char *) au32HeadHash, u32Size,
eckey);
if (NULL == signature) {
printf("Failed to generate EC Signature\n");
} else {
if (ECDSA_do_verify((unsigned char *) au32HeadHash, u32Size, signature,
eckey) != 1) {
printf("Failed to verify EC Signature\n");
} else {
BIGNUM *r, *s;
#if OPENSSL_VERSION_NUMBER >= 0x10100000L
ECDSA_SIG_get0(signature, &r, &s);
#else
r = signature->r;
s = signature->s;
#endif
BN_bn2bin(r, (unsigned char *) pFwInfo->sign.au32R);
BN_bn2bin(s, (unsigned char *) pFwInfo->sign.au32S);
BN_free(x);
BN_free(y);
BN_free(d);
BN_free(r);
BN_free(s);
}
}
ret = 0;
exit: EC_GROUP_free(ecgroup);
EC_KEY_free(eckey);
return ret;
}

static void get_icu_disp_value_src_php( char* tag_name, INTERNAL_FUNCTION_PARAMETERS) 
{
const char* loc_name        = NULL;
int         loc_name_len    = 0;
const char* disp_loc_name       = NULL;
int         disp_loc_name_len   = 0;
int         free_loc_name       = 0;
UChar*      disp_name      = NULL;
int32_t     disp_name_len  = 0;
char*       mod_loc_name        = NULL;
int32_t     buflen          = 512;
UErrorCode  status          = U_ZERO_ERROR;
char*       utf8value= NULL;
int         utf8value_len   = 0;
char*       msg             = NULL;
int         grOffset    = 0;
intl_error_reset( NULL TSRMLS_CC );
if(zend_parse_parameters( ZEND_NUM_ARGS() TSRMLS_CC, "s|s",
&loc_name, &loc_name_len , 
&disp_loc_name ,&disp_loc_name_len ) == FAILURE)
{
spprintf(&msg , 0, "locale_get_display_%s : unable to parse input params", tag_name );
intl_error_set( NULL, U_ILLEGAL_ARGUMENT_ERROR,  msg , 1 TSRMLS_CC );
efree(msg);
RETURN_FALSE;
}
if(loc_name_len > ULOC_FULLNAME_CAPACITY) {
spprintf(&msg , 0, "locale_get_display_%s : name too long", tag_name );
intl_error_set( NULL, U_ILLEGAL_ARGUMENT_ERROR,  msg , 1 TSRMLS_CC );
efree(msg);
RETURN_FALSE;
}
if(loc_name_len == 0) {
loc_name = intl_locale_get_default(TSRMLS_C);
}
if( strcmp(tag_name, DISP_NAME) != 0 ){
grOffset = findOffset( LOC_GRANDFATHERED , loc_name );
if( grOffset >= 0 ){
if( strcmp(tag_name , LOC_LANG_TAG)==0 ){
mod_loc_name = getPreferredTag( loc_name );
} else {
RETURN_FALSE;
}
}
} 
if( mod_loc_name==NULL ){
mod_loc_name = estrdup( loc_name );
}
if( !disp_loc_name){
disp_loc_name = estrdup(intl_locale_get_default(TSRMLS_C));
free_loc_name = 1;
}
do{
disp_name = erealloc( disp_name , buflen * sizeof(UChar)  );
disp_name_len = buflen;
if( strcmp(tag_name , LOC_LANG_TAG)==0 ){
buflen = uloc_getDisplayLanguage ( mod_loc_name , disp_loc_name , disp_name , disp_name_len , &status);
} else if( strcmp(tag_name , LOC_SCRIPT_TAG)==0 ){
buflen = uloc_getDisplayScript ( mod_loc_name , disp_loc_name , disp_name , disp_name_len , &status);
} else if( strcmp(tag_name , LOC_REGION_TAG)==0 ){
buflen = uloc_getDisplayCountry ( mod_loc_name , disp_loc_name , disp_name , disp_name_len , &status);
} else if( strcmp(tag_name , LOC_VARIANT_TAG)==0 ){
buflen = uloc_getDisplayVariant ( mod_loc_name , disp_loc_name , disp_name , disp_name_len , &status);
} else if( strcmp(tag_name , DISP_NAME)==0 ){
buflen = uloc_getDisplayName ( mod_loc_name , disp_loc_name , disp_name , disp_name_len , &status);
}
if( U_FAILURE( status ) )
{
if( status == U_BUFFER_OVERFLOW_ERROR )
{
status = U_ZERO_ERROR;
continue;
}
spprintf(&msg, 0, "locale_get_display_%s : unable to get locale %s", tag_name , tag_name );
intl_error_set( NULL, status, msg , 1 TSRMLS_CC );
efree(msg);
if( disp_name){
efree( disp_name );
}
if( mod_loc_name){
efree( mod_loc_name );
}
if (free_loc_name) {
efree((void *)disp_loc_name);
disp_loc_name = NULL;
}
RETURN_FALSE;
}
} while( buflen > disp_name_len );
if( mod_loc_name){
efree( mod_loc_name );
}
if (free_loc_name) {
efree((void *)disp_loc_name);
disp_loc_name = NULL;
}
intl_convert_utf16_to_utf8( &utf8value, &utf8value_len, disp_name, buflen, &status );
efree( disp_name );
if( U_FAILURE( status ) )
{
spprintf(&msg, 0, "locale_get_display_%s :error converting display name for %s to UTF-8", tag_name , tag_name );
intl_error_set( NULL, status, msg , 1 TSRMLS_CC );
efree(msg);
RETURN_FALSE;
}
RETVAL_STRINGL( utf8value, utf8value_len , FALSE);
}

void out_string(conn *c, const char *str) {
size_t len;
mc_resp *resp = c->resp;
assert(c != NULL);
resp_reset(resp);
if (c->noreply) {
resp->skip = true;
if (settings.verbose > 1)
fprintf(stderr, ">%d NOREPLY %s\n", c->sfd, str);
conn_set_state(c, conn_new_cmd);
return;
}
if (settings.verbose > 1)
fprintf(stderr, ">%d %s\n", c->sfd, str);
len = strlen(str);
if ((len + 2) > WRITE_BUFFER_SIZE) {
str = "SERVER_ERROR output line too long";
len = strlen(str);
}
memcpy(resp->wbuf, str, len);
memcpy(resp->wbuf + len, "\r\n", 2);
resp_add_iov(resp, resp->wbuf, len + 2);
conn_set_state(c, conn_new_cmd);
return;
}

TfLiteStatus Prepare(TfLiteContext* context, TfLiteNode* node) {
const auto* params = reinterpret_cast<TfLiteSVDFParams*>(node->builtin_data);
OpData* op_data = reinterpret_cast<OpData*>(node->user_data);
int scratch_tensor_index = op_data->scratch_tensor_index;
TF_LITE_ENSURE_EQ(context, node->outputs->size, 1);
TF_LITE_ENSURE_EQ(context, node->inputs->size, 5);
const TfLiteTensor* input;
TF_LITE_ENSURE_OK(context, GetInputSafe(context, node, kInputTensor, &input));
const TfLiteTensor* weights_feature;
TF_LITE_ENSURE_OK(context, GetInputSafe(context, node, kWeightsFeatureTensor,
&weights_feature));
const TfLiteTensor* weights_time;
TF_LITE_ENSURE_OK(
context, GetInputSafe(context, node, kWeightsTimeTensor, &weights_time));
TF_LITE_ENSURE(context,
input->type == kTfLiteFloat32 || input->type == kTfLiteInt8);
const int rank = params->rank;
const int batch_size = input->dims->data[0];
const int num_filters = weights_feature->dims->data[0];
TF_LITE_ENSURE(context, rank != 0);
TF_LITE_ENSURE_EQ(context, num_filters % rank, 0);
const int num_units = num_filters / rank;
const int memory_size = weights_time->dims->data[1];
TF_LITE_ENSURE_EQ(context, input->dims->data[1],
weights_feature->dims->data[1]);
TF_LITE_ENSURE_EQ(context, weights_time->dims->data[0], num_filters);
const TfLiteTensor* bias = GetOptionalInputTensor(context, node, kBiasTensor);
if (bias) {
TF_LITE_ENSURE_EQ(context, bias->dims->data[0], num_units);
}
const TfLiteTensor* state;
TF_LITE_ENSURE_OK(context, GetInputSafe(context, node, kStateTensor, &state));
TfLiteTensor* output;
TF_LITE_ENSURE_OK(context,
GetOutputSafe(context, node, kOutputTensor, &output));
TF_LITE_ENSURE_EQ(context, NumDimensions(state), 2);
TF_LITE_ENSURE_EQ(context, SizeOfDimension(state, 0), batch_size);
TF_LITE_ENSURE_EQ(context, SizeOfDimension(state, 1),
memory_size * num_filters);
TfLiteIntArray* output_size_array = TfLiteIntArrayCreate(2);
output_size_array->data[0] = batch_size;
output_size_array->data[1] = num_units;
TF_LITE_ENSURE_OK(context,
context->ResizeTensor(context, output, output_size_array));
const bool is_hybrid_op = IsHybridOp(input, weights_feature);
const bool is_full_integer = input->type == kTfLiteInt8;
TfLiteIntArrayFree(node->temporaries);
if (is_hybrid_op) {
node->temporaries = TfLiteIntArrayCreate(6);
} else if (is_full_integer) {
node->temporaries = TfLiteIntArrayCreate(2);
} else {
node->temporaries = TfLiteIntArrayCreate(1);
}
node->temporaries->data[0] = scratch_tensor_index;
TfLiteIntArray* scratch_size_array = TfLiteIntArrayCreate(2);
scratch_size_array->data[0] = batch_size;
scratch_size_array->data[1] = num_filters;
TfLiteTensor* scratch_tensor;
TF_LITE_ENSURE_OK(
context, GetTemporarySafe(context, node, 0, &scratch_tensor));
if (is_full_integer) {
scratch_tensor->type = kTfLiteInt32;
} else {
scratch_tensor->type = kTfLiteFloat32;
}
scratch_tensor->allocation_type = kTfLiteArenaRw;
TF_LITE_ENSURE_OK(context, context->ResizeTensor(context, scratch_tensor,
scratch_size_array));
if (is_hybrid_op) {
op_data->compute_row_sums = true;
node->temporaries->data[1] = scratch_tensor_index + 1;
TfLiteTensor* input_quantized;
TF_LITE_ENSURE_OK(context, GetTemporarySafe(context, node, 1,
&input_quantized));
input_quantized->type = weights_feature->type;
input_quantized->allocation_type = kTfLiteArenaRw;
if (!TfLiteIntArrayEqual(input_quantized->dims, input->dims)) {
TfLiteIntArray* input_quantized_size = TfLiteIntArrayCopy(input->dims);
TF_LITE_ENSURE_OK(context, context->ResizeTensor(context, input_quantized,
input_quantized_size));
}
node->temporaries->data[2] = scratch_tensor_index + 2;
TfLiteTensor* scaling_factors;
TF_LITE_ENSURE_OK(context, GetTemporarySafe(context, node, 2,
&scaling_factors));
scaling_factors->type = kTfLiteFloat32;
scaling_factors->allocation_type = kTfLiteArenaRw;
int scaling_dims[1] = {batch_size};
if (!TfLiteIntArrayEqualsArray(scaling_factors->dims, 1, scaling_dims)) {
TfLiteIntArray* scaling_factors_size = TfLiteIntArrayCreate(1);
scaling_factors_size->data[0] = batch_size;
TF_LITE_ENSURE_OK(context, context->ResizeTensor(context, scaling_factors,
scaling_factors_size));
}
node->temporaries->data[3] = scratch_tensor_index + 3;
TfLiteTensor* float_weights_time;
TF_LITE_ENSURE_OK(context, GetTemporarySafe(context, node, 3,
&float_weights_time));
float_weights_time->type = kTfLiteFloat32;
float_weights_time->allocation_type = kTfLiteArenaRwPersistent;
if (!TfLiteIntArrayEqual(float_weights_time->dims, weights_time->dims)) {
TfLiteIntArray* float_weights_time_size =
TfLiteIntArrayCopy(weights_time->dims);
TF_LITE_ENSURE_OK(context,
context->ResizeTensor(context, float_weights_time,
float_weights_time_size));
}
node->temporaries->data[4] = scratch_tensor_index + 4;
TfLiteTensor* zero_points;
TF_LITE_ENSURE_OK(
context, GetTemporarySafe(context, node, 4, &zero_points));
zero_points->type = kTfLiteFloat32;
zero_points->allocation_type = kTfLiteArenaRw;
int zero_points_dims[1] = {batch_size};
if (!TfLiteIntArrayEqualsArray(zero_points->dims, 1, zero_points_dims)) {
TfLiteIntArray* zero_points_size = TfLiteIntArrayCreate(1);
zero_points_size->data[0] = zero_points_dims[0];
TF_LITE_ENSURE_OK(context, context->ResizeTensor(context, zero_points,
zero_points_size));
}
node->temporaries->data[5] = scratch_tensor_index + 5;
TfLiteTensor* row_sums;
TF_LITE_ENSURE_OK(context,
GetTemporarySafe(context, node, 5, &row_sums));
row_sums->type = kTfLiteFloat32;
row_sums->allocation_type = kTfLiteArenaRwPersistent;
int row_sums_dims[1] = {num_filters};
if (!TfLiteIntArrayEqualsArray(row_sums->dims, 1, row_sums_dims)) {
TfLiteIntArray* row_sums_size = TfLiteIntArrayCreate(1);
row_sums_size->data[0] = row_sums_dims[0];
TF_LITE_ENSURE_OK(
context, context->ResizeTensor(context, row_sums, row_sums_size));
}
}
if (is_full_integer) {
TfLiteIntArray* output_temp_size_array = TfLiteIntArrayCreate(2);
output_temp_size_array->data[0] = num_units;
output_temp_size_array->data[1] = batch_size;
node->temporaries->data[1] = scratch_tensor_index + 1;
TfLiteTensor* output_temp;
TF_LITE_ENSURE_OK(
context, GetTemporarySafe(context, node, 1, &output_temp));
output_temp->type = kTfLiteInt32;
output_temp->allocation_type = kTfLiteArenaRw;
TF_LITE_ENSURE_OK(context, context->ResizeTensor(context, output_temp,
output_temp_size_array));
auto* input_params =
reinterpret_cast<TfLiteAffineQuantization*>(input->quantization.params);
auto* weights_feature_params = reinterpret_cast<TfLiteAffineQuantization*>(
weights_feature->quantization.params);
auto* state_params =
reinterpret_cast<TfLiteAffineQuantization*>(state->quantization.params);
auto* weight_time_params = reinterpret_cast<TfLiteAffineQuantization*>(
weights_time->quantization.params);
auto* output_params = reinterpret_cast<TfLiteAffineQuantization*>(
output->quantization.params);
const double effective_scale_1 = input_params->scale->data[0] *
weights_feature_params->scale->data[0] /
state_params->scale->data[0];
const double effective_scale_2 = state_params->scale->data[0] *
weight_time_params->scale->data[0] /
output_params->scale->data[0];
QuantizeMultiplier(effective_scale_1, &op_data->effective_scale_1_a,
&op_data->effective_scale_1_b);
QuantizeMultiplier(effective_scale_2, &op_data->effective_scale_2_a,
&op_data->effective_scale_2_b);
}
return kTfLiteOk;
}

static INLINE chunk_t *
chunk_grow(chunk_t *chunk, size_t sz)
{
off_t offset;
size_t memlen_orig = chunk->memlen;
tor_assert(sz > chunk->memlen);
offset = chunk->data - chunk->mem;
chunk = tor_realloc(chunk, CHUNK_ALLOC_SIZE(sz));
chunk->memlen = sz;
chunk->data = chunk->mem + offset;
#ifdef DEBUG_CHUNK_ALLOC
tor_assert(chunk->DBG_alloc == CHUNK_ALLOC_SIZE(memlen_orig));
chunk->DBG_alloc = CHUNK_ALLOC_SIZE(sz);
#endif
total_bytes_allocated_in_chunks +=
CHUNK_ALLOC_SIZE(sz) - CHUNK_ALLOC_SIZE(memlen_orig);
return chunk;
}

int pkey_gost_decrypt(EVP_PKEY_CTX *pctx, unsigned char *key,
size_t *key_len, const unsigned char *in, size_t in_len)
{
struct gost_pmeth_data *gctx = EVP_PKEY_CTX_get_data(pctx);
switch (gctx->cipher_nid)
{
case NID_id_Gost28147_89:
case NID_undef: 
return pkey_GOST_ECcp_decrypt(pctx, key, key_len, in, in_len);
case NID_kuznyechik_ctr:
case NID_magma_ctr:
return pkey_gost2018_decrypt(pctx, key, key_len, in, in_len);
default:
GOSTerr(GOST_F_PKEY_GOST_DECRYPT, ERR_R_INTERNAL_ERROR);
return -1;
}
}

static int pf_detect(void)
{
struct pf_unit *pf = units;
int k, unit;
printk("%s: %s version %s, major %d, cluster %d, nice %d\n",
name, name, PF_VERSION, major, cluster, nice);
par_drv = pi_register_driver(name);
if (!par_drv) {
pr_err("failed to register %s driver\n", name);
return -1;
}
k = 0;
if (pf_drive_count == 0) {
if (pi_init(pf->pi, 1, -1, -1, -1, -1, -1, pf_scratch, PI_PF,
verbose, pf->name)) {
if (!pf_probe(pf) && pf->disk) {
pf->present = 1;
k++;
} else
pi_release(pf->pi);
}
} else
for (unit = 0; unit < PF_UNITS; unit++, pf++) {
int *conf = *drives[unit];
if (!conf[D_PRT])
continue;
if (pi_init(pf->pi, 0, conf[D_PRT], conf[D_MOD],
conf[D_UNI], conf[D_PRO], conf[D_DLY],
pf_scratch, PI_PF, verbose, pf->name)) {
if (pf->disk && !pf_probe(pf)) {
pf->present = 1;
k++;
} else
pi_release(pf->pi);
}
}
if (k)
return 0;
printk("%s: No ATAPI disk detected\n", name);
for (pf = units, unit = 0; unit < PF_UNITS; pf++, unit++) {
blk_cleanup_queue(pf->disk->queue);
pf->disk->queue = NULL;
blk_mq_free_tag_set(&pf->tag_set);
put_disk(pf->disk);
}
pi_unregister_driver(par_drv);
return -1;
}

static struct line_info_table*
decode_line_info (struct comp_unit *unit, struct dwarf2_debug *stash)
{
bfd *abfd = unit->abfd;
struct line_info_table* table;
bfd_byte *line_ptr;
bfd_byte *line_end;
struct line_head lh;
unsigned int i, bytes_read, offset_size;
char *cur_file, *cur_dir;
unsigned char op_code, extended_op, adj_opcode;
unsigned int exop_len;
bfd_size_type amt;
if (! read_section (abfd, &stash->debug_sections[debug_line],
stash->syms, unit->line_offset,
&stash->dwarf_line_buffer, &stash->dwarf_line_size))
return NULL;
amt = sizeof (struct line_info_table);
table = (struct line_info_table *) bfd_alloc (abfd, amt);
if (table == NULL)
return NULL;
table->abfd = abfd;
table->comp_dir = unit->comp_dir;
table->num_files = 0;
table->files = NULL;
table->num_dirs = 0;
table->dirs = NULL;
table->num_sequences = 0;
table->sequences = NULL;
table->lcl_head = NULL;
if (stash->dwarf_line_size < 16)
{
_bfd_error_handler
(_("Dwarf Error: Line info section is too small (%Ld)"),
stash->dwarf_line_size);
bfd_set_error (bfd_error_bad_value);
return NULL;
}
line_ptr = stash->dwarf_line_buffer + unit->line_offset;
line_end = stash->dwarf_line_buffer + stash->dwarf_line_size;
lh.total_length = read_4_bytes (abfd, line_ptr, line_end);
line_ptr += 4;
offset_size = 4;
if (lh.total_length == 0xffffffff)
{
lh.total_length = read_8_bytes (abfd, line_ptr, line_end);
line_ptr += 8;
offset_size = 8;
}
else if (lh.total_length == 0 && unit->addr_size == 8)
{
lh.total_length = read_4_bytes (abfd, line_ptr, line_end);
line_ptr += 4;
offset_size = 8;
}
if (lh.total_length > (size_t) (line_end - line_ptr))
{
_bfd_error_handler
(_("Dwarf Error: Line info data is bigger (%#Lx)"
" than the space remaining in the section (%#lx)"),
lh.total_length, (unsigned long) (line_end - line_ptr));
bfd_set_error (bfd_error_bad_value);
return NULL;
}
line_end = line_ptr + lh.total_length;
lh.version = read_2_bytes (abfd, line_ptr, line_end);
if (lh.version < 2 || lh.version > 5)
{
_bfd_error_handler
(_("Dwarf Error: Unhandled .debug_line version %d."), lh.version);
bfd_set_error (bfd_error_bad_value);
return NULL;
}
line_ptr += 2;
if (line_ptr + offset_size + (lh.version >= 5 ? 8 : (lh.version >= 4 ? 6 : 5))
>= line_end)
{
_bfd_error_handler
(_("Dwarf Error: Ran out of room reading prologue"));
bfd_set_error (bfd_error_bad_value);
return NULL;
}
if (lh.version >= 5)
{
unsigned int segment_selector_size;
read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
segment_selector_size = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
if (segment_selector_size != 0)
{
_bfd_error_handler
(_("Dwarf Error: Line info unsupported segment selector size %u."),
segment_selector_size);
bfd_set_error (bfd_error_bad_value);
return NULL;
}
}
if (offset_size == 4)
lh.prologue_length = read_4_bytes (abfd, line_ptr, line_end);
else
lh.prologue_length = read_8_bytes (abfd, line_ptr, line_end);
line_ptr += offset_size;
lh.minimum_instruction_length = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
if (lh.version >= 4)
{
lh.maximum_ops_per_insn = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
}
else
lh.maximum_ops_per_insn = 1;
if (lh.maximum_ops_per_insn == 0)
{
_bfd_error_handler
(_("Dwarf Error: Invalid maximum operations per instruction."));
bfd_set_error (bfd_error_bad_value);
return NULL;
}
lh.default_is_stmt = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
lh.line_base = read_1_signed_byte (abfd, line_ptr, line_end);
line_ptr += 1;
lh.line_range = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
lh.opcode_base = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
if (line_ptr + (lh.opcode_base - 1) >= line_end)
{
_bfd_error_handler (_("Dwarf Error: Ran out of room reading opcodes"));
bfd_set_error (bfd_error_bad_value);
return NULL;
}
amt = lh.opcode_base * sizeof (unsigned char);
lh.standard_opcode_lengths = (unsigned char *) bfd_alloc (abfd, amt);
lh.standard_opcode_lengths[0] = 1;
for (i = 1; i < lh.opcode_base; ++i)
{
lh.standard_opcode_lengths[i] = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
}
if (lh.version >= 5)
{
if (!read_formatted_entries (unit, &line_ptr, line_end, table,
line_info_add_include_dir_stub))
goto fail;
if (!read_formatted_entries (unit, &line_ptr, line_end, table,
line_info_add_file_name))
goto fail;
}
else
{
while ((cur_dir = read_string (abfd, line_ptr, line_end, &bytes_read)) != NULL)
{
line_ptr += bytes_read;
if (!line_info_add_include_dir (table, cur_dir))
goto fail;
}
line_ptr += bytes_read;
while ((cur_file = read_string (abfd, line_ptr, line_end, &bytes_read)) != NULL)
{
unsigned int dir, xtime, size;
line_ptr += bytes_read;
dir = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read, FALSE, line_end);
line_ptr += bytes_read;
xtime = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read, FALSE, line_end);
line_ptr += bytes_read;
size = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read, FALSE, line_end);
line_ptr += bytes_read;
if (!line_info_add_file_name (table, cur_file, dir, xtime, size))
goto fail;
}
line_ptr += bytes_read;
}
while (line_ptr < line_end)
{
bfd_vma address = 0;
unsigned char op_index = 0;
char * filename = table->num_files ? concat_filename (table, 1) : NULL;
unsigned int line = 1;
unsigned int column = 0;
unsigned int discriminator = 0;
int is_stmt = lh.default_is_stmt;
int end_sequence = 0;
bfd_vma low_pc  = (bfd_vma) -1;
bfd_vma high_pc = 0;
while (! end_sequence)
{
op_code = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
if (op_code >= lh.opcode_base)
{
adj_opcode = op_code - lh.opcode_base;
if (lh.line_range == 0)
goto line_fail;
if (lh.maximum_ops_per_insn == 1)
address += (adj_opcode / lh.line_range
* lh.minimum_instruction_length);
else
{
address += ((op_index + adj_opcode / lh.line_range)
/ lh.maximum_ops_per_insn
* lh.minimum_instruction_length);
op_index = ((op_index + adj_opcode / lh.line_range)
% lh.maximum_ops_per_insn);
}
line += lh.line_base + (adj_opcode % lh.line_range);
if (!add_line_info (table, address, op_index, filename,
line, column, discriminator, 0))
goto line_fail;
discriminator = 0;
if (address < low_pc)
low_pc = address;
if (address > high_pc)
high_pc = address;
}
else switch (op_code)
{
case DW_LNS_extended_op:
exop_len = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
extended_op = read_1_byte (abfd, line_ptr, line_end);
line_ptr += 1;
switch (extended_op)
{
case DW_LNE_end_sequence:
end_sequence = 1;
if (!add_line_info (table, address, op_index, filename, line,
column, discriminator, end_sequence))
goto line_fail;
discriminator = 0;
if (address < low_pc)
low_pc = address;
if (address > high_pc)
high_pc = address;
if (!arange_add (unit, &unit->arange, low_pc, high_pc))
goto line_fail;
break;
case DW_LNE_set_address:
address = read_address (unit, line_ptr, line_end);
op_index = 0;
line_ptr += unit->addr_size;
break;
case DW_LNE_define_file:
cur_file = read_string (abfd, line_ptr, line_end, &bytes_read);
line_ptr += bytes_read;
if ((table->num_files % FILE_ALLOC_CHUNK) == 0)
{
struct fileinfo *tmp;
amt = table->num_files + FILE_ALLOC_CHUNK;
amt *= sizeof (struct fileinfo);
tmp = (struct fileinfo *) bfd_realloc (table->files, amt);
if (tmp == NULL)
goto line_fail;
table->files = tmp;
}
table->files[table->num_files].name = cur_file;
table->files[table->num_files].dir =
_bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
table->files[table->num_files].time =
_bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
table->files[table->num_files].size =
_bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
table->num_files++;
break;
case DW_LNE_set_discriminator:
discriminator =
_bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
break;
case DW_LNE_HP_source_file_correlation:
line_ptr += exop_len - 1;
break;
default:
_bfd_error_handler
(_("Dwarf Error: mangled line number section."));
bfd_set_error (bfd_error_bad_value);
line_fail:
if (filename != NULL)
free (filename);
goto fail;
}
break;
case DW_LNS_copy:
if (!add_line_info (table, address, op_index,
filename, line, column, discriminator, 0))
goto line_fail;
discriminator = 0;
if (address < low_pc)
low_pc = address;
if (address > high_pc)
high_pc = address;
break;
case DW_LNS_advance_pc:
if (lh.maximum_ops_per_insn == 1)
address += (lh.minimum_instruction_length
* _bfd_safe_read_leb128 (abfd, line_ptr,
&bytes_read,
FALSE, line_end));
else
{
bfd_vma adjust = _bfd_safe_read_leb128 (abfd, line_ptr,
&bytes_read,
FALSE, line_end);
address = ((op_index + adjust) / lh.maximum_ops_per_insn
* lh.minimum_instruction_length);
op_index = (op_index + adjust) % lh.maximum_ops_per_insn;
}
line_ptr += bytes_read;
break;
case DW_LNS_advance_line:
line += _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
TRUE, line_end);
line_ptr += bytes_read;
break;
case DW_LNS_set_file:
{
unsigned int file;
file = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
if (filename)
free (filename);
filename = concat_filename (table, file);
break;
}
case DW_LNS_set_column:
column = _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
break;
case DW_LNS_negate_stmt:
is_stmt = (!is_stmt);
break;
case DW_LNS_set_basic_block:
break;
case DW_LNS_const_add_pc:
if (lh.maximum_ops_per_insn == 1)
address += (lh.minimum_instruction_length
* ((255 - lh.opcode_base) / lh.line_range));
else
{
bfd_vma adjust = ((255 - lh.opcode_base) / lh.line_range);
address += (lh.minimum_instruction_length
* ((op_index + adjust)
/ lh.maximum_ops_per_insn));
op_index = (op_index + adjust) % lh.maximum_ops_per_insn;
}
break;
case DW_LNS_fixed_advance_pc:
address += read_2_bytes (abfd, line_ptr, line_end);
op_index = 0;
line_ptr += 2;
break;
default:
for (i = 0; i < lh.standard_opcode_lengths[op_code]; i++)
{
(void) _bfd_safe_read_leb128 (abfd, line_ptr, &bytes_read,
FALSE, line_end);
line_ptr += bytes_read;
}
break;
}
}
if (filename)
free (filename);
}
if (sort_line_sequences (table))
return table;
fail:
if (table->sequences != NULL)
free (table->sequences);
if (table->files != NULL)
free (table->files);
if (table->dirs != NULL)
free (table->dirs);
return NULL;
}

unsigned long hypercall_create_continuation(
unsigned int op, const char *format, ...)
{
struct mc_state *mcs = &current->mc_state;
struct cpu_user_regs *regs;
const char *p = format;
unsigned long arg, rc;
unsigned int i;
va_list args;
BUG_ON( !p || *p == '\0' );
current->hcall_preempted = true;
va_start(args, format);
if ( mcs->flags & MCSF_in_multicall )
{
for ( i = 0; *p != '\0'; i++ )
mcs->call.args[i] = next_arg(p, args);
rc = mcs->call.result;
}
else
{
regs = guest_cpu_user_regs();
#ifdef CONFIG_ARM_64
if ( !is_32bit_domain(current->domain) )
{
regs->x16 = op;
for ( i = 0; *p != '\0'; i++ )
{
arg = next_arg(p, args);
switch ( i )
{
case 0: regs->x0 = arg; break;
case 1: regs->x1 = arg; break;
case 2: regs->x2 = arg; break;
case 3: regs->x3 = arg; break;
case 4: regs->x4 = arg; break;
case 5: regs->x5 = arg; break;
}
}
rc = regs->x0;
}
else
#endif
{
regs->r12 = op;
for ( i = 0; *p != '\0'; i++ )
{
arg = next_arg(p, args);
switch ( i )
{
case 0: regs->r0 = arg; break;
case 1: regs->r1 = arg; break;
case 2: regs->r2 = arg; break;
case 3: regs->r3 = arg; break;
case 4: regs->r4 = arg; break;
case 5: regs->r5 = arg; break;
}
}
rc = regs->r0;
}
}
va_end(args);
return rc;
}

static __inline tTcpIpPacketParsingResult
ProcessTCPHeader(tTcpIpPacketParsingResult _res, PVOID pIpHeader, ULONG len, USHORT ipHeaderSize)
{
ULONG tcpipDataAt;
tTcpIpPacketParsingResult res = _res;
tcpipDataAt = ipHeaderSize + sizeof(TCPHeader);
res.xxpStatus = ppresXxpIncomplete;
res.TcpUdp = ppresIsTCP;
if (len >= tcpipDataAt)
{
TCPHeader *pTcpHeader = (TCPHeader *)RtlOffsetToPointer(pIpHeader, ipHeaderSize);
res.xxpStatus = ppresXxpKnown;
tcpipDataAt = ipHeaderSize + TCP_HEADER_LENGTH(pTcpHeader);
res.XxpIpHeaderSize = tcpipDataAt;
}
else
{
DPrintf(2, ("tcp: %d < min headers %d\n", len, tcpipDataAt));
}
return res;
}

Status SpectrogramShapeFn(InferenceContext* c) {
ShapeHandle input;
TF_RETURN_IF_ERROR(c->WithRank(c->input(0), 2, &input));
int32_t window_size;
TF_RETURN_IF_ERROR(c->GetAttr("window_size", &window_size));
int32_t stride;
TF_RETURN_IF_ERROR(c->GetAttr("stride", &stride));
DimensionHandle input_length = c->Dim(input, 0);
DimensionHandle input_channels = c->Dim(input, 1);
DimensionHandle output_length;
if (!c->ValueKnown(input_length)) {
output_length = c->UnknownDim();
} else {
const int64_t input_length_value = c->Value(input_length);
const int64_t length_minus_window = (input_length_value - window_size);
int64_t output_length_value;
if (length_minus_window < 0) {
output_length_value = 0;
} else {
output_length_value = 1 + (length_minus_window / stride);
}
output_length = c->MakeDim(output_length_value);
}
DimensionHandle output_channels =
c->MakeDim(1 + NextPowerOfTwo(window_size) / 2);
c->set_output(0,
c->MakeShape({input_channels, output_length, output_channels}));
return OkStatus();
}

const char *
le64addr_string(netdissect_options *ndo, const u_char *ep)
{
const unsigned int len = 8;
register u_int i;
register char *cp;
register struct enamemem *tp;
char buf[BUFSIZE];
tp = lookup_bytestring(ndo, ep, len);
if (tp->e_name)
return (tp->e_name);
cp = buf;
for (i = len; i > 0 ; --i) {
*cp++ = hex[*(ep + i - 1) >> 4];
*cp++ = hex[*(ep + i - 1) & 0xf];
*cp++ = ':';
}
cp --;
*cp = '\0';
tp->e_name = strdup(buf);
if (tp->e_name == NULL)
(*ndo->ndo_error)(ndo, "le64addr_string: strdup(buf)");
return (tp->e_name);
}

AXFRRetriever::AXFRRetriever(const ComboAddress& remote,
const DNSName& domain,
const TSIGTriplet& tt, 
const ComboAddress* laddr)
: d_tt(tt), d_tsigPos(0), d_nonSignedMessages(0)
{
ComboAddress local;
if (laddr != NULL) {
local = (ComboAddress) (*laddr);
} else {
if(remote.sin4.sin_family == AF_INET)
local=ComboAddress(::arg()["query-local-address"]);
else if(!::arg()["query-local-address6"].empty())
local=ComboAddress(::arg()["query-local-address6"]);
else
local=ComboAddress("::");
}
d_sock = -1;
try {
d_sock = makeQuerySocket(local, false);     if (d_sock < 0)
throw ResolverException("Error creating socket for AXFR request to "+d_remote.toStringWithPort());
d_buf = shared_array<char>(new char[65536]);
d_remote = remote;     this->connect();
d_soacount = 0;
vector<uint8_t> packet;
DNSPacketWriter pw(packet, domain, QType::AXFR);
pw.getHeader()->id = dns_random(0xffff);
if(!tt.name.empty()) {
if (tt.algo == DNSName("hmac-md5"))
d_trc.d_algoName = tt.algo + DNSName("sig-alg.reg.int");
else
d_trc.d_algoName = tt.algo;
d_trc.d_time = time(0);
d_trc.d_fudge = 300;
d_trc.d_origID=ntohs(pw.getHeader()->id);
d_trc.d_eRcode=0;
addTSIG(pw, &d_trc, tt.name, tt.secret, "", false);
}
uint16_t replen=htons(packet.size());
Utility::iovec iov[2];
iov[0].iov_base=reinterpret_cast<char*>(&replen);
iov[0].iov_len=2;
iov[1].iov_base=packet.data();
iov[1].iov_len=packet.size();
int ret=Utility::writev(d_sock, iov, 2);
if(ret < 0)
throw ResolverException("Error sending question to "+d_remote.toStringWithPort()+": "+stringerror());
if(ret != (int)(2+packet.size())) {
throw ResolverException("Partial write on AXFR request to "+d_remote.toStringWithPort());
}
int res = waitForData(d_sock, 10, 0);
if(!res)
throw ResolverException("Timeout waiting for answer from "+d_remote.toStringWithPort()+" during AXFR");
if(res<0)
throw ResolverException("Error waiting for answer from "+d_remote.toStringWithPort()+": "+stringerror());
}
catch(...) {
if(d_sock >= 0)
close(d_sock);
d_sock = -1;
throw;
}
}

static struct fixup_entry *
new_fixup(struct archive_write_disk *a, const char *pathname)
{
struct fixup_entry *fe;
fe = (struct fixup_entry *)calloc(1, sizeof(struct fixup_entry));
if (fe == NULL) {
archive_set_error(&a->archive, ENOMEM,
"Can't allocate memory for a fixup");
return (NULL);
}
fe->next = a->fixup_list;
a->fixup_list = fe;
fe->fixup = 0;
fe->name = strdup(pathname);
return (fe);
}

static void 
parse_rs274x(gint levelOfRecursion, gerb_file_t *fd, gerbv_image_t *image, 
gerb_state_t *state, gerbv_net_t *curr_net, gerbv_stats_t *stats, 
gchar *directoryPath, long int *line_num_p)
{
int op[2];
char str[3];
int tmp;
gerbv_aperture_t *a = NULL;
gerbv_amacro_t *tmp_amacro;
int ano;
gdouble scale = 1.0;
gerbv_error_list_t *error_list = stats->error_list;
if (state->state->unit == GERBV_UNIT_MM)
scale = 25.4;
op[0] = gerb_fgetc(fd);
op[1] = gerb_fgetc(fd);
if (op[0] == EOF || op[1] == EOF)
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unexpected EOF found in file \"%s\""), fd->filename);
switch (A2I(op[0], op[1])){
case A2I('A','S'): 
op[0] = gerb_fgetc(fd);
op[1] = gerb_fgetc(fd);
state->state = gerbv_image_return_new_netstate (state->state);
if (op[0] == EOF || op[1] == EOF)
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unexpected EOF found in file \"%s\""), fd->filename);
if (((op[0] == 'A') && (op[1] == 'Y')) ||
((op[0] == 'B') && (op[1] == 'X'))) {
state->state->axisSelect = GERBV_AXIS_SELECT_SWAPAB;
} else {
state->state->axisSelect = GERBV_AXIS_SELECT_NOSELECT;
}
op[0] = gerb_fgetc(fd);
op[1] = gerb_fgetc(fd);
if (op[0] == EOF || op[1] == EOF)
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unexpected EOF found in file \"%s\""), fd->filename);
if (((op[0] == 'A') && (op[1] == 'Y')) ||
((op[0] == 'B') && (op[1] == 'X'))) {
state->state->axisSelect = GERBV_AXIS_SELECT_SWAPAB;
} else {
state->state->axisSelect = GERBV_AXIS_SELECT_NOSELECT;
}
break;
case A2I('F','S'): 
image->format = g_new0 (gerbv_format_t,1);
switch (gerb_fgetc(fd)) {
case 'L':
image->format->omit_zeros = GERBV_OMIT_ZEROS_LEADING;
break;
case 'T':
image->format->omit_zeros = GERBV_OMIT_ZEROS_TRAILING;
break;
case 'D':
image->format->omit_zeros = GERBV_OMIT_ZEROS_EXPLICIT;
break;
default:
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("EagleCad bug detected: Undefined handling of zeros "
"in format code at line %ld in file \"%s\""),
*line_num_p, fd->filename);
gerbv_stats_printf(error_list, GERBV_MESSAGE_WARNING, -1,
_("Defaulting to omitting leading zeros"));
gerb_ungetc(fd);
image->format->omit_zeros = GERBV_OMIT_ZEROS_LEADING;
}
switch (gerb_fgetc(fd)) {
case 'A':
image->format->coordinate = GERBV_COORDINATE_ABSOLUTE;
break;
case 'I':
image->format->coordinate = GERBV_COORDINATE_INCREMENTAL;
break;
default:
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Invalid coordinate type defined in format code "
"at line %ld in file \"%s\""),
*line_num_p, fd->filename);
gerbv_stats_printf(error_list, GERBV_MESSAGE_WARNING, -1,
_("Defaulting to absolute coordinates"));
image->format->coordinate = GERBV_COORDINATE_ABSOLUTE;
}
op[0] = gerb_fgetc(fd);
while((op[0] != '*')&&(op[0] != EOF)) {
switch (op[0]) {
case 'N':
op[0] = (char)gerb_fgetc(fd);
image->format->lim_seqno = op[0] - '0';
break;
case 'G':
op[0] = (char)gerb_fgetc(fd);
image->format->lim_gf = op[0] - '0';
break;
case 'D':
op[0] = (char)gerb_fgetc(fd);
image->format->lim_pf = op[0] - '0';
break;
case 'M':
op[0] = (char)gerb_fgetc(fd);
image->format->lim_mf = op[0] - '0';
break;
case 'X' :
op[0] = gerb_fgetc(fd);
if ((op[0] < '0') || (op[0] > '6')) {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Illegal format size '%s' "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]),
*line_num_p, fd->filename);
}
image->format->x_int = op[0] - '0';
op[0] = gerb_fgetc(fd);
if ((op[0] < '0') || (op[0] > '6')) {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Illegal format size '%s' "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]),
*line_num_p, fd->filename);
}
image->format->x_dec = op[0] - '0';
break;
case 'Y':
op[0] = gerb_fgetc(fd);
if ((op[0] < '0') || (op[0] > '6')) {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Illegal format size '%s' "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]),
*line_num_p, fd->filename);
}
image->format->y_int = op[0] - '0';
op[0] = gerb_fgetc(fd);
if ((op[0] < '0') || (op[0] > '6')) {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Illegal format size '%s' "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]),
*line_num_p, fd->filename);
}
image->format->y_dec = op[0] - '0';
break;
default :
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Illegal format statement '%s' "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]),
*line_num_p, fd->filename);
gerbv_stats_printf(error_list, GERBV_MESSAGE_WARNING, -1,
_("Ignoring invalid format statement"));
}
op[0] = gerb_fgetc(fd);
}
break;
case A2I('M','I'): 
op[0] = gerb_fgetc(fd);
state->state = gerbv_image_return_new_netstate (state->state);
while ((op[0] != '*')&&(op[0] != EOF)) {
gint readValue=0;
switch (op[0]) {
case 'A' :
readValue = gerb_fgetint(fd, NULL);
if (readValue == 1) {
if (state->state->mirrorState == GERBV_MIRROR_STATE_FLIPB)
state->state->mirrorState=GERBV_MIRROR_STATE_FLIPAB;
else
state->state->mirrorState=GERBV_MIRROR_STATE_FLIPA;
}
break;
case 'B' :
readValue = gerb_fgetint(fd, NULL);
if (readValue == 1) {
if (state->state->mirrorState == GERBV_MIRROR_STATE_FLIPA)
state->state->mirrorState=GERBV_MIRROR_STATE_FLIPAB;
else
state->state->mirrorState=GERBV_MIRROR_STATE_FLIPB;
}
break;
default :
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Wrong character '%s' in mirror "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]), *line_num_p, fd->filename);
}
op[0] = gerb_fgetc(fd);
}
break;  
case A2I('M','O'): 
op[0] = gerb_fgetc(fd);
op[1] = gerb_fgetc(fd);
if (op[0] == EOF || op[1] == EOF)
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unexpected EOF found in file \"%s\""), fd->filename);
switch (A2I(op[0],op[1])) {
case A2I('I','N'):
state->state = gerbv_image_return_new_netstate (state->state);
state->state->unit = GERBV_UNIT_INCH;
break;
case A2I('M','M'):
state->state = gerbv_image_return_new_netstate (state->state);
state->state->unit = GERBV_UNIT_MM;
break;
default:
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Illegal unit '%s%s' at line %ld in file \"%s\""),
gerbv_escape_char(op[0]), gerbv_escape_char(op[1]),
*line_num_p, fd->filename);
}
break;
case A2I('O','F'): 
op[0] = gerb_fgetc(fd);
while ((op[0] != '*')&&(op[0] != EOF)) {
switch (op[0]) {
case 'A' :
state->state->offsetA = gerb_fgetdouble(fd) / scale;
break;
case 'B' :
state->state->offsetB = gerb_fgetdouble(fd) / scale;
break;
default :
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Wrong character '%s' in offset "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]), *line_num_p, fd->filename);
}
op[0] = gerb_fgetc(fd);
}
break;
case A2I('I','F'): 
{
gchar *includeFilename = gerb_fgetstring(fd, '*');
if (includeFilename) {
gchar *fullPath;
if (!g_path_is_absolute(includeFilename)) {
fullPath = g_build_filename (directoryPath, includeFilename, NULL);
} else {
fullPath = g_strdup (includeFilename);
}
if (levelOfRecursion < 10) {
gerb_file_t *includefd = NULL;
includefd = gerb_fopen(fullPath);
if (includefd) {
gerber_parse_file_segment (levelOfRecursion + 1, image, state, curr_net, stats, includefd, directoryPath);
gerb_fclose(includefd);
} else {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Included file \"%s\" cannot be found "
"at line %ld in file \"%s\""),
fullPath, *line_num_p, fd->filename);
}
g_free (fullPath);
} else {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Parser encountered more than 10 levels of "
"include file recursion which is not allowed "
"by the RS-274X spec"));
}
}
}
break;
case A2I('I','O'): 
op[0] = gerb_fgetc(fd);
while ((op[0] != '*')&&(op[0] != EOF)) {
switch (op[0]) {
case 'A' :
image->info->offsetA = gerb_fgetdouble(fd) / scale;
break;
case 'B' :
image->info->offsetB = gerb_fgetdouble(fd) / scale;
break;
default :
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Wrong character '%s' in image offset "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]), *line_num_p, fd->filename);
}
op[0] = gerb_fgetc(fd);
}
break;
case A2I('S','F'): 
state->state = gerbv_image_return_new_netstate (state->state);
if (gerb_fgetc(fd) == 'A')
state->state->scaleA = gerb_fgetdouble(fd);
else 
gerb_ungetc(fd);
if (gerb_fgetc(fd) == 'B')
state->state->scaleB = gerb_fgetdouble(fd);
else 
gerb_ungetc(fd);
break;
case A2I('I','C'): 
op[0] = gerb_fgetc(fd);
op[1] = gerb_fgetc(fd);
if (op[0] == EOF || op[1] == EOF)
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unexpected EOF found in file \"%s\""), fd->filename);
switch (A2I(op[0],op[1])) {
case A2I('A','S'):
image->info->encoding = GERBV_ENCODING_ASCII;
break;
case A2I('E','B'):
image->info->encoding = GERBV_ENCODING_EBCDIC;
break;
case A2I('B','C'):
image->info->encoding = GERBV_ENCODING_BCD;
break;
case A2I('I','S'):
image->info->encoding = GERBV_ENCODING_ISO_ASCII;
break;
case A2I('E','I'):
image->info->encoding = GERBV_ENCODING_EIA;
break;
default:
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unknown input code (IC) '%s%s' "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]), gerbv_escape_char(op[1]),
*line_num_p, fd->filename);
}
break;
case A2I('I','J'): 
op[0] = gerb_fgetc(fd);
image->info->imageJustifyTypeA = GERBV_JUSTIFY_LOWERLEFT;
image->info->imageJustifyTypeB = GERBV_JUSTIFY_LOWERLEFT;
image->info->imageJustifyOffsetA = 0.0;
image->info->imageJustifyOffsetB = 0.0;
while ((op[0] != '*')&&(op[0] != EOF)) {
switch (op[0]) {
case 'A' :
op[0] = gerb_fgetc(fd);
if (op[0] == 'C') {
image->info->imageJustifyTypeA = GERBV_JUSTIFY_CENTERJUSTIFY;
} else if (op[0] == 'L') {
image->info->imageJustifyTypeA = GERBV_JUSTIFY_LOWERLEFT;
} else {
gerb_ungetc (fd);
image->info->imageJustifyOffsetA = gerb_fgetdouble(fd) / scale;
}
break;
case 'B' :
op[0] = gerb_fgetc(fd);
if (op[0] == 'C') {
image->info->imageJustifyTypeB = GERBV_JUSTIFY_CENTERJUSTIFY;
} else if (op[0] == 'L') {
image->info->imageJustifyTypeB = GERBV_JUSTIFY_LOWERLEFT;
} else {
gerb_ungetc (fd);
image->info->imageJustifyOffsetB = gerb_fgetdouble(fd) / scale;
}
break;
default :
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Wrong character '%s' in image justify "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]), *line_num_p, fd->filename);
}
op[0] = gerb_fgetc(fd);
}
break;
case A2I('I','N'): 
image->info->name = gerb_fgetstring(fd, '*');
break;
case A2I('I','P'): 
for (ano = 0; ano < 3; ano++) {
op[0] = gerb_fgetc(fd);
if (op[0] == EOF) {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unexpected EOF while reading image polarity (IP) "
"in file \"%s\""), fd->filename);
}
str[ano] = (char)op[0];
}
if (strncmp(str, "POS", 3) == 0) 
image->info->polarity = GERBV_POLARITY_POSITIVE;
else if (strncmp(str, "NEG", 3) == 0)
image->info->polarity = GERBV_POLARITY_NEGATIVE;
else {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unknown polarity '%s%s%s' "
"at line %ld in file \"%s\""),
gerbv_escape_char(str[0]), gerbv_escape_char(str[1]),
gerbv_escape_char(str[2]), *line_num_p, fd->filename);
}
break;
case A2I('I','R'): 
tmp = gerb_fgetint(fd, NULL) % 360;
if (tmp == 0)
image->info->imageRotation = 0.0;
else if (tmp == 90)
image->info->imageRotation = M_PI_2;
else if (tmp == 180)
image->info->imageRotation = M_PI;
else if (tmp == 270)
image->info->imageRotation = M_PI + M_PI_2;
else {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Image rotation must be 0, 90, 180 or 270 "
"(is actually %d) at line %ld in file \"%s\""),
tmp, *line_num_p, fd->filename);
}
break;
case A2I('P','F'): 
image->info->plotterFilm = gerb_fgetstring(fd, '*');
break;
case A2I('A','D'): 
a = (gerbv_aperture_t *) g_new0 (gerbv_aperture_t,1);
ano = parse_aperture_definition(fd, a, image, scale, line_num_p);
if (ano == -1) {
}
else if ((ano >= 0) && (ano <= APERTURE_MAX)) {
a->unit = state->state->unit;
image->aperture[ano] = a;
dprintf("     In %s(), adding new aperture to aperture list ...\n",
__func__);
gerbv_stats_add_aperture(stats->aperture_list,
-1, ano, 
a->type,
a->parameter);
gerbv_stats_add_to_D_list(stats->D_code_list,
ano);
if (ano < APERTURE_MIN) {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Aperture number out of bounds %d "
"at line %ld in file \"%s\""),
ano, *line_num_p, fd->filename);
}
} else {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Aperture number out of bounds %d "
"at line %ld in file \"%s\""),
ano, *line_num_p, fd->filename);
}
break;
case A2I('A','M'): 
tmp_amacro = image->amacro;
image->amacro = parse_aperture_macro(fd);
if (image->amacro) {
image->amacro->next = tmp_amacro;
#ifdef AMACRO_DEBUG
print_program(image->amacro);
#endif
} else {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Failed to parse aperture macro "
"at line %ld in file \"%s\""),
*line_num_p, fd->filename);
}
return;
case A2I('L','N'): 
state->layer = gerbv_image_return_new_layer (state->layer);
state->layer->name = gerb_fgetstring(fd, '*');
break;
case A2I('L','P'): 
state->layer = gerbv_image_return_new_layer (state->layer);
switch (gerb_fgetc(fd)) {
case 'D': 
state->layer->polarity = GERBV_POLARITY_DARK;
break;
case 'C': 
state->layer->polarity = GERBV_POLARITY_CLEAR;
break;
default:
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unknown layer polarity '%s' "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]), *line_num_p, fd->filename);
}
break;
case A2I('K','O'): 
state->layer = gerbv_image_return_new_layer (state->layer);
gerber_update_any_running_knockout_measurements (image);
knockoutMeasure = FALSE;
op[0] = gerb_fgetc(fd);
if (op[0] == '*') { 
state->layer->knockout.type = GERBV_KNOCKOUT_TYPE_NOKNOCKOUT;
break;
} else if (op[0] == 'C') {
state->layer->knockout.polarity = GERBV_POLARITY_CLEAR;
} else if (op[0] == 'D') {
state->layer->knockout.polarity = GERBV_POLARITY_DARK;
} else {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Knockout must supply a polarity (C, D, or *) "
"at line %ld in file \"%s\""),
*line_num_p, fd->filename);
}
state->layer->knockout.lowerLeftX = 0.0;
state->layer->knockout.lowerLeftY = 0.0;
state->layer->knockout.width = 0.0;
state->layer->knockout.height = 0.0;
state->layer->knockout.border = 0.0;
state->layer->knockout.firstInstance = TRUE;
op[0] = gerb_fgetc(fd);
while ((op[0] != '*')&&(op[0] != EOF)) { 
switch (op[0]) {
case 'X':
state->layer->knockout.type = GERBV_KNOCKOUT_TYPE_FIXEDKNOCK;
state->layer->knockout.lowerLeftX = gerb_fgetdouble(fd) / scale;
break;
case 'Y':
state->layer->knockout.type = GERBV_KNOCKOUT_TYPE_FIXEDKNOCK;
state->layer->knockout.lowerLeftY = gerb_fgetdouble(fd) / scale;
break;
case 'I':
state->layer->knockout.type = GERBV_KNOCKOUT_TYPE_FIXEDKNOCK;
state->layer->knockout.width = gerb_fgetdouble(fd) / scale;
break;
case 'J':
state->layer->knockout.type = GERBV_KNOCKOUT_TYPE_FIXEDKNOCK;
state->layer->knockout.height = gerb_fgetdouble(fd) / scale;
break;
case 'K':
state->layer->knockout.type = GERBV_KNOCKOUT_TYPE_BORDER;
state->layer->knockout.border = gerb_fgetdouble(fd) / scale;
knockoutMeasure = TRUE;
knockoutLimitXmin = HUGE_VAL;
knockoutLimitYmin = HUGE_VAL;
knockoutLimitXmax = -HUGE_VAL;
knockoutLimitYmax = -HUGE_VAL;
knockoutLayer = state->layer;
break;
default:
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unknown variable in knockout "
"at line %ld in file \"%s\""),
*line_num_p, fd->filename);
}
op[0] = gerb_fgetc(fd);
}
break;
case A2I('S','R'): 
state->layer = gerbv_image_return_new_layer (state->layer);
op[0] = gerb_fgetc(fd);
if (op[0] == '*') { 
state->layer->stepAndRepeat.X = 1;
state->layer->stepAndRepeat.Y = 1;
state->layer->stepAndRepeat.dist_X = 0.0;
state->layer->stepAndRepeat.dist_Y = 0.0;
break;
}
while ((op[0] != '*')&&(op[0] != EOF)) {
switch (op[0]) {
case 'X':
state->layer->stepAndRepeat.X = gerb_fgetint(fd, NULL);
break;
case 'Y':
state->layer->stepAndRepeat.Y = gerb_fgetint(fd, NULL);
break;
case 'I':
state->layer->stepAndRepeat.dist_X = gerb_fgetdouble(fd) / scale;
break;
case 'J':
state->layer->stepAndRepeat.dist_Y = gerb_fgetdouble(fd) / scale;
break;
default:
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Step-and-repeat parameter error "
"at line %ld in file \"%s\""),
*line_num_p, fd->filename);
}
if(state->layer->stepAndRepeat.X == 0)
state->layer->stepAndRepeat.X = 1;
if(state->layer->stepAndRepeat.Y == 0)
state->layer->stepAndRepeat.Y = 1;
op[0] = gerb_fgetc(fd);
}
break;
case A2I('R','O'):
state->layer = gerbv_image_return_new_layer (state->layer);
state->layer->rotation = DEG2RAD(gerb_fgetdouble(fd));
op[0] = gerb_fgetc(fd);
if (op[0] != '*') {
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Error in layer rotation command "
"at line %ld in file \"%s\""),
*line_num_p, fd->filename);
}
break;
default:
gerbv_stats_printf(error_list, GERBV_MESSAGE_ERROR, -1,
_("Unknown RS-274X extension found %%%s%s%% "
"at line %ld in file \"%s\""),
gerbv_escape_char(op[0]), gerbv_escape_char(op[1]),
*line_num_p, fd->filename);
}
gerb_ungetc(fd);
do {
tmp = gerb_fgetc(fd);
} while (tmp != EOF && tmp != '*');
return;
}

GLOBAL(djpeg_dest_ptr)
jinit_write_bmp(j_decompress_ptr cinfo, boolean is_os2,
boolean use_inversion_array)
{
bmp_dest_ptr dest;
JDIMENSION row_width;
dest = (bmp_dest_ptr)
(*cinfo->mem->alloc_small) ((j_common_ptr)cinfo, JPOOL_IMAGE,
sizeof(bmp_dest_struct));
dest->pub.start_output = start_output_bmp;
dest->pub.finish_output = finish_output_bmp;
dest->pub.calc_buffer_dimensions = NULL;
dest->is_os2 = is_os2;
if (cinfo->out_color_space == JCS_GRAYSCALE) {
dest->pub.put_pixel_rows = put_gray_rows;
} else if (IsExtRGB(cinfo->out_color_space)) {
if (cinfo->quantize_colors)
dest->pub.put_pixel_rows = put_gray_rows;
else
dest->pub.put_pixel_rows = put_pixel_rows;
} else if (cinfo->out_color_space == JCS_RGB565 ||
cinfo->out_color_space == JCS_CMYK) {
dest->pub.put_pixel_rows = put_pixel_rows;
} else {
ERREXIT(cinfo, JERR_BMP_COLORSPACE);
}
jpeg_calc_output_dimensions(cinfo);
if (cinfo->out_color_space == JCS_RGB565) {
row_width = cinfo->output_width * 2;
dest->row_width = dest->data_width = cinfo->output_width * 3;
while ((row_width & 3) != 0) row_width++;
} else if (!cinfo->quantize_colors &&
(IsExtRGB(cinfo->out_color_space) ||
cinfo->out_color_space == JCS_CMYK)) {
row_width = cinfo->output_width * cinfo->output_components;
dest->row_width = dest->data_width = cinfo->output_width * 3;
} else {
row_width = cinfo->output_width * cinfo->output_components;
dest->row_width = dest->data_width = row_width;
}
while ((dest->row_width & 3) != 0) dest->row_width++;
dest->pad_bytes = (int)(dest->row_width - dest->data_width);
if (use_inversion_array) {
dest->whole_image = (*cinfo->mem->request_virt_sarray)
((j_common_ptr)cinfo, JPOOL_IMAGE, FALSE,
dest->row_width, cinfo->output_height, (JDIMENSION)1);
dest->cur_output_row = 0;
if (cinfo->progress != NULL) {
cd_progress_ptr progress = (cd_progress_ptr)cinfo->progress;
progress->total_extra_passes++; 
}
} else {
dest->iobuffer = (JSAMPLE *)(*cinfo->mem->alloc_small)
((j_common_ptr)cinfo, JPOOL_IMAGE, dest->row_width);
}
dest->use_inversion_array = use_inversion_array;
dest->pub.buffer = (*cinfo->mem->alloc_sarray)
((j_common_ptr)cinfo, JPOOL_IMAGE, row_width, (JDIMENSION)1);
dest->pub.buffer_height = 1;
return (djpeg_dest_ptr)dest;
}

static bool getCoverageFormat12(vector<uint32_t>& coverage, const uint8_t* data, size_t size) {
const size_t kNGroupsOffset = 12;
const size_t kFirstGroupOffset = 16;
const size_t kGroupSize = 12;
const size_t kStartCharCodeOffset = 0;
const size_t kEndCharCodeOffset = 4;
const size_t kMaxNGroups = 0xfffffff0 / kGroupSize;          if (kFirstGroupOffset > size) {
return false;
}
uint32_t nGroups = readU32(data, kNGroupsOffset);
if (nGroups >= kMaxNGroups || kFirstGroupOffset + nGroups * kGroupSize > size) {
return false;
}
for (uint32_t i = 0; i < nGroups; i++) {
uint32_t groupOffset = kFirstGroupOffset + i * kGroupSize;
uint32_t start = readU32(data, groupOffset + kStartCharCodeOffset);
uint32_t end = readU32(data, groupOffset + kEndCharCodeOffset);
if (end < start) {
return false;
}
addRange(coverage, start, end + 1);      }
return true;
}

void operator()(const CPUDevice& d, typename TTypes<T, 4>::ConstTensor input,
typename TTypes<T, 3>::ConstTensor filter,
typename TTypes<T, 4>::ConstTensor out_backprop,
int stride_rows, int stride_cols, int rate_rows,
int rate_cols, int pad_top, int pad_left,
typename TTypes<T, 3>::Tensor filter_backprop) {
const int batch = input.dimension(0);
const int input_rows = input.dimension(1);
const int input_cols = input.dimension(2);
const int depth = input.dimension(3);
const int filter_rows = filter.dimension(0);
const int filter_cols = filter.dimension(1);
const int output_rows = out_backprop.dimension(1);
const int output_cols = out_backprop.dimension(2);
filter_backprop.setZero();
for (int b = 0; b < batch; ++b) {
for (int h_out = 0; h_out < output_rows; ++h_out) {
int h_beg = h_out * stride_rows - pad_top;
for (int w_out = 0; w_out < output_cols; ++w_out) {
int w_beg = w_out * stride_cols - pad_left;
for (int d = 0; d < depth; ++d) {
T cur_val = Eigen::NumTraits<T>::lowest();
int h_max = 0;
int w_max = 0;
for (int h = 0; h < filter_rows; ++h) {
const int h_in = h_beg + h * rate_rows;
if (h_in >= 0 && h_in < input_rows) {
for (int w = 0; w < filter_cols; ++w) {
const int w_in = w_beg + w * rate_cols;
if (w_in >= 0 && w_in < input_cols) {
const T val = input(b, h_in, w_in, d) + filter(h, w, d);
if (val > cur_val) {
cur_val = val;
h_max = h;
w_max = w;
}
}
}
}
}
filter_backprop(h_max, w_max, d) +=
out_backprop(b, h_out, w_out, d);
}
}
}
}
}

static void
nlm_register_unmatched_msg(packet_info *pinfo, tvbuff_t *tvb, int offset)
{
nlm_msg_res_unmatched_data *umd;
nlm_msg_res_unmatched_data *old_umd;
umd=(nlm_msg_res_unmatched_data *)g_malloc(sizeof(nlm_msg_res_unmatched_data));
umd->req_frame=pinfo->fd->num;
umd->ns=pinfo->fd->abs_ts;
umd->cookie_len=tvb_get_ntohl(tvb, offset);
umd->cookie=(const guint8 *)tvb_memdup(NULL, tvb, offset+4, umd->cookie_len);
old_umd=(nlm_msg_res_unmatched_data *)g_hash_table_lookup(nlm_msg_res_unmatched, (gconstpointer)umd);
if(old_umd){
g_hash_table_remove(nlm_msg_res_unmatched, (gconstpointer)old_umd);
g_free((gpointer)old_umd->cookie);
g_free(old_umd);
}
g_hash_table_insert(nlm_msg_res_unmatched, (gpointer)umd, (gpointer)umd);
}

static st64 buf_format(RBuffer *dst, RBuffer *src, const char *fmt, int n) {
st64 res = 0;
int i;
for (i = 0; i < n; i++) {
int j;
int m = 1;
int tsize = 2;
bool bigendian = true;
for (j = 0; fmt[j]; j++) {
switch (fmt[j]) {
case '0':
case '1':
case '2':
case '3':
case '4':
case '5':
case '6':
case '7':
case '8':
case '9':
if (m == 1) {
m = r_num_get (NULL, &fmt[j]);
}
continue;
case 's': tsize = 2; bigendian = false; break;
case 'S': tsize = 2; bigendian = true; break;
case 'i': tsize = 4; bigendian = false; break;
case 'I': tsize = 4; bigendian = true; break;
case 'l': tsize = 8; bigendian = false; break;
case 'L': tsize = 8; bigendian = true; break;
case 'c': tsize = 1; bigendian = false; break;
default: return -1;
}
int k;
for (k = 0; k < m; k++) {
ut8 tmp[sizeof (ut64)];
ut8 d1;
ut16 d2;
ut32 d3;
ut64 d4;
st64 r = r_buf_read (src, tmp, tsize);
if (r < tsize) {
return -1;
}
switch (tsize) {
case 1:
d1 = r_read_ble8 (tmp);
r = r_buf_write (dst, (ut8 *)&d1, 1);
break;
case 2:
d2 = r_read_ble16 (tmp, bigendian);
r = r_buf_write (dst, (ut8 *)&d2, 2);
break;
case 4:
d3 = r_read_ble32 (tmp, bigendian);
r = r_buf_write (dst, (ut8 *)&d3, 4);
break;
case 8:
d4 = r_read_ble64 (tmp, bigendian);
r = r_buf_write (dst, (ut8 *)&d4, 8);
break;
}
if (r < 0) {
return -1;
}
res += r;
}
m = 1;
}
}
return res;
}

METHODDEF(JDIMENSION)
get_word_gray_row(j_compress_ptr cinfo, cjpeg_source_ptr sinfo)
{
ppm_source_ptr source = (ppm_source_ptr)sinfo;
register JSAMPROW ptr;
register U_CHAR *bufferptr;
register JSAMPLE *rescale = source->rescale;
JDIMENSION col;
unsigned int maxval = source->maxval;
if (!ReadOK(source->pub.input_file, source->iobuffer, source->buffer_width))
ERREXIT(cinfo, JERR_INPUT_EOF);
ptr = source->pub.buffer[0];
bufferptr = source->iobuffer;
for (col = cinfo->image_width; col > 0; col--) {
register unsigned int temp;
temp  = UCH(*bufferptr++) << 8;
temp |= UCH(*bufferptr++);
if (temp > maxval)
ERREXIT(cinfo, JERR_PPM_TOOLARGE);
*ptr++ = rescale[temp];
}
return 1;
}

