dont_close[j++] = -1;
fdwalk (proc_fd, close_extra_fds, dont_close);
}
return do_init (event_fd, pid);
}
}
__debug__ (("launch executable %s\n", argv[0]));
if (proc_fd != -1)
close (proc_fd);
if (opt_sync_fd != -1)
close (opt_sync_fd);
unblock_sigchild ();
if (label_exec (opt_exec_label) == -1)
die_with_error ("label_exec %s", argv[0]);
if (execvp (argv[0], argv) == -1)
die_with_error ("execvp %s", argv[0]);
return 0;
}

int rtl_usb_probe(struct usb_interface *intf,
const struct usb_device_id *id,
struct rtl_hal_cfg *rtl_hal_cfg)
{
int err;
struct ieee80211_hw *hw = NULL;
struct rtl_priv *rtlpriv = NULL;
struct usb_device*udev;
struct rtl_usb_priv *usb_priv;
hw = ieee80211_alloc_hw(sizeof(struct rtl_priv) +
sizeof(struct rtl_usb_priv), &rtl_ops);
if (!hw) {
WARN_ONCE(true, "rtl_usb: ieee80211 alloc failed\n");
return -ENOMEM;
}
rtlpriv = hw->priv;
rtlpriv->hw = hw;
rtlpriv->usb_data = kcalloc(RTL_USB_MAX_RX_COUNT, sizeof(u32),
GFP_KERNEL);
if (!rtlpriv->usb_data)
return -ENOMEM;
spin_lock_init(&rtlpriv->locks.usb_lock);
INIT_WORK(&rtlpriv->works.fill_h2c_cmd,
rtl_fill_h2c_cmd_work_callback);
INIT_WORK(&rtlpriv->works.lps_change_work,
rtl_lps_change_work_callback);
rtlpriv->usb_data_index = 0;
init_completion(&rtlpriv->firmware_loading_complete);
SET_IEEE80211_DEV(hw, &intf->dev);
udev = interface_to_usbdev(intf);
usb_get_dev(udev);
usb_priv = rtl_usbpriv(hw);
memset(usb_priv, 0, sizeof(*usb_priv));
usb_priv->dev.intf = intf;
usb_priv->dev.udev = udev;
usb_set_intfdata(intf, hw);
rtlpriv->rtlhal.interface = INTF_USB;
rtlpriv->cfg = rtl_hal_cfg;
rtlpriv->intf_ops = &rtl_usb_ops;
_rtl_usb_io_handler_init(&udev->dev, hw);
rtlpriv->cfg->ops->read_chip_version(hw);
rtlpriv->cfg->ops->read_eeprom_info(hw);
err = _rtl_usb_init(hw);
if (err)
goto error_out2;
rtl_usb_init_sw(hw);
err = rtl_init_core(hw);
if (err) {
pr_err("Can't allocate sw for mac80211\n");
goto error_out2;
}
if (rtlpriv->cfg->ops->init_sw_vars(hw)) {
pr_err("Can't init_sw_vars\n");
goto error_out;
}
rtlpriv->cfg->ops->init_sw_leds(hw);
err = ieee80211_register_hw(hw);
if (err) {
pr_err("Can't register mac80211 hw.\n");
err = -ENODEV;
goto error_out;
}
rtlpriv->mac80211.mac80211_registered = 1;
set_bit(RTL_STATUS_INTERFACE_START, &rtlpriv->status);
return 0;
error_out:
rtl_deinit_core(hw);
error_out2:
_rtl_usb_io_handler_release(hw);
usb_put_dev(udev);
complete(&rtlpriv->firmware_loading_complete);
return -ENODEV;
}

static void
dump_relocs_in_section (bfd *abfd,
asection *section,
void *dummy ATTRIBUTE_UNUSED)
{
arelent **relpp;
long relcount;
long relsize;
if (   bfd_is_abs_section (section)
|| bfd_is_und_section (section)
|| bfd_is_com_section (section)
|| (! process_section_p (section))
|| ((section->flags & SEC_RELOC) == 0))
return;
relsize = bfd_get_reloc_upper_bound (abfd, section);
if (relsize < 0)
bfd_fatal (bfd_get_filename (abfd));
printf ("RELOCATION RECORDS FOR [%s]:", section->name);
if (relsize == 0)
{
printf (" (none)\n\n");
return;
}
if ((bfd_get_file_flags (abfd) & (BFD_IN_MEMORY | BFD_LINKER_CREATED)) == 0
&& (ufile_ptr) relsize > bfd_get_file_size (abfd))
{
printf (" (too many: 0x%x)\n", section->reloc_count);
bfd_set_error (bfd_error_file_truncated);
bfd_fatal (bfd_get_filename (abfd));
}
relpp = (arelent **) xmalloc (relsize);
relcount = bfd_canonicalize_reloc (abfd, section, relpp, syms);
if (relcount < 0)
{
printf ("\n");
non_fatal (_("failed to read relocs in: %s"), bfd_get_filename (abfd));
bfd_fatal (_("error message was"));
}
else if (relcount == 0)
printf (" (none)\n\n");
else
{
printf ("\n");
dump_reloc_set (abfd, section, relpp, relcount);
printf ("\n\n");
}
free (relpp);
}

static int fsmMkdirs(rpmfiles files, rpmfs fs, rpmPlugins plugins)
{
DNLI_t dnli = dnlInitIterator(files, fs, 0);
struct stat sb;
const char *dpath;
int rc = 0;
int i;
size_t ldnlen = 0;
const char * ldn = NULL;
while ((dpath = dnlNextIterator(dnli)) != NULL) {
size_t dnlen = strlen(dpath);
char * te, dn[dnlen+1];
if (dnlen <= 1)
continue;
if (dnlen == ldnlen && rstreq(dpath, ldn))
continue;
(void) stpcpy(dn, dpath);
for (i = 1, te = dn + 1; *te != '\0'; te++, i++) {
if (*te != '/')
continue;
if (i < ldnlen &&
(ldn[i] == '/' || ldn[i] == '\0') && rstreqn(dn, ldn, i))
continue;
*te = '\0';
rc = fsmStat(dn, 1, &sb); 
*te = '/';
if (rc == 0 && S_ISDIR(sb.st_mode)) {
continue;
} else if (rc == RPMERR_ENOENT) {
*te = '\0';
mode_t mode = S_IFDIR | (_dirPerms & 07777);
rpmFsmOp op = (FA_CREATE|FAF_UNOWNED);
rc = rpmpluginsCallFsmFilePre(plugins, NULL, dn, mode, op);
if (!rc)
rc = fsmMkdir(dn, mode);
if (!rc) {
rc = rpmpluginsCallFsmFilePrepare(plugins, NULL, dn, dn,
mode, op);
}
rpmpluginsCallFsmFilePost(plugins, NULL, dn, mode, op, rc);
if (!rc) {
rpmlog(RPMLOG_DEBUG,
"%s directory created with perms %04o\n",
dn, (unsigned)(mode & 07777));
}
*te = '/';
}
if (rc)
break;
}
if (rc) break;
ldn = dpath;
ldnlen = dnlen;
}
dnlFreeIterator(dnli);
return rc;
}

static long do_poll(struct sched_poll *sched_poll)
{
struct vcpu   *v = current;
struct domain *d = v->domain;
evtchn_port_t  port = 0;
long           rc;
unsigned int   i;
if ( sched_poll->nr_ports > 128 )
return -EINVAL;
if ( !guest_handle_okay(sched_poll->ports, sched_poll->nr_ports) )
return -EFAULT;
set_bit(_VPF_blocked, &v->pause_flags);
v->poll_evtchn = -1;
set_bit(v->vcpu_id, d->poll_mask);
arch_vcpu_block(v);
#ifndef CONFIG_X86 
smp_mb();
rc = 0;
if ( (v->poll_evtchn == 0) ||
!test_bit(_VPF_blocked, &v->pause_flags) ||
!test_bit(v->vcpu_id, d->poll_mask) )
goto out;
#endif
rc = 0;
if ( local_events_need_delivery() )
goto out;
for ( i = 0; i < sched_poll->nr_ports; i++ )
{
rc = -EFAULT;
if ( __copy_from_guest_offset(&port, sched_poll->ports, i, 1) )
goto out;
rc = -EINVAL;
if ( port >= d->max_evtchns )
goto out;
rc = 0;
if ( evtchn_port_is_pending(d, port) )
goto out;
}
if ( sched_poll->nr_ports == 1 )
v->poll_evtchn = port;
if ( sched_poll->timeout != 0 )
set_timer(&v->poll_timer, sched_poll->timeout);
TRACE_2D(TRC_SCHED_BLOCK, d->domain_id, v->vcpu_id);
raise_softirq(SCHEDULE_SOFTIRQ);
return 0;
out:
v->poll_evtchn = 0;
clear_bit(v->vcpu_id, d->poll_mask);
clear_bit(_VPF_blocked, &v->pause_flags);
return rc;
}

phys_addr_t swiotlb_tbl_map_single(struct device *dev, phys_addr_t orig_addr,
size_t mapping_size, size_t alloc_size,
unsigned int alloc_align_mask, enum dma_data_direction dir,
unsigned long attrs)
{
struct io_tlb_mem *mem = dev->dma_io_tlb_mem;
unsigned int offset = swiotlb_align_offset(dev, orig_addr);
unsigned int i;
int index;
phys_addr_t tlb_addr;
if (!mem)
panic("Can not allocate SWIOTLB buffer earlier and can't now provide you with the DMA bounce buffer");
if (cc_platform_has(CC_ATTR_MEM_ENCRYPT))
pr_warn_once("Memory encryption is active and system is using DMA bounce buffers\n");
if (mapping_size > alloc_size) {
dev_warn_once(dev, "Invalid sizes (mapping: %zd bytes, alloc: %zd bytes)",
mapping_size, alloc_size);
return (phys_addr_t)DMA_MAPPING_ERROR;
}
index = swiotlb_find_slots(dev, orig_addr,
alloc_size + offset, alloc_align_mask);
if (index == -1) {
if (!(attrs & DMA_ATTR_NO_WARN))
dev_warn_ratelimited(dev,
"swiotlb buffer is full (sz: %zd bytes), total %lu (slots), used %lu (slots)\n",
alloc_size, mem->nslabs, mem->used);
return (phys_addr_t)DMA_MAPPING_ERROR;
}
for (i = 0; i < nr_slots(alloc_size + offset); i++)
mem->slots[index + i].orig_addr = slot_addr(orig_addr, i);
tlb_addr = slot_addr(mem->start, index) + offset;
if (!(attrs & DMA_ATTR_SKIP_CPU_SYNC) &&
(!(attrs & DMA_ATTR_OVERWRITE) || dir == DMA_TO_DEVICE ||
dir == DMA_BIDIRECTIONAL))
swiotlb_bounce(dev, tlb_addr, mapping_size, DMA_TO_DEVICE);
return tlb_addr;
}

mbfl_string *
mbfl_strcut(
mbfl_string *string,
mbfl_string *result,
int from,
int length)
{
const mbfl_encoding *encoding;
mbfl_memory_device device;
if (string == NULL || string->val == NULL || result == NULL) {
return NULL;
}
if (from < 0 || length < 0) {
return NULL;
}
if (from >= string->len) {
from = string->len;
}
encoding = mbfl_no2encoding(string->no_encoding);
if (encoding == NULL) {
return NULL;
}
mbfl_string_init(result);
result->no_language = string->no_language;
result->no_encoding = string->no_encoding;
if ((encoding->flag & (MBFL_ENCTYPE_SBCS
| MBFL_ENCTYPE_WCS2BE
| MBFL_ENCTYPE_WCS2LE
| MBFL_ENCTYPE_WCS4BE
| MBFL_ENCTYPE_WCS4LE))
|| encoding->mblen_table != NULL) {
const unsigned char *start = NULL;
const unsigned char *end = NULL;
unsigned char *w;
unsigned int sz;
if (encoding->flag & (MBFL_ENCTYPE_WCS2BE | MBFL_ENCTYPE_WCS2LE)) {
from &= -2;
if (from + length >= string->len) {
length = string->len - from;
}
start = string->val + from;
end   = start + (length & -2);
} else if (encoding->flag & (MBFL_ENCTYPE_WCS4BE | MBFL_ENCTYPE_WCS4LE)) {
from &= -4;
if (from + length >= string->len) {
length = string->len - from;
}
start = string->val + from;
end   = start + (length & -4);
} else if ((encoding->flag & MBFL_ENCTYPE_SBCS)) {
if (from + length >= string->len) {
length = string->len - from;
}
start = string->val + from;
end = start + length;
} else if (encoding->mblen_table != NULL) {
const unsigned char *mbtab = encoding->mblen_table;
const unsigned char *p, *q;
int m;
for (m = 0, p = string->val, q = p + from;
p < q; p += (m = mbtab[*p]));
if (p > q) {
p -= m;
}
start = p;
if ((start - string->val) + length >= (int)string->len) {
end = string->val + string->len;
} else {
for (q = p + length; p < q; p += (m = mbtab[*p]));
if (p > q) {
p -= m;
}
end = p;
}
} else {
return NULL;
}
sz = end - start;
if ((w = (unsigned char*)mbfl_calloc(sz + 8,
sizeof(unsigned char))) == NULL) {
return NULL;
}
memcpy(w, start, sz);
w[sz] = '\0';
w[sz + 1] = '\0';
w[sz + 2] = '\0';
w[sz + 3] = '\0';
result->val = w;
result->len = sz;
} else {
mbfl_convert_filter *encoder     = NULL;
mbfl_convert_filter *decoder     = NULL;
const unsigned char *p, *q, *r;
struct {
mbfl_convert_filter encoder;
mbfl_convert_filter decoder;
const unsigned char *p;
int pos;
} bk, _bk;
if (!(decoder = mbfl_convert_filter_new(
mbfl_no_encoding_wchar,
string->no_encoding,
mbfl_memory_device_output, 0, &device))) {
return NULL;
}
if (!(encoder = mbfl_convert_filter_new(
string->no_encoding,
mbfl_no_encoding_wchar,
mbfl_filter_output_null,
NULL, NULL))) {
mbfl_convert_filter_delete(decoder);
return NULL;
}
mbfl_memory_device_init(&device, length + 8, 0);
p = string->val;
for (q = string->val + from; p < q; p++) {
(*encoder->filter_function)(*p, encoder);
}
encoder->output_function = (int(*)(int,void *))decoder->filter_function;
encoder->flush_function = (int(*)(void *))decoder->filter_flush;
encoder->data = decoder;
q = string->val + string->len;
mbfl_convert_filter_copy(decoder, &_bk.decoder);
mbfl_convert_filter_copy(encoder, &_bk.encoder);
_bk.p = p;
_bk.pos = device.pos;
if (length > q - p) {
length = q - p;
}
if (length >= 20) {
for (r = p + length - 20; p < r; p++) {
(*encoder->filter_function)(*p, encoder);
}
if (device.pos > length) {
p = _bk.p;
device.pos = _bk.pos;
decoder->filter_dtor(decoder);
encoder->filter_dtor(encoder);
mbfl_convert_filter_copy(&_bk.decoder, decoder);
mbfl_convert_filter_copy(&_bk.encoder, encoder);
bk = _bk;
} else {
mbfl_convert_filter_copy(decoder, &bk.decoder);
mbfl_convert_filter_copy(encoder, &bk.encoder);
bk.p = p;
bk.pos = device.pos;
(*encoder->filter_flush)(encoder);
if (device.pos > length) {
bk.decoder.filter_dtor(&bk.decoder);
bk.encoder.filter_dtor(&bk.encoder);
p = _bk.p;
device.pos = _bk.pos;
decoder->filter_dtor(decoder);
encoder->filter_dtor(encoder);
mbfl_convert_filter_copy(&_bk.decoder, decoder);
mbfl_convert_filter_copy(&_bk.encoder, encoder);
bk = _bk;
} else {
_bk.decoder.filter_dtor(&_bk.decoder);
_bk.encoder.filter_dtor(&_bk.encoder);
p = bk.p;
device.pos = bk.pos;
decoder->filter_dtor(decoder);
encoder->filter_dtor(encoder);
mbfl_convert_filter_copy(&bk.decoder, decoder);
mbfl_convert_filter_copy(&bk.encoder, encoder);
}
}
} else {
bk = _bk;
}
while (p < q) {
(*encoder->filter_function)(*p, encoder);
if (device.pos > length) {
p = bk.p;
device.pos = bk.pos;
decoder->filter_dtor(decoder);
encoder->filter_dtor(encoder);
mbfl_convert_filter_copy(&bk.decoder, decoder);
mbfl_convert_filter_copy(&bk.encoder, encoder);
break;
}
p++;
mbfl_convert_filter_copy(decoder, &_bk.decoder);
mbfl_convert_filter_copy(encoder, &_bk.encoder);
_bk.pos = device.pos;
_bk.p = p;
(*encoder->filter_flush)(encoder);
if (device.pos > length) {
_bk.decoder.filter_dtor(&_bk.decoder);
_bk.encoder.filter_dtor(&_bk.encoder);
p = bk.p;
device.pos = bk.pos;
decoder->filter_dtor(decoder);
encoder->filter_dtor(encoder);
mbfl_convert_filter_copy(&bk.decoder, decoder);
mbfl_convert_filter_copy(&bk.encoder, encoder);
break;
}
bk.decoder.filter_dtor(&bk.decoder);
bk.encoder.filter_dtor(&bk.encoder);
p = _bk.p;
device.pos = _bk.pos;
decoder->filter_dtor(decoder);
encoder->filter_dtor(encoder);
mbfl_convert_filter_copy(&_bk.decoder, decoder);
mbfl_convert_filter_copy(&_bk.encoder, encoder);
bk = _bk;
}
(*encoder->filter_flush)(encoder);
bk.decoder.filter_dtor(&bk.decoder);
bk.encoder.filter_dtor(&bk.encoder);
result = mbfl_memory_device_result(&device, result);
mbfl_convert_filter_delete(encoder);
mbfl_convert_filter_delete(decoder);
}
return result;
}

