module->allocateSongMessage(len+1);
memset(module->message, 0, len+1);
f.read(module->message, 1, len);
}
}
module->postProcessSamples();
return MP_OK;
}

GF_Err BD_DecMFFieldVec(GF_BifsDecoder * codec, GF_BitStream *bs, GF_Node *node, GF_FieldInfo *field, Bool is_mem_com)
{
GF_Err e;
u32 NbBits, nbFields;
u32 i;
GF_ChildNodeItem *last;
u8 qp_local, qp_on, initial_qp;
GF_FieldInfo sffield;
memset(&sffield, 0, sizeof(GF_FieldInfo));
sffield.fieldIndex = field->fieldIndex;
sffield.fieldType = gf_sg_vrml_get_sf_type(field->fieldType);
sffield.NDTtype = field->NDTtype;
sffield.name = field->name;
initial_qp = qp_local = qp_on = 0;
NbBits = gf_bs_read_int(bs, 5);
nbFields = gf_bs_read_int(bs, NbBits);
if (codec->ActiveQP) {
initial_qp = 1;
gf_bifs_dec_qp14_set_length(codec, nbFields);
}
if (field->fieldType != GF_SG_VRML_MFNODE) {
e = gf_sg_vrml_mf_alloc(field->far_ptr, field->fieldType, nbFields);
if (e) return e;
for (i=0; i<nbFields; i++) {
e = gf_sg_vrml_mf_get_item(field->far_ptr, field->fieldType, & sffield.far_ptr, i);
if (e) return e;
e = gf_bifs_dec_sf_field(codec, bs, node, &sffield, GF_FALSE);
if (e) return e;
}
} else {
last = NULL;
for (i=0; i<nbFields; i++) {
GF_Node *new_node = gf_bifs_dec_node(codec, bs, field->NDTtype);
if (new_node) {
e = gf_node_register(new_node, is_mem_com ? NULL : node);
if (e) return e;
if (node) {
if (gf_node_get_tag(new_node) == TAG_MPEG4_QuantizationParameter) {
qp_local = ((M_QuantizationParameter *)new_node)->isLocal;
if (qp_on) gf_bifs_dec_qp_remove(codec, GF_FALSE);
e = gf_bifs_dec_qp_set(codec, new_node);
if (e) return e;
qp_on = 1;
if (qp_local) qp_local = 2;
if (codec->force_keep_qp) {
e = gf_node_list_add_child_last(field->far_ptr, new_node, &last);
if (e) return e;
} else {
gf_node_register(new_node, NULL);
gf_node_unregister(new_node, node);
}
} else {
e = gf_node_list_add_child_last(field->far_ptr, new_node, &last);
if (e) return e;
}
}
else if (codec->pCurrentProto) {
e = gf_node_list_add_child_last( (GF_ChildNodeItem **)field->far_ptr, new_node, &last);
if (e) return e;
}
} else {
return codec->LastError ? codec->LastError : GF_NON_COMPLIANT_BITSTREAM;
}
}
if (qp_on && qp_local) {
if (qp_local == 2) {
} else {
gf_bifs_dec_qp_remove(codec, initial_qp);
}
}
}
if (qp_on) gf_bifs_dec_qp_remove(codec, GF_TRUE);
return GF_OK;
}

static int sfb_enqueue(struct sk_buff *skb, struct Qdisc *sch,
struct sk_buff **to_free)
{
struct sfb_sched_data *q = qdisc_priv(sch);
struct Qdisc *child = q->qdisc;
struct tcf_proto *fl;
int i;
u32 p_min = ~0;
u32 minqlen = ~0;
u32 r, sfbhash;
u32 slot = q->slot;
int ret = NET_XMIT_SUCCESS | __NET_XMIT_BYPASS;
if (unlikely(sch->q.qlen >= q->limit)) {
qdisc_qstats_overlimit(sch);
q->stats.queuedrop++;
goto drop;
}
if (q->rehash_interval > 0) {
unsigned long limit = q->rehash_time + q->rehash_interval;
if (unlikely(time_after(jiffies, limit))) {
sfb_swap_slot(q);
q->rehash_time = jiffies;
} else if (unlikely(!q->double_buffering && q->warmup_time > 0 &&
time_after(jiffies, limit - q->warmup_time))) {
q->double_buffering = true;
}
}
fl = rcu_dereference_bh(q->filter_list);
if (fl) {
u32 salt;
if (!sfb_classify(skb, fl, &ret, &salt))
goto other_drop;
sfbhash = jhash_1word(salt, q->bins[slot].perturbation);
} else {
sfbhash = skb_get_hash_perturb(skb, q->bins[slot].perturbation);
}
if (!sfbhash)
sfbhash = 1;
sfb_skb_cb(skb)->hashes[slot] = sfbhash;
for (i = 0; i < SFB_LEVELS; i++) {
u32 hash = sfbhash & SFB_BUCKET_MASK;
struct sfb_bucket *b = &q->bins[slot].bins[i][hash];
sfbhash >>= SFB_BUCKET_SHIFT;
if (b->qlen == 0)
decrement_prob(b, q);
else if (b->qlen >= q->bin_size)
increment_prob(b, q);
if (minqlen > b->qlen)
minqlen = b->qlen;
if (p_min > b->p_mark)
p_min = b->p_mark;
}
slot ^= 1;
sfb_skb_cb(skb)->hashes[slot] = 0;
if (unlikely(minqlen >= q->max)) {
qdisc_qstats_overlimit(sch);
q->stats.bucketdrop++;
goto drop;
}
if (unlikely(p_min >= SFB_MAX_PROB)) {
if (q->double_buffering) {
sfbhash = skb_get_hash_perturb(skb,
q->bins[slot].perturbation);
if (!sfbhash)
sfbhash = 1;
sfb_skb_cb(skb)->hashes[slot] = sfbhash;
for (i = 0; i < SFB_LEVELS; i++) {
u32 hash = sfbhash & SFB_BUCKET_MASK;
struct sfb_bucket *b = &q->bins[slot].bins[i][hash];
sfbhash >>= SFB_BUCKET_SHIFT;
if (b->qlen == 0)
decrement_prob(b, q);
else if (b->qlen >= q->bin_size)
increment_prob(b, q);
}
}
if (sfb_rate_limit(skb, q)) {
qdisc_qstats_overlimit(sch);
q->stats.penaltydrop++;
goto drop;
}
goto enqueue;
}
r = prandom_u32() & SFB_MAX_PROB;
if (unlikely(r < p_min)) {
if (unlikely(p_min > SFB_MAX_PROB / 2)) {
if (r < (p_min - SFB_MAX_PROB / 2) * 2) {
q->stats.earlydrop++;
goto drop;
}
}
if (INET_ECN_set_ce(skb)) {
q->stats.marked++;
} else {
q->stats.earlydrop++;
goto drop;
}
}
enqueue:
ret = qdisc_enqueue(skb, child, to_free);
if (likely(ret == NET_XMIT_SUCCESS)) {
qdisc_qstats_backlog_inc(sch, skb);
sch->q.qlen++;
increment_qlen(skb, q);
} else if (net_xmit_drop_count(ret)) {
q->stats.childdrop++;
qdisc_qstats_drop(sch);
}
return ret;
drop:
qdisc_drop(skb, sch, to_free);
return NET_XMIT_CN;
other_drop:
if (ret & __NET_XMIT_BYPASS)
qdisc_qstats_drop(sch);
kfree_skb(skb);
return ret;
}

static int io_timeout_prep(struct io_kiocb *req, const struct io_uring_sqe *sqe,
bool is_timeout_link)
{
struct io_timeout_data *data;
unsigned flags;
u32 off = READ_ONCE(sqe->off);
if (unlikely(req->ctx->flags & IORING_SETUP_IOPOLL))
return -EINVAL;
if (sqe->ioprio || sqe->buf_index || sqe->len != 1 ||
sqe->splice_fd_in)
return -EINVAL;
if (off && is_timeout_link)
return -EINVAL;
flags = READ_ONCE(sqe->timeout_flags);
if (flags & ~(IORING_TIMEOUT_ABS | IORING_TIMEOUT_CLOCK_MASK |
IORING_TIMEOUT_ETIME_SUCCESS))
return -EINVAL;
if (hweight32(flags & IORING_TIMEOUT_CLOCK_MASK) > 1)
return -EINVAL;
INIT_LIST_HEAD(&req->timeout.list);
req->timeout.off = off;
if (unlikely(off && !req->ctx->off_timeout_used))
req->ctx->off_timeout_used = true;
if (WARN_ON_ONCE(req_has_async_data(req)))
return -EFAULT;
if (io_alloc_async_data(req))
return -ENOMEM;
data = req->async_data;
data->req = req;
data->flags = flags;
if (get_timespec64(&data->ts, u64_to_user_ptr(sqe->addr)))
return -EFAULT;
if (data->ts.tv_sec < 0 || data->ts.tv_nsec < 0)
return -EINVAL;
data->mode = io_translate_timeout_mode(flags);
hrtimer_init(&data->timer, io_timeout_get_clock(data), data->mode);
if (is_timeout_link) {
struct io_submit_link *link = &req->ctx->submit_state.link;
if (!link->head)
return -EINVAL;
if (link->last->opcode == IORING_OP_LINK_TIMEOUT)
return -EINVAL;
req->timeout.head = link->last;
link->last->flags |= REQ_F_ARM_LTIMEOUT;
}
return 0;
}

int fmt_mtm_load_song(song_t *song, slurp_t *fp, unsigned int lflags)
{
uint8_t b[192];
int16_t ntrk, nchan, nord, npat, nsmp; uint16_t comment_len;
int n, pat, chan, smp, rows, todo = 0;
song_note_t *note;
uint16_t tmp;
uint32_t tmplong;
song_note_t **trackdata, *tracknote;
song_sample_t *sample;
slurp_read(fp, b, 3);
if (memcmp(b, "MTM", 3) != 0)
return LOAD_UNSUPPORTED;
n = slurp_getc(fp);
sprintf(song->tracker_id, "MultiTracker %d.%d", n >> 4, n & 0xf);
slurp_read(fp, song->title, 20);
song->title[20] = 0;
slurp_read(fp, &ntrk, 2);
ntrk = bswapLE16(ntrk);
npat = slurp_getc(fp);
nord = slurp_getc(fp) + 1;
slurp_read(fp, &comment_len, 2);
comment_len = bswapLE16(comment_len);
nsmp = slurp_getc(fp);
slurp_getc(fp); 
rows = slurp_getc(fp); 
if (rows != 64)
todo |= 64;
rows = MIN(rows, 64);
nchan = slurp_getc(fp);
for (n = 0; n < 32; n++) {
int pan = slurp_getc(fp) & 0xf;
pan = SHORT_PANNING(pan);
pan *= 4; song->channels[n].panning = pan;
}
for (n = nchan; n < MAX_CHANNELS; n++)
song->channels[n].flags = CHN_MUTE;
if (slurp_eof(fp)) {
return LOAD_FORMAT_ERROR;
}
if (nsmp > MAX_SAMPLES) {
log_appendf(4, " Warning: Too many samples");
}
for (n = 1, sample = song->samples + 1; n <= nsmp; n++, sample++) {
if (n > MAX_SAMPLES) {
slurp_seek(fp, 37, SEEK_CUR);
continue;
}
char name[23];
slurp_read(fp, name, 22);
name[22] = '\0';
strcpy(sample->name, name);
slurp_read(fp, &tmplong, 4);
sample->length = bswapLE32(tmplong);
slurp_read(fp, &tmplong, 4);
sample->loop_start = bswapLE32(tmplong);
slurp_read(fp, &tmplong, 4);
sample->loop_end = bswapLE32(tmplong);
if ((sample->loop_end - sample->loop_start) > 2) {
sample->flags |= CHN_LOOP;
} else {
sample->loop_start = 0;
sample->loop_end = 0;
}
song->samples[n].c5speed = MOD_FINETUNE(slurp_getc(fp));
sample->volume = slurp_getc(fp);
sample->volume *= 4; sample->global_volume = 64;
if (slurp_getc(fp) & 1) {
todo |= 16;
sample->flags |= CHN_16BIT;
sample->length >>= 1;
sample->loop_start >>= 1;
sample->loop_end >>= 1;
}
song->samples[n].vib_type = 0;
song->samples[n].vib_rate = 0;
song->samples[n].vib_depth = 0;
song->samples[n].vib_speed = 0;
}
slurp_read(fp, song->orderlist, 128);
memset(song->orderlist + nord, ORDER_LAST, MAX_ORDERS - nord);
trackdata = mem_calloc(ntrk, sizeof(song_note_t *));
for (n = 0; n < ntrk; n++) {
slurp_read(fp, b, 3 * rows);
trackdata[n] = mem_calloc(rows, sizeof(song_note_t));
mtm_unpack_track(b, trackdata[n], rows);
}
if (npat >= MAX_PATTERNS) {
log_appendf(4, " Warning: Too many patterns");
}
for (pat = 0; pat <= npat; pat++) {
if (pat >= MAX_PATTERNS) {
slurp_seek(fp, 64, SEEK_CUR);
continue;
}
song->patterns[pat] = csf_allocate_pattern(MAX(rows, 32));
song->pattern_size[pat] = song->pattern_alloc_size[pat] = 64;
tracknote = trackdata[n];
for (chan = 0; chan < 32; chan++) {
slurp_read(fp, &tmp, 2);
tmp = bswapLE16(tmp);
if (tmp == 0) {
continue;
} else if (tmp > ntrk) {
for (n = 0; n < ntrk; n++)
free(trackdata[n]);
free(trackdata);
return LOAD_FORMAT_ERROR;
}
note = song->patterns[pat] + chan;
tracknote = trackdata[tmp - 1];
for (n = 0; n < rows; n++, tracknote++, note += MAX_CHANNELS)
*note = *tracknote;
}
if (rows < 32) {
note = song->patterns[pat] + 64 * (rows - 1);
while (note->effect || note->param)
note++;
note->effect = FX_PATTERNBREAK;
}
}
for (n = 0; n < ntrk; n++)
free(trackdata[n]);
free(trackdata);
read_lined_message(song->message, fp, comment_len, 40);
if (!(lflags & LOAD_NOSAMPLES)) {
for (smp = 1; smp <= nsmp && smp <= MAX_SAMPLES; smp++) {
uint32_t ssize;
if (song->samples[smp].length == 0)
continue;
ssize = csf_read_sample(song->samples + smp,
(SF_LE | SF_PCMU | SF_M
| ((song->samples[smp].flags & CHN_16BIT) ? SF_16 : SF_8)),
fp->data + fp->pos, fp->length - fp->pos);
slurp_seek(fp, ssize, SEEK_CUR);
}
}
song->flags = SONG_ITOLDEFFECTS | SONG_COMPATGXX;
if (todo & 64)
log_appendf(2, " TODO: test this file with other players (beats per track != 64)");
if (todo & 16)
log_appendf(2, " TODO: double check 16 bit sample loading");
return LOAD_SUCCESS;
}

static int
dissect_kafka_varint(proto_tree *tree, int hf_item, tvbuff_t *tvb, packet_info *pinfo, int offset,
gint64 *p_value)
{
gint64 value;
guint len;
proto_item *pi;
len = tvb_get_varint(tvb, offset, FT_VARINT_MAX_LEN, &value, ENC_VARINT_ZIGZAG);
pi = proto_tree_add_int64(tree, hf_item, tvb, offset, len, value);
if (len == 0) {
expert_add_info(pinfo, pi, &ei_kafka_bad_varint);
return offset;
}
if (p_value != NULL) *p_value = value;
return offset + len;
}

njs_int_t
njs_async_function_frame_invoke(njs_vm_t *vm, njs_value_t *retval)
{
njs_int_t                 ret;
njs_value_t               ctor;
njs_native_frame_t        *frame;
njs_promise_capability_t  *capability;
frame = vm->top_frame;
frame->retval = retval;
njs_set_function(&ctor, &vm->constructors[NJS_OBJ_TYPE_PROMISE]);
capability = njs_promise_new_capability(vm, &ctor);
if (njs_slow_path(capability == NULL)) {
return NJS_ERROR;
}
frame->function->context = capability;
ret = njs_function_lambda_call(vm);
if (ret == NJS_OK) {
ret = njs_function_call(vm, njs_function(&capability->resolve),
&njs_value_undefined, retval, 1, &vm->retval);
} else if (ret == NJS_AGAIN) {
ret = NJS_OK;
} else if (ret == NJS_ERROR) {
if (njs_is_memory_error(vm, &vm->retval)) {
return NJS_ERROR;
}
ret = njs_function_call(vm, njs_function(&capability->reject),
&njs_value_undefined, &vm->retval, 1,
&vm->retval);
}
*retval = capability->promise;
return ret;
}

int gdImageColorMatch (gdImagePtr im1, gdImagePtr im2)
{
unsigned long *buf; 
unsigned long *bp; 
int color, rgb;
int x,y;
int count;
if( !im1->trueColor ) {
return -1; 
}
if( im2->trueColor ) {
return -2; 
}
if( (im1->sx != im2->sx) || (im1->sy != im2->sy) ) {
return -3; 
}
if (im2->colorsTotal<1) {
return -4; 
}
buf = (unsigned long *)safe_emalloc(sizeof(unsigned long), 5 * im2->colorsTotal, 0);
memset( buf, 0, sizeof(unsigned long) * 5 * im2->colorsTotal );
for (x=0; x<im1->sx; x++) {
for( y=0; y<im1->sy; y++ ) {
color = im2->pixels[y][x];
rgb = im1->tpixels[y][x];
bp = buf + (color * 5);
(*(bp++))++;
*(bp++) += gdTrueColorGetRed(rgb);
*(bp++) += gdTrueColorGetGreen(rgb);
*(bp++) += gdTrueColorGetBlue(rgb);
*(bp++) += gdTrueColorGetAlpha(rgb);
}
}
bp = buf;
for (color=0; color<im2->colorsTotal; color++) {
count = *(bp++);
if( count > 0 ) {
im2->red[color]= *(bp++) / count;
im2->green[color]= *(bp++) / count;
im2->blue[color]= *(bp++) / count;
im2->alpha[color]= *(bp++) / count;
} else {
bp += 4;
}
}
gdFree(buf);
return 0;
}

txNode* fxObjectBindingFromExpression(txParser* parser, txNode* theNode, txToken theToken)
{
txNodeList* list = ((txObjectNode*)theNode)->items;
txNode* property = list->first;
txNode* binding;
txUnsigned flags = 0;
while (property) {
if (property->description->token == XS_TOKEN_PROPERTY) {
binding = fxBindingFromExpression(parser, ((txPropertyNode*)property)->value, theToken);
if (!binding) {
parser->errorSymbol = parser->SyntaxErrorSymbol;
return NULL;
}
property->description = &gxTokenDescriptions[XS_TOKEN_PROPERTY_BINDING];
((txPropertyBindingNode*)property)->binding = binding;
}
else if (property->description->token == XS_TOKEN_PROPERTY_AT) {
binding = fxBindingFromExpression(parser, ((txPropertyAtNode*)property)->value, theToken);
if (!binding) {
parser->errorSymbol = parser->SyntaxErrorSymbol;
return NULL;
}
property->description = &gxTokenDescriptions[XS_TOKEN_PROPERTY_BINDING_AT];
((txPropertyBindingAtNode*)property)->binding = binding;
}
else if (property->description->token == XS_TOKEN_SPREAD) {
binding = fxRestBindingFromExpression(parser, property, theToken, 1);
if (!binding) {
parser->errorSymbol = parser->SyntaxErrorSymbol;
return NULL;
}
flags |= mxSpreadFlag;
break;
}
property = property->next;
}
fxPushNode(parser, (txNode*)list);
fxPushNodeStruct(parser, 1, XS_TOKEN_OBJECT_BINDING, theNode->line);
parser->root->flags |= flags;
return fxPopNode(parser);
}

static s32 naludmx_parse_nal_vvc(GF_NALUDmxCtx *ctx, char *data, u32 size, Bool *skip_nal, Bool *is_slice, Bool *is_islice)
{
s32 ps_idx = 0;
s32 res;
u8 nal_unit_type, temporal_id, layer_id;
*skip_nal = GF_FALSE;
if (size<2) return -1;
gf_bs_reassign_buffer(ctx->bs_r, data, size);
res = gf_vvc_parse_nalu_bs(ctx->bs_r, ctx->vvc_state, &nal_unit_type, &temporal_id, &layer_id);
ctx->nb_nalus++;
if (res < 0) {
if (res == -1) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[%s] Warning: Error parsing NAL unit\n", ctx->log_name));
}
*skip_nal = GF_TRUE;
}
if (layer_id && ctx->nosvc) {
*skip_nal = GF_TRUE;
return 0;
}
switch (nal_unit_type) {
case GF_VVC_NALU_VID_PARAM:
if (ctx->novpsext) {
ps_idx = ctx->vvc_state->last_parsed_vps_id;
} else {
ps_idx = ctx->vvc_state->last_parsed_vps_id;
}
if (ps_idx<0) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[%s] Error parsing Video Param Set\n", ctx->log_name));
} else {
naludmx_queue_param_set(ctx, data, size, GF_VVC_NALU_VID_PARAM, ps_idx, temporal_id, layer_id);
}
*skip_nal = GF_TRUE;
break;
case GF_VVC_NALU_SEQ_PARAM:
ps_idx = ctx->vvc_state->last_parsed_sps_id;
if (ps_idx<0) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[%s] Error parsing Sequence Param Set\n", ctx->log_name));
} else {
naludmx_queue_param_set(ctx, data, size, GF_VVC_NALU_SEQ_PARAM, ps_idx, temporal_id, layer_id);
}
*skip_nal = GF_TRUE;
break;
case GF_VVC_NALU_PIC_PARAM:
ps_idx = ctx->vvc_state->last_parsed_pps_id;
if (ps_idx<0) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[%s] Error parsing Picture Param Set\n", ctx->log_name));
} else {
naludmx_queue_param_set(ctx, data, size, GF_VVC_NALU_PIC_PARAM, ps_idx, temporal_id, layer_id);
}
*skip_nal = GF_TRUE;
break;
case GF_VVC_NALU_DEC_PARAM:
ps_idx = 0;
naludmx_queue_param_set(ctx, data, size, GF_VVC_NALU_DEC_PARAM, ps_idx, temporal_id, layer_id);
*skip_nal = GF_TRUE;
break;
case GF_VVC_NALU_OPI:
ps_idx = 0;
naludmx_queue_param_set(ctx, data, size, GF_VVC_NALU_OPI, ps_idx, temporal_id, layer_id);
*skip_nal = GF_TRUE;
break;
case GF_VVC_NALU_APS_PREFIX:
#if 0
ps_idx = ctx->vvc_state->last_parsed_aps_id;
if (ps_idx<0) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[%s] Error parsing Decoder Param Set\n", ctx->log_name));
} else {
naludmx_queue_param_set(ctx, data, size, GF_VVC_NALU_APS_PREFIX, ps_idx, temporal_id, layer_id);
}
*skip_nal = GF_TRUE;
#else
naludmx_push_prefix(ctx, data, size, GF_FALSE);
*skip_nal = GF_TRUE;
#endif
break;
case GF_VVC_NALU_SEI_PREFIX:
gf_vvc_parse_sei(data, size, ctx->vvc_state);
if (!ctx->nosei) {
ctx->nb_sei++;
naludmx_push_prefix(ctx, data, size, GF_FALSE);
} else {
ctx->nb_nalus--;
}
*skip_nal = GF_TRUE;
break;
case GF_VVC_NALU_SEI_SUFFIX:
if (! ctx->is_playing) return 0;
gf_vvc_parse_sei(data, size, ctx->vvc_state);
if (ctx->nosei) {
*skip_nal = GF_TRUE;
ctx->nb_nalus--;
} else {
ctx->nb_sei++;
}
break;
case GF_VVC_NALU_PIC_HEADER:
if (! ctx->is_playing) return 0;
break;
case GF_VVC_NALU_SLICE_TRAIL:
case GF_VVC_NALU_SLICE_STSA:
case GF_VVC_NALU_SLICE_RADL:
case GF_VVC_NALU_SLICE_RASL:
case GF_VVC_NALU_SLICE_IDR_W_RADL:
case GF_VVC_NALU_SLICE_IDR_N_LP:
case GF_VVC_NALU_SLICE_CRA:
case GF_VVC_NALU_SLICE_GDR:
if (! ctx->is_playing) return 0;
*is_slice = GF_TRUE;
ctx->last_layer_id = layer_id;
ctx->last_temporal_id = temporal_id;
if (! *skip_nal) {
switch (ctx->vvc_state->s_info.slice_type) {
case GF_VVC_SLICE_TYPE_P:
if (layer_id) ctx->nb_e_p++;
else ctx->nb_p++;
break;
case GF_VVC_SLICE_TYPE_I:
if (layer_id) ctx->nb_e_i++;
else ctx->nb_i++;
*is_islice = GF_TRUE;
break;
case GF_VVC_SLICE_TYPE_B:
if (layer_id) ctx->nb_e_b++;
else ctx->nb_b++;
break;
case GF_VVC_SLICE_TYPE_UNKNOWN:
ctx->vvc_no_stats = GF_TRUE;
break;
}
}
break;
case GF_VVC_NALU_ACCESS_UNIT:
ctx->nb_aud++;
if (!ctx->opid) {
ctx->has_initial_aud = GF_TRUE;
memcpy(ctx->init_aud, data, 3);
}
break;
case GF_VVC_NALU_FILLER_DATA:
case GF_VVC_NALU_END_OF_SEQ:
case GF_VVC_NALU_END_OF_STREAM:
*skip_nal = GF_TRUE;
break;
default:
if (! ctx->is_playing) return 0;
GF_LOG(GF_LOG_WARNING, GF_LOG_MEDIA, ("[%s] NAL Unit type %d not handled - adding\n", ctx->log_name, nal_unit_type));
break;
}
if (*skip_nal) return res;
ctx->linf[layer_id].layer_id_plus_one = layer_id + 1;
if (! ctx->linf[layer_id].max_temporal_id ) ctx->linf[layer_id].max_temporal_id = temporal_id;
else if (ctx->linf[layer_id].max_temporal_id < temporal_id) ctx->linf[layer_id].max_temporal_id = temporal_id;
if (! ctx->linf[layer_id].min_temporal_id ) ctx->linf[layer_id].min_temporal_id = temporal_id;
else if (ctx->linf[layer_id].min_temporal_id > temporal_id) ctx->linf[layer_id].min_temporal_id = temporal_id;
if (ctx->max_temporal_id[layer_id] < temporal_id)
ctx->max_temporal_id[layer_id] = temporal_id;
if (ctx->min_layer_id > layer_id) ctx->min_layer_id = layer_id;
return res;
}

TypeAttr CastQuantizedTypeAttrFromExpressedType(Builder builder,
TypeAttr source, Type target,
int axis) {
auto source_type = source.getValue().dyn_cast_or_null<ShapedType>();
if (!source_type) return {};
auto src_ele_type = source_type.getElementType();
auto qtype = src_ele_type.dyn_cast<quant::QuantizedType>();
if (auto per_axis =
qtype.dyn_cast_or_null<quant::UniformQuantizedPerAxisType>()) {
qtype =
ResetAxisAndBroadcast(source_type.getShape(), per_axis, target, axis);
}
if (!qtype) return {};
Type final_type = qtype.castFromExpressedType(target);
if (!final_type) return {};
return TypeAttr::get(final_type);
}

