for (ExifData::const_iterator pos = exifData.begin(); pos != exifData.end(); ++pos) {
if (pos->groupName() == group_) {
uint16_t tag = pos->tag();
if (tag != 0x00fe && tag != 0x00ff && Internal::isTiffImageTag(tag, Internal::ifd0Id)) {
preview.add(ExifKey(tag, "Image"), &pos->value());
}
}
}
Value &dataValue = const_cast<Value&>(preview["Exif.Image." + offsetTag_].value());
if (dataValue.sizeDataArea() == 0) {
BasicIo &io = image_.io();
if (io.open() != 0) {
throw Error(kerDataSourceOpenFailed, io.path(), strError());
}
IoCloser closer(io);
const Exiv2::byte* base = io.mmap();
const Value &sizes = preview["Exif.Image." + sizeTag_].value();
if (sizes.count() == dataValue.count()) {
if (sizes.count() == 1) {
uint32_t offset = dataValue.toLong(0);
uint32_t size = sizes.toLong(0);
if (offset + size <= static_cast<uint32_t>(io.size()))
dataValue.setDataArea(base + offset, size);
}
else {
DataBuf buf(size_);
Exiv2::byte* pos = buf.pData_;
for (int i = 0; i < sizes.count(); i++) {
uint32_t offset = dataValue.toLong(i);
uint32_t size = sizes.toLong(i);
if (size!=0 && offset + size <= static_cast<uint32_t>(io.size()))
memcpy(pos, base + offset, size);
pos += size;
}
dataValue.setDataArea(buf.pData_, buf.size_);
}
}
}
if (0 == strcmp(group_, "Image2") && image_.mimeType() == "image/x-canon-cr2") {
preview["Exif.Image.Compression"] = uint16_t(1);
}
MemIo mio;
IptcData emptyIptc;
XmpData  emptyXmp;
TiffParser::encode(mio, 0, 0, Exiv2::littleEndian, preview, emptyIptc, emptyXmp);
return DataBuf(mio.mmap(), (long) mio.size());
}

void LoadBorders(const Rect& block_rect, size_t hshift, size_t vshift,
const FrameDimensions& frame_dim, size_t padding,
const ImageF& border_storage_h, const ImageF& border_storage_v,
const Rect& r, ImageF* plane_out) {
constexpr size_t kGroupDataXBorder = PassesDecoderState::kGroupDataXBorder;
constexpr size_t kGroupDataYBorder = PassesDecoderState::kGroupDataYBorder;
size_t x0 = DivCeil(block_rect.x0() * kBlockDim, 1 << hshift);
size_t x1 =
DivCeil((block_rect.x0() + block_rect.xsize()) * kBlockDim, 1 << hshift);
size_t y0 = DivCeil(block_rect.y0() * kBlockDim, 1 << vshift);
size_t y1 =
DivCeil((block_rect.y0() + block_rect.ysize()) * kBlockDim, 1 << vshift);
size_t gy = block_rect.y0() / kGroupDimInBlocks;
size_t gx = block_rect.x0() / kGroupDimInBlocks;
size_t borderx = GroupBorderAssigner::PaddingX(padding);
size_t bordery = padding;
size_t borderx_write = padding + borderx;
size_t bordery_write = padding + bordery;
JXL_DASSERT(r.x0() == 0 || r.x0() >= borderx);
size_t x0src = DivCeil(r.x0() == 0 ? r.x0() : r.x0() - borderx, 1 << hshift);
size_t x1src =
DivCeil(r.x0() + r.xsize() +
(r.x0() + r.xsize() == frame_dim.xsize_padded ? 0 : borderx),
1 << hshift);
JXL_DASSERT(r.y0() == 0 || r.y0() >= bordery);
size_t y0src = DivCeil(r.y0() == 0 ? r.y0() : r.y0() - bordery, 1 << vshift);
size_t y1src =
DivCeil(r.y0() + r.ysize() +
(r.y0() + r.ysize() == frame_dim.ysize_padded ? 0 : bordery),
1 << vshift);
if (y0src < y0) {
CopyImageTo(
Rect(x0src, (gy * 2 - 1) * bordery_write, x1src - x0src, bordery_write),
border_storage_h,
Rect(kGroupDataXBorder + x0src - x0, kGroupDataYBorder - bordery_write,
x1src - x0src, bordery_write),
plane_out);
}
if (y1src > y1) {
CopyImageTo(
Rect(x0src, (gy * 2 + 2) * bordery_write, x1src - x0src, bordery_write),
border_storage_h,
Rect(kGroupDataXBorder + x0src - x0, kGroupDataYBorder + y1 - y0,
x1src - x0src, bordery_write),
plane_out);
}
if (x0src < x0) {
CopyImageTo(
Rect((gx * 2 - 1) * borderx_write, y0src, borderx_write, y1src - y0src),
border_storage_v,
Rect(kGroupDataXBorder - borderx_write, kGroupDataYBorder + y0src - y0,
borderx_write, y1src - y0src),
plane_out);
}
if (x1src > x1) {
CopyImageTo(
Rect((gx * 2 + 2) * borderx_write, y0src, borderx_write, y1src - y0src),
border_storage_v,
Rect(kGroupDataXBorder + x1 - x0, kGroupDataYBorder + y0src - y0,
borderx_write, y1src - y0src),
plane_out);
}
}

GF_Err tenc_box_read(GF_Box *s, GF_BitStream *bs)
{
u8 iv_size;
GF_TrackEncryptionBox *ptr = (GF_TrackEncryptionBox*)s;
ISOM_DECREASE_SIZE(ptr, 3);
gf_bs_read_u8(bs); 
if (!ptr->version) {
gf_bs_read_u8(bs); } else {
ptr->crypt_byte_block = gf_bs_read_int(bs, 4);
ptr->skip_byte_block = gf_bs_read_int(bs, 4);
}
ptr->isProtected = gf_bs_read_u8(bs);
ISOM_DECREASE_SIZE(ptr, 17);
ptr->key_info[0] = 0;
ptr->key_info[1] = 0;
ptr->key_info[2] = 0;
ptr->key_info[3] = iv_size = gf_bs_read_u8(bs);
gf_bs_read_data(bs, ptr->key_info+4, 16);
if (!iv_size && ptr->isProtected) {
ISOM_DECREASE_SIZE(ptr, 1);
iv_size = ptr->key_info[20] = gf_bs_read_u8(bs);
ISOM_DECREASE_SIZE(ptr, ptr->key_info[20]);
gf_bs_read_data(bs, ptr->key_info+21, iv_size);
}
return GF_OK;
}

static void cf_check init_intel(struct cpuinfo_x86 *c)
{
detect_extended_topology(c);
init_intel_cacheinfo(c);
if (c->cpuid_level > 9) {
unsigned eax = cpuid_eax(10);
if ((eax & 0xff) && (((eax>>8) & 0xff) > 1))
__set_bit(X86_FEATURE_ARCH_PERFMON, c->x86_capability);
}
if ( !cpu_has(c, X86_FEATURE_XTOPOLOGY) )
{
c->x86_max_cores = num_cpu_cores(c);
detect_ht(c);
}
Intel_errata_workarounds(c);
if ((c->x86 == 0xf && c->x86_model >= 0x03) ||
(c->x86 == 0x6 && c->x86_model >= 0x0e))
__set_bit(X86_FEATURE_CONSTANT_TSC, c->x86_capability);
if (cpu_has(c, X86_FEATURE_ITSC)) {
__set_bit(X86_FEATURE_CONSTANT_TSC, c->x86_capability);
__set_bit(X86_FEATURE_NONSTOP_TSC, c->x86_capability);
__set_bit(X86_FEATURE_TSC_RELIABLE, c->x86_capability);
}
if ( opt_arat &&
( c->cpuid_level >= 0x00000006 ) &&
( cpuid_eax(0x00000006) & (1u<<2) ) )
__set_bit(X86_FEATURE_ARAT, c->x86_capability);
if ((opt_cpu_info && !(c->apicid & (c->x86_num_siblings - 1))) ||
c == &boot_cpu_data )
intel_log_freq(c);
}

static MagickBooleanType SkipDXTMipmaps(Image *image,DDSInfo *dds_info,
int texel_size,ExceptionInfo *exception)
{
register ssize_t
i;
MagickOffsetType
offset;
size_t
h,
w;
if (dds_info->ddscaps1 & DDSCAPS_MIPMAP
&& (dds_info->ddscaps1 & DDSCAPS_TEXTURE
|| dds_info->ddscaps2 & DDSCAPS2_CUBEMAP))
{
if (EOFBlob(image) != MagickFalse)
{
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
return(MagickFalse);
}
w = DIV2(dds_info->width);
h = DIV2(dds_info->height);
for (i = 1; (i < (ssize_t) dds_info->mipmapcount) && w && h; i++)
{
offset = (MagickOffsetType) ((w + 3) / 4) * ((h + 3) / 4) * texel_size;
(void) SeekBlob(image, offset, SEEK_CUR);
w = DIV2(w);
h = DIV2(h);
}
}
return(MagickTrue);
}

