LOG(LOG_DEBUG, "pb_controller::play_file: running `%s'", cmdline.c_str());
::system(cmdline.c_str());
}

static void
find_entries (FILE *inf)
{
char *cp;
language *lang = curfdp->lang;
Lang_function *parser = NULL;
if (lang != NULL && lang->function != NULL)
{
parser = lang->function;
}
if (parser == NULL)
{
lang = get_language_from_filename (curfdp->infname, true);
if (lang != NULL && strcmp (lang->name, "objc") == 0)
test_objc_is_mercury (curfdp->infname, &lang);
if (lang != NULL && lang->function != NULL)
{
curfdp->lang = lang;
parser = lang->function;
}
}
if (parser == NULL
&& readline_internal (&lb, inf, infilename) > 0
&& lb.len >= 2
&& lb.buffer[0] == '#'
&& lb.buffer[1] == '!')
{
char *lp;
lp = strrchr (lb.buffer+2, '/');
if (lp != NULL)
lp += 1;
else
lp = skip_spaces (lb.buffer + 2);
cp = skip_non_spaces (lp);
if (cp > lp && strneq (lp, "env", cp - lp))
{
lp = skip_spaces (cp);
cp = skip_non_spaces (lp);
}
*cp = '\0';
if (*lp)
{
lang = get_language_from_interpreter (lp);
if (lang != NULL && lang->function != NULL)
{
curfdp->lang = lang;
parser = lang->function;
}
}
}
reset_input (inf);
if (parser == NULL)
{
lang = get_language_from_filename (curfdp->infname, false);
if (lang != NULL && lang->function != NULL)
{
curfdp->lang = lang;
parser = lang->function;
}
}
if (parser == NULL)
{
node *old_last_node = last_node;
curfdp->lang = get_language_from_langname ("fortran");
find_entries (inf);
if (old_last_node == last_node)
{
reset_input (inf);
curfdp->lang = get_language_from_langname (cplusplus ? "c++" : "c");
find_entries (inf);
}
return;
}
if (!no_line_directive
&& curfdp->lang != NULL && curfdp->lang->metasource)
{
fdesc **fdpp = &fdhead;
while (*fdpp != NULL)
if (*fdpp != curfdp
&& streq ((*fdpp)->taggedfname, curfdp->taggedfname))
{
fdesc *badfdp = *fdpp;
invalidate_nodes (badfdp, &nodehead);
*fdpp = badfdp->next; 
free_fdesc (badfdp);
}
else
fdpp = &(*fdpp)->next; 
}
assert (parser != NULL);
linebuffer_setlen (&filebuf, 0); 
lineno = 0;       
charno = 0;       
linecharno = 0;       
parser (inf);
regex_tag_multiline ();
}

