Supports_Condition_Obj Parser::parse_supports_condition_in_parens()
{
Supports_Condition_Obj interp = parse_supports_interpolation();
if (interp != 0) return interp;
if (!lex < exactly <'('> >()) return {};
lex < css_whitespace >();
Supports_Condition_Obj cond = parse_supports_condition();
if (cond != 0) {
if (!lex < exactly <')'> >()) error("unclosed parenthesis in @supports declaration");
} else {
cond = parse_supports_declaration();
if (!lex < exactly <')'> >()) error("unclosed parenthesis in @supports declaration");
}
lex < css_whitespace >();
return cond;
}

static bool vgacon_scroll(struct vc_data *c, unsigned int t, unsigned int b,
enum con_scroll dir, unsigned int lines)
{
unsigned long oldo;
unsigned int delta;
if (t || b != c->vc_rows || vga_is_gfx || c->vc_mode != KD_TEXT)
return false;
if (!vga_hardscroll_enabled || lines >= c->vc_rows / 2)
return false;
vgacon_restore_screen(c);
oldo = c->vc_origin;
delta = lines * c->vc_size_row;
if (dir == SM_UP) {
vgacon_scrollback_update(c, t, lines);
if (c->vc_scr_end + delta >= vga_vram_end) {
scr_memcpyw((u16 *) vga_vram_base,
(u16 *) (oldo + delta),
c->vc_screenbuf_size - delta);
c->vc_origin = vga_vram_base;
vga_rolled_over = oldo - vga_vram_base;
} else
c->vc_origin += delta;
scr_memsetw((u16 *) (c->vc_origin + c->vc_screenbuf_size -
delta), c->vc_video_erase_char,
delta);
} else {
if (oldo - delta < vga_vram_base) {
scr_memmovew((u16 *) (vga_vram_end -
c->vc_screenbuf_size +
delta), (u16 *) oldo,
c->vc_screenbuf_size - delta);
c->vc_origin = vga_vram_end - c->vc_screenbuf_size;
vga_rolled_over = 0;
} else
c->vc_origin -= delta;
c->vc_scr_end = c->vc_origin + c->vc_screenbuf_size;
scr_memsetw((u16 *) (c->vc_origin), c->vc_video_erase_char,
delta);
}
c->vc_scr_end = c->vc_origin + c->vc_screenbuf_size;
c->vc_visible_origin = c->vc_origin;
vga_set_mem_top(c);
c->vc_pos = (c->vc_pos - oldo) + c->vc_origin;
return true;
}

static void
nv_scroll(cmdarg_T *cap)
{
intused = 0;
longn;
#ifdef FEAT_FOLDING
linenr_Tlnum;
#endif
inthalf;
cap->oap->motion_type = MLINE;
setpcmark();
if (cap->cmdchar == 'L')
{
validate_botline();    curwin->w_cursor.lnum = curwin->w_botline - 1;
if (cap->count1 - 1 >= curwin->w_cursor.lnum)
curwin->w_cursor.lnum = 1;
else
{
#ifdef FEAT_FOLDING
if (hasAnyFolding(curwin))
{
for (n = cap->count1 - 1; n > 0
&& curwin->w_cursor.lnum > curwin->w_topline; --n)
{
(void)hasFolding(curwin->w_cursor.lnum,
&curwin->w_cursor.lnum, NULL);
--curwin->w_cursor.lnum;
}
}
else
#endif
curwin->w_cursor.lnum -= cap->count1 - 1;
}
}
else
{
if (cap->cmdchar == 'M')
{
#ifdef FEAT_DIFF
used -= diff_check_fill(curwin, curwin->w_topline)
- curwin->w_topfill;
#endif
validate_botline();        half = (curwin->w_height - curwin->w_empty_rows + 1) / 2;
for (n = 0; curwin->w_topline + n < curbuf->b_ml.ml_line_count; ++n)
{
#ifdef FEAT_DIFF
if (n > 0 && used + diff_check_fill(curwin, curwin->w_topline
+ n) / 2 >= half)
{
--n;
break;
}
#endif
used += plines(curwin->w_topline + n);
if (used >= half)
break;
#ifdef FEAT_FOLDING
if (hasFolding(curwin->w_topline + n, NULL, &lnum))
n = lnum - curwin->w_topline;
#endif
}
if (n > 0 && used > curwin->w_height)
--n;
}
else {
n = cap->count1 - 1;
#ifdef FEAT_FOLDING
if (hasAnyFolding(curwin))
{
lnum = curwin->w_topline;
while (n-- > 0 && lnum < curwin->w_botline - 1)
{
(void)hasFolding(lnum, NULL, &lnum);
++lnum;
}
n = lnum - curwin->w_topline;
}
#endif
}
curwin->w_cursor.lnum = curwin->w_topline + n;
if (curwin->w_cursor.lnum > curbuf->b_ml.ml_line_count)
curwin->w_cursor.lnum = curbuf->b_ml.ml_line_count;
}
if (cap->oap->op_type == OP_NOP)
cursor_correct();
beginline(BL_SOL | BL_FIX);
}

