bool parse( char* ptr )
{
bool first = true;
bool ok = true;
FileNode root_collection(fs->getFS(), 0, 0);
for(;;)
{
for(;;)
{
ptr = skipSpaces( ptr, 0, INT_MAX );
if( !ptr || *ptr == '\0' )
{
ok = !first;
break;
}
if( *ptr == '%' )
{
if( memcmp( ptr, "%YAML", 5 ) == 0 &&
memcmp( ptr, "%YAML:1.", 8 ) != 0 &&
memcmp( ptr, "%YAML 1.", 8 ) != 0)
CV_PARSE_ERROR_CPP( "Unsupported YAML version (it must be 1.x)" );
*ptr = '\0';
}
else if( *ptr == '-' )
{
if( memcmp(ptr, "---", 3) == 0 )
{
ptr += 3;
break;
}
else if( first )
break;
}
else if( cv_isalnum(*ptr) || *ptr=='_')
{
if( !first )
CV_PARSE_ERROR_CPP( "The YAML streams must start with '---', except the first one" );
break;
}
else if( fs->eof() )
break;
else
CV_PARSE_ERROR_CPP( "Invalid or unsupported syntax" );
}
if( ptr )
ptr = skipSpaces( ptr, 0, INT_MAX );
if( !ptr || !ptr[0] )
break;
if( memcmp( ptr, "...", 3 ) != 0 )
{
FileNode root_node = fs->addNode(root_collection, std::string(), FileNode::NONE);
ptr = parseValue( ptr, root_node, 0, false );
if( !root_node.isMap() && !root_node.isSeq() )
CV_PARSE_ERROR_CPP( "Only collections as YAML streams are supported by this parser" );
ptr = skipSpaces( ptr, 0, INT_MAX );
if( !ptr )
break;
}
if( fs->eof() )
break;
ptr += 3;
first = false;
}
return ok;
}

void WT_VoiceFilter (S_FILTER_CONTROL *pFilter, S_WT_INT_FRAME *pWTIntFrame)
{
EAS_PCM *pAudioBuffer;
EAS_I32 k;
EAS_I32 b1;
EAS_I32 b2;
EAS_I32 z1;
EAS_I32 z2;
EAS_I32 acc0;
EAS_I32 acc1;
EAS_I32 numSamples;
numSamples = pWTIntFrame->numSamples;
pAudioBuffer = pWTIntFrame->pAudioBuffer;
z1 = pFilter->z1;
z2 = pFilter->z2;
b1 = -pWTIntFrame->frame.b1;
b2 = -pWTIntFrame->frame.b2 >> 1;
k = pWTIntFrame->frame.k >> 1;
while (numSamples--)
{
acc0 = *pAudioBuffer;
acc1 = z1 * b1;
acc1 += z2 * b2;
acc0 = acc1 + k * acc0;
z2 = z1;
z1 = acc0 >> 14;
*pAudioBuffer++ = (EAS_I16) z1;
}
pFilter->z1 = (EAS_I16) z1;
pFilter->z2 = (EAS_I16) z2;
}

static gint rtps_util_add_type_union_member(proto_tree *tree,
tvbuff_t * tvb, gint offset, const guint encoding, guint64 union_type_id,
gboolean is_discriminator, dissection_info * info _U_) {
proto_tree * labels;
gint long_number, i;
gint offset_tmp;
guint32 member_id = 0, member_length = 0;
dissection_element object;
offset = rtps_util_add_type_member(tree, tvb, offset, encoding, NULL, &object); 
rtps_util_dissect_parameter_header(tvb, &offset, encoding, &member_id, &member_length);
offset_tmp = offset;
long_number = tvb_get_guint32(tvb, offset_tmp, encoding);
labels = proto_tree_add_subtree_format(tree, tvb, offset_tmp, member_length,
ett_rtps_type_enum_constant, NULL, "Labels (%u elements)", long_number);
offset_tmp += 4;
if ((object.flags & 8) == 8) {
union_member_mapping * mapping = NULL;
mapping = wmem_new(wmem_file_scope(), union_member_mapping);
(void) g_strlcpy(mapping->member_name, object.member_name, 256);
mapping->member_type_id = object.type_id;
mapping->discriminator = HASHMAP_DISCRIMINATOR_CONSTANT;
mapping->union_type_id = union_type_id + mapping->discriminator;
wmem_map_insert(union_member_mappings, &(mapping->union_type_id), (void *) mapping);
proto_item_append_text(labels, " Added mapping for discriminator (0x%016" PRIx64 ") name = %s",
mapping->union_type_id, mapping->member_name);
}
if (is_discriminator) {
union_member_mapping * mapping = NULL;
mapping = wmem_new(wmem_file_scope(), union_member_mapping);
(void) g_strlcpy(mapping->member_name, object.member_name, 256);
mapping->member_type_id = object.type_id;
mapping->discriminator = -1;
mapping->union_type_id = union_type_id + mapping->discriminator;
wmem_map_insert(union_member_mappings, &(mapping->union_type_id), (void *) mapping);
proto_item_append_text(labels, " Added mapping for discriminator (0x%016" PRIx64 ") name = %s",
mapping->union_type_id, mapping->member_name);
}
for (i = 0; i < long_number; i++) {
proto_item * ti;
union_member_mapping * mapping = NULL;
guint32 discriminator_case;
mapping = wmem_new(wmem_file_scope(), union_member_mapping);
discriminator_case = tvb_get_guint32(tvb, offset_tmp, encoding);
ti = proto_tree_add_item(labels, hf_rtps_type_object_union_label, tvb, offset_tmp, 4, encoding);
offset_tmp += 4;
(void) g_strlcpy(mapping->member_name, object.member_name, 256);
mapping->member_type_id = object.type_id;
mapping->discriminator = discriminator_case;
mapping->union_type_id = union_type_id + discriminator_case;
wmem_map_insert(union_member_mappings, &(mapping->union_type_id), (void *) mapping);
proto_item_append_text(ti, " Added mapping for discriminator (0x%016" PRIx64 ") name = %s",
mapping->union_type_id, mapping->member_name);
}
offset = check_offset_addition(offset, member_length, tree, NULL, tvb);
long_number = tvb_get_guint32(tvb, offset_tmp, encoding);
if ((long_number & PID_LIST_END) == PID_LIST_END) {
offset += 4;
}
return offset;
}

static int
get_entries(struct net *net, struct ipt_get_entries __user *uptr,
const int *len)
{
int ret;
struct ipt_get_entries get;
struct xt_table *t;
if (*len < sizeof(get))
return -EINVAL;
if (copy_from_user(&get, uptr, sizeof(get)) != 0)
return -EFAULT;
if (*len != sizeof(struct ipt_get_entries) + get.size)
return -EINVAL;
get.name[sizeof(get.name) - 1] = '\0';
t = xt_find_table_lock(net, AF_INET, get.name);
if (!IS_ERR(t)) {
const struct xt_table_info *private = t->private;
if (get.size == private->size)
ret = copy_entries_to_user(private->size,
t, uptr->entrytable);
else
ret = -EAGAIN;
module_put(t->me);
xt_table_unlock(t);
} else
ret = PTR_ERR(t);
return ret;
}

SIXELAPI SIXELSTATUS
sixel_decoder_decode(
sixel_decoder_t  *decoder)
{
SIXELSTATUS status = SIXEL_FALSE;
unsigned char *raw_data;
int sx;
int sy;
int raw_len;
int max;
int n;
FILE *input_fp = NULL;
unsigned char *indexed_pixels;
unsigned char *palette;
int ncolors;
unsigned char *pixels = NULL;
sixel_decoder_ref(decoder);
if (strcmp(decoder->input, "-") == 0) {
#if defined(O_BINARY)
# if HAVE__SETMODE
_setmode(fileno(stdin), O_BINARY);
# elif HAVE_SETMODE
setmode(fileno(stdin), O_BINARY);
# endif  
#endif  
input_fp = stdin;
} else {
input_fp = fopen(decoder->input, "rb");
if (!input_fp) {
sixel_helper_set_additional_message(
"sixel_decoder_decode: fopen() failed.");
status = (SIXEL_LIBC_ERROR | (errno & 0xff));
goto end;
}
}
raw_len = 0;
max = 64 * 1024;
raw_data = (unsigned char *)sixel_allocator_malloc(decoder->allocator, (size_t)max);
if (raw_data == NULL) {
sixel_helper_set_additional_message(
"sixel_decoder_decode: sixel_allocator_malloc() failed.");
status = SIXEL_BAD_ALLOCATION;
goto end;
}
for (;;) {
if ((max - raw_len) < 4096) {
max *= 2;
raw_data = (unsigned char *)sixel_allocator_realloc(decoder->allocator, raw_data, (size_t)max);
if (raw_data == NULL) {
sixel_helper_set_additional_message(
"sixel_decoder_decode: sixel_allocator_realloc() failed.");
status = SIXEL_BAD_ALLOCATION;
goto end;
}
}
if ((n = (int)fread(raw_data + raw_len, 1, 4096, input_fp)) <= 0) {
break;
}
raw_len += n;
}
if (input_fp != stdout) {
fclose(input_fp);
}
status = sixel_decode_raw(
raw_data,
raw_len,
&indexed_pixels,
&sx,
&sy,
&palette,
&ncolors,
decoder->allocator);
if (SIXEL_FAILED(status)) {
goto end;
}
status = sixel_helper_write_image_file(indexed_pixels, sx, sy, palette,
SIXEL_PIXELFORMAT_PAL8,
decoder->output,
SIXEL_FORMAT_PNG,
decoder->allocator);
if (SIXEL_FAILED(status)) {
goto end;
}
end:
sixel_allocator_free(decoder->allocator, pixels);
sixel_decoder_unref(decoder);
return status;
}

