else if (buf->b_p_bh[0] == 'u')unload_buf = TRUE;
#ifdef FEAT_TERMINAL
if (bt_terminal(buf) && (buf->b_nwindows == 1 || del_buf))
{
CHECK_CURBUF;
if (term_job_running(buf->b_term))
{
if (wipe_buf || unload_buf)
{
if (!can_unload_buffer(buf))
return;
free_terminal(buf);
}
else
{
del_buf = FALSE;
unload_buf = FALSE;
}
}
else if (buf->b_p_bh[0] == 'h' && !del_buf)
{
unload_buf = FALSE;
}
else
{
del_buf = TRUE;
unload_buf = TRUE;
wipe_buf = TRUE;
}
CHECK_CURBUF;
}
#endif
if ((del_buf || wipe_buf) && !can_unload_buffer(buf))
return;
if (win != NULL && win_valid_any_tab(win))
{
if (buf->b_nwindows == 1)
set_last_cursor(win);
buflist_setfpos(buf, win,
win->w_cursor.lnum == 1 ? 0 : win->w_cursor.lnum,
win->w_cursor.col, TRUE);
}
set_bufref(&bufref, buf);
if (buf->b_nwindows == 1)
{
++buf->b_locked;
if (apply_autocmds(EVENT_BUFWINLEAVE, buf->b_fname, buf->b_fname,
FALSE, buf)
&& !bufref_valid(&bufref))
{
aucmd_abort:
emsg(_(e_auabort));
return;
}
--buf->b_locked;
if (abort_if_last && one_window())
goto aucmd_abort;
if (!unload_buf)
{
++buf->b_locked;
if (apply_autocmds(EVENT_BUFHIDDEN, buf->b_fname, buf->b_fname,
FALSE, buf)
&& !bufref_valid(&bufref))
goto aucmd_abort;
--buf->b_locked;
if (abort_if_last && one_window())
goto aucmd_abort;
}
#ifdef FEAT_EVAL
if (!ignore_abort && aborting())
return;
#endif
}
if (is_curwin && curwin != the_curwin &&  win_valid_any_tab(the_curwin))
{
block_autocmds();
goto_tabpage_win(the_curtab, the_curwin);
unblock_autocmds();
}
nwindows = buf->b_nwindows;
if (buf->b_nwindows > 0)
--buf->b_nwindows;
#ifdef FEAT_DIFF
if (diffopt_hiddenoff() && !unload_buf && buf->b_nwindows == 0)
diff_buf_delete(buf);#endif
if (buf->b_nwindows > 0 || !unload_buf)
return;
if (buf->b_ffname == NULL)
del_buf = TRUE;
if (buf == curbuf && VIsual_active
#if defined(EXITFREE)
&& !entered_free_all_mem
#endif
)
end_visual_mode();
is_curbuf = (buf == curbuf);
buf->b_nwindows = nwindows;
buf_freeall(buf, (del_buf ? BFA_DEL : 0)
+ (wipe_buf ? BFA_WIPE : 0)
+ (ignore_abort ? BFA_IGNORE_ABORT : 0));
if (!bufref_valid(&bufref))
return;
#ifdef FEAT_EVAL
if (!ignore_abort && aborting())
return;
#endif
if (buf == curbuf && !is_curbuf)
return;
if (win_valid_any_tab(win) && win->w_buffer == buf)
win->w_buffer = NULL;  
if (buf->b_nwindows > 0)
--buf->b_nwindows;
if (wipe_buf)
{
if (action == DOBUF_WIPE_REUSE)
{
if (buf_reuse.ga_itemsize == 0)
ga_init2(&buf_reuse, sizeof(int), 50);
if (ga_grow(&buf_reuse, 1) == OK)
((int *)buf_reuse.ga_data)[buf_reuse.ga_len++] = buf->b_fnum;
}
if (buf->b_sfname != buf->b_ffname)
VIM_CLEAR(buf->b_sfname);
else
buf->b_sfname = NULL;
VIM_CLEAR(buf->b_ffname);
if (buf->b_prev == NULL)
firstbuf = buf->b_next;
else
buf->b_prev->b_next = buf->b_next;
if (buf->b_next == NULL)
lastbuf = buf->b_prev;
else
buf->b_next->b_prev = buf->b_prev;
free_buffer(buf);
}
else
{
if (del_buf)
{
free_buffer_stuff(buf, TRUE);
buf->b_flags = BF_CHECK_RO | BF_NEVERLOADED;
buf->b_p_initialized = FALSE;
}
buf_clear_file(buf);
if (del_buf)
buf->b_p_bl = FALSE;
}
}

static void readMovie(FILE *f)
{
int block, type, blockstart, blockoffset, length, nextFrame=0;
SWF_Parserstruct *blockp;
for (;;)
{
blockoffset = fileOffset;
if(filelen_check_fails(2))
break;
block = readUInt16 (f);
type = block >> 6;
length = block & ((1 << 6) - 1);
if (length == 63) 
{
if(filelen_check_fails(4))
break;
unsigned long real_length = readUInt32 (f);
if (real_length > INT_MAX) {
SWF_warn(" Could not process long block with length %lu:"
" blocks with length > %d not supported on this system\n",
real_length, INT_MAX);
continue;
} else {
length = (int) real_length;
}
}
blockstart = fileOffset;
nextFrame = fileOffset+length;
if(filelen_check_fails(length))
break;
blockp= blockParse(f, length, type);
if( ftell(f) != nextFrame ) 
{
SWF_warn(" Stream out of sync after parse of blocktype %d (%s)."
" %ld but expecting %d.\n", type, blockName(type),
ftell(f),nextFrame);
}
if( blockp ) 
{
outputBlock( type, blockp, f);
free(blockp);
} else {
SWF_warn("Error parsing block (unknown block type: %d, length %d)\n", 
type, length);
}
if (type == 0 || fileOffset >= m.size)
break;
fseek(f, nextFrame, SEEK_SET);
fileOffset = ftell(f);
}
putchar ('\n');
if (fileOffset < m.size)
{
SWF_warn("extra garbage (i.e., we messed up in main): \n");
dumpBytes (f, m.size - fileOffset);
printf ("\n\n");
}
outputTrailer(&m);
}

static guint32
rtmpt_get_amf_txid(tvbuff_t *tvb, gint offset)
{
guint32 remain = tvb_reported_length_remaining(tvb, offset);
if (remain > 0) {
guint32 itemlen = rtmpt_get_amf_length(tvb, offset);
if (remain<itemlen)
return 0;
offset += itemlen;
remain -= itemlen;
}
if (remain >= 9) {
guint8 iObjType = tvb_get_guint8(tvb, offset);
if (iObjType == AMF0_NUMBER) {
return (guint32)tvb_get_ntohieee_double(tvb, offset+1);
}
}
return 0;
}

