{
U_16 cpIndex = *(U_16 *)(J9ROMCLASS_SPECIALSPLITMETHODREFINDEXES(ramCP->ramClass->romClass) + splitTableIndex);
J9Method *method = ramCP->ramClass->specialSplitMethodTable[splitTableIndex];
