static MagickBooleanType WritePCXImage(const ImageInfo *image_info,Image *image)
{
MagickBooleanType
status;
MagickOffsetType
offset,
*page_table,
scene;
MemoryInfo
*pixel_info;
PCXInfo
pcx_info;
register const IndexPacket
*indexes;
register const PixelPacket
*p;
register ssize_t
i,
x;
register unsigned char
*q;
size_t
length;
ssize_t
y;
unsigned char
*pcx_colormap,
*pixels;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickSignature);
assert(image != (Image *) NULL);
assert(image->signature == MagickSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
status=OpenBlob(image_info,image,WriteBinaryBlobMode,&image->exception);
if (status == MagickFalse)
return(status);
(void) TransformImageColorspace(image,sRGBColorspace);
page_table=(MagickOffsetType *) NULL;
if ((LocaleCompare(image_info->magick,"DCX") == 0) ||
((GetNextImageInList(image) != (Image *) NULL) &&
(image_info->adjoin != MagickFalse)))
{
(void) WriteBlobLSBLong(image,0x3ADE68B1L);
page_table=(MagickOffsetType *) AcquireQuantumMemory(1024UL,
sizeof(*page_table));
if (page_table == (MagickOffsetType *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
for (scene=0; scene < 1024; scene++)
(void) WriteBlobLSBLong(image,0x00000000L);
}
scene=0;
do
{
if (page_table != (MagickOffsetType *) NULL)
page_table[scene]=TellBlob(image);
pcx_info.identifier=0x0a;
pcx_info.version=5;
pcx_info.encoding=image_info->compression == NoCompression ? 0 : 1;
pcx_info.bits_per_pixel=8;
if ((image->storage_class == PseudoClass) &&
(SetImageMonochrome(image,&image->exception) != MagickFalse))
pcx_info.bits_per_pixel=1;
pcx_info.left=0;
pcx_info.top=0;
pcx_info.right=(unsigned short) (image->columns-1);
pcx_info.bottom=(unsigned short) (image->rows-1);
switch (image->units)
{
case UndefinedResolution:
case PixelsPerInchResolution:
default:
{
pcx_info.horizontal_resolution=(unsigned short) image->x_resolution;
pcx_info.vertical_resolution=(unsigned short) image->y_resolution;
break;
}
case PixelsPerCentimeterResolution:
{
pcx_info.horizontal_resolution=(unsigned short)
(2.54*image->x_resolution+0.5);
pcx_info.vertical_resolution=(unsigned short)
(2.54*image->y_resolution+0.5);
break;
}
}
pcx_info.reserved=0;
pcx_info.planes=1;
if ((image->storage_class == DirectClass) || (image->colors > 256))
{
pcx_info.planes=3;
if (image->matte != MagickFalse)
pcx_info.planes++;
}
pcx_info.bytes_per_line=(unsigned short) (((size_t) image->columns*
pcx_info.bits_per_pixel+7)/8);
pcx_info.palette_info=1;
pcx_info.colormap_signature=0x0c;
(void) WriteBlobByte(image,pcx_info.identifier);
(void) WriteBlobByte(image,pcx_info.version);
(void) WriteBlobByte(image,pcx_info.encoding);
(void) WriteBlobByte(image,pcx_info.bits_per_pixel);
(void) WriteBlobLSBShort(image,pcx_info.left);
(void) WriteBlobLSBShort(image,pcx_info.top);
(void) WriteBlobLSBShort(image,pcx_info.right);
(void) WriteBlobLSBShort(image,pcx_info.bottom);
(void) WriteBlobLSBShort(image,pcx_info.horizontal_resolution);
(void) WriteBlobLSBShort(image,pcx_info.vertical_resolution);
pcx_colormap=(unsigned char *) AcquireQuantumMemory(256UL,
3*sizeof(*pcx_colormap));
if (pcx_colormap == (unsigned char *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
(void) memset(pcx_colormap,0,3*256*sizeof(*pcx_colormap));
q=pcx_colormap;
if ((image->storage_class == PseudoClass) && (image->colors <= 256))
for (i=0; i < (ssize_t) image->colors; i++)
{
*q++=ScaleQuantumToChar(image->colormap[i].red);
*q++=ScaleQuantumToChar(image->colormap[i].green);
*q++=ScaleQuantumToChar(image->colormap[i].blue);
}
(void) WriteBlob(image,3*16,(const unsigned char *) pcx_colormap);
(void) WriteBlobByte(image,pcx_info.reserved);
(void) WriteBlobByte(image,pcx_info.planes);
(void) WriteBlobLSBShort(image,pcx_info.bytes_per_line);
(void) WriteBlobLSBShort(image,pcx_info.palette_info);
for (i=0; i < 58; i++)
(void) WriteBlobByte(image,'\0');
length=(size_t) pcx_info.bytes_per_line;
pixel_info=AcquireVirtualMemory(length,pcx_info.planes*sizeof(*pixels));
if (pixel_info == (MemoryInfo *) NULL)
{
pcx_colormap=(unsigned char *) RelinquishMagickMemory(pcx_colormap);
if (page_table != (MagickOffsetType *) NULL)
page_table=(MagickOffsetType *) RelinquishMagickMemory(page_table);
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
}
pixels=(unsigned char *) GetVirtualMemoryBlob(pixel_info);
q=pixels;
if ((image->storage_class == DirectClass) || (image->colors > 256))
{
for (y=0; y < (ssize_t) image->rows; y++)
{
q=pixels;
for (i=0; i < pcx_info.planes; i++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,&image->exception);
if (p == (const PixelPacket *) NULL)
break;
switch ((int) i)
{
case 0:
{
for (x=0; x < (ssize_t) pcx_info.bytes_per_line; x++)
{
*q++=ScaleQuantumToChar(GetPixelRed(p));
p++;
}
break;
}
case 1:
{
for (x=0; x < (ssize_t) pcx_info.bytes_per_line; x++)
{
*q++=ScaleQuantumToChar(GetPixelGreen(p));
p++;
}
break;
}
case 2:
{
for (x=0; x < (ssize_t) pcx_info.bytes_per_line; x++)
{
*q++=ScaleQuantumToChar(GetPixelBlue(p));
p++;
}
break;
}
case 3:
default:
{
for (x=(ssize_t) pcx_info.bytes_per_line; x != 0; x--)
{
*q++=ScaleQuantumToChar((Quantum)
(GetPixelAlpha(p)));
p++;
}
break;
}
}
}
if (PCXWritePixels(&pcx_info,pixels,image) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
}
else
{
if (pcx_info.bits_per_pixel > 1)
for (y=0; y < (ssize_t) image->rows; y++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,&image->exception);
if (p == (const PixelPacket *) NULL)
break;
indexes=GetVirtualIndexQueue(image);
q=pixels;
for (x=0; x < (ssize_t) image->columns; x++)
*q++=(unsigned char) GetPixelIndex(indexes+x);
if (PCXWritePixels(&pcx_info,pixels,image) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,SaveImageTag,(MagickOffsetType)
y,image->rows);
if (status == MagickFalse)
break;
}
}
else
{
register unsigned char
bit,
byte;
for (y=0; y < (ssize_t) image->rows; y++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,&image->exception);
if (p == (const PixelPacket *) NULL)
break;
indexes=GetVirtualIndexQueue(image);
bit=0;
byte=0;
q=pixels;
for (x=0; x < (ssize_t) image->columns; x++)
{
byte<<=1;
if (GetPixelLuma(image,p) >= (QuantumRange/2.0))
byte|=0x01;
bit++;
if (bit == 8)
{
*q++=byte;
bit=0;
byte=0;
}
p++;
}
if (bit != 0)
*q++=byte << (8-bit);
if (PCXWritePixels(&pcx_info,pixels,image) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,SaveImageTag,(MagickOffsetType)
y,image->rows);
if (status == MagickFalse)
break;
}
}
}
(void) WriteBlobByte(image,pcx_info.colormap_signature);
(void) WriteBlob(image,3*256,pcx_colormap);
}
pixel_info=RelinquishVirtualMemory(pixel_info);
pcx_colormap=(unsigned char *) RelinquishMagickMemory(pcx_colormap);
if (page_table == (MagickOffsetType *) NULL)
break;
if (scene >= 1023)
break;
if (GetNextImageInList(image) == (Image *) NULL)
break;
image=SyncNextImageInList(image);
status=SetImageProgress(image,SaveImagesTag,scene++,
GetImageListLength(image));
if (status == MagickFalse)
break;
} while (image_info->adjoin != MagickFalse);
if (page_table != (MagickOffsetType *) NULL)
{
page_table[scene+1]=0;
offset=SeekBlob(image,0L,SEEK_SET);
if (offset < 0)
{
page_table=(MagickOffsetType *) RelinquishMagickMemory(page_table);
ThrowWriterException(CorruptImageError,"ImproperImageHeader");
}
(void) WriteBlobLSBLong(image,0x3ADE68B1L);
for (i=0; i <= (ssize_t) scene; i++)
(void) WriteBlobLSBLong(image,(unsigned int) page_table[i]);
page_table=(MagickOffsetType *) RelinquishMagickMemory(page_table);
}
if (status == MagickFalse)
{
char
*message;
message=GetExceptionMessage(errno);
(void) ThrowMagickException(&image->exception,GetMagickModule(),
FileOpenError,"UnableToWriteFile","`%s': %s",image->filename,message);
message=DestroyString(message);
}
(void) CloseBlob(image);
return(MagickTrue);
}

RList *r_bin_ne_get_segments(r_bin_ne_obj_t *bin) {
int i;
if (!bin) {
return NULL;
}
RList *segments = r_list_newf (free);
for (i = 0; i < bin->ne_header->SegCount; i++) {
RBinSection *bs = R_NEW0 (RBinSection);
if (!bs) {
return segments;
}
NE_image_segment_entry *se = &bin->segment_entries[i];
bs->size = se->length;
bs->vsize = se->minAllocSz ? se->minAllocSz : 64000;
bs->bits = R_SYS_BITS_16;
bs->is_data = se->flags & IS_DATA;
bs->perm = __translate_perms (se->flags);
bs->paddr = (ut64)se->offset * bin->alignment;
bs->name = r_str_newf ("%s.%" PFMT64d, se->flags & IS_MOVEABLE ? "MOVEABLE" : "FIXED", bs->paddr);
bs->is_segment = true;
r_list_append (segments, bs);
}
bin->segments = segments;
return segments;
}

static void
createFileDirectoryResponse(const char* basepath, uint32_t invokeId, ByteBuffer* response, int maxPduSize, char* directoryName, char* continueAfterFileName)
{
int maxSize = maxPduSize - 3; 
uint8_t* buffer = response->buffer;
bool moreFollows = false;
int tempStartPos = 30; 
int tempCurPos = tempStartPos;
int tempEncoded = 0;
if (continueAfterFileName != NULL) {
if (strlen(continueAfterFileName) == 0)
continueAfterFileName = NULL;
}
tempCurPos = addFileEntriesToResponse(basepath, buffer, tempCurPos, maxSize, directoryName, &continueAfterFileName, &moreFollows);
if (tempCurPos < 0) {
if (DEBUG_MMS_SERVER)
printf("MMS_SERVER: Error opening directory!\n");
mmsMsg_createServiceErrorPdu(invokeId, response, MMS_ERROR_FILE_FILE_NON_EXISTENT);
return;
}
tempEncoded = tempCurPos - tempStartPos;
uint32_t invokeIdSize = BerEncoder_UInt32determineEncodedSize((uint32_t) invokeId) + 2;
uint32_t listOfDirectoryEntrySeqSize = tempEncoded;
uint32_t listOfDirectoryEntrySize = 1 + BerEncoder_determineLengthSize(tempEncoded) + tempEncoded;
uint32_t fileDirectoryResponseSize = 1 + BerEncoder_determineLengthSize(listOfDirectoryEntrySize)
+ listOfDirectoryEntrySize;
if (moreFollows)
fileDirectoryResponseSize += 3; 
uint32_t confirmedResponsePDUSize = invokeIdSize + 2 + BerEncoder_determineLengthSize(fileDirectoryResponseSize)
+ fileDirectoryResponseSize;
int bufPos = 0;
bufPos = BerEncoder_encodeTL(0xa1, confirmedResponsePDUSize, buffer, bufPos);
bufPos = BerEncoder_encodeTL(0x02, invokeIdSize - 2, buffer, bufPos);
bufPos = BerEncoder_encodeUInt32(invokeId, buffer, bufPos);
buffer[bufPos++] = 0xbf;
bufPos = BerEncoder_encodeTL(0x4d, fileDirectoryResponseSize, buffer, bufPos);
bufPos = BerEncoder_encodeTL(0xa0, listOfDirectoryEntrySize, buffer, bufPos);
bufPos = BerEncoder_encodeTL(0x30, listOfDirectoryEntrySeqSize, buffer, bufPos); 
memmove(buffer + bufPos, buffer + tempStartPos, tempEncoded);
bufPos += tempEncoded;
if (moreFollows)
bufPos = BerEncoder_encodeBoolean(0x81, moreFollows, buffer, bufPos);
response->size = bufPos;
}

GF_Err gf_media_export_webvtt_metadata(GF_MediaExporter *dumper)
{
GF_ESD *esd;
char szName[1000], szMedia[1000];
FILE *med, *vtt;
u32 w, h;
u32 track, i, di, count, pos;
u32 mtype, mstype;
Bool isText;
char *mime = NULL;
Bool useBase64 = GF_FALSE;
u32 headerLength = 0;
if (!(track = gf_isom_get_track_by_id(dumper->file, dumper->trackID))) {
GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("Wrong track ID %d for file %s \n", dumper->trackID, gf_isom_get_filename(dumper->file)));
return GF_BAD_PARAM;
}
if (!track) return gf_export_message(dumper, GF_BAD_PARAM, "Invalid track ID %d", dumper->trackID);
if (dumper->flags & GF_EXPORT_PROBE_ONLY) {
return GF_OK;
}
esd = gf_isom_get_esd(dumper->file, track, 1);
med = NULL;
if (dumper->flags & GF_EXPORT_WEBVTT_META_EMBEDDED) {
} else {
sprintf(szMedia, "%s.media", dumper->out_name);
med = gf_fopen(szMedia, "wb");
if (!med) {
if (esd) gf_odf_desc_del((GF_Descriptor *) esd);
return gf_export_message(dumper, GF_IO_ERR, "Error opening %s for writing - check disk access & permissions", szMedia);
}
}
sprintf(szName, "%s.vtt", dumper->out_name);
vtt = gf_fopen(szName, "wt");
if (!vtt) {
gf_fclose(med);
if (esd) gf_odf_desc_del((GF_Descriptor *) esd);
return gf_export_message(dumper, GF_IO_ERR, "Error opening %s for writing - check disk access & permissions", szName);
}
mtype = gf_isom_get_media_type(dumper->file, track);
if (mtype==GF_ISOM_MEDIA_TEXT || mtype == GF_ISOM_MEDIA_MPEG_SUBT || mtype == GF_ISOM_MEDIA_SUBT) {
isText = GF_TRUE;
} else {
isText = GF_FALSE;
}
mstype = gf_isom_get_media_subtype(dumper->file, track, 1);
gf_fprintf(vtt, "WEBVTT Metadata track generated by GPAC MP4Box %s\n", gf_sys_is_test_mode() ? "" : gf_gpac_version());
gf_fprintf(vtt, "kind:metadata\n");
{
char *lang;
gf_isom_get_media_language(dumper->file, track, &lang);
gf_fprintf(vtt, "language:%s\n", lang);
gf_free(lang);
}
{
const char *handler;
gf_isom_get_handler_name(dumper->file, track, &handler);
gf_fprintf(vtt, "label: %s\n", handler);
}
if (gf_isom_is_track_in_root_od(dumper->file, track)) gf_fprintf(vtt, "inRootOD: yes\n");
gf_fprintf(vtt, "trackID: %d\n", dumper->trackID);
if (med) {
gf_fprintf(vtt, "baseMediaFile: %s\n", gf_file_basename(szMedia));
}
if (esd) {
if (esd->decoderConfig) {
gf_fprintf(vtt, "MPEG-4-streamType: %d\n", esd->decoderConfig->streamType);
gf_fprintf(vtt, "MPEG-4-objectTypeIndication: %d\n", esd->decoderConfig->objectTypeIndication);
}
if (gf_isom_is_video_handler_type(mtype) ) {
gf_isom_get_visual_info(dumper->file, track, 1, &w, &h);
gf_fprintf(vtt, "width:%d\n", w);
gf_fprintf(vtt, "height:%d\n", h);
}
else if (mtype==GF_ISOM_MEDIA_AUDIO) {
u32 sr, nb_ch, bps;
gf_isom_get_audio_info(dumper->file, track, 1, &sr, &nb_ch, &bps);
gf_fprintf(vtt, "sampleRate: %d\n", sr);
gf_fprintf(vtt, "numChannels: %d\n", nb_ch);
} else if (isText) {
s32 tx, ty;
s16 layer;
gf_isom_get_track_layout_info(dumper->file, track, &w, &h, &tx, &ty, &layer);
gf_fprintf(vtt, "width:%d\n", w);
gf_fprintf(vtt, "height:%d\n", h);
if (tx || ty) gf_fprintf(vtt, "translation:%d,%d\n", tx, ty);
if (layer) gf_fprintf(vtt, "layer:%d\n", layer);
}
if (esd->decoderConfig && esd->decoderConfig->decoderSpecificInfo && esd->decoderConfig->decoderSpecificInfo->data) {
if (isText) {
if (mstype == GF_ISOM_SUBTYPE_WVTT) {
mime = "text/vtt";
} else if (mstype == GF_ISOM_SUBTYPE_STXT) {
mime = "image/svg+xml";
} else if (mstype == GF_ISOM_SUBTYPE_STPP) {
mime = "application/ttml+xml";
}
if (dumper->flags & GF_EXPORT_WEBVTT_META_EMBEDDED) {
if (mstype == GF_ISOM_SUBTYPE_STXT) {
if (esd->decoderConfig->decoderSpecificInfo->dataLength) {
gf_fprintf(vtt, "text-header: \n");
gf_webvtt_dump_header_boxed(vtt, esd->decoderConfig->decoderSpecificInfo->data+4, esd->decoderConfig->decoderSpecificInfo->dataLength, &headerLength);
}
}
} else {
gf_webvtt_dump_header_boxed(med, esd->decoderConfig->decoderSpecificInfo->data+4, esd->decoderConfig->decoderSpecificInfo->dataLength, &headerLength);
gf_fprintf(vtt, "text-header-length: %d\n", headerLength);
}
} else {
char b64[200];
u32 size = gf_base64_encode(esd->decoderConfig->decoderSpecificInfo->data, esd->decoderConfig->decoderSpecificInfo->dataLength, b64, 200);
useBase64 = GF_TRUE;
if (size != (u32)-1 && size != 0) {
b64[size] = 0;
gf_fprintf(vtt, "MPEG-4-DecoderSpecificInfo: %s\n", b64);
}
}
}
gf_odf_desc_del((GF_Descriptor *) esd);
} else {
GF_GenericSampleDescription *sdesc = gf_isom_get_generic_sample_description(dumper->file, track, 1);
gf_fprintf(vtt, "mediaType: %s\n", gf_4cc_to_str(mtype));
gf_fprintf(vtt, "mediaSubType: %s\n", gf_4cc_to_str(mstype ));
if (sdesc) {
if (gf_isom_is_video_handler_type(mtype) ) {
gf_fprintf(vtt, "codecVendor: %s\n", gf_4cc_to_str(sdesc->vendor_code));
gf_fprintf(vtt, "codecVersion: %d\n", sdesc->version);
gf_fprintf(vtt, "codecRevision: %d\n", sdesc->revision);
gf_fprintf(vtt, "width: %d\n", sdesc->width);
gf_fprintf(vtt, "height: %d\n", sdesc->height);
gf_fprintf(vtt, "compressorName: %s\n", sdesc->compressor_name);
gf_fprintf(vtt, "temporalQuality: %d\n", sdesc->temporal_quality);
gf_fprintf(vtt, "spatialQuality: %d\n", sdesc->spatial_quality);
gf_fprintf(vtt, "horizontalResolution: %d\n", sdesc->h_res);
gf_fprintf(vtt, "verticalResolution: %d\n", sdesc->v_res);
gf_fprintf(vtt, "bitDepth: %d\n", sdesc->depth);
} else if (mtype==GF_ISOM_MEDIA_AUDIO) {
gf_fprintf(vtt, "codecVendor: %s\n", gf_4cc_to_str(sdesc->vendor_code));
gf_fprintf(vtt, "codecVersion: %d\n", sdesc->version);
gf_fprintf(vtt, "codecRevision: %d\n", sdesc->revision);
gf_fprintf(vtt, "sampleRate: %d\n", sdesc->samplerate);
gf_fprintf(vtt, "numChannels: %d\n", sdesc->nb_channels);
gf_fprintf(vtt, "bitsPerSample: %d\n", sdesc->bits_per_sample);
}
if (sdesc->extension_buf) {
char b64[200];
u32 size = gf_base64_encode(sdesc->extension_buf, sdesc->extension_buf_size, b64, 200);
useBase64 = GF_TRUE;
if (size != (u32)-1) {
b64[size] = 0;
gf_fprintf(vtt, "specificInfo: %s\n", b64);
gf_free(sdesc->extension_buf);
}
}
gf_free(sdesc);
}
}
gf_fprintf(vtt, "inBandMetadataTrackDispatchType: %s\n", (mime ? mime : (isText? "text/plain" : "application/octet-stream")));
if (useBase64) gf_fprintf(vtt, "encoding: base64\n");
gf_fprintf(vtt, "\n");
pos = 0;
count = gf_isom_get_sample_count(dumper->file, track);
for (i=0; i<count; i++) {
GF_ISOSample *samp = gf_isom_get_sample(dumper->file, track, i+1, &di);
if (!samp) break;
{
GF_WebVTTTimestamp start, end;
u64 dur = gf_isom_get_sample_duration(dumper->file, track, i+1);
gf_webvtt_timestamp_set(&start, samp->DTS);
gf_webvtt_timestamp_set(&end, samp->DTS+dur);
gf_webvtt_timestamp_dump(&start, vtt, GF_TRUE);
gf_fprintf(vtt, " --> ");
gf_webvtt_timestamp_dump(&end, vtt, GF_TRUE);
gf_fprintf(vtt, " ");
if (med) {
gf_fprintf(vtt, "mediaOffset:%d ", pos+headerLength);
gf_fprintf(vtt, "dataLength:%d ", samp->dataLength);
}
if (samp->CTS_Offset) gf_fprintf(vtt, "CTS: "LLD"", samp->DTS+samp->CTS_Offset);
if (samp->IsRAP==RAP) gf_fprintf(vtt, "isRAP:true ");
else if (samp->IsRAP==RAP_REDUNDANT) gf_fprintf(vtt, "isSyncShadow: true ");
else gf_fprintf(vtt, "isRAP:false ");
gf_fprintf(vtt, "\n");
}
if (med) {
gf_fwrite(samp->data, samp->dataLength, med);
} else if (dumper->flags & GF_EXPORT_WEBVTT_META_EMBEDDED) {
if (isText) {
samp->data = (char *)gf_realloc(samp->data, samp->dataLength+1);
samp->data[samp->dataLength] = 0;
gf_fprintf(vtt, "%s\n", samp->data);
} else {
u32 b64_size;
char *b64;
b64 = (char *)gf_malloc(samp->dataLength*3);
b64_size = gf_base64_encode(samp->data, samp->dataLength, b64, samp->dataLength*3);
if (b64_size != (u32)-1) {
b64[b64_size] = 0;
gf_fprintf(vtt, "%s\n", b64);
}
gf_free(b64);
}
}
gf_fprintf(vtt, "\n");
pos += samp->dataLength;
gf_isom_sample_del(&samp);
gf_set_progress("WebVTT metadata Export", i+1, count);
if (dumper->flags & GF_EXPORT_DO_ABORT) break;
}
if (med) gf_fclose(med);
gf_fclose(vtt);
return GF_OK;
}

static s32 gf_avc_read_pps_bs_internal(GF_BitStream *bs, AVCState *avc, u32 nal_hdr)
{
s32 pps_id;
AVC_PPS *pps;
gf_bs_enable_emulation_byte_removal(bs, GF_TRUE);
if (!nal_hdr) {
gf_bs_read_int_log(bs, 1, "forbidden_zero_bit");
gf_bs_read_int_log(bs, 2, "nal_ref_idc");
gf_bs_read_int_log(bs, 5, "nal_unit_type");
}
pps_id = gf_bs_read_ue_log(bs, "pps_id");
if ((pps_id<0) || (pps_id >= 255)) {
return -1;
}
pps = &avc->pps[pps_id];
pps->id = pps_id;
if (!pps->status) pps->status = 1;
pps->sps_id = gf_bs_read_ue_log(bs, "sps_id");
if ((pps->sps_id<0) || (pps->sps_id >= 32)) {
pps->sps_id = 0;
return -1;
}
if (!avc->sps[pps->sps_id].state && !avc->sps[pps->sps_id + GF_SVC_SSPS_ID_SHIFT].state) {
return -1;
}
avc->pps_active_idx = pps->id; 
avc->sps_active_idx = pps->sps_id; 
pps->entropy_coding_mode_flag = gf_bs_read_int_log(bs, 1, "entropy_coding_mode_flag");
pps->pic_order_present = gf_bs_read_int_log(bs, 1, "pic_order_present");
pps->slice_group_count = gf_bs_read_ue_log(bs, "slice_group_count_minus1") + 1;
if (pps->slice_group_count > 1) {
u32 iGroup;
pps->mb_slice_group_map_type = gf_bs_read_ue_log(bs, "mb_slice_group_map_type");
if (pps->mb_slice_group_map_type == 0) {
for (iGroup = 0; iGroup <= pps->slice_group_count - 1; iGroup++)
gf_bs_read_ue_log_idx(bs, "run_length_minus1", iGroup);
}
else if (pps->mb_slice_group_map_type == 2) {
for (iGroup = 0; iGroup < pps->slice_group_count - 1; iGroup++) {
gf_bs_read_ue_log_idx(bs, "top_left", iGroup);
gf_bs_read_ue_log_idx(bs, "bottom_right", iGroup);
}
}
else if (pps->mb_slice_group_map_type == 3 || pps->mb_slice_group_map_type == 4 || pps->mb_slice_group_map_type == 5) {
gf_bs_read_int_log(bs, 1, "slice_group_change_direction_flag");
gf_bs_read_ue_log(bs, "slice_group_change_rate_minus1");
}
else if (pps->mb_slice_group_map_type == 6) {
u32 i;
pps->pic_size_in_map_units_minus1 = gf_bs_read_ue_log(bs, "pic_size_in_map_units_minus1");
for (i = 0; i <= pps->pic_size_in_map_units_minus1; i++) {
gf_bs_read_int_log_idx(bs, (u32)ceil(log(pps->slice_group_count) / log(2)), "slice_group_id", i);
}
}
}
pps->num_ref_idx_l0_default_active_minus1 = gf_bs_read_ue_log(bs, "num_ref_idx_l0_default_active_minus1");
pps->num_ref_idx_l1_default_active_minus1 = gf_bs_read_ue_log(bs, "num_ref_idx_l1_default_active_minus1");
pps->weighted_pred_flag = gf_bs_read_int_log(bs, 1, "weighted_pred_flag");
gf_bs_read_int_log(bs, 2, "weighted_bipred_idc");
gf_bs_read_se_log(bs, "init_qp_minus26");
gf_bs_read_se_log(bs, "init_qs_minus26");
gf_bs_read_se_log(bs, "chroma_qp_index_offset");
pps->deblocking_filter_control_present_flag = gf_bs_read_int_log(bs, 1, "deblocking_filter_control_present_flag");
gf_bs_read_int_log(bs, 1, "constrained_intra_pred");
pps->redundant_pic_cnt_present = gf_bs_read_int_log(bs, 1, "redundant_pic_cnt_present");
return pps_id;
}

static void youngcollection (lua_State *L, global_State *g) {
GCObject **psurvival;  
lua_assert(g->gcstate == GCSpropagate);
markold(g, g->allgc, g->reallyold);
markold(g, g->finobj, g->finobjrold);
atomic(L);
psurvival = sweepgen(L, g, &g->allgc, g->survival);
sweepgen(L, g, psurvival, g->reallyold);
g->reallyold = g->old;
g->old = *psurvival;  
g->survival = g->allgc;  
psurvival = sweepgen(L, g, &g->finobj, g->finobjsur);
sweepgen(L, g, psurvival, g->finobjrold);
g->finobjrold = g->finobjold;
g->finobjold = *psurvival;  
g->finobjsur = g->finobj;  
sweepgen(L, g, &g->tobefnz, NULL);
finishgencycle(L, g);
}

static int prb_calc_retire_blk_tmo(struct packet_sock *po,
int blk_size_in_bytes)
{
struct net_device *dev;
unsigned int mbits = 0, msec = 0, div = 0, tmo = 0;
struct ethtool_link_ksettings ecmd;
int err;
rtnl_lock();
dev = __dev_get_by_index(sock_net(&po->sk), po->ifindex);
if (unlikely(!dev)) {
rtnl_unlock();
return DEFAULT_PRB_RETIRE_TOV;
}
err = __ethtool_get_link_ksettings(dev, &ecmd);
rtnl_unlock();
if (!err) {
if (ecmd.base.speed < SPEED_1000 ||
ecmd.base.speed == SPEED_UNKNOWN) {
return DEFAULT_PRB_RETIRE_TOV;
} else {
msec = 1;
div = ecmd.base.speed / 1000;
}
}
mbits = (blk_size_in_bytes * 8) / (1024 * 1024);
if (div)
mbits /= div;
tmo = mbits * msec;
if (div)
return tmo+1;
return tmo;
}

int nghttp2_session_on_rst_stream_received(nghttp2_session *session,
nghttp2_frame *frame) {
int rv;
nghttp2_stream *stream;
if (frame->hd.stream_id == 0) {
return session_handle_invalid_connection(session, frame, NGHTTP2_ERR_PROTO,
"RST_STREAM: stream_id == 0");
}
if (session_detect_idle_stream(session, frame->hd.stream_id)) {
return session_handle_invalid_connection(session, frame, NGHTTP2_ERR_PROTO,
"RST_STREAM: stream in idle");
}
stream = nghttp2_session_get_stream(session, frame->hd.stream_id);
if (stream) {
nghttp2_stream_shutdown(stream, NGHTTP2_SHUT_RD);
}
rv = session_call_on_frame_received(session, frame);
if (rv != 0) {
return rv;
}
rv = nghttp2_session_close_stream(session, frame->hd.stream_id,
frame->rst_stream.error_code);
if (nghttp2_is_fatal(rv)) {
return rv;
}
return 0;
}

void Compute(OpKernelContext* context) override {
const Tensor& starts_in = context->input(0);
const Tensor& limits_in = context->input(1);
const Tensor& deltas_in = context->input(2);
OP_REQUIRES(context, starts_in.shape().dims() <= 1,
InvalidArgument("starts must be a scalar or vector"));
OP_REQUIRES(context, limits_in.shape().dims() <= 1,
InvalidArgument("limits must be a scalar or vector"));
OP_REQUIRES(context, deltas_in.shape().dims() <= 1,
InvalidArgument("deltas must be a scalar or vector"));
bool broadcast_starts = starts_in.shape().dims() == 0;
bool broadcast_limits = limits_in.shape().dims() == 0;
bool broadcast_deltas = deltas_in.shape().dims() == 0;
std::vector<int> in_sizes;
if (!broadcast_starts) in_sizes.push_back(starts_in.shape().dim_size(0));
if (!broadcast_limits) in_sizes.push_back(limits_in.shape().dim_size(0));
if (!broadcast_deltas) in_sizes.push_back(deltas_in.shape().dim_size(0));
for (int i = 1; i < in_sizes.size(); ++i) {
OP_REQUIRES(context, in_sizes[i] == in_sizes[i - 1],
InvalidArgument("starts, limits, and deltas must have the "
"same shape"));
}
SPLITS_TYPE nrows = in_sizes.empty() ? 1 : in_sizes[0];
const auto& starts = starts_in.flat<T>();
const auto& limits = limits_in.flat<T>();
const auto& deltas = deltas_in.flat<T>();
Tensor* rt_nested_splits_out = nullptr;
OP_REQUIRES_OK(context,
context->allocate_output(0, TensorShape({nrows + 1}),
&rt_nested_splits_out));
auto rt_nested_splits = rt_nested_splits_out->flat<SPLITS_TYPE>();
rt_nested_splits(0) = 0;
for (int row = 0; row < nrows; ++row) {
T start = broadcast_starts ? starts(0) : starts(row);
T limit = broadcast_limits ? limits(0) : limits(row);
T delta = broadcast_deltas ? deltas(0) : deltas(row);
OP_REQUIRES(context, delta != 0, InvalidArgument("Requires delta != 0"));
rt_nested_splits(row + 1) =
rt_nested_splits(row) + RangeSize(start, limit, delta);
}
SPLITS_TYPE nvals = rt_nested_splits(nrows);
Tensor* rt_dense_values_out = nullptr;
OP_REQUIRES_OK(context, context->allocate_output(1, TensorShape({nvals}),
&rt_dense_values_out));
auto rt_dense_values = rt_dense_values_out->flat<T>();
int value_index = 0;
for (int row = 0; row < nrows; ++row) {
SPLITS_TYPE row_size = rt_nested_splits(row + 1) - rt_nested_splits(row);
T value = broadcast_starts ? starts(0) : starts(row);
T delta = broadcast_deltas ? deltas(0) : deltas(row);
for (SPLITS_TYPE i = 0; i < row_size; ++i) {
rt_dense_values(value_index++) = T(value);
value += delta;
}
}
}

int
xmlParseBalancedChunkMemoryRecover(xmlDocPtr doc, xmlSAXHandlerPtr sax,
void *user_data, int depth, const xmlChar *string, xmlNodePtr *lst,
int recover) {
xmlParserCtxtPtr ctxt;
xmlDocPtr newDoc;
xmlSAXHandlerPtr oldsax = NULL;
xmlNodePtr content, newRoot;
int size;
int ret = 0;
if (depth > 40) {
return(XML_ERR_ENTITY_LOOP);
}
if (lst != NULL)
*lst = NULL;
if (string == NULL)
return(-1);
size = xmlStrlen(string);
ctxt = xmlCreateMemoryParserCtxt((char *) string, size);
if (ctxt == NULL) return(-1);
ctxt->userData = ctxt;
if (sax != NULL) {
oldsax = ctxt->sax;
ctxt->sax = sax;
if (user_data != NULL)
ctxt->userData = user_data;
}
newDoc = xmlNewDoc(BAD_CAST "1.0");
if (newDoc == NULL) {
xmlFreeParserCtxt(ctxt);
return(-1);
}
newDoc->properties = XML_DOC_INTERNAL;
if ((doc != NULL) && (doc->dict != NULL)) {
xmlDictFree(ctxt->dict);
ctxt->dict = doc->dict;
xmlDictReference(ctxt->dict);
ctxt->str_xml = xmlDictLookup(ctxt->dict, BAD_CAST "xml", 3);
ctxt->str_xmlns = xmlDictLookup(ctxt->dict, BAD_CAST "xmlns", 5);
ctxt->str_xml_ns = xmlDictLookup(ctxt->dict, XML_XML_NAMESPACE, 36);
ctxt->dictNames = 1;
} else {
xmlCtxtUseOptionsInternal(ctxt, XML_PARSE_NODICT, NULL);
}
if (doc != NULL) {
newDoc->intSubset = doc->intSubset;
newDoc->extSubset = doc->extSubset;
}
newRoot = xmlNewDocNode(newDoc, NULL, BAD_CAST "pseudoroot", NULL);
if (newRoot == NULL) {
if (sax != NULL)
ctxt->sax = oldsax;
xmlFreeParserCtxt(ctxt);
newDoc->intSubset = NULL;
newDoc->extSubset = NULL;
xmlFreeDoc(newDoc);
return(-1);
}
xmlAddChild((xmlNodePtr) newDoc, newRoot);
nodePush(ctxt, newRoot);
if (doc == NULL) {
ctxt->myDoc = newDoc;
} else {
ctxt->myDoc = newDoc;
newDoc->children->doc = doc;
xmlSearchNsByHref(doc, (xmlNodePtr)doc, XML_XML_NAMESPACE);
newDoc->oldNs = doc->oldNs;
}
ctxt->instate = XML_PARSER_CONTENT;
ctxt->input_id = 2;
ctxt->depth = depth;
ctxt->validate = 0;
ctxt->loadsubset = 0;
xmlDetectSAX2(ctxt);
if ( doc != NULL ){
content = doc->children;
doc->children = NULL;
xmlParseContent(ctxt);
doc->children = content;
}
else {
xmlParseContent(ctxt);
}
if ((RAW == '<') && (NXT(1) == '/')) {
xmlFatalErr(ctxt, XML_ERR_NOT_WELL_BALANCED, NULL);
} else if (RAW != 0) {
xmlFatalErr(ctxt, XML_ERR_EXTRA_CONTENT, NULL);
}
if (ctxt->node != newDoc->children) {
xmlFatalErr(ctxt, XML_ERR_NOT_WELL_BALANCED, NULL);
}
if (!ctxt->wellFormed) {
if (ctxt->errNo == 0)
ret = 1;
else
ret = ctxt->errNo;
} else {
ret = 0;
}
if ((lst != NULL) && ((ret == 0) || (recover == 1))) {
xmlNodePtr cur;
cur = newDoc->children->children;
*lst = cur;
while (cur != NULL) {
xmlSetTreeDoc(cur, doc);
cur->parent = NULL;
cur = cur->next;
}
newDoc->children->children = NULL;
}
if (sax != NULL)
ctxt->sax = oldsax;
xmlFreeParserCtxt(ctxt);
newDoc->intSubset = NULL;
newDoc->extSubset = NULL;
newDoc->oldNs = NULL;
xmlFreeDoc(newDoc);
return(ret);
}

