static void  Ins_MIRP( INS_ARG )
{
Int         point,
cvtEntry;
TT_F26Dot6  cvt_dist,
distance,
cur_dist,
org_dist;
point    = (Int)args[0];
cvtEntry = (Int)args[1];
if ( BOUNDS( args[0],   CUR.zp1.n_points ) ||
BOUNDS( args[1]+1, CUR.cvtSize+1 )    )
{
CUR.error = TT_Err_Invalid_Reference;
return;
}
if ( args[1] < 0 )
cvt_dist = 0;
else
cvt_dist = CUR_Func_read_cvt( cvtEntry );
if ( ABS( cvt_dist ) < CUR.GS.single_width_cutin )
{
if ( cvt_dist >= 0 )
cvt_dist =  CUR.GS.single_width_value;
else
cvt_dist = -CUR.GS.single_width_value;
}
if ( CUR.GS.gep1 == 0 )
{
CUR.zp1.org_x[point] = CUR.zp0.org_x[CUR.GS.rp0] +
MulDiv_Round( cvt_dist,
CUR.GS.freeVector.x,
0x4000 );
CUR.zp1.org_y[point] = CUR.zp0.org_y[CUR.GS.rp0] +
MulDiv_Round( cvt_dist,
CUR.GS.freeVector.y,
0x4000 );
CUR.zp1.cur_x[point] = CUR.zp1.org_x[point];
CUR.zp1.cur_y[point] = CUR.zp1.org_y[point];
}
org_dist = CUR_Func_dualproj( CUR.zp1.org_x[point] -
CUR.zp0.org_x[CUR.GS.rp0],
CUR.zp1.org_y[point] -
CUR.zp0.org_y[CUR.GS.rp0] );
cur_dist = CUR_Func_project( CUR.zp1.cur_x[point] -
CUR.zp0.cur_x[CUR.GS.rp0],
CUR.zp1.cur_y[point] -
CUR.zp0.cur_y[CUR.GS.rp0] );
if ( CUR.GS.auto_flip )
{
if ( (org_dist ^ cvt_dist) < 0 )
cvt_dist = -cvt_dist;
}
if ( (CUR.opcode & 4) != 0 )
{
if ( CUR.GS.gep0 == CUR.GS.gep1 )
if ( ABS( cvt_dist - org_dist ) >= CUR.GS.control_value_cutin )
cvt_dist = org_dist;
distance = CUR_Func_round( cvt_dist,
CUR.metrics.compensations[CUR.opcode & 3] );
}
else
distance = Round_None( EXEC_ARGS
cvt_dist,
CUR.metrics.compensations[CUR.opcode & 3] );
if ( (CUR.opcode & 8) != 0 )
{
if ( org_dist >= 0 )
{
if ( distance < CUR.GS.minimum_distance )
distance = CUR.GS.minimum_distance;
}
else
{
if ( distance > -CUR.GS.minimum_distance )
distance = -CUR.GS.minimum_distance;
}
}
CUR_Func_move( &CUR.zp1, point, distance - cur_dist );
CUR.GS.rp1 = CUR.GS.rp0;
if ( (CUR.opcode & 16) != 0 )
CUR.GS.rp0 = point;
CUR.GS.rp2 = point;
}

TfLiteStatus ResizeOutput(TfLiteContext* context, const TfLiteTensor* input,
const TfLiteTensor* axis, TfLiteTensor* output) {
int axis_value;
if (axis->type == kTfLiteInt64) {
axis_value = static_cast<int>(*GetTensorData<int64_t>(axis));
} else {
axis_value = *GetTensorData<int>(axis);
}
if (axis_value < 0) {
axis_value += NumDimensions(input);
}
TfLiteIntArray* output_dims = TfLiteIntArrayCreate(NumDimensions(input) - 1);
int j = 0;
for (int i = 0; i < NumDimensions(input); ++i) {
if (i != axis_value) {
output_dims->data[j] = SizeOfDimension(input, i);
++j;
}
}
return context->ResizeTensor(context, output, output_dims);
}

static void
mqtts_tcptran_pipe_recv_cb(void *arg)
{
nni_aio *           aio;
nni_iov             iov;
uint8_t             type, pos, flags;
uint32_t            len = 0, rv;
size_t              n;
nni_msg *           msg, *qmsg;
mqtts_tcptran_pipe *p     = arg;
nni_aio *           rxaio = p->rxaio;
bool                ack   = false;
nni_mtx_lock(&p->mtx);
aio = nni_list_first(&p->recvq);
if ((rv = nni_aio_result(rxaio)) != 0) {
rv = SERVER_UNAVAILABLE;
goto recv_error;
}
n = nni_aio_count(rxaio);
p->gotrxhead += n;
nni_aio_iov_advance(rxaio, n);
if (nni_aio_iov_count(rxaio) > 0) {
nng_stream_recv(p->conn, rxaio);
nni_mtx_unlock(&p->mtx);
return;
}
rv = mqtt_get_remaining_length(p->rxlen, p->gotrxhead, &len, &pos);
p->wantrxhead = len + 1 + pos;
if (p->gotrxhead <= 5 && p->rxlen[p->gotrxhead - 1] > 0x7f) {
if (p->gotrxhead == NNI_NANO_MAX_HEADER_SIZE) {
rv = PACKET_TOO_LARGE;
goto recv_error;
}
iov.iov_buf = &p->rxlen[p->gotrxhead];
iov.iov_len = 1;
nni_aio_set_iov(rxaio, 1, &iov);
nng_stream_recv(p->conn, rxaio);
nni_mtx_unlock(&p->mtx);
return;
}
if (NULL == p->rxmsg) {
if ((len > p->rcvmax) && (p->rcvmax > 0)) {
rv = PACKET_TOO_LARGE;
goto recv_error;
}
if ((rv = nni_msg_alloc(&p->rxmsg, (size_t) len)) != 0) {
rv = UNSPECIFIED_ERROR;
goto recv_error;
}
nni_msg_set_remaining_len(p->rxmsg, len);
if (len != 0) {
iov.iov_buf = nni_msg_body(p->rxmsg);
iov.iov_len = (size_t) len;
nni_aio_set_iov(rxaio, 1, &iov);
nng_stream_recv(p->conn, rxaio);
nni_mtx_unlock(&p->mtx);
return;
}
}
nni_aio_list_remove(aio);
nni_msg_header_append(p->rxmsg, p->rxlen, pos + 1);
msg      = p->rxmsg;
p->rxmsg = NULL;
n        = nni_msg_len(msg);
type     = p->rxlen[0] & 0xf0;
flags    = p->rxlen[0] & 0x0f;
uint8_t   qos_pac;
uint16_t  packet_id   = 0;
uint8_t   reason_code = 0;
property *prop        = NULL;
uint8_t   ack_cmd     = 0;
switch (type) {
case CMD_PUBLISH:
qos_pac = nni_msg_get_pub_qos(msg);
if (qos_pac > 0) {
if (qos_pac == 1) {
ack_cmd = CMD_PUBACK;
} else if (qos_pac == 2) {
ack_cmd = CMD_PUBREC;
}
packet_id = nni_msg_get_pub_pid(msg);
ack = true;
}
break;
case CMD_PUBREC:
if (nni_mqtt_pubres_decode(msg, &packet_id, &reason_code, &prop,
p->proto) != 0) {
rv = PROTOCOL_ERROR;
goto recv_error;
}
ack_cmd = CMD_PUBREL;
ack     = true;
break;
case CMD_PUBREL:
if (flags == 0x02) {
if (nni_mqtt_pubres_decode(msg, &packet_id, &reason_code,
&prop, p->proto) != 0) {
rv = PROTOCOL_ERROR;
goto recv_error;
}
ack_cmd = CMD_PUBCOMP;
ack     = true;
break;
} else {
rv = PROTOCOL_ERROR;
goto recv_error;
}
case CMD_PUBACK:
case CMD_PUBCOMP:
if (nni_mqtt_pubres_decode(
msg, &packet_id, &reason_code, &prop, p->proto) != 0) {
rv = PROTOCOL_ERROR;
goto recv_error;
}
if (p->proto == MQTT_PROTOCOL_VERSION_v5) {
p->sndmax++;
}
break;
default:
break;
}
if (ack == true) {
if ((rv = nni_msg_alloc(&qmsg, 0)) != 0) {
ack = false;
rv  = UNSPECIFIED_ERROR;
goto recv_error;
}
nni_mqtt_msgack_encode(
qmsg, packet_id, reason_code, prop, p->proto);
nni_mqtt_pubres_header_encode(qmsg, ack_cmd);
if (p->proto == MQTT_PROTOCOL_VERSION_v5) {
property_free(prop);
}
if (p->busy == false) {
nni_msg_insert(qmsg, nni_msg_header(qmsg),
nni_msg_header_len(qmsg));
iov.iov_len    = nni_msg_len(qmsg);
iov.iov_buf    = nni_msg_body(qmsg);
p->busy        = true;
nni_aio_set_msg(p->qsaio, qmsg);
nni_aio_set_iov(p->qsaio, 1, &iov);
nng_stream_send(p->conn, p->qsaio);
} else {
if (nni_lmq_full(&p->rslmq)) {
if (nni_lmq_cap(&p->rslmq) <=
NNG_TRAN_MAX_LMQ_SIZE) {
if ((rv = nni_lmq_resize(&p->rslmq,
nni_lmq_cap(&p->rslmq) *
2)) == 0) {
nni_lmq_put(&p->rslmq, qmsg);
} else {
nni_msg_free(qmsg);
}
} else {
nni_msg *old;
(void) nni_lmq_get(&p->rslmq, &old);
nni_msg_free(old);
nni_lmq_put(&p->rslmq, qmsg);
}
} else {
nni_lmq_put(&p->rslmq, qmsg);
}
}
ack = false;
}
nni_pipe_bump_rx(p->npipe, n);
if (!nni_list_empty(&p->recvq)) {
mqtts_tcptran_pipe_recv_start(p);
}
#ifdef NNG_HAVE_MQTT_BROKER
nni_msg_set_conn_param(msg, p->cparam);
#endif
nni_aio_set_msg(aio, msg);
p->pingcnt = 0;
nni_mtx_unlock(&p->mtx);
nni_aio_finish_sync(aio, 0, n);
return;
recv_error:
nni_aio_list_remove(aio);
msg      = p->rxmsg;
p->rxmsg = NULL;
nni_pipe_bump_error(p->npipe, rv);
nni_mtx_unlock(&p->mtx);
nni_msg_free(msg);
nni_aio_finish_error(aio, rv);
}

void fli_read_lc_2(FILE *f, s_fli_header *fli_header, unsigned char *old_framebuf, unsigned char *framebuf)
{
unsigned short yc, lc, numline;
unsigned char *pos;
memcpy(framebuf, old_framebuf, fli_header->width * fli_header->height);
yc=0;
numline = fli_read_short(f);
for (lc=0; lc < numline; lc++) {
unsigned short xc, pc, pcnt, lpf, lpn;
pc=fli_read_short(f);
lpf=0; lpn=0;
while (pc & 0x8000) {
if (pc & 0x4000) {
yc+=-(signed short)pc;
} else {
lpf=1;lpn=pc&0xFF;
}
pc=fli_read_short(f);
}
xc=0;
pos=framebuf+(fli_header->width * yc);
for (pcnt=pc; pcnt>0; pcnt--) {
unsigned short ps,skip;
skip=fli_read_char(f);
ps=fli_read_char(f);
xc+=skip;
if (ps & 0x80) {
unsigned char v1,v2;
ps=-(signed char)ps;
v1=fli_read_char(f);
v2=fli_read_char(f);
while (ps>0) {
pos[xc++]=v1;
pos[xc++]=v2;
ps--;
}
} else {
fread(&(pos[xc]), ps, 2, f);
xc+=ps << 1;
}
}
if (lpf) pos[xc]=lpn;
yc++;
}
}

void Compute(OpKernelContext* context) override {
const Tensor& spectrogram = context->input(0);
OP_REQUIRES(context, spectrogram.dims() == 3,
errors::InvalidArgument("spectrogram must be 3-dimensional",
spectrogram.shape().DebugString()));
const Tensor& sample_rate_tensor = context->input(1);
OP_REQUIRES(context, TensorShapeUtils::IsScalar(sample_rate_tensor.shape()),
errors::InvalidArgument(
"Input sample_rate should be a scalar tensor, got ",
sample_rate_tensor.shape().DebugString(), " instead."));
const int32_t sample_rate = sample_rate_tensor.scalar<int32>()();
const int spectrogram_channels = spectrogram.dim_size(2);
const int spectrogram_samples = spectrogram.dim_size(1);
const int audio_channels = spectrogram.dim_size(0);
Mfcc mfcc;
mfcc.set_upper_frequency_limit(upper_frequency_limit_);
mfcc.set_lower_frequency_limit(lower_frequency_limit_);
mfcc.set_filterbank_channel_count(filterbank_channel_count_);
mfcc.set_dct_coefficient_count(dct_coefficient_count_);
OP_REQUIRES(context, mfcc.Initialize(spectrogram_channels, sample_rate),
errors::InvalidArgument(
"Mfcc initialization failed for channel count ",
spectrogram_channels, " and sample rate ", sample_rate));
Tensor* output_tensor = nullptr;
OP_REQUIRES_OK(context,
context->allocate_output(
0,
TensorShape({audio_channels, spectrogram_samples,
dct_coefficient_count_}),
&output_tensor));
const float* spectrogram_flat = spectrogram.flat<float>().data();
float* output_flat = output_tensor->flat<float>().data();
for (int audio_channel = 0; audio_channel < audio_channels;
++audio_channel) {
for (int spectrogram_sample = 0; spectrogram_sample < spectrogram_samples;
++spectrogram_sample) {
const float* sample_data =
spectrogram_flat +
(audio_channel * spectrogram_samples * spectrogram_channels) +
(spectrogram_sample * spectrogram_channels);
std::vector<double> mfcc_input(sample_data,
sample_data + spectrogram_channels);
std::vector<double> mfcc_output;
mfcc.Compute(mfcc_input, &mfcc_output);
DCHECK_EQ(dct_coefficient_count_, mfcc_output.size());
float* output_data =
output_flat +
(audio_channel * spectrogram_samples * dct_coefficient_count_) +
(spectrogram_sample * dct_coefficient_count_);
for (int i = 0; i < dct_coefficient_count_; ++i) {
output_data[i] = mfcc_output[i];
}
}
}
}

int nghttp2_session_add_goaway(nghttp2_session *session, int32_t last_stream_id,
uint32_t error_code, const uint8_t *opaque_data,
size_t opaque_data_len, uint8_t aux_flags) {
int rv;
nghttp2_outbound_item *item;
nghttp2_frame *frame;
uint8_t *opaque_data_copy = NULL;
nghttp2_goaway_aux_data *aux_data;
nghttp2_mem *mem;
mem = &session->mem;
if (nghttp2_session_is_my_stream_id(session, last_stream_id)) {
return NGHTTP2_ERR_INVALID_ARGUMENT;
}
if (opaque_data_len) {
if (opaque_data_len + 8 > NGHTTP2_MAX_PAYLOADLEN) {
return NGHTTP2_ERR_INVALID_ARGUMENT;
}
opaque_data_copy = nghttp2_mem_malloc(mem, opaque_data_len);
if (opaque_data_copy == NULL) {
return NGHTTP2_ERR_NOMEM;
}
memcpy(opaque_data_copy, opaque_data, opaque_data_len);
}
item = nghttp2_mem_malloc(mem, sizeof(nghttp2_outbound_item));
if (item == NULL) {
nghttp2_mem_free(mem, opaque_data_copy);
return NGHTTP2_ERR_NOMEM;
}
nghttp2_outbound_item_init(item);
frame = &item->frame;
last_stream_id = nghttp2_min(last_stream_id, session->local_last_stream_id);
nghttp2_frame_goaway_init(&frame->goaway, last_stream_id, error_code,
opaque_data_copy, opaque_data_len);
aux_data = &item->aux_data.goaway;
aux_data->flags = aux_flags;
rv = nghttp2_session_add_item(session, item);
if (rv != 0) {
nghttp2_frame_goaway_free(&frame->goaway, mem);
nghttp2_mem_free(mem, item);
return rv;
}
return 0;
}

int vfs_rename(struct inode *old_dir, struct dentry *old_dentry,
struct inode *new_dir, struct dentry *new_dentry,
struct inode **delegated_inode, unsigned int flags)
{
int error;
bool is_dir = d_is_dir(old_dentry);
const unsigned char *old_name;
struct inode *source = old_dentry->d_inode;
struct inode *target = new_dentry->d_inode;
bool new_is_dir = false;
unsigned max_links = new_dir->i_sb->s_max_links;
if (source == target)
return 0;
error = may_delete(old_dir, old_dentry, is_dir);
if (error)
return error;
if (!target) {
error = may_create(new_dir, new_dentry);
} else {
new_is_dir = d_is_dir(new_dentry);
if (!(flags & RENAME_EXCHANGE))
error = may_delete(new_dir, new_dentry, is_dir);
else
error = may_delete(new_dir, new_dentry, new_is_dir);
}
if (error)
return error;
if (!old_dir->i_op->rename && !old_dir->i_op->rename2)
return -EPERM;
if (flags && !old_dir->i_op->rename2)
return -EINVAL;
if (new_dir != old_dir) {
if (is_dir) {
error = inode_permission(source, MAY_WRITE);
if (error)
return error;
}
if ((flags & RENAME_EXCHANGE) && new_is_dir) {
error = inode_permission(target, MAY_WRITE);
if (error)
return error;
}
}
error = security_inode_rename(old_dir, old_dentry, new_dir, new_dentry,
flags);
if (error)
return error;
old_name = fsnotify_oldname_init(old_dentry->d_name.name);
dget(new_dentry);
if (!is_dir || (flags & RENAME_EXCHANGE))
lock_two_nondirectories(source, target);
else if (target)
inode_lock(target);
error = -EBUSY;
if (is_local_mountpoint(old_dentry) || is_local_mountpoint(new_dentry))
goto out;
if (max_links && new_dir != old_dir) {
error = -EMLINK;
if (is_dir && !new_is_dir && new_dir->i_nlink >= max_links)
goto out;
if ((flags & RENAME_EXCHANGE) && !is_dir && new_is_dir &&
old_dir->i_nlink >= max_links)
goto out;
}
if (is_dir && !(flags & RENAME_EXCHANGE) && target)
shrink_dcache_parent(new_dentry);
if (!is_dir) {
error = try_break_deleg(source, delegated_inode);
if (error)
goto out;
}
if (target && !new_is_dir) {
error = try_break_deleg(target, delegated_inode);
if (error)
goto out;
}
if (!old_dir->i_op->rename2) {
error = old_dir->i_op->rename(old_dir, old_dentry,
new_dir, new_dentry);
} else {
WARN_ON(old_dir->i_op->rename != NULL);
error = old_dir->i_op->rename2(old_dir, old_dentry,
new_dir, new_dentry, flags);
}
if (error)
goto out;
if (!(flags & RENAME_EXCHANGE) && target) {
if (is_dir)
target->i_flags |= S_DEAD;
dont_mount(new_dentry);
detach_mounts(new_dentry);
}
if (!(old_dir->i_sb->s_type->fs_flags & FS_RENAME_DOES_D_MOVE)) {
if (!(flags & RENAME_EXCHANGE))
d_move(old_dentry, new_dentry);
else
d_exchange(old_dentry, new_dentry);
}
out:
if (!is_dir || (flags & RENAME_EXCHANGE))
unlock_two_nondirectories(source, target);
else if (target)
inode_unlock(target);
dput(new_dentry);
if (!error) {
fsnotify_move(old_dir, new_dir, old_name, is_dir,
!(flags & RENAME_EXCHANGE) ? target : NULL, old_dentry);
if (flags & RENAME_EXCHANGE) {
fsnotify_move(new_dir, old_dir, old_dentry->d_name.name,
new_is_dir, NULL, new_dentry);
}
}
fsnotify_oldname_free(old_name);
return error;
}

static s32
brcmf_wowl_nd_results(struct brcmf_if *ifp, const struct brcmf_event_msg *e,
void *data)
{
struct brcmf_cfg80211_info *cfg = ifp->drvr->config;
struct wiphy *wiphy = cfg_to_wiphy(cfg);
struct brcmf_pno_scanresults_le *pfn_result;
struct brcmf_pno_net_info_le *netinfo;
brcmf_dbg(SCAN, "Enter\n");
if (e->datalen < (sizeof(*pfn_result) + sizeof(*netinfo))) {
brcmf_dbg(SCAN, "Event data to small. Ignore\n");
return 0;
}
pfn_result = (struct brcmf_pno_scanresults_le *)data;
if (e->event_code == BRCMF_E_PFN_NET_LOST) {
brcmf_dbg(SCAN, "PFN NET LOST event. Ignore\n");
return 0;
}
if (le32_to_cpu(pfn_result->count) < 1) {
bphy_err(wiphy, "Invalid result count, expected 1 (%d)\n",
le32_to_cpu(pfn_result->count));
return -EINVAL;
}
netinfo = brcmf_get_netinfo_array(pfn_result);
memcpy(cfg->wowl.nd->ssid.ssid, netinfo->SSID, netinfo->SSID_len);
cfg->wowl.nd->ssid.ssid_len = netinfo->SSID_len;
cfg->wowl.nd->n_channels = 1;
cfg->wowl.nd->channels[0] =
ieee80211_channel_to_frequency(netinfo->channel,
netinfo->channel <= CH_MAX_2G_CHANNEL ?
NL80211_BAND_2GHZ : NL80211_BAND_5GHZ);
cfg->wowl.nd_info->n_matches = 1;
cfg->wowl.nd_info->matches[0] = cfg->wowl.nd;
cfg->wowl.nd_data_completed = true;
wake_up(&cfg->wowl.nd_data_wait);
return 0;
}

void derive_spatial_luma_vector_prediction(base_context* ctx,
de265_image* img,
const slice_segment_header* shdr,
int xC,int yC,int nCS,int xP,int yP,
int nPbW,int nPbH, int X,
int refIdxLX, int partIdx,
uint8_t out_availableFlagLXN[2],
MotionVector out_mvLXN[2])
{
if (refIdxLX >= MAX_NUM_REF_PICS) {
ctx->add_warning(DE265_WARNING_INCORRECT_MOTION_VECTOR_SCALING, false);
img->integrity = INTEGRITY_DECODING_ERRORS;
out_availableFlagLXN[0] = false;
out_availableFlagLXN[1] = false;
out_mvLXN[0] = MotionVector{};
out_mvLXN[1] = MotionVector{};
return;
}
int isScaledFlagLX = 0;
const int A=0;
const int B=1;
out_availableFlagLXN[A] = 0;
out_availableFlagLXN[B] = 0;
int xA[2], yA[2];
xA[0] = xP-1;
yA[0] = yP + nPbH;
xA[1] = xA[0];
yA[1] = yA[0]-1;
out_availableFlagLXN[A] = 0;
out_mvLXN[A].x = 0;
out_mvLXN[A].y = 0;
bool availableA[2];
availableA[0] = img->available_pred_blk(xC,yC, nCS, xP,yP, nPbW,nPbH,partIdx, xA[0],yA[0]);
availableA[1] = img->available_pred_blk(xC,yC, nCS, xP,yP, nPbW,nPbH,partIdx, xA[1],yA[1]);
if (availableA[0] || availableA[1]) {
isScaledFlagLX = 1;
}
int refIdxA=-1;
const de265_image* tmpimg = ctx->get_image(shdr->RefPicList[X][ refIdxLX ]);
if (tmpimg==NULL) { return; }
const int referenced_POC = tmpimg->PicOrderCntVal;
for (int k=0;k<=1;k++) {
if (availableA[k] &&
out_availableFlagLXN[A]==0 &&         img->get_pred_mode(xA[k],yA[k]) != MODE_INTRA) {
int Y=1-X;
const PBMotion& vi = img->get_mv_info(xA[k],yA[k]);
logtrace(LogMotion,"MVP A%d=\n",k);
logmvcand(vi);
const de265_image* imgX = NULL;
if (vi.predFlag[X]) imgX = ctx->get_image(shdr->RefPicList[X][ vi.refIdx[X] ]);
const de265_image* imgY = NULL;
if (vi.predFlag[Y]) imgY = ctx->get_image(shdr->RefPicList[Y][ vi.refIdx[Y] ]);
if (vi.predFlag[X] && imgX && imgX->PicOrderCntVal == referenced_POC) {
logtrace(LogMotion,"take A%d/L%d as A candidate with same POC\n",k,X);
out_availableFlagLXN[A]=1;
out_mvLXN[A] = vi.mv[X];
refIdxA = vi.refIdx[X];
}
else if (vi.predFlag[Y] && imgY && imgY->PicOrderCntVal == referenced_POC) {
logtrace(LogMotion,"take A%d/L%d as A candidate with same POC\n",k,Y);
out_availableFlagLXN[A]=1;
out_mvLXN[A] = vi.mv[Y];
refIdxA = vi.refIdx[Y];
}
}
}
for (int k=0 ; k<=1 && out_availableFlagLXN[A]==0 ; k++) {
int refPicList=-1;
if (availableA[k] &&
img->get_pred_mode(xA[k],yA[k]) != MODE_INTRA) {
int Y=1-X;
const PBMotion& vi = img->get_mv_info(xA[k],yA[k]);
if (vi.predFlag[X]==1 &&
shdr->LongTermRefPic[X][refIdxLX] == shdr->LongTermRefPic[X][ vi.refIdx[X] ]) {
logtrace(LogMotion,"take A%D/L%d as A candidate with different POCs\n",k,X);
out_availableFlagLXN[A]=1;
out_mvLXN[A] = vi.mv[X];
refIdxA = vi.refIdx[X];
refPicList = X;
}
else if (vi.predFlag[Y]==1 &&
shdr->LongTermRefPic[X][refIdxLX] == shdr->LongTermRefPic[Y][ vi.refIdx[Y] ]) {
logtrace(LogMotion,"take A%d/L%d as A candidate with different POCs\n",k,Y);
out_availableFlagLXN[A]=1;
out_mvLXN[A] = vi.mv[Y];
refIdxA = vi.refIdx[Y];
refPicList = Y;
}
}
if (out_availableFlagLXN[A]==1) {
if (refIdxA<0) {
out_availableFlagLXN[0] = out_availableFlagLXN[1] = false;
return;       }
assert(refIdxA>=0);
assert(refPicList>=0);
const de265_image* refPicA = ctx->get_image(shdr->RefPicList[refPicList][refIdxA ]);
const de265_image* refPicX = ctx->get_image(shdr->RefPicList[X         ][refIdxLX]);
int isLongTermA = shdr->LongTermRefPic[refPicList][refIdxA ];
int isLongTermX = shdr->LongTermRefPic[X         ][refIdxLX];
logtrace(LogMotion,"scale MVP A: A-POC:%d X-POC:%d\n",
refPicA->PicOrderCntVal,refPicX->PicOrderCntVal);
if (!isLongTermA && !isLongTermX)
{
int distA = img->PicOrderCntVal - refPicA->PicOrderCntVal;
int distX = img->PicOrderCntVal - referenced_POC;
if (!scale_mv(&out_mvLXN[A], out_mvLXN[A], distA, distX)) {
ctx->add_warning(DE265_WARNING_INCORRECT_MOTION_VECTOR_SCALING, false);
img->integrity = INTEGRITY_DECODING_ERRORS;
}
}
}
}
int xB[3], yB[3];
xB[0] = xP+nPbW;
yB[0] = yP-1;
xB[1] = xB[0]-1;
yB[1] = yP-1;
xB[2] = xP-1;
yB[2] = yP-1;
out_availableFlagLXN[B] = 0;
out_mvLXN[B].x = 0;
out_mvLXN[B].y = 0;
int refIdxB=-1;
bool availableB[3];
for (int k=0;k<3;k++) {
availableB[k] = img->available_pred_blk(xC,yC, nCS, xP,yP, nPbW,nPbH,partIdx, xB[k],yB[k]);
if (availableB[k] && out_availableFlagLXN[B]==0) {
int Y=1-X;
const PBMotion& vi = img->get_mv_info(xB[k],yB[k]);
logtrace(LogMotion,"MVP B%d=\n",k);
logmvcand(vi);
const de265_image* imgX = NULL;
if (vi.predFlag[X]) imgX = ctx->get_image(shdr->RefPicList[X][ vi.refIdx[X] ]);
const de265_image* imgY = NULL;
if (vi.predFlag[Y]) imgY = ctx->get_image(shdr->RefPicList[Y][ vi.refIdx[Y] ]);
if (vi.predFlag[X] && imgX && imgX->PicOrderCntVal == referenced_POC) {
logtrace(LogMotion,"a) take B%d/L%d as B candidate with same POC\n",k,X);
out_availableFlagLXN[B]=1;
out_mvLXN[B] = vi.mv[X];
refIdxB = vi.refIdx[X];
}
else if (vi.predFlag[Y] && imgY && imgY->PicOrderCntVal == referenced_POC) {
logtrace(LogMotion,"b) take B%d/L%d as B candidate with same POC\n",k,Y);
out_availableFlagLXN[B]=1;
out_mvLXN[B] = vi.mv[Y];
refIdxB = vi.refIdx[Y];
}
}
}
if (isScaledFlagLX==0 &&            out_availableFlagLXN[B])      {
logtrace(LogMotion,"copy the same-POC B candidate as additional A candidate\n");
out_availableFlagLXN[A]=1;
out_mvLXN[A] = out_mvLXN[B];
refIdxA = refIdxB;
}
if (isScaledFlagLX==0) {
out_availableFlagLXN[B]=0;
for (int k=0 ; k<=2 && out_availableFlagLXN[B]==0 ; k++) {
int refPicList=-1;
if (availableB[k]) {
int Y=1-X;
const PBMotion& vi = img->get_mv_info(xB[k],yB[k]);
if (vi.predFlag[X]==1 &&
shdr->LongTermRefPic[X][refIdxLX] == shdr->LongTermRefPic[X][ vi.refIdx[X] ]) {
out_availableFlagLXN[B]=1;
out_mvLXN[B] = vi.mv[X];
refIdxB = vi.refIdx[X];
refPicList = X;
}
else if (vi.predFlag[Y]==1 &&
shdr->LongTermRefPic[X][refIdxLX] == shdr->LongTermRefPic[Y][ vi.refIdx[Y] ]) {
out_availableFlagLXN[B]=1;
out_mvLXN[B] = vi.mv[Y];
refIdxB = vi.refIdx[Y];
refPicList = Y;
}
}
if (out_availableFlagLXN[B]==1) {
if (refIdxB<0) {
out_availableFlagLXN[0] = out_availableFlagLXN[1] = false;
return;         }
assert(refPicList>=0);
assert(refIdxB>=0);
const de265_image* refPicB=ctx->get_image(shdr->RefPicList[refPicList][refIdxB ]);
const de265_image* refPicX=ctx->get_image(shdr->RefPicList[X         ][refIdxLX]);
int isLongTermB = shdr->LongTermRefPic[refPicList][refIdxB ];
int isLongTermX = shdr->LongTermRefPic[X         ][refIdxLX];
if (refPicB==NULL || refPicX==NULL) {
img->decctx->add_warning(DE265_WARNING_NONEXISTING_REFERENCE_PICTURE_ACCESSED,false);
img->integrity = INTEGRITY_DECODING_ERRORS;
}
else if (refPicB->PicOrderCntVal != refPicX->PicOrderCntVal &&
!isLongTermB && !isLongTermX) {
int distB = img->PicOrderCntVal - refPicB->PicOrderCntVal;
int distX = img->PicOrderCntVal - referenced_POC;
logtrace(LogMotion,"scale MVP B: B-POC:%d X-POC:%d\n",refPicB->PicOrderCntVal,refPicX->PicOrderCntVal);
if (!scale_mv(&out_mvLXN[B], out_mvLXN[B], distB, distX)) {
ctx->add_warning(DE265_WARNING_INCORRECT_MOTION_VECTOR_SCALING, false);
img->integrity = INTEGRITY_DECODING_ERRORS;
}
}
}
}
}
}

static void
print_gnu_property_note (Elf_Internal_Note * pnote)
{
unsigned char * ptr = (unsigned char *) pnote->descdata;
unsigned char * ptr_end = ptr + pnote->descsz;
unsigned int    size = is_32bit_elf ? 4 : 8;
printf (_("      Properties: "));
if (pnote->descsz < 8 || (pnote->descsz % size) != 0)
{
printf (_("<corrupt GNU_PROPERTY_TYPE, size = %#lx>\n"), pnote->descsz);
return;
}
while (1)
{
unsigned int j;
unsigned int type = byte_get (ptr, 4);
unsigned int datasz = byte_get (ptr + 4, 4);
ptr += 8;
if ((ptr + datasz) > ptr_end)
{
printf (_("<corrupt type (%#x) datasz: %#x>\n"),
type, datasz);
break;
}
if (type >= GNU_PROPERTY_LOPROC && type <= GNU_PROPERTY_HIPROC)
{
if (elf_header.e_machine == EM_X86_64
|| elf_header.e_machine == EM_IAMCU
|| elf_header.e_machine == EM_386)
{
switch (type)
{
case GNU_PROPERTY_X86_ISA_1_USED:
printf ("x86 ISA used: ");
if (datasz != 4)
printf (_("<corrupt length: %#x> "), datasz);
else
decode_x86_isa (byte_get (ptr, 4));
goto next;
case GNU_PROPERTY_X86_ISA_1_NEEDED:
printf ("x86 ISA needed: ");
if (datasz != 4)
printf (_("<corrupt length: %#x> "), datasz);
else
decode_x86_isa (byte_get (ptr, 4));
goto next;
case GNU_PROPERTY_X86_FEATURE_1_AND:
printf ("x86 feature: ");
if (datasz != 4)
printf (_("<corrupt length: %#x> "), datasz);
else
decode_x86_feature (type, byte_get (ptr, 4));
goto next;
default:
break;
}
}
}
else
{
switch (type)
{
case GNU_PROPERTY_STACK_SIZE:
printf (_("stack size: "));
if (datasz != size)
printf (_("<corrupt length: %#x> "), datasz);
else
printf ("%#lx", (unsigned long) byte_get (ptr, size));
goto next;
case GNU_PROPERTY_NO_COPY_ON_PROTECTED:
printf ("no copy on protected ");
if (datasz)
printf (_("<corrupt length: %#x> "), datasz);
goto next;
default:
break;
}
}
if (type < GNU_PROPERTY_LOPROC)
printf (_("<unknown type %#x data: "), type);
else if (type < GNU_PROPERTY_LOUSER)
printf (_("<procesor-specific type %#x data: "), type);
else
printf (_("<application-specific type %#x data: "), type);
for (j = 0; j < datasz; ++j)
printf ("%02x ", ptr[j] & 0xff);
printf (">");
next:
ptr += ((datasz + (size - 1)) & ~ (size - 1));
if (ptr == ptr_end)
break;
else
{
if (do_wide)
printf (", ");
else
printf ("\n\t");
}
if (ptr > (ptr_end - 8))
{
printf (_("<corrupt descsz: %#lx>\n"), pnote->descsz);
break;
}
}
printf ("\n");
}

void recv_msg_userauth_info_request() {
char *name = NULL;
char *instruction = NULL;
unsigned int num_prompts = 0;
unsigned int i;
char *prompt = NULL;
unsigned int echo = 0;
char *response = NULL;
TRACE(("enter recv_msg_recv_userauth_info_request"))
if (!cli_ses.interact_request_received) {
fprintf(stderr, "Login for %s@%s\n", cli_opts.username,
cli_opts.remotehost);
}
cli_ses.interact_request_received = 1;
name = buf_getstring(ses.payload, NULL);
instruction = buf_getstring(ses.payload, NULL);
buf_eatstring(ses.payload);
num_prompts = buf_getint(ses.payload);
if (num_prompts >= DROPBEAR_MAX_CLI_INTERACT_PROMPTS) {
dropbear_exit("Too many prompts received for keyboard-interactive");
}
CHECKCLEARTOWRITE();
buf_putbyte(ses.writepayload, SSH_MSG_USERAUTH_INFO_RESPONSE);
buf_putint(ses.writepayload, num_prompts);
if (strlen(name) > 0) {
cleantext(name);
fprintf(stderr, "%s", name);
}
m_free(name);
if (strlen(instruction) > 0) {
cleantext(instruction);
fprintf(stderr, "%s", instruction);
}
m_free(instruction);
for (i = 0; i < num_prompts; i++) {
unsigned int response_len = 0;
prompt = buf_getstring(ses.payload, NULL);
cleantext(prompt);
echo = buf_getbool(ses.payload);
if (!echo) {
char* p = getpass_or_cancel(prompt);
response = m_strdup(p);
m_burn(p, strlen(p));
} else {
response = get_response(prompt);
}
response_len = strlen(response);
buf_putstring(ses.writepayload, response, response_len);
m_burn(response, response_len);
m_free(prompt);
m_free(response);
}
encrypt_packet();
TRACE(("leave recv_msg_recv_userauth_info_request"))
}

static void
add_capabilities (proto_tree *tree, packet_info *pinfo, tvbuff_t *tvb, guint8 pdu_type)
{
proto_tree *wsp_capabilities, *cap_subtree, *cap_subtree2;
proto_item *ti, *cap_item, *cap_item2;
char       *capaName, *str;
guint32     offset       = 0;
guint32     len          = 0;
guint32     capaStart    = 0; 
guint32     capaLen      = 0; 
guint32     capaValueLen = 0; 
guint32     tvb_len      = tvb_reported_length(tvb);
gboolean    ok           = FALSE;
guint8      peek;
guint32     value;
if (tvb_len == 0) {
return;
}
ti = proto_tree_add_item(tree, hf_capabilities_section,
tvb, 0, tvb_len, ENC_NA);
wsp_capabilities = proto_item_add_subtree(ti, ett_capabilities);
while (offset < tvb_len) {
capaStart = offset;
capaValueLen = tvb_get_guintvar(tvb, offset, &len, pinfo, &ei_wsp_oversized_uintvar);
capaLen = capaValueLen + len;
cap_subtree = proto_tree_add_subtree(wsp_capabilities, tvb, offset, capaLen, ett_capabilities_entry, &cap_item, "Capability");
offset += len;
peek = tvb_get_guint8(tvb, offset);
if (is_token_text(peek)) { 
capaName = (gchar *)tvb_get_stringz_enc(wmem_packet_scope(), tvb, capaStart, (gint *)&len, ENC_ASCII);
if (g_ascii_strcasecmp(capaName, "client-sdu-size") == 0) {
peek = WSP_CAPA_CLIENT_SDU_SIZE;
} else if (g_ascii_strcasecmp(capaName, "server-sdu-size") == 0) {
peek = WSP_CAPA_SERVER_SDU_SIZE;
} else if (g_ascii_strcasecmp(capaName, "protocol options") == 0) {
peek = WSP_CAPA_PROTOCOL_OPTIONS;
} else if (g_ascii_strcasecmp(capaName, "method-mor") == 0) {
peek = WSP_CAPA_METHOD_MOR;
} else if (g_ascii_strcasecmp(capaName, "push-mor") == 0) {
peek = WSP_CAPA_PUSH_MOR;
} else if (g_ascii_strcasecmp(capaName, "extended methods") == 0) {
peek = WSP_CAPA_EXTENDED_METHODS;
} else if (g_ascii_strcasecmp(capaName, "header code pages") == 0) {
peek = WSP_CAPA_HEADER_CODE_PAGES;
} else if (g_ascii_strcasecmp(capaName, "aliases") == 0) {
peek = WSP_CAPA_ALIASES;
} else if (g_ascii_strcasecmp(capaName, "client-message-size") == 0) {
peek = WSP_CAPA_CLIENT_MESSAGE_SIZE;
} else if (g_ascii_strcasecmp(capaName, "server-message-size") == 0) {
peek = WSP_CAPA_SERVER_MESSAGE_SIZE;
} else {
expert_add_info_format(pinfo, cap_item, &ei_wsp_capability_invalid,
"Unknown or invalid textual capability: %s", capaName);
offset = capaStart + capaLen;
continue;
}
offset += len;
} else if (peek < 0x80) {
expert_add_info_format(pinfo, cap_item, &ei_wsp_capability_invalid,
"Invalid well-known capability: 0x%02X", peek);
return;
}
if (peek & 0x80) { 
peek &= 0x7F;
len = 1;
offset++;
}
proto_item_append_text(cap_item, ": %s", val_to_str_const(peek, wsp_capability_vals, "Invalid capabiliity"));
switch (peek) {
case WSP_CAPA_CLIENT_SDU_SIZE:
value = tvb_get_guintvar(tvb, offset, &len, pinfo, &ei_wsp_oversized_uintvar);
proto_tree_add_uint(cap_subtree, hf_capa_client_sdu_size,
tvb, offset, len, value);
break;
case WSP_CAPA_SERVER_SDU_SIZE:
value = tvb_get_guintvar(tvb, offset, &len, pinfo, &ei_wsp_oversized_uintvar);
proto_tree_add_uint(cap_subtree, hf_capa_server_sdu_size,
tvb, offset, len, value);
break;
case WSP_CAPA_PROTOCOL_OPTIONS:
if (capaValueLen - len == 1) {
static const int * capabilities[] = {
&hf_capa_protocol_option_confirmed_push,
&hf_capa_protocol_option_push,
&hf_capa_protocol_option_session_resume,
&hf_capa_protocol_option_ack_headers,
&hf_capa_protocol_option_large_data_transfer,
NULL
};
proto_tree_add_bitmask_with_flags(cap_subtree, tvb, offset, hf_capa_protocol_options,
ett_proto_option_capability, capabilities, ENC_NA, BMT_NO_FALSE);
}
else
{
proto_item_append_text(cap_item,
" <warning: bit field too large>");
offset = capaStart + capaLen;
continue;
}
break;
case WSP_CAPA_METHOD_MOR:
proto_tree_add_item(cap_subtree, hf_capa_method_mor, tvb, offset, len, ENC_NA);
break;
case WSP_CAPA_PUSH_MOR:
proto_tree_add_item(cap_subtree, hf_capa_push_mor, tvb, offset, len, ENC_NA);
break;
case WSP_CAPA_EXTENDED_METHODS:
cap_subtree2 = proto_tree_add_subtree(cap_subtree, tvb, capaStart, capaLen, ett_capabilities_extended_methods, &cap_item2, "Extended Methods");
if (pdu_type == WSP_PDU_CONNECT) {
while (offset < capaStart + capaLen) {
ti = proto_tree_add_item(cap_subtree2, hf_capa_extended_method, tvb, offset, 1, ENC_NA);
offset++;
get_text_string(str, tvb, offset, len, ok);
if (! ok) {
expert_add_info(pinfo, ti, &ei_wsp_capability_encoding_invalid);
return;
}
proto_item_append_text(ti, " = %s", str);
proto_item_set_len(ti, len+1);
offset += len;
}
} else {
while (offset < capaStart + capaLen) {
proto_tree_add_item(cap_subtree2, hf_capa_extended_method, tvb, offset, 1, ENC_NA);
offset++;
}
}
break;
case WSP_CAPA_HEADER_CODE_PAGES:
cap_subtree2 = proto_tree_add_subtree(cap_subtree, tvb, capaStart, capaLen, ett_capabilities_header_code_pages, &cap_item2, "Header Code Pages");
if (pdu_type == WSP_PDU_CONNECT) {
while (offset < capaStart + capaLen) {
ti = proto_tree_add_item(cap_subtree2, hf_capa_header_code_page, tvb, offset, 1, ENC_NA);
offset++;
get_text_string(str, tvb, offset, len, ok);
if (! ok) {
expert_add_info(pinfo, ti, &ei_wsp_capability_encoding_invalid);
return;
}
proto_item_append_text(ti, " = %s", str);
proto_item_set_len(ti, len+1);
offset += len;
}
} else {
while (offset < capaStart + capaLen) {
proto_tree_add_item(cap_subtree2, hf_capa_header_code_page, tvb, offset, 1, ENC_NA);
offset++;
}
}
break;
case WSP_CAPA_ALIASES:
proto_tree_add_item(cap_subtree, hf_capa_aliases,
tvb, capaStart, capaLen, ENC_NA);
break;
case WSP_CAPA_CLIENT_MESSAGE_SIZE:
value = tvb_get_guintvar(tvb, offset, &len, pinfo, &ei_wsp_oversized_uintvar);
proto_tree_add_uint(cap_subtree, hf_capa_client_message_size,
tvb, offset, len, value);
break;
case WSP_CAPA_SERVER_MESSAGE_SIZE:
value = tvb_get_guintvar(tvb, offset, &len, pinfo, &ei_wsp_oversized_uintvar);
proto_tree_add_uint(cap_subtree, hf_capa_server_message_size,
tvb, offset, len, value);
break;
default:
expert_add_info_format(pinfo, cap_item, &ei_wsp_capability_invalid,
"Unknown well-known capability: 0x%02X", peek);
break;
}
offset = capaStart + capaLen;
}
}

Status MakeGrapplerFunctionItem(const FunctionDef& func,
const AttrSlice& func_instantiation_attr,
const FunctionLibraryDefinition& flib,
const int graph_def_version,
GrapplerFunctionItem* item) {
const OpDef& signature = func.signature();
if (signature.name().empty()) {
return errors::InvalidArgument("Function name must be specified");
}
for (const OpDef::AttrDef& attr : signature.attr()) {
if (attr.type() != "type") {
return errors::InvalidArgument(
"Function signature must have only type attributes");
}
}
std::unique_ptr<FunctionBody> fbody;
TF_RETURN_IF_ERROR(
FunctionDefToBodyHelper(func, func_instantiation_attr, &flib, &fbody));
GraphDef function_body;
fbody->graph->ToGraphDef(&function_body);
*function_body.mutable_library() = flib.ReachableDefinitions(func).ToProto();
VLOG(3) << absl::Substitute(
"Deleted $0 unreachable functions from the Grappler function item "
"instantiation of $1 (library size = $2)",
flib.num_functions() - function_body.library().function_size(),
signature.name(), function_body.library().function_size());
const int num_instantiated_inputs = fbody->arg_types.size();
const int num_instantiated_outputs = fbody->ret_types.size();
std::vector<InputArgInstantiation> inputs;
inputs.reserve(num_instantiated_inputs);
for (int in_id = 0; in_id < num_instantiated_inputs; ++in_id) {
const Node* node = fbody->arg_nodes[in_id];
const DataType& dtype = fbody->arg_types[in_id];
inputs.emplace_back(node->name(), dtype);
}
std::vector<OutputArgInstantiation> outputs;
outputs.reserve(num_instantiated_outputs);
for (int out_id = 0; out_id < num_instantiated_outputs; ++out_id) {
const Node* node = fbody->ret_nodes[out_id];
const DataType& dtype = fbody->ret_types[out_id];
outputs.emplace_back(node->name(), dtype);
}
std::vector<ControlOutput> control_outputs;
control_outputs.reserve(func.control_ret_size());
for (const auto& control_ret : func.control_ret()) {
control_outputs.push_back({control_ret.first, control_ret.second});
}
std::sort(control_outputs.begin(), control_outputs.end());
std::vector<const FunctionDef::ArgAttrs*> arg_attr(inputs.size(), nullptr);
for (const auto& attr : func.arg_attr()) {
arg_attr.at(attr.first) = &attr.second;
}
*item = GrapplerFunctionItem(
signature.name(),
signature.description(),
AttrSlice(&func.attr()), std::move(arg_attr),
std::move(inputs), std::move(outputs), std::move(control_outputs),
graph_def_version, signature.is_stateful(), std::move(function_body));
return OkStatus();
}

static s32 gf_vvc_read_pps_bs_internal(GF_BitStream *bs, VVCState *vvc)
{
u32 i;
s32 pps_id;
VVC_PPS *pps;
pps_id = gf_bs_read_int_log(bs, 6, "pps_id");
if ((pps_id < 0) || (pps_id >= 64)) {
GF_LOG(GF_LOG_ERROR, GF_LOG_CODING, ("[VVC] wrong PPS ID %d in PPS\n", pps_id));
return -1;
}
pps = &vvc->pps[pps_id];
if (!pps->state) {
pps->id = pps_id;
pps->state = 1;
}
pps->sps_id = gf_bs_read_int_log(bs, 4, "sps_id");
if (((s32)pps->sps_id<0) || (pps->sps_id >= 16)) {
GF_LOG(GF_LOG_ERROR, GF_LOG_CODING, ("[VVC] wrong SPS ID %d in PPS\n", pps->sps_id));
pps->sps_id=0;
return -1;
}
vvc->sps_active_idx = pps->sps_id; 
pps->mixed_nal_types = gf_bs_read_int_log(bs, 1, "mixed_nal_types");
pps->width = gf_bs_read_ue_log(bs, "width");
pps->height = gf_bs_read_ue_log(bs, "height");
pps->conf_window = gf_bs_read_int_log(bs, 1, "conformance_window_flag");
if (pps->conf_window) {
pps->cw_left = gf_bs_read_ue_log(bs, "conf_win_left_offset");
pps->cw_right = gf_bs_read_ue_log(bs, "conf_win_right_offset");
pps->cw_top = gf_bs_read_ue_log(bs, "conf_win_top_offset");
pps->cw_bottom = gf_bs_read_ue_log(bs, "conf_win_bottom_offset");
}
if (gf_bs_read_int_log(bs, 1, "scaling_window_explicit_signaling_flag")) {
gf_bs_read_se_log(bs, "scaling_win_left_offset");
gf_bs_read_se_log(bs, "scaling_win_right_offset");
gf_bs_read_se_log(bs, "scaling_win_top_offset");
gf_bs_read_se_log(bs, "scaling_win_bottom_offset");
}
pps->output_flag_present_flag = gf_bs_read_int_log(bs, 1, "output_flag_present_flag");
pps->no_pic_partition_flag = gf_bs_read_int_log(bs, 1, "no_pic_partition_flag");
pps->subpic_id_mapping_present_flag = gf_bs_read_int_log(bs, 1, "subpic_id_mapping_present_flag");
u32 pps_num_subpics = 1;
if (pps->subpic_id_mapping_present_flag) {
u32 pps_subpic_id_len;
if (!pps->no_pic_partition_flag) {
pps_num_subpics = 1+gf_bs_read_ue_log(bs, "pps_num_subpics_minus1");
}
pps_subpic_id_len = 1 + gf_bs_read_ue(bs);
for (i=0; i<pps_num_subpics; i++) {
gf_bs_read_int_log_idx(bs, pps_subpic_id_len, "subpic_id", i);
}
}
pps->single_slice_per_subpic_flag = 1;
pps->num_slices_in_pic = 1;
pps->num_tiles_in_pic = 0;
if (!pps->no_pic_partition_flag) {
u32 ctu_size = 5 + gf_bs_read_int_log(bs, 2, "pps_log2_ctu_size_minus5");
u32 num_exp_tile_columns = 1 + gf_bs_read_ue_log(bs, "num_exp_tile_columns_minus1");
u32 num_exp_tile_rows = 1 + gf_bs_read_ue_log(bs, "num_exp_tile_rows_minus1");
if (num_exp_tile_columns > VVC_MAX_TILE_COLS) {
GF_LOG(GF_LOG_ERROR, GF_LOG_CODING, ("[VVC] wrong num tile columns %d in PPS\n", num_exp_tile_columns));
pps->sps_id=0;
return -1;
}
if (num_exp_tile_rows > VVC_MAX_TILE_ROWS) {
GF_LOG(GF_LOG_ERROR, GF_LOG_CODING, ("[VVC] wrong num tile rows %d in PPS\n", num_exp_tile_rows));
pps->sps_id=0;
return -1;
}
ctu_size = 1<<ctu_size;
pps->pic_width_in_ctbsY = pps->width / ctu_size;
if (pps->pic_width_in_ctbsY * ctu_size < pps->width) pps->pic_width_in_ctbsY++;
pps->pic_height_in_ctbsY = pps->height / ctu_size;
if (pps->pic_height_in_ctbsY * ctu_size < pps->height) pps->pic_height_in_ctbsY++;
u32 nb_ctb_left = pps->pic_width_in_ctbsY;
pps->num_tile_cols=0;
u32 nb_ctb_last=0;
for (i=0; i<num_exp_tile_columns; i++) {
u32 nb_ctb_width = 1 + gf_bs_read_ue_log_idx(bs, "tile_column_width_minus1", i);
if (nb_ctb_left < nb_ctb_width) {
pps->sps_id=0;
return -1;
}
nb_ctb_left -= nb_ctb_width;
pps->tile_cols_width_ctb[i] = nb_ctb_width;
