m_ucLowBit + m_ucHiddenBits,
m_ucHighBit + m_ucHiddenBits,
true,true);
break;
case ACResidual:
m_pParser = new(m_pEnviron) ACSequentialScan(m_pFrame,this,
m_ucScanStart,m_ucScanStop,
m_ucLowBit + m_ucHiddenBits,
m_ucHighBit + m_ucHiddenBits,
true,true);  
break;
case ResidualDCT:
m_pParser = new(m_pEnviron) SequentialScan(m_pFrame,this,
m_ucScanStart,m_ucScanStop,
m_ucLowBit + m_ucHiddenBits,
m_ucHighBit + m_ucHiddenBits,
false,false,true);
break; 
case ACResidualDCT:
m_pParser = new(m_pEnviron) ACSequentialScan(m_pFrame,this,
m_ucScanStart,m_ucScanStop,
m_ucLowBit + m_ucHiddenBits,
m_ucHighBit + m_ucHiddenBits,
false,false,true);
break;
case JPEG_LS:
switch(m_ucScanStop) {
case 0:
if (m_ucCount != 1)
JPG_THROW(MALFORMED_STREAM,"Scan::CreateParser",
"invalid codestream, found a single comonent scan containing more than one component");
m_pParser = new(m_pEnviron) class SingleComponentLSScan(m_pFrame,this,
m_ucScanStart,                                                               m_ucMappingTable,
m_ucLowBit + m_ucHiddenBits); 
break;
case 1:
m_pParser = new(m_pEnviron) class LineInterleavedLSScan(m_pFrame,this,
m_ucScanStart,
m_ucMappingTable,
m_ucLowBit + m_ucHiddenBits);
break;
case 2:
m_pParser = new(m_pEnviron) class SampleInterleavedLSScan(m_pFrame,this,
m_ucScanStart,
m_ucMappingTable,
m_ucLowBit + m_ucHiddenBits);
break;
}
break;
default:
JPG_THROW(NOT_IMPLEMENTED,"Scan::CreateParser",
"sorry, the coding mode in the codestream is currently not supported");
}
}

static long
elf_i386_get_synthetic_symtab (bfd *abfd,
long symcount ATTRIBUTE_UNUSED,
asymbol **syms ATTRIBUTE_UNUSED,
long dynsymcount,
asymbol **dynsyms,
asymbol **ret)
{
long size, count, i, n;
int j;
unsigned int plt_got_offset, plt_entry_size;
asymbol *s;
bfd_byte *plt_contents;
long dynrelcount, relsize;
arelent **dynrelbuf;
const struct elf_i386_lazy_plt_layout *lazy_plt;
const struct elf_i386_non_lazy_plt_layout *non_lazy_plt;
const struct elf_i386_lazy_plt_layout *lazy_ibt_plt;
const struct elf_i386_non_lazy_plt_layout *non_lazy_ibt_plt;
asection *plt;
bfd_vma got_addr;
char *names;
enum elf_i386_plt_type plt_type;
struct elf_i386_plt plts[] =
{
{ ".plt", NULL, NULL, plt_unknown, 0, 0, 0 },
{ ".plt.got", NULL, NULL, plt_non_lazy, 0, 0, 0 },
{ ".plt.sec", NULL, NULL, plt_second, 0, 0, 0 },
{ NULL, NULL, NULL, plt_non_lazy, 0, 0, 0 }
};
*ret = NULL;
if ((abfd->flags & (DYNAMIC | EXEC_P)) == 0)
return 0;
if (dynsymcount <= 0)
return 0;
relsize = bfd_get_dynamic_reloc_upper_bound (abfd);
if (relsize <= 0)
return -1;
dynrelbuf = (arelent **) bfd_malloc (relsize);
if (dynrelbuf == NULL)
return -1;
dynrelcount = bfd_canonicalize_dynamic_reloc (abfd, dynrelbuf,
dynsyms);
if (dynrelcount < 0)
return -1;
qsort (dynrelbuf, dynrelcount, sizeof (arelent *), compare_relocs);
non_lazy_plt = NULL;
lazy_plt = NULL;
non_lazy_ibt_plt = NULL;
lazy_ibt_plt = NULL;
switch (get_elf_i386_backend_data (abfd)->os)
{
case is_normal:
non_lazy_plt = &elf_i386_non_lazy_plt;
lazy_ibt_plt = &elf_i386_lazy_ibt_plt;
non_lazy_ibt_plt = &elf_i386_non_lazy_ibt_plt;
case is_vxworks:
lazy_plt = &elf_i386_lazy_plt;
break;
case is_nacl:
lazy_plt = &elf_i386_nacl_plt;
break;
}
got_addr = 0;
count = 0;
for (j = 0; plts[j].name != NULL; j++)
{
plt = bfd_get_section_by_name (abfd, plts[j].name);
if (plt == NULL || plt->size == 0)
continue;
plt_contents = (bfd_byte *) bfd_malloc (plt->size);
if (plt_contents == NULL)
break;
if (!bfd_get_section_contents (abfd, (asection *) plt,
plt_contents, 0, plt->size))
{
free (plt_contents);
break;
}
plt_type = plt_unknown;
if (plts[j].type == plt_unknown
&& (plt->size >= (lazy_plt->plt0_entry_size
+ lazy_plt->plt_entry_size)))
{
if (memcmp (plt_contents, lazy_plt->plt0_entry,
lazy_plt->plt0_got1_offset) == 0)
{
if (lazy_ibt_plt != NULL
&& (memcmp (plt_contents + lazy_ibt_plt->plt0_entry_size,
lazy_ibt_plt->plt_entry,
lazy_ibt_plt->plt_got_offset) == 0))
plt_type = plt_lazy | plt_second;
else
plt_type = plt_lazy;
}
else if (memcmp (plt_contents, lazy_plt->pic_plt0_entry,
lazy_plt->plt0_got1_offset) == 0)
{
if (lazy_ibt_plt != NULL
&& (memcmp (plt_contents + lazy_ibt_plt->plt0_entry_size,
lazy_ibt_plt->pic_plt_entry,
lazy_ibt_plt->plt_got_offset) == 0))
plt_type = plt_lazy | plt_pic | plt_second;
else
plt_type = plt_lazy | plt_pic;
}
}
if (non_lazy_plt != NULL
&& (plt_type == plt_unknown || plt_type == plt_non_lazy)
&& plt->size >= non_lazy_plt->plt_entry_size)
{
if (memcmp (plt_contents, non_lazy_plt->plt_entry,
non_lazy_plt->plt_got_offset) == 0)
plt_type = plt_non_lazy;
else if (memcmp (plt_contents, non_lazy_plt->pic_plt_entry,
non_lazy_plt->plt_got_offset) == 0)
plt_type = plt_pic;
}
if ((non_lazy_ibt_plt != NULL)
&& (plt_type == plt_unknown || plt_type == plt_second)
&& plt->size >= non_lazy_ibt_plt->plt_entry_size)
{
if (memcmp (plt_contents,
non_lazy_ibt_plt->plt_entry,
non_lazy_ibt_plt->plt_got_offset) == 0)
{
plt_type = plt_second;
non_lazy_plt = non_lazy_ibt_plt;
}
else if (memcmp (plt_contents,
non_lazy_ibt_plt->pic_plt_entry,
non_lazy_ibt_plt->plt_got_offset) == 0)
{
plt_type = plt_second | plt_pic;
non_lazy_plt = non_lazy_ibt_plt;
}
}
if (plt_type == plt_unknown)
continue;
plts[j].sec = plt;
plts[j].type = plt_type;
if ((plt_type & plt_lazy))
{
plts[j].plt_got_offset = lazy_plt->plt_got_offset;
plts[j].plt_entry_size = lazy_plt->plt_entry_size;
i = 1;
}
else
{
plts[j].plt_got_offset = non_lazy_plt->plt_got_offset;
plts[j].plt_entry_size = non_lazy_plt->plt_entry_size;
i = 0;
}
if ((plt_type & (plt_lazy | plt_second))
== (plt_lazy | plt_second))
plts[j].count = 0;
else
{
n = plt->size / plts[j].plt_entry_size;
plts[j].count = n;
count += n - i;
}
plts[j].contents = plt_contents;
if ((plt_type & plt_pic))
got_addr = (bfd_vma) -1;
}
if (count == 0)
return -1;
size = count * sizeof (asymbol);
s = *ret = (asymbol *) bfd_zmalloc (size);
if (s == NULL)
{
bad_return:
for (j = 0; plts[j].name != NULL; j++)
if (plts[j].contents != NULL)
free (plts[j].contents);
free (dynrelbuf);
return -1;
}
if (got_addr)
{
asection *sec = bfd_get_section_by_name (abfd, ".got.plt");
if (sec != NULL)
got_addr = sec->vma;
else
{
sec = bfd_get_section_by_name (abfd, ".got");
if (sec != NULL)
got_addr = sec->vma;
}
if (got_addr == (bfd_vma) -1)
goto bad_return;
}
size = 0;
n = 0;
for (j = 0; plts[j].name != NULL; j++)
if ((plt_contents = plts[j].contents) != NULL)
{
long k;
bfd_vma offset;
plt_got_offset = plts[j].plt_got_offset;
plt_entry_size = plts[j].plt_entry_size;
plt = plts[j].sec;
if ((plts[j].type & plt_lazy))
{
k = 1;
offset = plt_entry_size;
}
else
{
k = 0;
offset = 0;
}
for (; k < plts[j].count; k++)
{
int off;
bfd_vma got_vma;
long min, max, mid;
arelent *p;
off = H_GET_32 (abfd, (plt_contents + offset
+ plt_got_offset));
got_vma = got_addr + off;
p = dynrelbuf[0];
min = 0;
max = dynrelcount;
while ((min + 1) < max)
{
arelent *r;
mid = (min + max) / 2;
r = dynrelbuf[mid];
if (got_vma > r->address)
min = mid;
else if (got_vma < r->address)
max = mid;
else
{
p = r;
break;
}
}
if (got_vma == p->address
&& p->howto != NULL
&& (p->howto->type == R_386_JUMP_SLOT
|| p->howto->type == R_386_GLOB_DAT
|| p->howto->type == R_386_IRELATIVE))
{
*s = **p->sym_ptr_ptr;
if ((s->flags & BSF_LOCAL) == 0)
s->flags |= BSF_GLOBAL;
s->flags |= BSF_SYNTHETIC;
s->flags &= ~BSF_SECTION_SYM;
s->section = plt;
s->the_bfd = plt->owner;
s->value = offset;
s->udata.p = p;
size += strlen (s->name) + sizeof ("@plt");
if (p->addend != 0)
size += sizeof ("+0x") - 1 + 8;
n++;
s++;
}
offset += plt_entry_size;
}
}
if (n == 0)
goto bad_return;
count = n;
names = (char *) bfd_malloc (size);
if (s == NULL)
goto bad_return;
s = *ret;
for (i = 0; i < count; i++)
{
arelent *p = (arelent *) s->udata.p;
s->udata.p = NULL;
size = strlen (s->name);
memcpy (names, s->name, size);
s->name = names;
names += size;
if (p->addend != 0)
{
char buf[30], *a;
memcpy (names, "+0x", sizeof ("+0x") - 1);
names += sizeof ("+0x") - 1;
bfd_sprintf_vma (abfd, buf, p->addend);
for (a = buf; *a == '0'; ++a)
;
size = strlen (a);
memcpy (names, a, size);
names += size;
}
memcpy (names, "@plt", sizeof ("@plt"));
names += sizeof ("@plt");
s++;
}
for (j = 0; plts[j].name != NULL; j++)
if (plts[j].contents != NULL)
free (plts[j].contents);
free (dynrelbuf);
return count;
}

MEM_STATIC size_t
ZSTD_buildCTable(void* dst, size_t dstCapacity,
FSE_CTable* nextCTable, U32 FSELog, symbolEncodingType_e type,
U32* count, U32 max,
const BYTE* codeTable, size_t nbSeq,
const S16* defaultNorm, U32 defaultNormLog, U32 defaultMax,
const FSE_CTable* prevCTable, size_t prevCTableSize,
void* workspace, size_t workspaceSize)
{
BYTE* op = (BYTE*)dst;
const BYTE* const oend = op + dstCapacity;
switch (type) {
case set_rle:
*op = codeTable[0];
CHECK_F(FSE_buildCTable_rle(nextCTable, (BYTE)max));
return 1;
case set_repeat:
memcpy(nextCTable, prevCTable, prevCTableSize);
return 0;
case set_basic:
CHECK_F(FSE_buildCTable_wksp(nextCTable, defaultNorm, defaultMax, defaultNormLog, workspace, workspaceSize));  
return 0;
case set_compressed: {
S16 norm[MaxSeq + 1];
size_t nbSeq_1 = nbSeq;
const U32 tableLog = FSE_optimalTableLog(FSELog, nbSeq, max);
if (count[codeTable[nbSeq-1]] > 1) {
count[codeTable[nbSeq-1]]--;
nbSeq_1--;
}
assert(nbSeq_1 > 1);
CHECK_F(FSE_normalizeCount(norm, tableLog, count, nbSeq_1, max));
{   size_t const NCountSize = FSE_writeNCount(op, oend - op, norm, max, tableLog);   
if (FSE_isError(NCountSize)) return NCountSize;
CHECK_F(FSE_buildCTable_wksp(nextCTable, norm, max, tableLog, workspace, workspaceSize));
return NCountSize;
}
}
default: return assert(0), ERROR(GENERIC);
}
}

static bool parseUrlAddrFromRtspUrlString(const char* rtspUrlString, char* destination) {
char* rtspUrlScratchBuffer;
char* portSeparator;
char* v6EscapeEndChar;
char* urlPathSeparator;
int prefixLen;
rtspUrlScratchBuffer = strdup(rtspUrlString);
if (rtspUrlScratchBuffer == NULL) {
return false;
}
portSeparator = strrchr(rtspUrlScratchBuffer, ':');
v6EscapeEndChar = strchr(rtspUrlScratchBuffer, ']');
for (prefixLen = 2; rtspUrlScratchBuffer[prefixLen - 2] != 0 && (rtspUrlScratchBuffer[prefixLen - 2] != '/' || rtspUrlScratchBuffer[prefixLen - 1] != '/'); prefixLen++);
if (rtspUrlScratchBuffer[prefixLen - 2] == 0) {
free(rtspUrlScratchBuffer);
return false;
}
urlPathSeparator = strchr(rtspUrlScratchBuffer + prefixLen, '/');
if (v6EscapeEndChar) {
*(v6EscapeEndChar + 1) = 0;
}
else if (portSeparator) {
*portSeparator = 0;
}
else if (urlPathSeparator) {
*urlPathSeparator = 0;
}
strcpy(destination, rtspUrlScratchBuffer + prefixLen);
free(rtspUrlScratchBuffer);
return true;
}

int
dissect_ber_constrained_bitstring(gboolean implicit_tag, asn1_ctx_t *actx, proto_tree *parent_tree, tvbuff_t *tvb, int offset, gint32 min_len, gint32 max_len, const asn_namedbit *named_bits, gint hf_id, gint ett_id, tvbuff_t **out_tvb)
{
gint8       ber_class;
gboolean    pc, ind;
gint32      tag;
guint32     len, byteno;
guint8      pad  = 0, b0, b1, val, *bitstring;
int         end_offset;
int         hoffset;
proto_item *item = NULL;
proto_item *cause;
proto_tree *tree = NULL;
const char *sep;
gboolean    term;
const asn_namedbit *nb;
if (!implicit_tag) {
hoffset = offset;
offset = dissect_ber_identifier(actx->pinfo, parent_tree, tvb, offset, &ber_class, &pc, &tag);
offset = dissect_ber_length(actx->pinfo, parent_tree, tvb, offset, &len, &ind);
end_offset = offset + len;
if (!implicit_tag && (ber_class != BER_CLASS_APP)) {
if ( (ber_class != BER_CLASS_UNI)
|| (tag != BER_UNI_TAG_BITSTRING) ) {
tvb_ensure_bytes_exist(tvb, hoffset, 2);
cause = proto_tree_add_string_format_value(
parent_tree, hf_ber_error, tvb, offset, len, "bitstring_expected",
"BitString expected but class:%s(%d) %s tag:%d was unexpected",
val_to_str_const(ber_class, ber_class_codes, "Unknown"),
ber_class, pc ? ber_pc_codes_short.true_string : ber_pc_codes_short.false_string,
tag);
expert_add_info(actx->pinfo, cause, &ei_ber_expected_bitstring);
if (decode_unexpected) {
proto_tree *unknown_tree = proto_item_add_subtree(cause, ett_ber_unknown);
dissect_unknown_ber(actx->pinfo, tvb, hoffset, unknown_tree);
}
return end_offset;
}
}
} else {
pc=0;
len = tvb_reported_length_remaining(tvb, offset);
end_offset = offset+len;
}
actx->created_item = NULL;
if (pc) {
} else {
pad = tvb_get_guint8(tvb, offset);
if ((pad == 0) && (len == 1)) {
proto_tree_add_item(parent_tree, hf_ber_bitstring_empty, tvb, offset, 1, ENC_BIG_ENDIAN);
} else {
proto_item *pad_item = proto_tree_add_item(parent_tree, hf_ber_bitstring_padding, tvb, offset, 1, ENC_BIG_ENDIAN);
if (pad > 7) {
expert_add_info_format(
actx->pinfo, pad_item, &ei_ber_illegal_padding,
"Illegal padding (0 .. 7): %d", pad);
}
}
offset++;
len--;
if (hf_id >= 0) {
item = proto_tree_add_item(parent_tree, hf_id, tvb, offset, len, ENC_BIG_ENDIAN);
actx->created_item = item;
if (ett_id != -1) {
tree = proto_item_add_subtree(item, ett_id);
}
}
if (out_tvb) {
*out_tvb = ber_tvb_new_subset_length(tvb, offset, len);
}
}
if (named_bits) {
sep  = " (";
term = FALSE;
nb = named_bits;
bitstring = (guint8 *)tvb_memdup(wmem_packet_scope(), tvb, offset, len);
while (nb->p_id) {
if ((len > 0) && (pad < 8*len) && (nb->bit < (8*len-pad))) {
val = tvb_get_guint8(tvb, offset + nb->bit/8);
bitstring[(nb->bit/8)] &= ~(0x80 >> (nb->bit%8));
val &= 0x80 >> (nb->bit%8);
b0 = (nb->gb0 == -1) ? nb->bit/8 :
((guint32)nb->gb0)/8;
b1 = (nb->gb1 == -1) ? nb->bit/8 :
((guint32)nb->gb1)/8;
proto_tree_add_item(tree, *(nb->p_id), tvb, offset + b0, b1 - b0 + 1, ENC_BIG_ENDIAN);
} else {  
val = 0;
proto_tree_add_boolean(tree, *(nb->p_id), tvb, offset + len, 0, 0x00);
}
if (val) {
if (item && nb->tstr) {
proto_item_append_text(item, "%s%s", sep, nb->tstr);
sep  = ", ";
term = TRUE;
}
} else {
if (item && nb->fstr) {
proto_item_append_text(item, "%s%s", sep, nb->fstr);
sep  = ", ";
term = TRUE;
}
}
nb++;
}
if (term)
proto_item_append_text(item, ")");
for (byteno = 0; byteno < len; byteno++) {
if (bitstring[byteno]) {
expert_add_info_format(
actx->pinfo, item, &ei_ber_bits_unknown,
"Unknown bit(s): 0x%s", bytes_to_str(wmem_packet_scope(), bitstring, len));
break;
}
}
}
if ((pad > 0) && (pad < 8) && (len > 0)) {
guint8 bits_in_pad = tvb_get_guint8(tvb, offset + len - 1) & (0xFF >> (8-pad));
if (bits_in_pad) {
expert_add_info_format(
actx->pinfo, item, &ei_ber_bits_set_padded,
"Bits set in padded area: 0x%02x", bits_in_pad);
}
}
ber_check_length(8*len-pad, min_len, max_len, actx, item, TRUE);
return end_offset;
}

static int
ssh_packet_set_postauth(struct ssh *ssh)
{
struct sshcomp *comp;
int r, mode;
debug("%s: called", __func__);
ssh->state->after_authentication = 1;
ssh->state->rekeying = 0;
for (mode = 0; mode < MODE_MAX; mode++) {
if (ssh->state->newkeys[mode] == NULL)
continue;
comp = &ssh->state->newkeys[mode]->comp;
if (comp && comp->enabled &&
(r = ssh_packet_init_compression(ssh)) != 0)
return r;
}
return 0;
}

Value GetValueOrCreatePlaceholder(StringRef full_name) {
StringRef node_name;
StringRef output_name = "";
bool is_control_dep = full_name[0] == '^';
int output_num = 0;
if (is_control_dep) full_name = full_name.drop_front();
{
size_t colon_sep = full_name.find_first_of(':');
if (colon_sep == StringRef::npos) {
node_name = full_name;
} else {
node_name = full_name.take_front(colon_sep);
output_name = full_name.drop_front(colon_sep + 1);
}
colon_sep = output_name.find_last_of(':');
if (colon_sep != StringRef::npos) {
unsigned long long value;
if (!llvm::getAsUnsignedInteger(output_name.drop_front(colon_sep + 1),
10, value))
output_num = value;
output_name = output_name.take_front(colon_sep);
}
}
llvm::StringMap<SmallVector<Value, 1>>& op_info = values_map_[node_name];
SmallVector<Value, 1>& base_operation = op_info["^"];
if (base_operation.empty()) {
OperationState state(loc_, mlir_placeholder_);
state.addAttribute(TFGraphDialect::getNameAttrKey(),
builder_.getStringAttr(node_name));
state.types.push_back(placeholder_ty_);
state.types.push_back(control_ty_);
Operation* placeholder = builder_.create(state);
base_operation.push_back(placeholder->getResult(1));
base_operation.push_back(placeholder->getResult(0));
}
if (is_control_dep) return base_operation[0];
SmallVector<Value, 1>& value_info = op_info[output_name];
if (value_info.size() <= output_num)
value_info.resize(output_num + 1, Value{});
if (!value_info[output_num]) {
value_info[output_num] = builder_.create<GetResultOp>(
loc_, base_operation[1], output_name, output_num);
}
return value_info[output_num];
}

int dtls1_process_buffered_records(SSL *s)
{
pitem *item;
SSL3_BUFFER *rb;
item = pqueue_peek(s->rlayer.d->unprocessed_rcds.q);
if (item) {
if (s->rlayer.d->unprocessed_rcds.epoch != s->rlayer.d->r_epoch)
return (1);         
rb = RECORD_LAYER_get_rbuf(&s->rlayer);
if (SSL3_BUFFER_get_left(rb) > 0) {
return 1;
}
while (pqueue_peek(s->rlayer.d->unprocessed_rcds.q)) {
dtls1_get_unprocessed_record(s);
if (!dtls1_process_record(s))
return (0);
if (dtls1_buffer_record(s, &(s->rlayer.d->processed_rcds),
SSL3_RECORD_get_seq_num(s->rlayer.rrec)) <
0)
return -1;
}
}
s->rlayer.d->processed_rcds.epoch = s->rlayer.d->r_epoch;
s->rlayer.d->unprocessed_rcds.epoch = s->rlayer.d->r_epoch + 1;
return (1);
}

int socket_create(uint16_t port)
{
int sfd = -1;
int yes = 1;
#ifdef WIN32
WSADATA wsa_data;
if (!wsa_init) {
if (WSAStartup(MAKEWORD(2,2), &wsa_data) != ERROR_SUCCESS) {
fprintf(stderr, "WSAStartup failed!\n");
ExitProcess(-1);
}
wsa_init = 1;
}
#endif
struct sockaddr_in saddr;
if (0 > (sfd = socket(PF_INET, SOCK_STREAM, IPPROTO_TCP))) {
perror("socket()");
return -1;
}
if (setsockopt(sfd, SOL_SOCKET, SO_REUSEADDR, (void*)&yes, sizeof(int)) == -1) {
perror("setsockopt()");
socket_close(sfd);
return -1;
}
memset((void *) &saddr, 0, sizeof(saddr));
saddr.sin_family = AF_INET;
saddr.sin_addr.s_addr = htonl(INADDR_ANY);
saddr.sin_port = htons(port);
if (0 > bind(sfd, (struct sockaddr *) &saddr, sizeof(saddr))) {
perror("bind()");
socket_close(sfd);
return -1;
}
if (listen(sfd, 1) == -1) {
perror("listen()");
socket_close(sfd);
return -1;
}
return sfd;
}

