void Binary::shift(size_t value) {
Header& header = this->header();
const uint64_t loadcommands_start = is64_ ? sizeof(details::mach_header_64) :
sizeof(details::mach_header);
const uint64_t loadcommands_end = loadcommands_start + header.sizeof_cmds();
SegmentCommand* load_cmd_segment = segment_from_offset(loadcommands_end);
if (load_cmd_segment == nullptr) {
LIEF_WARN("Can't find segment associated with last load command");
return;
}
LIEF_DEBUG("LC Table wrapped by {} / End offset: 0x{:x} (size: {:x})",
load_cmd_segment->name(), loadcommands_end, load_cmd_segment->data_.size());
load_cmd_segment->content_insert(loadcommands_end, value);
for (std::unique_ptr<LoadCommand>& cmd : commands_) {
if (cmd->command_offset() >= loadcommands_end) {
cmd->command_offset(cmd->command_offset() + value);
}
}
shift_command(value, loadcommands_end);
for (SegmentCommand* segment : segments_) {
if (segment->file_offset() <= loadcommands_end &&
loadcommands_end < (segment->file_offset() + segment->file_size()))
{
LIEF_DEBUG("Extending '{}' by {:x}", segment->name(), value);
segment->virtual_size(segment->virtual_size() + value);
segment->file_size(segment->file_size() + value);
for (const std::unique_ptr<Section>& section : segment->sections_) {
if (section->offset() >= loadcommands_end) {
section->offset(section->offset() + value);
section->virtual_address(section->virtual_address() + value);
}
}
} else {
if (segment->file_offset() >= loadcommands_end) {
segment->file_offset(segment->file_offset() + value);
segment->virtual_address(segment->virtual_address() + value);
}
for (const std::unique_ptr<Section>& section : segment->sections_) {
if (section->offset() >= loadcommands_end) {
section->offset(section->offset() + value);
section->virtual_address(section->virtual_address() + value);
}
if (section->type() == MACHO_SECTION_TYPES::S_ZEROFILL) {
section->virtual_address(section->virtual_address() + value);
}
}
}
}
refresh_seg_offset();
}

static bool
parser_process_group_expression (parser_context_t *context_p, 
size_t *grouping_level_p) 
{
JERRY_ASSERT (*grouping_level_p >= PARSER_GROUPING_LEVEL_INCREASE);
(*grouping_level_p) -= PARSER_GROUPING_LEVEL_INCREASE;
uint8_t token = context_p->stack_top_uint8;
if (token == LEXER_COMMA_SEP_LIST)
{
parser_push_result (context_p);
parser_flush_cbc (context_p);
}
parser_stack_pop_uint8 (context_p);
lexer_next_token (context_p);
if (context_p->token.type == LEXER_ASSIGN)
{
uint32_t flags = 0;
#if ENABLED (JERRY_ES2015)
if (JERRY_UNLIKELY (token == LEXER_LEFT_PAREN))
{
flags = PARSER_PATTERN_GROUP_EXPR;
}
#endif 
parser_append_binary_single_assignment_token (context_p, flags);
lexer_next_token (context_p);
return true;
}
return false;
}

CmdResult HandleLocal(LocalUser* user, const Params& parameters) CXX11_OVERRIDE
{
size_t origin = parameters.size() > 1 ? 1 : 0;
if (parameters[origin].empty())
{
user->WriteNumeric(ERR_NOORIGIN, "No origin specified");
return CMD_FAILURE;
}
ClientProtocol::Messages::Pong pong(parameters[0], origin ? parameters[1] : "");
user->Send(ServerInstance->GetRFCEvents().pong, pong);
return CMD_SUCCESS;
}

static int
qf_jump_edit_buffer(
qf_info_T*qi,
qfline_T*qf_ptr,
intforceit,
intprev_winid,
int*opened_window)
{
qf_list_T*qfl = qf_get_curlist(qi);
intold_changedtick = qfl->qf_changedtick;
qfltype_Tqfl_type = qfl->qfl_type;
intretval = OK;
intold_qf_curlist = qi->qf_curlist;
intsave_qfid = qfl->qf_id;
if (qf_ptr->qf_type == 1)
{
if (!can_abandon(curbuf, forceit))
{
no_write_message();
return FAIL;
}
retval = do_ecmd(qf_ptr->qf_fnum, NULL, NULL, NULL, (linenr_T)1,
ECMD_HIDE + ECMD_SET_HELP,
prev_winid == curwin->w_id ? curwin : NULL);
}
else
retval = buflist_getfile(qf_ptr->qf_fnum,
(linenr_T)1, GETF_SETMARK | GETF_SWITCH, forceit);
if (qfl_type == QFLT_LOCATION)
{
win_T*wp = win_id2wp(prev_winid);
if (wp == NULL && curwin->w_llist != qi)
{
emsg(_(e_current_window_was_closed));
*opened_window = FALSE;
return NOTDONE;
}
}
if (qfl_type == QFLT_QUICKFIX && !qflist_valid(NULL, save_qfid))
{
emsg(_(e_current_quickfix_list_was_changed));
return NOTDONE;
}
if (old_qf_curlist != qi->qf_curlist
|| old_changedtick != qfl->qf_changedtick
|| !is_qf_entry_present(qfl, qf_ptr))
{
if (qfl_type == QFLT_QUICKFIX)
emsg(_(e_current_quickfix_list_was_changed));
else
emsg(_(e_current_location_list_was_changed));
return NOTDONE;
}
return retval;
}

static int do_mq_notify(mqd_t mqdes, const struct sigevent *notification)
{
int ret;
struct fd f;
struct sock *sock;
struct inode *inode;
struct mqueue_inode_info *info;
struct sk_buff *nc;
audit_mq_notify(mqdes, notification);
nc = NULL;
sock = NULL;
if (notification != NULL) {
if (unlikely(notification->sigev_notify != SIGEV_NONE &&
notification->sigev_notify != SIGEV_SIGNAL &&
notification->sigev_notify != SIGEV_THREAD))
return -EINVAL;
if (notification->sigev_notify == SIGEV_SIGNAL &&
!valid_signal(notification->sigev_signo)) {
return -EINVAL;
}
if (notification->sigev_notify == SIGEV_THREAD) {
long timeo;
nc = alloc_skb(NOTIFY_COOKIE_LEN, GFP_KERNEL);
if (!nc) {
ret = -ENOMEM;
goto out;
}
if (copy_from_user(nc->data,
notification->sigev_value.sival_ptr,
NOTIFY_COOKIE_LEN)) {
ret = -EFAULT;
goto out;
}
skb_put(nc, NOTIFY_COOKIE_LEN);
retry:
f = fdget(notification->sigev_signo);
if (!f.file) {
ret = -EBADF;
goto out;
}
sock = netlink_getsockbyfilp(f.file);
fdput(f);
if (IS_ERR(sock)) {
ret = PTR_ERR(sock);
sock = NULL;
goto out;
}
timeo = MAX_SCHEDULE_TIMEOUT;
ret = netlink_attachskb(sock, nc, &timeo, NULL);
if (ret == 1)
goto retry;
if (ret) {
sock = NULL;
nc = NULL;
goto out;
}
}
}
f = fdget(mqdes);
if (!f.file) {
ret = -EBADF;
goto out;
}
inode = file_inode(f.file);
if (unlikely(f.file->f_op != &mqueue_file_operations)) {
ret = -EBADF;
goto out_fput;
}
info = MQUEUE_I(inode);
ret = 0;
spin_lock(&info->lock);
if (notification == NULL) {
if (info->notify_owner == task_tgid(current)) {
remove_notification(info);
inode->i_atime = inode->i_ctime = current_time(inode);
}
} else if (info->notify_owner != NULL) {
ret = -EBUSY;
} else {
switch (notification->sigev_notify) {
case SIGEV_NONE:
info->notify.sigev_notify = SIGEV_NONE;
break;
case SIGEV_THREAD:
info->notify_sock = sock;
info->notify_cookie = nc;
sock = NULL;
nc = NULL;
info->notify.sigev_notify = SIGEV_THREAD;
break;
case SIGEV_SIGNAL:
info->notify.sigev_signo = notification->sigev_signo;
info->notify.sigev_value = notification->sigev_value;
info->notify.sigev_notify = SIGEV_SIGNAL;
break;
}
info->notify_owner = get_pid(task_tgid(current));
info->notify_user_ns = get_user_ns(current_user_ns());
inode->i_atime = inode->i_ctime = current_time(inode);
}
spin_unlock(&info->lock);
out_fput:
fdput(f);
out:
if (sock)
netlink_detachskb(sock, nc);
else if (nc)
dev_kfree_skb(nc);
return ret;
}

int get_superpage(unsigned long mfn, struct domain *d)
{
struct spage_info *spage;
unsigned long x, nx, y;
int pages_done = 0;
ASSERT(opt_allow_superpage);
spage = mfn_to_spage(mfn);
y = spage->type_info;
do {
x = y;
nx = x + 1;
if ( (x & SGT_type_mask) != SGT_none )
{
if ( pages_done )
{
put_spage_pages(spage_to_page(spage));
pages_done = 0;
}
}
else
{
if ( !get_spage_pages(spage_to_page(spage), d) )
{
MEM_LOG("Type conflict on superpage mapping mfn %lx",
spage_to_mfn(spage));
return -EINVAL;
}
pages_done = 1;
nx = (nx & ~SGT_type_mask) | SGT_dynamic;
}
} while ( (y = cmpxchg(&spage->type_info, x, nx)) != x );
return 0;
}

