static bool
scan_unit_for_symbols (struct comp_unit *unit)
{
bfd *abfd = unit->abfd;
bfd_byte *info_ptr = unit->first_child_die_ptr;
bfd_byte *info_ptr_end = unit->end_ptr;
int nesting_level = 0;
struct nest_funcinfo
{
struct funcinfo *func;
} *nested_funcs;
int nested_funcs_size;
struct funcinfo *last_func;
struct varinfo *last_var;
nested_funcs_size = 32;
nested_funcs = (struct nest_funcinfo *)
bfd_malloc (nested_funcs_size * sizeof (*nested_funcs));
if (nested_funcs == NULL)
return false;
nested_funcs[nesting_level].func = 0;
while (nesting_level >= 0)
{
unsigned int abbrev_number, i;
struct abbrev_info *abbrev;
struct funcinfo *func;
struct varinfo *var;
uint64_t current_offset;
if (info_ptr >= info_ptr_end)
goto fail;
current_offset = info_ptr - unit->info_ptr_unit;
abbrev_number = _bfd_safe_read_leb128 (abfd, &info_ptr,
false, info_ptr_end);
if (abbrev_number == 0)
{
nesting_level--;
continue;
}
abbrev = lookup_abbrev (abbrev_number, unit->abbrevs);
if (! abbrev)
{
static unsigned int previous_failed_abbrev = -1U;
if (abbrev_number != previous_failed_abbrev)
{
_bfd_error_handler
(_("DWARF error: could not find abbrev number %u"),
abbrev_number);
previous_failed_abbrev = abbrev_number;
}
bfd_set_error (bfd_error_bad_value);
goto fail;
}
if (abbrev->tag == DW_TAG_subprogram
|| abbrev->tag == DW_TAG_entry_point
|| abbrev->tag == DW_TAG_inlined_subroutine)
{
size_t amt = sizeof (struct funcinfo);
var = NULL;
func = (struct funcinfo *) bfd_zalloc (abfd, amt);
if (func == NULL)
goto fail;
func->tag = abbrev->tag;
func->prev_func = unit->function_table;
func->unit_offset = current_offset;
unit->function_table = func;
unit->number_of_functions++;
BFD_ASSERT (!unit->cached);
if (func->tag == DW_TAG_inlined_subroutine)
for (i = nesting_level; i-- != 0; )
if (nested_funcs[i].func)
{
func->caller_func = nested_funcs[i].func;
break;
}
nested_funcs[nesting_level].func = func;
}
else
{
func = NULL;
if (abbrev->tag == DW_TAG_variable
|| abbrev->tag == DW_TAG_member)
{
size_t amt = sizeof (struct varinfo);
var = (struct varinfo *) bfd_zalloc (abfd, amt);
if (var == NULL)
goto fail;
var->tag = abbrev->tag;
var->stack = true;
var->prev_var = unit->variable_table;
unit->variable_table = var;
var->unit_offset = current_offset;
}
else
var = NULL;
nested_funcs[nesting_level].func = 0;
}
for (i = 0; i < abbrev->num_attrs; ++i)
{
struct attribute attr;
info_ptr = read_attribute (&attr, &abbrev->attrs[i],
unit, info_ptr, info_ptr_end);
if (info_ptr == NULL)
goto fail;
}
if (abbrev->has_children)
{
nesting_level++;
if (nesting_level >= nested_funcs_size)
{
struct nest_funcinfo *tmp;
nested_funcs_size *= 2;
tmp = (struct nest_funcinfo *)
bfd_realloc (nested_funcs,
nested_funcs_size * sizeof (*nested_funcs));
if (tmp == NULL)
goto fail;
nested_funcs = tmp;
}
nested_funcs[nesting_level].func = 0;
}
}
unit->function_table = reverse_funcinfo_list (unit->function_table);
unit->variable_table = reverse_varinfo_list (unit->variable_table);
info_ptr = unit->first_child_die_ptr;
nesting_level = 0;
last_func = NULL;
last_var = NULL;
while (nesting_level >= 0)
{
unsigned int abbrev_number, i;
struct abbrev_info *abbrev;
struct attribute attr;
struct funcinfo *func;
struct varinfo *var;
bfd_vma low_pc = 0;
bfd_vma high_pc = 0;
bool high_pc_relative = false;
uint64_t current_offset;
if (info_ptr >= info_ptr_end)
goto fail;
current_offset = info_ptr - unit->info_ptr_unit;
abbrev_number = _bfd_safe_read_leb128 (abfd, &info_ptr,
false, info_ptr_end);
if (! abbrev_number)
{
nesting_level--;
continue;
}
abbrev = lookup_abbrev (abbrev_number, unit->abbrevs);
BFD_ASSERT (abbrev != NULL);
func = NULL;
var = NULL;
if (abbrev->tag == DW_TAG_subprogram
|| abbrev->tag == DW_TAG_entry_point
|| abbrev->tag == DW_TAG_inlined_subroutine)
{
if (last_func
&& last_func->prev_func
&& last_func->prev_func->unit_offset == current_offset)
func = last_func->prev_func;
else
func = lookup_func_by_offset (current_offset, unit->function_table);
if (func == NULL)
goto fail;
last_func = func;
}
else if (abbrev->tag == DW_TAG_variable
|| abbrev->tag == DW_TAG_member)
{
if (last_var
&& last_var->prev_var
&& last_var->prev_var->unit_offset == current_offset)
var = last_var->prev_var;
else
var = lookup_var_by_offset (current_offset, unit->variable_table);
if (var == NULL)
goto fail;
last_var = var;
}
for (i = 0; i < abbrev->num_attrs; ++i)
{
info_ptr = read_attribute (&attr, &abbrev->attrs[i],
unit, info_ptr, info_ptr_end);
if (info_ptr == NULL)
goto fail;
if (func)
{
switch (attr.name)
{
case DW_AT_call_file:
if (is_int_form (&attr))
func->caller_file = concat_filename (unit->line_table,
attr.u.val);
break;
case DW_AT_call_line:
if (is_int_form (&attr))
func->caller_line = attr.u.val;
break;
case DW_AT_abstract_origin:
case DW_AT_specification:
if (is_int_form (&attr)
&& !find_abstract_instance (unit, &attr, 0,
&func->name,
&func->is_linkage,
&func->file,
&func->line))
goto fail;
break;
case DW_AT_name:
if (func->name == NULL && is_str_form (&attr))
{
func->name = attr.u.str;
if (mangle_style (unit->lang) == 0)
func->is_linkage = true;
}
break;
case DW_AT_linkage_name:
case DW_AT_MIPS_linkage_name:
if (is_str_form (&attr))
{
func->name = attr.u.str;
func->is_linkage = true;
}
break;
case DW_AT_low_pc:
if (is_int_form (&attr))
low_pc = attr.u.val;
break;
case DW_AT_high_pc:
if (is_int_form (&attr))
{
high_pc = attr.u.val;
high_pc_relative = attr.form != DW_FORM_addr;
}
break;
case DW_AT_ranges:
if (is_int_form (&attr)
&& !read_rangelist (unit, &func->arange,
&unit->file->trie_root, attr.u.val))
goto fail;
break;
case DW_AT_decl_file:
if (is_int_form (&attr))
func->file = concat_filename (unit->line_table,
attr.u.val);
break;
case DW_AT_decl_line:
if (is_int_form (&attr))
func->line = attr.u.val;
break;
default:
break;
}
}
else if (var)
{
switch (attr.name)
{
case DW_AT_specification:
if (is_int_form (&attr) && attr.u.val)
{
bool is_linkage;
if (!find_abstract_instance (unit, &attr, 0,
&var->name,
&is_linkage,
&var->file,
&var->line))
{
_bfd_error_handler (_("DWARF error: could not find "
"variable specification "
"at offset 0x%lx"),
(unsigned long) attr.u.val);
break;
}
}
break;
case DW_AT_name:
if (is_str_form (&attr))
var->name = attr.u.str;
break;
case DW_AT_decl_file:
if (is_int_form (&attr))
var->file = concat_filename (unit->line_table,
attr.u.val);
break;
case DW_AT_decl_line:
if (is_int_form (&attr))
var->line = attr.u.val;
break;
case DW_AT_external:
if (is_int_form (&attr) && attr.u.val != 0)
var->stack = false;
break;
case DW_AT_location:
switch (attr.form)
{
case DW_FORM_block:
case DW_FORM_block1:
case DW_FORM_block2:
case DW_FORM_block4:
case DW_FORM_exprloc:
if (attr.u.blk->data != NULL
&& *attr.u.blk->data == DW_OP_addr)
{
var->stack = false;
if (attr.u.blk->size == unit->addr_size + 1U)
var->addr = bfd_get (unit->addr_size * 8,
unit->abfd,
attr.u.blk->data + 1);
}
break;
default:
break;
}
break;
default:
break;
}
}
}
if (abbrev->has_children)
nesting_level++;
if (high_pc_relative)
high_pc += low_pc;
if (func && high_pc != 0)
{
if (!arange_add (unit, &func->arange, &unit->file->trie_root,
low_pc, high_pc))
goto fail;
}
}
unit->function_table = reverse_funcinfo_list (unit->function_table);
unit->variable_table = reverse_varinfo_list (unit->variable_table);
free (nested_funcs);
return true;
fail:
free (nested_funcs);
return false;
}

int
nng_proxy_start(int argc, char **argv)
{
if (strncmp(argv[0], "sub0", 3) == 0)
nng_proxy_client(argc-1, argv+1, SUB0);
else if (strncmp(argv[0], "pub0", 3) == 0)
nng_proxy_client(argc-1, argv+1, PUB0);
else if (strncmp(argv[0], "pair1", 5) == 0)
nng_proxy_client(argc-1, argv+1, PAIR1);
else
help(SUB0);
return 0;
}

void
completeHTMLstream(struct html_feed_environ *h_env, struct readbuffer *obuf)
{
close_anchor(h_env, obuf);
if (obuf->img_alt) {
push_tag(obuf, "</img_alt>", HTML_N_IMG_ALT);
obuf->img_alt = NULL;
}
if (obuf->input_alt.in) {
push_tag(obuf, "</input_alt>", HTML_N_INPUT_ALT);
obuf->input_alt.hseq = 0;
obuf->input_alt.fid = -1;
obuf->input_alt.in = 0;
obuf->input_alt.type = NULL;
obuf->input_alt.name = NULL;
obuf->input_alt.value = NULL;
}
if (obuf->in_bold) {
push_tag(obuf, "</b>", HTML_N_B);
obuf->in_bold = 0;
}
if (obuf->in_italic) {
push_tag(obuf, "</i>", HTML_N_I);
obuf->in_italic = 0;
}
if (obuf->in_under) {
push_tag(obuf, "</u>", HTML_N_U);
obuf->in_under = 0;
}
if (obuf->in_strike) {
push_tag(obuf, "</s>", HTML_N_S);
obuf->in_strike = 0;
}
if (obuf->in_ins) {
push_tag(obuf, "</ins>", HTML_N_INS);
obuf->in_ins = 0;
}
if (obuf->flag & RB_INTXTA)
HTMLlineproc1("</textarea>", h_env);
if (obuf->flag & RB_INSELECT)
HTMLlineproc1("</select>", h_env);
if (obuf->flag & RB_TITLE)
HTMLlineproc1("</title>", h_env);
if (obuf->table_level >= MAX_TABLE)
obuf->table_level = MAX_TABLE - 1;
while (obuf->table_level >= 0) {
table_mode[obuf->table_level].pre_mode
&= ~(TBLM_SCRIPT | TBLM_STYLE | TBLM_PLAIN);
HTMLlineproc1("</table>", h_env);
}
}

GF_Err DumpRawUIConfig(GF_DefaultDescriptor *dsi, FILE *trace, u32 indent, Bool XMTDump, u32 oti)
{
char devName[255];
u32 i;
u64 len;
GF_BitStream *bs;
bs = gf_bs_new(dsi->data, dsi->dataLength, GF_BITSTREAM_READ);
StartDescDump(trace, "UIConfig" , indent, XMTDump);
indent++;
len = gf_bs_read_int(bs, 8);
for (i=0; i<len; i++) devName[i] = gf_bs_read_int(bs, 8);
devName[i] = 0;
DumpString(trace, "deviceName", devName, indent, XMTDump);
if (!stricmp(devName, "StringSensor") && gf_bs_available(bs)) {
devName[0] = gf_bs_read_int(bs, 8);
devName[1] = 0;
DumpString(trace, "termChar", devName, indent, XMTDump);
devName[0] = gf_bs_read_int(bs, 8);
DumpString(trace, "delChar", devName, indent, XMTDump);
}
len = gf_bs_available(bs);
if (len) {
if (!stricmp(devName, "HTKSensor")) {
u32 nb_word, nbPhone, c, j;
char szPh[3];
StartAttribute(trace, "uiData", indent, XMTDump);
if (!XMTDump) gf_fprintf(trace, "\"");
gf_fprintf(trace, "HTK:");
szPh[2] = 0;
nb_word = gf_bs_read_int(bs, 8);
for (i=0; i<nb_word; i++) {
nbPhone = gf_bs_read_int(bs, 8);
if (i) gf_fprintf(trace, ";");
while ((c=gf_bs_read_int(bs, 8))) gf_fprintf(trace, "%c", c);
gf_fprintf(trace, " ");
for (j=0; j<nbPhone; j++) {
gf_bs_read_data(bs, szPh, 2);
if (j) gf_fprintf(trace, " ");
if (!stricmp(szPh, "vc")) gf_fprintf(trace, "vcl");
else gf_fprintf(trace, "%s", szPh);
}
}
if (!XMTDump) gf_fprintf(trace, "\"");
EndAttribute(trace, indent, XMTDump);
} else {
char *data = dsi->data;
data += gf_bs_get_position(bs);
